pub fn CalcBands(arg_diff: [*c]Int32, arg_start: Int32, arg_stop: Int32, arg_num_bands: Int32) void {
    var diff = arg_diff;
    _ = &diff;
    var start = arg_start;
    _ = &start;
    var stop = arg_stop;
    _ = &stop;
    var num_bands = arg_num_bands;
    _ = &num_bands;
    var i: Int32 = undefined;
    _ = &i;
    var previous: Int32 = undefined;
    _ = &previous;
    var current: Int32 = undefined;
    _ = &current;
    var tmp_q1: Int32 = undefined;
    _ = &tmp_q1;
    previous = start;
    {
        i = 1;
        while (i <= num_bands) : (i += 1) {
            tmp_q1 = pv_log2(@divTrunc(stop << @intCast(@as(c_int, 20)), start));
            tmp_q1 = fxp_mul32_Q20(tmp_q1, @divTrunc(i << @intCast(@as(c_int, 27)), num_bands));
            tmp_q1 = pv_pow2(tmp_q1);
            tmp_q1 = fxp_mul32_Q20(tmp_q1, start);
            current = (tmp_q1 + @as(c_int, 16)) >> @intCast(@as(c_int, 5));
            diff[@bitCast(@as(isize, @intCast(i - @as(c_int, 1))))] = current - previous;
            previous = current;
        }
    }
}

