pub fn PVMP4AudioDecoderConfig(arg_pExt: [*c]tPVMP4AudioDecoderExternal, arg_pMem: ?*anyopaque) Int {
    var pExt = arg_pExt;
    _ = &pExt;
    var pMem = arg_pMem;
    _ = &pMem;
    var initialUsedBits: UInt = undefined;
    _ = &initialUsedBits;
    var pVars: [*c]tDec_Int_File = undefined;
    _ = &pVars;
    var status: Int = MP4AUDEC_INCOMPLETE_FRAME;
    _ = &status;
    pVars = @ptrCast(@alignCast(pMem));
    pVars.*.inputStream.pBuffer = pExt.*.pInputBuffer;
    pVars.*.inputStream.inputBufferCurrentLength = @bitCast(@as(c_int, pExt.*.inputBufferCurrentLength));
    pVars.*.inputStream.availableBits = @bitCast(@as(c_int, pExt.*.inputBufferCurrentLength << @intCast(@as(c_int, 3))));
    initialUsedBits = @bitCast(@as(c_int, (pExt.*.inputBufferUsedLength << @intCast(@as(c_int, 3))) + pExt.*.remainderBits));
    pVars.*.inputStream.usedBits = initialUsedBits;
    if (initialUsedBits <= pVars.*.inputStream.availableBits) {
        pVars.*.aacConfigUtilityEnabled = @as(c_int, 0) != 0;
        status = get_audio_specific_config(pVars);
    }
    byte_align(&pVars.*.inputStream);
    if (status == @as(c_int, 0)) {
        pVars.*.bno +%= 1;
        pExt.*.samplingRate = samp_rate_info[@bitCast(@as(isize, @intCast(pVars.*.prog_config.sampling_rate_idx)))].samp_rate;
        pExt.*.aacPlusEnabled = pVars.*.aacPlusEnabled;
        pExt.*.encodedChannels = 2;
        pExt.*.frameLength = pVars.*.frameLength;
        pExt.*.aacPlusUpsamplingFactor = pVars.*.mc_info.upsamplingFactor;
    } else {
        status = MP4AUDEC_INVALID_FRAME;
        if (pVars.*.inputStream.usedBits > pVars.*.inputStream.availableBits) {
            pVars.*.inputStream.usedBits = pVars.*.inputStream.availableBits;
            status = MP4AUDEC_INCOMPLETE_FRAME;
        }
    }
    pExt.*.inputBufferUsedLength = @bitCast(@as(c_uint, @truncate(pv_shr(pVars.*.inputStream.usedBits, @as(UInt, @bitCast(@as(c_int, @as(c_int, 3))))))));
    pExt.*.remainderBits = @bitCast(@as(c_uint, @truncate(pVars.*.inputStream.usedBits & @as(UInt, @bitCast(@as(c_int, (@as(c_int, 1) << @intCast(@as(c_int, 3))) - @as(c_int, 1)))))));
    pVars.*.status = status;
    return status;
}

pub fn PVMP4AudioDecoderDisableAacPlus(arg_pExt: [*c]tPVMP4AudioDecoderExternal, arg_pMem: ?*anyopaque) void {
    var pExt = arg_pExt;
    _ = &pExt;
    var pMem = arg_pMem;
    _ = &pMem;
    var pVars: [*c]tDec_Int_File = undefined;
    _ = &pVars;
    pVars = @ptrCast(@alignCast(pMem));
    if ((@as(c_int, @intFromBool(pVars.*.aacPlusEnabled)) == @as(c_int, 1)) and (@as(c_int, @intFromBool(pExt.*.aacPlusEnabled)) == @as(c_int, 1))) {
        pVars.*.aacPlusEnabled = @as(c_int, 0) != 0;
        pExt.*.aacPlusEnabled = @as(c_int, 0) != 0;
        pVars.*.mc_info.upsamplingFactor = 1;
        pVars.*.mc_info.psPresentFlag = 0;
        pVars.*.mc_info.sbrPresentFlag = 0;
        pVars.*.prog_config.sampling_rate_idx += 3;
        pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 0)].syncState = SBR_NOT_INITIALIZED;
        pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 1)].syncState = SBR_NOT_INITIALIZED;
        pExt.*.samplingRate = samp_rate_info[@bitCast(@as(isize, @intCast(pVars.*.prog_config.sampling_rate_idx)))].samp_rate;
        pExt.*.aacPlusUpsamplingFactor = 1;
    }
}

