    _ = infoinit(pVars.*.mc_info.sampling_rate_idx, @ptrCast(@alignCast(&pVars.*.winmap)), @ptrCast(@alignCast(&pVars.*.SFBWidth128)));
    pExt.*.bitRate = 0;
