    pExt.*.samplingRate = 0;
    pExt.*.aacPlusUpsamplingFactor = 1;
    pVars.*.aacPlusEnabled = pExt.*.aacPlusEnabled;
    pVars.*.sbrDecoderData.setStreamType = 1;
