            _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData_1.*.HistsbrQmfBufferImag))))), 0, (@sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData_1.*.HistsbrQmfBufferImag))).*)) *% @as(c_ulong, 6)) *% @as(c_ulong, 48));
            if (pVars.*.sbrDec.LC_aacP_DecoderFlag == @as(c_int, 1)) {
                {
                    i = 0;
                    while (i < @as(c_int, 8)) : (i += 1) {
                        _ = memset(@ptrCast(@alignCast(&hFrameData_2.*.codecQmfBufferReal[@bitCast(@as(isize, @intCast(i)))])), 0, @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][32]Int32, @ptrCast(@alignCast(&hFrameData_1.*.codecQmfBufferReal))).*))).*)) << @intCast(@as(c_ulong, 5)));
                    }
                }
                _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData_2.*.HistsbrQmfBufferReal))))), 0, (@sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData_2.*.HistsbrQmfBufferReal))).*)) *% @as(c_ulong, 6)) *% @as(c_ulong, 48));
                _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData_2.*.BwVectorOld))))), 0, @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData_2.*.BwVectorOld))).*)) *% @as(c_ulong, 6));
                {
                    i = 0;
                    while (i < @as(c_int, 5)) : (i += 1) {
                        _ = memset(@ptrCast(@alignCast(&hFrameData_2.*.fBuffer_man[@bitCast(@as(isize, @intCast(i)))])), 0, @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][64]Int32, @ptrCast(@alignCast(&hFrameData_2.*.fBuffer_man))).*))).*)) *% @as(c_ulong, 64));
                        _ = memset(@ptrCast(@alignCast(&hFrameData_2.*.fBufferN_man[@bitCast(@as(isize, @intCast(i)))])), 0, @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][64]Int32, @ptrCast(@alignCast(&hFrameData_2.*.fBufferN_man))).*))).*)) *% @as(c_ulong, 64));
                    }
                }
            } else if (pVars.*.mc_info.psPresentFlag == @as(c_int, 1)) {
                {
                    i = 0;
                    while (i < @as(c_int, 3)) : (i += 1) {
                        _ = memset(@ptrCast(@alignCast(sbrDecoderData.*.hParametricStereoDec.*.hHybrid.*.mQmfBufferReal[@bitCast(@as(isize, @intCast(i)))])), 0, @as(c_ulong, 12) *% @sizeOf(Int32));
                        _ = memset(@ptrCast(@alignCast(sbrDecoderData.*.hParametricStereoDec.*.hHybrid.*.mQmfBufferImag[@bitCast(@as(isize, @intCast(i)))])), 0, @as(c_ulong, 12) *% @sizeOf(Int32));
                    }
                }
            }
            pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 0)].syncState = UPSAMPLING;
            pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 1)].syncState = UPSAMPLING;
        }
    }
    pVars.*.bno = 1;
    return;
}

pub fn PVMP4SetAudioConfig(arg_pExt: [*c]tPVMP4AudioDecoderExternal, arg_pMem: ?*anyopaque, arg_upsamplingFactor: Int, arg_samp_rate: Int, arg_num_ch: Int, arg_audioObjectType: tMP4AudioObjectType) Int {
    var pExt = arg_pExt;
    _ = &pExt;
    var pMem = arg_pMem;
    _ = &pMem;
    var upsamplingFactor = arg_upsamplingFactor;
    _ = &upsamplingFactor;
    var samp_rate = arg_samp_rate;
    _ = &samp_rate;
    var num_ch = arg_num_ch;
    _ = &num_ch;
    var audioObjectType = arg_audioObjectType;
    _ = &audioObjectType;
    var pVars: [*c]tDec_Int_File = undefined;
    _ = &pVars;
    var status: Int = MP4AUDEC_INCOMPLETE_FRAME;
    _ = &status;
    pVars = @ptrCast(@alignCast(pMem));
    pVars.*.inputStream.pBuffer = pExt.*.pInputBuffer;
    pVars.*.inputStream.availableBits = 0;
    pVars.*.inputStream.usedBits = 0;
    blk: {
        switch (samp_rate) {
            @as(c_int, 96000) => {
                pVars.*.prog_config.sampling_rate_idx = 0;
                break :blk;
            },
            @as(c_int, 88200) => {
                pVars.*.prog_config.sampling_rate_idx = 1;
                break :blk;
            },
            @as(c_int, 64000) => {
                pVars.*.prog_config.sampling_rate_idx = 2;
                break :blk;
            },
            @as(c_int, 48000) => {
                pVars.*.prog_config.sampling_rate_idx = 3;
                break :blk;
            },
            @as(c_int, 44100) => {
                pVars.*.prog_config.sampling_rate_idx = 4;
                break :blk;
            },
            @as(c_int, 32000) => {
                pVars.*.prog_config.sampling_rate_idx = 5;
                break :blk;
            },
            @as(c_int, 24000) => {
                pVars.*.prog_config.sampling_rate_idx = 6;
                break :blk;
            },
            @as(c_int, 22050) => {
                pVars.*.prog_config.sampling_rate_idx = 7;
                break :blk;
            },
            @as(c_int, 16000) => {
                pVars.*.prog_config.sampling_rate_idx = 8;
                break :blk;
            },
            @as(c_int, 12000) => {
                pVars.*.prog_config.sampling_rate_idx = 9;
                break :blk;
            },
            @as(c_int, 11025) => {
                pVars.*.prog_config.sampling_rate_idx = 10;
                break :blk;
            },
            @as(c_int, 8000) => {
                pVars.*.prog_config.sampling_rate_idx = 11;
                break :blk;
            },
            @as(c_int, 7350) => {
                pVars.*.prog_config.sampling_rate_idx = 12;
                break :blk;
            },
            else => {
                status = -@as(c_int, 1);
                break :blk;
            },
        }
    }
    pVars.*.mc_info.sbrPresentFlag = 0;
    pVars.*.mc_info.psPresentFlag = 0;
    pVars.*.mc_info.bDownSampledSbr = @as(c_int, 0) != 0;
    pVars.*.mc_info.implicit_channeling = 0;
    pVars.*.mc_info.nch = num_ch;
    pVars.*.mc_info.upsamplingFactor = upsamplingFactor;
    if (num_ch == @as(c_int, 2)) {
        pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)] = 1;
    } else if (num_ch == @as(c_int, 1)) {
        pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)] = 0;
    } else {
        status = -@as(c_int, 1);
        pVars.*.status = status;
        return status;
    }
    if ((audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_AAC_LC)) or (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_LTP))) {
        pVars.*.aacPlusEnabled = @as(c_int, 0) != 0;
        status = set_mc_info(&pVars.*.mc_info, audioObjectType, pVars.*.prog_config.sampling_rate_idx, pVars.*.prog_config.front.ele_tag[@as(c_int, 0)], pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)], @ptrCast(@alignCast(&pVars.*.winmap)), @ptrCast(@alignCast(&pVars.*.SFBWidth128)));
    } else if ((audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_SBR)) or (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_PS))) {
        pVars.*.aacPlusEnabled = @as(c_int, 1) != 0;
        status = set_mc_info(&pVars.*.mc_info, MP4AUDIO_AAC_LC, pVars.*.prog_config.sampling_rate_idx, pVars.*.prog_config.front.ele_tag[@as(c_int, 0)], pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)], @ptrCast(@alignCast(&pVars.*.winmap)), @ptrCast(@alignCast(&pVars.*.SFBWidth128)));
        pVars.*.mc_info.sbrPresentFlag = 1;
        if (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_PS)) {
            pVars.*.mc_info.psPresentFlag = 1;
        }
        if (upsamplingFactor == @as(c_int, 1)) {
            pVars.*.mc_info.bDownSampledSbr = @as(c_int, 1) != 0;
            if (pVars.*.prog_config.sampling_rate_idx < @as(c_int, 6)) {
                pVars.*.aacPlusEnabled = @as(c_int, 0) != 0;
            }
        }
    } else {
        status = -@as(c_int, 1);
    }
    pExt.*.inputBufferUsedLength = 0;
    pExt.*.remainderBits = 0;
    pVars.*.bno +%= 1;
    pExt.*.samplingRate = samp_rate * upsamplingFactor;
    pExt.*.aacPlusEnabled = pVars.*.aacPlusEnabled;
    pExt.*.encodedChannels = 2;
    pExt.*.frameLength = 1024;
    pExt.*.aacPlusUpsamplingFactor = upsamplingFactor;
    pVars.*.status = status;
    return status;
}

