pub fn analysis_sub_band(arg_vec: [*c]Int32, arg_cosine_total: [*c]Int32, arg_sine_total: [*c]Int32, arg_maxBand: Int32, arg_scratch_mem: [*c][64]Int32) void {
    var vec = arg_vec;
    _ = &vec;
    var cosine_total = arg_cosine_total;
    _ = &cosine_total;
    var sine_total = arg_sine_total;
    _ = &sine_total;
    var maxBand = arg_maxBand;
    _ = &maxBand;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var i: Int32 = undefined;
    _ = &i;
    var sine_term1: [*c]Int32 = &scratch_mem[@as(c_int, 0)][@as(c_int, 0)];
    _ = &sine_term1;
    var sine_term2: [*c]Int32 = &scratch_mem[@as(c_int, 0)][@as(c_int, 32)];
    _ = &sine_term2;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var temp3: Int32 = undefined;
    _ = &temp3;
    var temp4: Int32 = undefined;
    _ = &temp4;
    var pt_exp: [*c]const Int32 = undefined;
    _ = &pt_exp;
    var exp_1_5: Int32 = undefined;
    _ = &exp_1_5;
    var pt_vec: [*c]Int32 = &vec[@as(c_int, 0)];
    _ = &pt_vec;
    var pt_vec_32: [*c]Int32 = &vec[@as(c_int, 32)];
    _ = &pt_vec_32;
    var pt_cos1: [*c]Int32 = pt_vec;
    _ = &pt_cos1;
    var pt_sin1: [*c]Int32 = sine_term1;
    _ = &pt_sin1;
    var pt_cos2: [*c]Int32 = pt_vec_32;
    _ = &pt_cos2;
    var pt_sin2: [*c]Int32 = sine_term2;
    _ = &pt_sin2;
    _ = memcpy(@ptrCast(@alignCast(sine_term1)), @ptrCast(@alignCast(vec)), @as(c_ulong, 64) *% @sizeOf(@TypeOf(vec.*)));
    mdst_32(sine_term1, @ptrCast(@alignCast(&scratch_mem[@as(c_int, 1)])));
    mdst_32(sine_term2, @ptrCast(@alignCast(&scratch_mem[@as(c_int, 1)])));
    mdct_32(&vec[@as(c_int, 0)]);
    mdct_32(&vec[@as(c_int, 32)]);
    pt_cos1 = &vec[@as(c_int, 0)];
    pt_cos2 = &vec[@as(c_int, 32)];
    pt_sin1 = sine_term1;
    pt_sin2 = sine_term2;
    pt_vec = cosine_total;
    pt_vec_32 = sine_total;
    pt_exp = @ptrCast(@alignCast(&exp_1_5_phi));
    temp3 = (blk: {
        const ref = &pt_cos1;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).* - (blk: {
        const ref = &pt_sin2;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    temp4 = (blk: {
        const ref = &pt_sin1;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).* + (blk: {
        const ref = &pt_cos2;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    {
        i = 0;
        while (i < maxBand) : (i += 2) {
            exp_1_5 = (blk: {
                const ref = &pt_exp;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp1 = cmplx_mul32_by_16(temp3, temp4, exp_1_5);
            temp2 = cmplx_mul32_by_16(temp4, -temp3, exp_1_5);
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = shft_lft_1(temp1);
            (blk: {
                const ref = &pt_vec_32;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = shft_lft_1(temp2);
            temp3 = (blk: {
                const ref = &pt_cos1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* + (blk: {
                const ref = &pt_sin2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp4 = (blk: {
                const ref = &pt_sin1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* - (blk: {
                const ref = &pt_cos2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            exp_1_5 = (blk: {
                const ref = &pt_exp;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp1 = cmplx_mul32_by_16(temp3, temp4, exp_1_5);
            temp2 = cmplx_mul32_by_16(temp4, -temp3, exp_1_5);
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = shft_lft_1(temp1);
            (blk: {
                const ref = &pt_vec_32;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = shft_lft_1(temp2);
            temp3 = (blk: {
                const ref = &pt_cos1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* - (blk: {
                const ref = &pt_sin2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp4 = (blk: {
                const ref = &pt_sin1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* + (blk: {
                const ref = &pt_cos2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
        }
    }
    pt_cos1 = &cosine_total[@bitCast(@as(isize, @intCast(maxBand)))];
    pt_sin1 = &sine_total[@bitCast(@as(isize, @intCast(maxBand)))];
    {
        i = @as(c_int, 32) - maxBand;
        while (i != @as(c_int, 0)) : (i -= 1) {
            (blk: {
                const ref = &pt_cos1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = 0;
            (blk: {
                const ref = &pt_sin1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = 0;
        }
    }
}

pub fn analysis_sub_band_LC(arg_vec: [*c]Int32, arg_cosine_total: [*c]Int32, arg_maxBand: Int32, arg_scratch_mem: [*c][64]Int32) void {
