pub fn apply_ms_synt(pFrameInfo: [*c]const FrameInfo, arg_group: [*c]const Int, arg_mask_map: [*c]const Bool, arg_codebook_map: [*c]const Int, arg_coefLeft: [*c]Int32, arg_coefRight: [*c]Int32, arg_q_formatLeft: [*c]Int, arg_q_formatRight: [*c]Int) void {
    _ = &pFrameInfo;
    var group = arg_group;
    _ = &group;
    var mask_map = arg_mask_map;
    _ = &mask_map;
    var codebook_map = arg_codebook_map;
    _ = &codebook_map;
    var coefLeft = arg_coefLeft;
    _ = &coefLeft;
    var coefRight = arg_coefRight;
    _ = &coefRight;
    var q_formatLeft = arg_q_formatLeft;
    _ = &q_formatLeft;
    var q_formatRight = arg_q_formatRight;
    _ = &q_formatRight;
    var pCoefRight: [*c]Int32 = undefined;
    _ = &pCoefRight;
    var pCoefLeft: [*c]Int32 = undefined;
    _ = &pCoefLeft;
    var tot_sfb: Int = undefined;
    _ = &tot_sfb;
    var sfb: Int = undefined;
    _ = &sfb;
    var band_length: Int = undefined;
    _ = &band_length;
    var band_start: Int = undefined;
    _ = &band_start;
    var band_stop: Int = undefined;
    _ = &band_stop;
    var coef_per_win: Int = undefined;
    _ = &coef_per_win;
    var codebook: Int = undefined;
    _ = &codebook;
    var partition: Int = undefined;
    _ = &partition;
    var window_start: Int = undefined;
    _ = &window_start;
    var sfb_per_win: Int = undefined;
    _ = &sfb_per_win;
    var wins_in_group: Int = undefined;
    _ = &wins_in_group;
    var pBand: [*c]const Int16 = undefined;
    _ = &pBand;
    var pCodebookMap: [*c]const Int = codebook_map;
    _ = &pCodebookMap;
    var pGroup: [*c]const Int = group;
    _ = &pGroup;
    var pMaskMap: [*c]const Bool = mask_map;
    _ = &pMaskMap;
    var mask_enabled: Bool = undefined;
    _ = &mask_enabled;
    pCoefRight = coefRight;
    pCoefLeft = coefLeft;
    window_start = 0;
    tot_sfb = 0;
    coef_per_win = pFrameInfo.*.coef_per_win[@as(c_int, 0)];
    sfb_per_win = pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
    while (true) {
        pBand = pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(window_start)))];
        partition = (blk: {
            const ref = &pGroup;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        band_start = 0;
        wins_in_group = partition - window_start;
        {
            sfb = sfb_per_win;
            while (sfb > @as(c_int, 0)) : (sfb -= 1) {
                band_stop = (blk: {
                    const ref = &pBand;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                codebook = (blk: {
                    const ref = &pCodebookMap;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                mask_enabled = (blk: {
                    const ref = &pMaskMap;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                if (codebook < NOISE_HCB) {
                    if (mask_enabled != @as(c_int, 0)) {
                        band_length = band_stop - band_start;
                        ms_synt(wins_in_group, coef_per_win, sfb_per_win, band_length, (pCoefLeft + @as(usize, @bitCast(@as(isize, @intCast(band_start))))), (pCoefRight + @as(usize, @bitCast(@as(isize, @intCast(band_start))))), (q_formatLeft + @as(usize, @bitCast(@as(isize, @intCast(tot_sfb))))), (q_formatRight + @as(usize, @bitCast(@as(isize, @intCast(tot_sfb))))));
                    }
                }
                band_start = band_stop;
                tot_sfb += 1;
            }
        }
        pCoefRight += @as(usize, @bitCast(@as(isize, @intCast(coef_per_win * wins_in_group))));
        pCoefLeft += @as(usize, @bitCast(@as(isize, @intCast(coef_per_win * (blk: {
            const ref = &wins_in_group;
            const tmp = ref.*;
            ref.* -= 1;
            break :blk tmp;
        })))));
        tot_sfb += sfb_per_win * wins_in_group;
        window_start = partition;
        if (!(partition < pFrameInfo.*.num_win)) break;
    }
    return;
}

pub fn apply_tns(arg_coef: [*c]Int32, arg_q_format: [*c]Int, pFrameInfo: [*c]const FrameInfo, pTNS_frame_info: [*c]TNS_frame_info, inverse_flag: Bool, arg_scratch_Int_buffer: [*c]Int32) void {
    var coef = arg_coef;
    _ = &coef;
    var q_format = arg_q_format;
    _ = &q_format;
    _ = &pFrameInfo;
    _ = &pTNS_frame_info;
    _ = &inverse_flag;
    var scratch_Int_buffer = arg_scratch_Int_buffer;
    _ = &scratch_Int_buffer;
    var num_tns_bands: Int = undefined;
    _ = &num_tns_bands;
    var num_TNS_coef: Int = undefined;
    _ = &num_TNS_coef;
    var f: Int = undefined;
    _ = &f;
    var tempInt: Int = undefined;
    _ = &tempInt;
    var tempInt2: Int = undefined;
    _ = &tempInt2;
    var sfb_per_win: Int = undefined;
    _ = &sfb_per_win;
    var sfbWidth: Int = undefined;
    _ = &sfbWidth;
    var coef_per_win: Int = undefined;
    _ = &coef_per_win;
    var min_q: Int = undefined;
    _ = &min_q;
    var win: Int = undefined;
    _ = &win;
    var pCoef: [*c]Int32 = coef;
    _ = &pCoef;
    var pTempCoef: [*c]Int32 = undefined;
    _ = &pTempCoef;
    var pStartQformat: [*c]Int = q_format;
    _ = &pStartQformat;
    var pQformat: [*c]Int = undefined;
    _ = &pQformat;
    var pLpcCoef: [*c]Int32 = undefined;
    _ = &pLpcCoef;
    var sfb_offset: Int = undefined;
    _ = &sfb_offset;
    var pWinSfbTop: [*c]const Int16 = undefined;
    _ = &pWinSfbTop;
    var pFilt: [*c]TNSfilt = undefined;
    _ = &pFilt;
    coef_per_win = pFrameInfo.*.coef_per_win[@as(c_int, 0)];
    sfb_per_win = pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
    win = 0;
    pLpcCoef = @ptrCast(@alignCast(&pTNS_frame_info.*.lpc_coef));
    pFilt = @ptrCast(@alignCast(&pTNS_frame_info.*.filt));
    while (true) {
        {
            f = pTNS_frame_info.*.n_filt[@bitCast(@as(isize, @intCast(win)))];
            while (f > @as(c_int, 0)) : (f -= 1) {
                tempInt = @bitCast(@as(c_uint, @truncate(pFilt.*.order)));
                if (tempInt > @as(c_int, 0)) {
                    num_TNS_coef = pFilt.*.stop_coef - pFilt.*.start_coef;
                    if (num_TNS_coef > @as(c_int, 0)) {
                        if (inverse_flag != @as(c_int, 0)) {
                            tns_inv_filter(&pCoef[@bitCast(@as(isize, @intCast(pFilt.*.start_coef)))], num_TNS_coef, pFilt.*.direction, pLpcCoef, pFilt.*.q_lpc, @bitCast(@as(c_uint, @truncate(pFilt.*.order))), scratch_Int_buffer);
                        } else {
                            num_tns_bands = pFilt.*.stop_band - pFilt.*.start_band;
                            pQformat = &pStartQformat[@bitCast(@as(isize, @intCast(pFilt.*.stop_band)))];
                            min_q = 32767;
                            {
                                tempInt = num_tns_bands;
                                while (tempInt > @as(c_int, 0)) : (tempInt -= 1) {
                                    tempInt2 = (blk: {
                                        const ref = &pQformat;
                                        ref.* -= 1;
                                        break :blk ref.*;
                                    }).*;
                                    if (tempInt2 < min_q) {
                                        min_q = tempInt2;
                                    }
                                }
                            }
                            tempInt = pFilt.*.start_band;
                            tempInt -= 1;
                            if (tempInt >= @as(c_int, 0)) {
                                pWinSfbTop = &pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(win)))][@bitCast(@as(isize, @intCast(tempInt)))];
                                sfb_offset = (blk: {
                                    const ref = &pWinSfbTop;
                                    const tmp = ref.*;
                                    ref.* += 1;
                                    break :blk tmp;
                                }).*;
                            } else {
                                pWinSfbTop = pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(win)))];
                                sfb_offset = 0;
                            }
                            pTempCoef = pCoef + @as(usize, @bitCast(@as(isize, @intCast(pFilt.*.start_coef))));
                            {
                                tempInt = num_tns_bands;
                                while (tempInt > @as(c_int, 0)) : (tempInt -= 1) {
                                    sfbWidth = @as(c_int, (blk: {
                                        const ref = &pWinSfbTop;
                                        const tmp = ref.*;
                                        ref.* += 1;
                                        break :blk tmp;
                                    }).*) - sfb_offset;
                                    sfb_offset += sfbWidth;
                                    tempInt2 = (blk: {
                                        const ref = &pQformat;
                                        const tmp = ref.*;
                                        ref.* += 1;
                                        break :blk tmp;
                                    }).* - min_q;
                                    if (tempInt2 > @as(c_int, 31)) {
                                        tempInt2 = 31;
                                    }
                                    {
                                        sfbWidth >>= @intCast(@as(c_int, 2));
                                        while (sfbWidth > @as(c_int, 0)) : (sfbWidth -= 1) {
                                            (blk: {
                                                const ref = &pTempCoef;
                                                const tmp = ref.*;
                                                ref.* += 1;
                                                break :blk tmp;
                                            }).* >>= @intCast(tempInt2);
                                            (blk: {
                                                const ref = &pTempCoef;
                                                const tmp = ref.*;
                                                ref.* += 1;
                                                break :blk tmp;
                                            }).* >>= @intCast(tempInt2);
                                            (blk: {
                                                const ref = &pTempCoef;
                                                const tmp = ref.*;
                                                ref.* += 1;
                                                break :blk tmp;
                                            }).* >>= @intCast(tempInt2);
                                            (blk: {
                                                const ref = &pTempCoef;
                                                const tmp = ref.*;
                                                ref.* += 1;
                                                break :blk tmp;
                                            }).* >>= @intCast(tempInt2);
                                        }
                                    }
                                }
                            }
                            tempInt2 = tns_ar_filter(&pCoef[@bitCast(@as(isize, @intCast(pFilt.*.start_coef)))], num_TNS_coef, pFilt.*.direction, pLpcCoef, pFilt.*.q_lpc, @bitCast(@as(c_uint, @truncate(pFilt.*.order))));
                            min_q -= tempInt2;
                            {
                                tempInt = num_tns_bands;
                                while (tempInt > @as(c_int, 0)) : (tempInt -= 1) {
                                    (blk: {
                                        const ref = &pQformat;
                                        ref.* -= 1;
                                        break :blk ref.*;
                                    }).* = min_q;
                                }
                            }
                        }
                    }
                    pLpcCoef += pFilt.*.order;
                }
                pFilt += 1;
            }
        }
        pCoef += @as(usize, @bitCast(@as(isize, @intCast(coef_per_win))));
        pStartQformat += @as(usize, @bitCast(@as(isize, @intCast(sfb_per_win))));
        win += 1;
        if (!(win < pFrameInfo.*.num_win)) break;
    }
    return;
}

