pub fn buf_get_1bit(arg_hBitBuf: [*c]BIT_BUFFER) UInt32 {
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    if (hBitBuf.*.buffered_bits <= @as(UInt32, 16)) {
        hBitBuf.*.buffer_word = (pv_shl(hBitBuf.*.buffer_word, @as(UInt32, 16))) | @as(UInt32, @bitCast(@as(c_int, @as(c_int, (blk: {
            const ref = &hBitBuf.*.char_ptr;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*) << @intCast(@as(c_int, 8)))));
        hBitBuf.*.buffer_word |= @bitCast(@as(c_int, @as(c_int, (blk: {
            const ref = &hBitBuf.*.char_ptr;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*)));
        hBitBuf.*.buffered_bits +%= 16;
    }
    hBitBuf.*.buffered_bits -%= 1;
    hBitBuf.*.nrBitsRead +%= 1;
    return (pv_shr(hBitBuf.*.buffer_word, hBitBuf.*.buffered_bits)) & @as(UInt32, 1);
}

pub fn buf_getbits(arg_hBitBuf: [*c]BIT_BUFFER, arg_n: Int32) UInt32 {
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var n = arg_n;
    _ = &n;
    if (hBitBuf.*.buffered_bits <= @as(UInt32, 16)) {
        hBitBuf.*.buffer_word = (pv_shl(hBitBuf.*.buffer_word, @as(UInt32, 16))) | @as(UInt32, @bitCast(@as(c_int, @as(c_int, (blk: {
            const ref = &hBitBuf.*.char_ptr;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*) << @intCast(@as(c_int, 8)))));
        hBitBuf.*.buffer_word |= @bitCast(@as(c_int, @as(c_int, (blk: {
            const ref = &hBitBuf.*.char_ptr;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*)));
        hBitBuf.*.buffered_bits +%= 16;
    }
    hBitBuf.*.buffered_bits -%= @bitCast(@as(c_int, n));
    hBitBuf.*.nrBitsRead +%= @bitCast(@as(c_int, n));
    return (pv_shr(hBitBuf.*.buffer_word, hBitBuf.*.buffered_bits)) & @as(UInt32, @bitCast(@as(c_int, (pv_shl(@as(c_int, 1), n)) - @as(c_int, 1))));
}

pub fn byte_align(arg_pInputStream: [*c]BITS) void {
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    pInputStream.*.usedBits +%= 7;
    pInputStream.*.usedBits &= @as(UInt, @bitCast(@as(c_int, -@as(c_int, 8))));
    return;
}

pub fn calc_auto_corr(arg_ac: [*c]struct_ACORR_COEFS, arg_realBuf: [*c][32]Int32, arg_imagBuf: [*c][32]Int32, arg_bd: Int32, arg_len: Int32) void {
    var ac = arg_ac;
    _ = &ac;
    var realBuf = arg_realBuf;
    _ = &realBuf;
    var imagBuf = arg_imagBuf;
    _ = &imagBuf;
    var bd = arg_bd;
    _ = &bd;
    var len = arg_len;
    _ = &len;
    var j: Int32 = undefined;
    _ = &j;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var temp3: Int32 = undefined;
    _ = &temp3;
    var temp4: Int32 = undefined;
    _ = &temp4;
    var temp5: Int32 = undefined;
    _ = &temp5;
    var temp6: Int32 = undefined;
    _ = &temp6;
    var accu1: i64 = 0;
    _ = &accu1;
    var accu2: i64 = 0;
    _ = &accu2;
    var accu3: i64 = 0;
    _ = &accu3;
    var accu4: i64 = 0;
    _ = &accu4;
    var accu5: i64 = 0;
    _ = &accu5;
    var temp_r12r: i64 = undefined;
    _ = &temp_r12r;
    var temp_r12i: i64 = undefined;
    _ = &temp_r12i;
    var temp_r22r: i64 = undefined;
    _ = &temp_r22r;
    var max: i64 = 0;
    _ = &max;
    temp1 = realBuf[@as(c_int, 0)][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp2 = imagBuf[@as(c_int, 0)][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp3 = realBuf[@bitCast(@as(isize, @intCast(@as(c_int, 0) - @as(c_int, 1))))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp4 = imagBuf[@bitCast(@as(isize, @intCast(@as(c_int, 0) - @as(c_int, 1))))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp5 = realBuf[@bitCast(@as(isize, @intCast(@as(c_int, 0) - @as(c_int, 2))))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp6 = imagBuf[@bitCast(@as(isize, @intCast(@as(c_int, 0) - @as(c_int, 2))))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp_r22r = fxp_mac64_Q31(0, temp5, temp5);
    temp_r22r = fxp_mac64_Q31(temp_r22r, temp6, temp6);
    temp_r12r = fxp_mac64_Q31(0, temp3, temp5);
    temp_r12r = fxp_mac64_Q31(temp_r12r, temp4, temp6);
    temp_r12i = -fxp_mac64_Q31(0, temp3, temp6);
    temp_r12i = fxp_mac64_Q31(temp_r12i, temp4, temp5);
    {
        j = 1;
        while (j < len) : (j += 1) {
            accu1 = fxp_mac64_Q31(accu1, temp3, temp3);
            accu1 = fxp_mac64_Q31(accu1, temp4, temp4);
            accu2 = fxp_mac64_Q31(accu2, temp1, temp3);
            accu2 = fxp_mac64_Q31(accu2, temp2, temp4);
            accu3 = fxp_mac64_Q31(accu3, temp2, temp3);
            accu3 = fxp_mac64_Q31(accu3, -temp1, temp4);
            accu4 = fxp_mac64_Q31(accu4, temp1, temp5);
            accu4 = fxp_mac64_Q31(accu4, temp2, temp6);
            accu5 = fxp_mac64_Q31(accu5, temp2, temp5);
            accu5 = fxp_mac64_Q31(accu5, -temp1, temp6);
            temp5 = temp3;
            temp6 = temp4;
            temp3 = temp1;
            temp4 = temp2;
            temp1 = realBuf[@bitCast(@as(isize, @intCast(j)))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
            temp2 = imagBuf[@bitCast(@as(isize, @intCast(j)))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
        }
    }
    temp_r22r += accu1;
    temp_r12r += accu2;
    temp_r12i += accu3;
    accu1 = fxp_mac64_Q31(accu1, temp3, temp3);
    accu1 = fxp_mac64_Q31(accu1, temp4, temp4);
    accu2 = fxp_mac64_Q31(accu2, temp1, temp3);
    accu2 = fxp_mac64_Q31(accu2, temp2, temp4);
    accu3 = fxp_mac64_Q31(accu3, temp2, temp3);
    accu3 = fxp_mac64_Q31(accu3, -temp1, temp4);
    accu4 = fxp_mac64_Q31(accu4, temp1, temp5);
    accu4 = fxp_mac64_Q31(accu4, temp2, temp6);
    accu5 = fxp_mac64_Q31(accu5, temp2, temp5);
    accu5 = fxp_mac64_Q31(accu5, -temp1, temp6);
    max |= accu5 ^ (accu5 >> @intCast(@as(i64, 63)));
    max |= accu4 ^ (accu4 >> @intCast(@as(i64, 63)));
    max |= accu3 ^ (accu3 >> @intCast(@as(i64, 63)));
    max |= accu2 ^ (accu2 >> @intCast(@as(i64, 63)));
    max |= accu1;
    max |= temp_r12r ^ (temp_r12r >> @intCast(@as(i64, 63)));
    max |= temp_r12i ^ (temp_r12i >> @intCast(@as(i64, 63)));
    max |= temp_r22r;
    if (max != 0) {
        temp1 = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, @truncate(max >> @intCast(@as(i64, 32)))))))));
        if (temp1 != 0) {
            temp1 = @as(c_int, 34) - pv_normalize(temp1);
            ac.*.r11r = @truncate(pv_shr(accu1, @as(i64, temp1)));
            ac.*.r01r = @truncate(pv_shr(accu2, @as(i64, temp1)));
            ac.*.r01i = @truncate(pv_shr(accu3, @as(i64, temp1)));
            ac.*.r02r = @truncate(pv_shr(accu4, @as(i64, temp1)));
            ac.*.r02i = @truncate(pv_shr(accu5, @as(i64, temp1)));
            ac.*.r12r = @truncate(pv_shr(temp_r12r, @as(i64, temp1)));
            ac.*.r12i = @truncate(pv_shr(temp_r12i, @as(i64, temp1)));
            ac.*.r22r = @truncate(pv_shr(temp_r22r, @as(i64, temp1)));
        } else {
            temp1 = pv_normalize(@bitCast(@as(c_uint, @truncate(pv_shr(@as(UInt32, @bitCast(@as(c_int, @truncate(max)))), @as(UInt32, 1)))))) - @as(c_int, 3);
            if (temp1 > @as(c_int, 0)) {
                ac.*.r11r = @truncate(pv_shl(accu1, @as(i64, temp1)));
                ac.*.r01r = @truncate(pv_shl(accu2, @as(i64, temp1)));
                ac.*.r01i = @truncate(pv_shl(accu3, @as(i64, temp1)));
                ac.*.r02r = @truncate(pv_shl(accu4, @as(i64, temp1)));
                ac.*.r02i = @truncate(pv_shl(accu5, @as(i64, temp1)));
                ac.*.r12r = @truncate(pv_shl(temp_r12r, @as(i64, temp1)));
                ac.*.r12i = @truncate(pv_shl(temp_r12i, @as(i64, temp1)));
                ac.*.r22r = @truncate(pv_shl(temp_r22r, @as(i64, temp1)));
            } else {
                temp1 = -temp1;
                ac.*.r11r = @truncate(pv_shr(accu1, @as(i64, temp1)));
                ac.*.r01r = @truncate(pv_shr(accu2, @as(i64, temp1)));
                ac.*.r01i = @truncate(pv_shr(accu3, @as(i64, temp1)));
                ac.*.r02r = @truncate(pv_shr(accu4, @as(i64, temp1)));
                ac.*.r02i = @truncate(pv_shr(accu5, @as(i64, temp1)));
                ac.*.r12r = @truncate(pv_shr(temp_r12r, @as(i64, temp1)));
                ac.*.r12i = @truncate(pv_shr(temp_r12i, @as(i64, temp1)));
                ac.*.r22r = @truncate(pv_shr(temp_r22r, @as(i64, temp1)));
            }
        }
        ac.*.det = fxp_mul32_Q29(ac.*.r12i, ac.*.r12i);
        ac.*.det = fxp_mac32_Q29(ac.*.r12r, ac.*.r12r, ac.*.det);
        ac.*.det -= ac.*.det >> @intCast(@as(c_int, 20));
        ac.*.det = -fxp_msu32_Q29(ac.*.r11r, ac.*.r22r, ac.*.det);
    } else {
        _ = memset(@ptrCast(@alignCast(ac)), 0, @sizeOf(struct_ACORR_COEFS));
    }
}

pub fn calc_auto_corr_LC(arg_ac: [*c]struct_ACORR_COEFS, arg_realBuf: [*c][32]Int32, arg_bd: Int32, arg_len: Int32) void {
    var ac = arg_ac;
    _ = &ac;
    var realBuf = arg_realBuf;
    _ = &realBuf;
    var bd = arg_bd;
    _ = &bd;
    var len = arg_len;
    _ = &len;
    var j: Int32 = undefined;
    _ = &j;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp3: Int32 = undefined;
    _ = &temp3;
    var temp5: Int32 = undefined;
    _ = &temp5;
    var temp_r01r: i64 = undefined;
    _ = &temp_r01r;
    var temp_r02r: i64 = undefined;
    _ = &temp_r02r;
    var temp_r11r: i64 = undefined;
    _ = &temp_r11r;
    var temp_r12r: i64 = undefined;
    _ = &temp_r12r;
    var temp_r22r: i64 = undefined;
    _ = &temp_r22r;
    var max: i64 = 0;
    _ = &max;
    temp1 = realBuf[@as(c_int, 0)][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp3 = realBuf[@bitCast(@as(isize, @intCast(-@as(c_int, 1))))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp5 = realBuf[@bitCast(@as(isize, @intCast(-@as(c_int, 2))))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
    temp_r11r = fxp_mac64_Q31(0, temp3, temp3);
    temp_r12r = fxp_mac64_Q31(0, temp3, temp5);
    temp_r22r = fxp_mac64_Q31(0, temp5, temp5);
    temp_r01r = 0;
    temp_r02r = 0;
    {
        j = 1;
        while (j < len) : (j += 1) {
            temp_r01r = fxp_mac64_Q31(temp_r01r, temp1, temp3);
            temp_r02r = fxp_mac64_Q31(temp_r02r, temp1, temp5);
            temp_r11r = fxp_mac64_Q31(temp_r11r, temp1, temp1);
            temp5 = temp3;
            temp3 = temp1;
            temp1 = realBuf[@bitCast(@as(isize, @intCast(j)))][@bitCast(@as(isize, @intCast(bd)))] >> @intCast(@as(c_int, 2));
        }
    }
    temp_r22r += temp_r11r;
    temp_r12r += temp_r01r;
    temp_r22r = fxp_mac64_Q31(temp_r22r, -temp3, temp3);
    temp_r01r = fxp_mac64_Q31(temp_r01r, temp1, temp3);
    temp_r02r = fxp_mac64_Q31(temp_r02r, temp1, temp5);
    max |= temp_r01r ^ (temp_r01r >> @intCast(@as(i64, 63)));
    max |= temp_r02r ^ (temp_r02r >> @intCast(@as(i64, 63)));
    max |= temp_r11r;
    max |= temp_r12r ^ (temp_r12r >> @intCast(@as(i64, 63)));
    max |= temp_r22r;
    if (max != 0) {
        temp1 = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, @truncate(max >> @intCast(@as(i64, 32)))))))));
        if (temp1 != 0) {
            temp3 = @as(c_int, 33) - pv_normalize(temp1);
            ac.*.r01r = @truncate(pv_shr(temp_r01r, @as(i64, temp3)));
            ac.*.r02r = @truncate(pv_shr(temp_r02r, @as(i64, temp3)));
            ac.*.r11r = @truncate(pv_shr(temp_r11r, @as(i64, temp3)));
            ac.*.r12r = @truncate(pv_shr(temp_r12r, @as(i64, temp3)));
            ac.*.r22r = @truncate(pv_shr(temp_r22r, @as(i64, temp3)));
        } else {
            temp3 = pv_normalize(@bitCast(@as(c_uint, @truncate(pv_shr(@as(UInt32, @bitCast(@as(c_int, @truncate(max)))), @as(UInt32, 1)))))) - @as(c_int, 2);
            if (temp3 > @as(c_int, 0)) {
                ac.*.r01r = @truncate(pv_shl(temp_r01r, @as(i64, temp3)));
                ac.*.r02r = @truncate(pv_shl(temp_r02r, @as(i64, temp3)));
                ac.*.r11r = @truncate(pv_shl(temp_r11r, @as(i64, temp3)));
                ac.*.r12r = @truncate(pv_shl(temp_r12r, @as(i64, temp3)));
                ac.*.r22r = @truncate(pv_shl(temp_r22r, @as(i64, temp3)));
            } else {
                temp3 = -temp3;
                ac.*.r01r = @truncate(pv_shr(temp_r01r, @as(i64, temp3)));
                ac.*.r02r = @truncate(pv_shr(temp_r02r, @as(i64, temp3)));
                ac.*.r11r = @truncate(pv_shr(temp_r11r, @as(i64, temp3)));
                ac.*.r12r = @truncate(pv_shr(temp_r12r, @as(i64, temp3)));
                ac.*.r22r = @truncate(pv_shr(temp_r22r, @as(i64, temp3)));
            }
        }
        ac.*.det = fxp_mul32_Q30(ac.*.r12r, ac.*.r12r);
        ac.*.det -= ac.*.det >> @intCast(@as(c_int, 20));
        ac.*.det = fxp_mul32_Q30(ac.*.r11r, ac.*.r22r) - ac.*.det;
    } else {
        _ = memset(@ptrCast(@alignCast(ac)), 0, @sizeOf(struct_ACORR_COEFS));
    }
}

pub fn calc_gsfb_table(arg_pFrameInfo: [*c]FrameInfo, arg_group: [*c]Int) void {
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var group = arg_group;
    _ = &group;
    var group_idx: Int = undefined;
    _ = &group_idx;
    var offset: Int = undefined;
    _ = &offset;
    var pFrameSfbTop: [*c]Int = undefined;
    _ = &pFrameSfbTop;
    var pSfbWidth128: [*c]Int = undefined;
    _ = &pSfbWidth128;
    var sfb: Int = undefined;
    _ = &sfb;
    var nsfb: Int = undefined;
    _ = &nsfb;
    var len: Int = undefined;
    _ = &len;
    var ngroups: Int = undefined;
    _ = &ngroups;
    _ = memset(@ptrCast(@alignCast(@as([*c]Int, @ptrCast(@alignCast(&pFrameInfo.*.frame_sfb_top))))), 0, @as(c_ulong, MAXBANDS) *% @sizeOf(@TypeOf(pFrameInfo.*.frame_sfb_top[@as(c_int, 0)])));
    offset = 0;
    ngroups = 0;
    while (true) {
        pFrameInfo.*.group_len[@bitCast(@as(isize, @intCast(ngroups)))] = group[@bitCast(@as(isize, @intCast(ngroups)))] - offset;
        offset = group[@bitCast(@as(isize, @intCast(ngroups)))];
        ngroups += 1;
        if (!(offset < @as(c_int, 8))) break;
    }
    pFrameInfo.*.num_groups = ngroups;
    pFrameSfbTop = @ptrCast(@alignCast(&pFrameInfo.*.frame_sfb_top));
    offset = 0;
    {
        group_idx = 0;
        while (group_idx < ngroups) : (group_idx += 1) {
            len = pFrameInfo.*.group_len[@bitCast(@as(isize, @intCast(group_idx)))];
            nsfb = pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(group_idx)))];
            pSfbWidth128 = pFrameInfo.*.sfb_width_128;
            {
                sfb = nsfb;
