pub fn calc_sbr_envelope(arg_frameData: [*c]SBR_FRAME_DATA, arg_aBufR: [*c]Int32, arg_aBufI: [*c]Int32, arg_freqBandTable1: [*c][59]Int, arg_nSfb: [*c]const Int32, arg_freqBandTable2: [*c]Int32, arg_nNBands: Int32, arg_reset: Int32, arg_degreeAlias: [*c]Int32, arg_harm_index: [*c]Int32, arg_phase_index: [*c]Int32, arg_hFp: [*c]Int32, arg_sUp: [*c]Int32, arg_limSbc: [*c][13]Int32, arg_gateMode: [*c]Int32, arg_fBuf_man: [*c][*c]Int32, arg_fBuf_exp: [*c][*c]Int32, arg_fBufN_man: [*c][*c]Int32, arg_fBufN_exp: [*c][*c]Int32, arg_scratch_mem: [*c][64]Int32, arg_Patch: struct_PATCH, arg_sqrt_cache: [*c][4]Int32, arg_LC_flag: Int32) void {
