    _ = &aBufR;
    var aBufI = arg_aBufI;
    _ = &aBufI;
    var freqBandTable1 = arg_freqBandTable1;
    _ = &freqBandTable1;
    var nSfb = arg_nSfb;
    _ = &nSfb;
    var freqBandTable2 = arg_freqBandTable2;
    _ = &freqBandTable2;
    var nNBands = arg_nNBands;
    _ = &nNBands;
    var reset = arg_reset;
    _ = &reset;
    var degreeAlias = arg_degreeAlias;
    _ = &degreeAlias;
    var harm_index = arg_harm_index;
    _ = &harm_index;
    var phase_index = arg_phase_index;
    _ = &phase_index;
    var hFp = arg_hFp;
    _ = &hFp;
    var sUp = arg_sUp;
    _ = &sUp;
    var limSbc = arg_limSbc;
    _ = &limSbc;
    var gateMode = arg_gateMode;
    _ = &gateMode;
    var fBuf_man = arg_fBuf_man;
    _ = &fBuf_man;
    var fBuf_exp = arg_fBuf_exp;
    _ = &fBuf_exp;
    var fBufN_man = arg_fBufN_man;
    _ = &fBufN_man;
    var fBufN_exp = arg_fBufN_exp;
    _ = &fBufN_exp;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var Patch = arg_Patch;
    _ = &Patch;
    var sqrt_cache = arg_sqrt_cache;
    _ = &sqrt_cache;
    var LC_flag = arg_LC_flag;
    _ = &LC_flag;
    var c: Int32 = undefined;
    _ = &c;
    var li: Int32 = undefined;
    _ = &li;
    var ui: Int32 = undefined;
    _ = &ui;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var k: Int32 = 0;
    _ = &k;
    var l: Int32 = undefined;
    _ = &l;
    var m: Int = 0;
    _ = &m;
    var kk: Int = 0;
    _ = &kk;
    var o: Int = undefined;
    _ = &o;
    var next: Int = -@as(c_int, 1);
    _ = &next;
    var ui2: Int32 = undefined;
    _ = &ui2;
    var flag: Int = undefined;
    _ = &flag;
    var noNoiseFlag: Int = undefined;
    _ = &noNoiseFlag;
    var ptr: [*c]Int = undefined;
    _ = &ptr;
    var nrg: UInt32 = 0;
    _ = &nrg;
    var nrg_exp: Int32 = 0;
    _ = &nrg_exp;
    var quotient: struct_intg_div = undefined;
    _ = &quotient;
    var root_sq: struct_intg_sqrt = undefined;
    _ = &root_sq;
    var aux1: Int32 = undefined;
    _ = &aux1;
    var nL_man: [*c]Int32 = @ptrCast(@alignCast(&frameData.*.sbrNoiseFloorLevel_man));
    _ = &nL_man;
    var nL_exp: [*c]Int32 = @ptrCast(@alignCast(&frameData.*.sbrNoiseFloorLevel_exp));
    _ = &nL_exp;
    var sfb_nrg_man: [*c]Int32 = @ptrCast(@alignCast(&frameData.*.iEnvelope_man));
    _ = &sfb_nrg_man;
    var sfb_nrg_exp: [*c]Int32 = @ptrCast(@alignCast(&frameData.*.iEnvelope_exp));
    _ = &sfb_nrg_exp;
    var tmp_q1: Int32 = undefined;
    _ = &tmp_q1;
    var tmp_q2: Int32 = undefined;
    _ = &tmp_q2;
    var g_max_man: Int32 = undefined;
    _ = &g_max_man;
    var g_max_exp: Int32 = undefined;
    _ = &g_max_exp;
    var p_ref_man: Int32 = undefined;
    _ = &p_ref_man;
    var p_ref_exp: Int32 = undefined;
    _ = &p_ref_exp;
    var p_est_man: Int32 = undefined;
    _ = &p_est_man;
    var p_est_exp: Int32 = undefined;
    _ = &p_est_exp;
    var p_adj_man: Int32 = undefined;
    _ = &p_adj_man;
    var p_adj_exp: Int32 = undefined;
    _ = &p_adj_exp;
    var avg_gain: Int32 = undefined;
    _ = &avg_gain;
    var boost_gain_q: Int32 = undefined;
    _ = &boost_gain_q;
    var band_nrg_tone_detector: Int32 = undefined;
    _ = &band_nrg_tone_detector;
    var nrg_est_man: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 0)]));
    _ = &nrg_est_man;
    var nrg_est_exp: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 1)]));
    _ = &nrg_est_exp;
    var nrg_ref_man: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 2)]));
    _ = &nrg_ref_man;
    var nrg_ref_exp: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 3)]));
    _ = &nrg_ref_exp;
    var nrg_gain_man: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 4)]));
    _ = &nrg_gain_man;
    var nrg_gain_exp: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 5)]));
    _ = &nrg_gain_exp;
    var noise_level_man: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 6)]));
    _ = &noise_level_man;
    var noise_level_exp: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 7)]));
    _ = &noise_level_exp;
    var nrg_tone_man: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 8)]));
    _ = &nrg_tone_man;
    var nrg_tone_exp: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 9)]));
    _ = &nrg_tone_exp;
    var hF: [*c]Int32 = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 10)]));
    _ = &hF;
    var frame_info: [*c]const Int32 = @ptrCast(@alignCast(&frameData.*.frameInfo));
    _ = &frame_info;
    var int_mode: Int32 = frameData.*.sbr_header.interpolFreq;
    _ = &int_mode;
    var dontUseTheseGainValues: [64]Int32 = undefined;
    _ = &dontUseTheseGainValues;
    var n: Int32 = undefined;
    _ = &n;
    var smooth_length: Int32 = undefined;
    _ = &smooth_length;
    var smoothingLength: Int32 = frameData.*.sbr_header.smoothingLength;
    _ = &smoothingLength;
    var maxSmoothLength: Int32 = smoothLengths[@as(c_int, 0)];
    _ = &maxSmoothLength;
    var limiterBand: Int32 = frameData.*.sbr_header.limiterBands;
    _ = &limiterBand;
    var limiterGains: Int32 = frameData.*.sbr_header.limiterGains;
    _ = &limiterGains;
    var addHarmonics: [*c]Int32 = @ptrCast(@alignCast(&frameData.*.addHarmonics));
    _ = &addHarmonics;
    var lowSubband: Int32 = freqBandTable1[@as(c_int, 0)][@as(c_int, 0)];
    _ = &lowSubband;
    var noSubbands: Int32 = freqBandTable1[@as(c_int, 0)][@bitCast(@as(isize, @intCast(nSfb[@as(c_int, 0)])))] - lowSubband;
    _ = &noSubbands;
    var nEnv: Int32 = frame_info[@as(c_int, 0)];
    _ = &nEnv;
    var sEnv: Int32 = frame_info[@bitCast(@as(isize, @intCast((nEnv + @as(c_int, 1)) << @intCast(@as(c_int, 1)))))];
    _ = &sEnv;
    noSubbands = (noSubbands >> @intCast(@as(c_int, 31))) ^ noSubbands;
    if (noSubbands > @as(c_int, 64)) {
        noSubbands = 64;
    }
    if (reset != 0) {
        sUp.* = 1;
        phase_index.* = 0;
        sbr_create_limiter_bands(limSbc, gateMode, @ptrCast(@alignCast(&freqBandTable1[@as(c_int, 0)])), Patch, nSfb[@as(c_int, 0)]);
    }
    _ = memset(@ptrCast(@alignCast(hF)), 0, @sizeOf(@TypeOf(hF.*)) << @intCast(@as(c_ulong, 6)));
    ptr = @ptrCast(@alignCast(&freqBandTable1[@as(c_int, 1)]));
    l = (blk: {
        const ref = &ptr;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    {
        i = nSfb[@as(c_int, 1)];
        while (i != @as(c_int, 0)) : (i -= 1) {
            k = (blk: {
                const ref = &ptr;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            j = ((k + l) >> @intCast(@as(c_int, 1))) - lowSubband;
            l = k;
            hF[@bitCast(@as(isize, @intCast(j)))] = (blk: {
                const ref = &addHarmonics;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
        }
    }
    {
        i = 0;
        while (i < nEnv) : (i += 1) {
            if (frame_info[@bitCast(@as(isize, @intCast(@as(c_int, 1) + i)))] == frame_info[@bitCast(@as(isize, @intCast(((nEnv << @intCast(@as(c_int, 1))) + @as(c_int, 4)) + kk)))]) {
                kk += 1;
                next += 1;
            }
            noNoiseFlag = if ((i == sEnv) or (i == frameData.*.prevEnvIsShort)) @as(c_int, 1) else @as(c_int, 0);
            smooth_length = if (noNoiseFlag != 0) @as(c_int, 0) else smoothLengths[@bitCast(@as(isize, @intCast(smoothingLength)))];
            c = 0;
            o = 0;
            band_nrg_tone_detector = 0;
            var kkkk: Int = freqBandTable1[@bitCast(@as(isize, @intCast(frame_info[@bitCast(@as(isize, @intCast((nEnv + @as(c_int, 2)) + i)))])))][@as(c_int, 0)];
            _ = &kkkk;
            {
                j = 0;
                while (j < nSfb[@bitCast(@as(isize, @intCast(frame_info[@bitCast(@as(isize, @intCast((nEnv + @as(c_int, 2)) + i)))])))]) : (j += 1) {
                    li = freqBandTable1[@bitCast(@as(isize, @intCast(frame_info[@bitCast(@as(isize, @intCast((nEnv + @as(c_int, 2)) + i)))])))][@bitCast(@as(isize, @intCast(j)))];
                    ui = freqBandTable1[@bitCast(@as(isize, @intCast(frame_info[@bitCast(@as(isize, @intCast((nEnv + @as(c_int, 2)) + i)))])))][@bitCast(@as(isize, @intCast(j + @as(c_int, 1))))];
                    flag = 0;
                    {
                        k = li;
                        while (k < ui) : (k += 1) {
                            ui2 = frame_info[@bitCast(@as(isize, @intCast(@as(c_int, 1) + i)))] << @intCast(@as(c_int, 1));
                            if (LC_flag == @as(c_int, 1)) {
                                energy_estimation_LC(aBufR, nrg_est_man, nrg_est_exp, frame_info, i, k - kkkk, c, ui2);
                            } else {
                                energy_estimation(aBufR, aBufI, nrg_est_man, nrg_est_exp, frame_info, i, k - kkkk, c, ui2);
                            }
                            flag = if ((hF[@bitCast(@as(isize, @intCast(c)))] != 0) and ((i >= sEnv) or (hFp[@bitCast(@as(isize, @intCast(c + lowSubband)))] != 0))) @as(c_int, 1) else flag;
                            c += 1;
                        }
                    }
                    ui2 = freqBandTable2[@bitCast(@as(isize, @intCast(o + @as(c_int, 1))))];
                    if (!(int_mode != 0)) {
                        tmp_q1 = -@as(c_int, 100);
                        {
                            k = c - (ui - li);
                            while (k < c) : (k += 1) {
                                if (tmp_q1 < nrg_est_exp[@bitCast(@as(isize, @intCast(k)))]) {
                                    tmp_q1 = nrg_est_exp[@bitCast(@as(isize, @intCast(k)))];
                                }
                            }
                        }
                        nrg = 0;
                        {
                            k = c - (ui - li);
                            while (k < c) : (k += 1) {
                                nrg +%= @bitCast(@as(c_int, pv_shr(nrg_est_man[@bitCast(@as(isize, @intCast(k)))], tmp_q1 - nrg_est_exp[@bitCast(@as(isize, @intCast(k)))])));
                            }
                        }
                        nrg /= @bitCast(@as(c_int, ui - li));
                        nrg_exp = tmp_q1;
                    }
                    c -= ui - li;
                    {
                        k = 0;
                        while (k < (ui - li)) : (k += 1) {
                            o = if ((k + li) >= ui2) o + @as(c_int, 1) else o;
                            ui2 = freqBandTable2[@bitCast(@as(isize, @intCast(o + @as(c_int, 1))))];
                            if (!(int_mode != 0)) {
                                nrg_est_man[@bitCast(@as(isize, @intCast(c)))] = @bitCast(@as(c_uint, @truncate(nrg)));
                                nrg_est_exp[@bitCast(@as(isize, @intCast(c)))] = nrg_exp;
                            }
                            if (LC_flag == @as(c_int, 1)) {
                                nrg_est_exp[@bitCast(@as(isize, @intCast(c)))] += 1;
                                if (flag != 0) {
                                    dontUseTheseGainValues[@bitCast(@as(isize, @intCast((k + li) - lowSubband)))] = 1;
                                } else {
                                    dontUseTheseGainValues[@bitCast(@as(isize, @intCast((k + li) - lowSubband)))] = 0;
                                }
                            }
                            nrg_ref_man[@bitCast(@as(isize, @intCast(c)))] = sfb_nrg_man[@bitCast(@as(isize, @intCast(m)))];
                            nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] = sfb_nrg_exp[@bitCast(@as(isize, @intCast(m)))];
                            aux1 = (next * nNBands) + o;
                            tmp_q1 = nL_exp[@bitCast(@as(isize, @intCast(aux1)))];
                            if (tmp_q1 >= @as(c_int, 0)) {
                                pv_div(nL_man[@bitCast(@as(isize, @intCast(aux1)))], nL_man[@bitCast(@as(isize, @intCast(aux1)))] + (pv_shr(@as(c_int, 1073741823), tmp_q1)), &quotient);
                            } else {
                                tmp_q1 = pv_shr(nL_man[@bitCast(@as(isize, @intCast(aux1)))], -tmp_q1);
                                pv_div(tmp_q1, tmp_q1 + @as(c_int, 1073741823), &quotient);
                            }
                            tmp_q1 = fxp_mul32_Q30(pv_shr(quotient.quotient, quotient.shift_factor), nrg_ref_man[@bitCast(@as(isize, @intCast(c)))]);
                            if (flag != 0) {
                                pv_div(tmp_q1, nrg_est_man[@bitCast(@as(isize, @intCast(c)))] + @as(c_int, 1), &quotient);
                                tmp_q2 = ((nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] - nrg_est_exp[@bitCast(@as(isize, @intCast(c)))]) - quotient.shift_factor) - @as(c_int, 30);
                                pv_sqrt(quotient.quotient, tmp_q2, &root_sq, @ptrCast(@alignCast(&sqrt_cache[@as(c_int, 1)])));
                                nrg_gain_man[@bitCast(@as(isize, @intCast(c)))] = root_sq.root;
                                nrg_gain_exp[@bitCast(@as(isize, @intCast(c)))] = root_sq.shift_factor;
                                if ((hF[@bitCast(@as(isize, @intCast(c)))] != 0) and ((i >= sEnv) or (hFp[@bitCast(@as(isize, @intCast(c + lowSubband)))] != 0))) {
                                    tmp_q2 = nL_exp[@bitCast(@as(isize, @intCast(aux1)))];
                                    if (tmp_q2 >= @as(c_int, 0)) {
                                        pv_div(nrg_ref_man[@bitCast(@as(isize, @intCast(c)))], nL_man[@bitCast(@as(isize, @intCast(aux1)))] + (pv_shr(@as(c_int, 1073741823), tmp_q2)), &quotient);
                                    } else {
                                        tmp_q2 = pv_shr(nL_man[@bitCast(@as(isize, @intCast(aux1)))], -tmp_q2);
                                        pv_div(nrg_ref_man[@bitCast(@as(isize, @intCast(c)))], tmp_q2 + @as(c_int, 1073741823), &quotient);
                                        tmp_q2 = 0;
                                    }
                                    tmp_q2 = (nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] - tmp_q2) - quotient.shift_factor;
                                    pv_sqrt(quotient.quotient, tmp_q2, &root_sq, @ptrCast(@alignCast(&sqrt_cache[@as(c_int, 2)])));
                                    nrg_tone_man[@bitCast(@as(isize, @intCast(c)))] = root_sq.root;
                                    nrg_tone_exp[@bitCast(@as(isize, @intCast(c)))] = root_sq.shift_factor;
                                } else {
                                    nrg_tone_man[@bitCast(@as(isize, @intCast(c)))] = 0;
                                    nrg_tone_exp[@bitCast(@as(isize, @intCast(c)))] = 0;
                                }
                            } else {
                                if (noNoiseFlag != 0) {
                                    pv_div(nrg_ref_man[@bitCast(@as(isize, @intCast(c)))], nrg_est_man[@bitCast(@as(isize, @intCast(c)))] + @as(c_int, 1), &quotient);
                                    tmp_q2 = ((nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] - nrg_est_exp[@bitCast(@as(isize, @intCast(c)))]) - quotient.shift_factor) - @as(c_int, 30);
                                    pv_sqrt(quotient.quotient, tmp_q2, &root_sq, @ptrCast(@alignCast(&sqrt_cache[@as(c_int, 3)])));
                                    nrg_gain_man[@bitCast(@as(isize, @intCast(c)))] = root_sq.root;
                                    nrg_gain_exp[@bitCast(@as(isize, @intCast(c)))] = root_sq.shift_factor;
                                } else {
                                    tmp_q2 = nL_exp[@bitCast(@as(isize, @intCast(aux1)))];
                                    if (nrg_est_man[@bitCast(@as(isize, @intCast(c)))] == @as(c_int, 0)) {
                                        tmp_q2 = 0;
                                    }
                                    if (tmp_q2 >= @as(c_int, 0)) {
                                        tmp_q2 = fxp_mul32_Q30(nrg_est_man[@bitCast(@as(isize, @intCast(c)))] + @as(c_int, 1), nL_man[@bitCast(@as(isize, @intCast(aux1)))] + (pv_shr(@as(c_int, 1073741823), tmp_q2)));
                                        pv_div(nrg_ref_man[@bitCast(@as(isize, @intCast(c)))], tmp_q2, &quotient);
                                        tmp_q2 = ((nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] - quotient.shift_factor) - @as(c_int, 30)) - nL_exp[@bitCast(@as(isize, @intCast(aux1)))];
                                        if (nrg_est_man[@bitCast(@as(isize, @intCast(c)))] != 0) {
                                            tmp_q2 -= nrg_est_exp[@bitCast(@as(isize, @intCast(c)))];
                                        }
                                        tmp_q2 = (((nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] - nrg_est_exp[@bitCast(@as(isize, @intCast(c)))]) - quotient.shift_factor) - @as(c_int, 30)) - nL_exp[@bitCast(@as(isize, @intCast(aux1)))];
                                    } else {
                                        if (tmp_q2 > -@as(c_int, 10)) {
                                            tmp_q2 = pv_shr(nL_man[@bitCast(@as(isize, @intCast(aux1)))], -tmp_q2);
                                            tmp_q2 = fxp_mul32_Q30(nrg_est_man[@bitCast(@as(isize, @intCast(c)))] + @as(c_int, 1), tmp_q2 + @as(c_int, 1073741823));
                                        } else {
                                            tmp_q2 = nrg_est_man[@bitCast(@as(isize, @intCast(c)))] + @as(c_int, 1);
                                        }
                                        pv_div(nrg_ref_man[@bitCast(@as(isize, @intCast(c)))], tmp_q2, &quotient);
                                        tmp_q2 = (nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))] - quotient.shift_factor) - @as(c_int, 30);
                                        if (nrg_est_man[@bitCast(@as(isize, @intCast(c)))] != 0) {
                                            tmp_q2 -= nrg_est_exp[@bitCast(@as(isize, @intCast(c)))];
                                        }
                                    }
                                    pv_sqrt(quotient.quotient, tmp_q2, &root_sq, @ptrCast(@alignCast(&sqrt_cache[@as(c_int, 4)])));
                                    nrg_gain_man[@bitCast(@as(isize, @intCast(c)))] = root_sq.root;
                                    nrg_gain_exp[@bitCast(@as(isize, @intCast(c)))] = root_sq.shift_factor;
                                }
                                nrg_tone_man[@bitCast(@as(isize, @intCast(c)))] = 0;
                                nrg_tone_exp[@bitCast(@as(isize, @intCast(c)))] = -@as(c_int, 100);
                            }
                            band_nrg_tone_detector |= nrg_tone_man[@bitCast(@as(isize, @intCast(c)))];
                            pv_sqrt(tmp_q1, nrg_ref_exp[@bitCast(@as(isize, @intCast(c)))], &root_sq, @ptrCast(@alignCast(&sqrt_cache[@as(c_int, 5)])));
                            noise_level_man[@bitCast(@as(isize, @intCast(c)))] = root_sq.root;
                            noise_level_exp[@bitCast(@as(isize, @intCast(c)))] = root_sq.shift_factor;
                            c += 1;
                        }
                    }
                    m += 1;
                }
            }
            {
                c = 0;
                while (c < gateMode[@bitCast(@as(isize, @intCast(limiterBand)))]) : (c += 1) {
                    p_ref_man = 0;
                    p_est_man = 0;
                    p_ref_exp = -@as(c_int, 100);
                    p_est_exp = -@as(c_int, 100);
                    {
                        k = limSbc[@bitCast(@as(isize, @intCast(limiterBand)))][@bitCast(@as(isize, @intCast(c)))];
                        while (k < limSbc[@bitCast(@as(isize, @intCast(limiterBand)))][@bitCast(@as(isize, @intCast(c + @as(c_int, 1))))]) : (k += 1) {
                            if (p_ref_exp < nrg_ref_exp[@bitCast(@as(isize, @intCast(k)))]) {
                                p_ref_exp = nrg_ref_exp[@bitCast(@as(isize, @intCast(k)))];
                            }
                            if (p_est_exp < nrg_est_exp[@bitCast(@as(isize, @intCast(k)))]) {
                                p_est_exp = nrg_est_exp[@bitCast(@as(isize, @intCast(k)))];
                            }
                        }
                    }
                    k -= limSbc[@bitCast(@as(isize, @intCast(limiterBand)))][@bitCast(@as(isize, @intCast(c)))];
                    while (k != @as(c_int, 0)) {
                        k >>= @intCast(@as(c_int, 1));
                        p_ref_exp += 1;
                    }
                    {
                        k = limSbc[@bitCast(@as(isize, @intCast(limiterBand)))][@bitCast(@as(isize, @intCast(c)))];
