            i += 1;
            bMask >>= @intCast(@as(UInt32, 1));
        }) {
            var flag: UInt16 = @bitCast(@as(c_short, @truncate(if ((@as(c_int, hCrcBuf.*.crcState) & @as(c_int, hCrcBuf.*.crcMask)) != 0) @as(c_int, 1) else @as(c_int, 0))));
            _ = &flag;
            var flag1: UInt16 = @bitCast(@as(c_short, @truncate(if ((bMask & bValue) != 0) @as(c_int, 1) else @as(c_int, 0))));
            _ = &flag1;
            {
                const ref = &flag;
                ref.* = @bitCast(@as(c_short, @truncate(@as(c_int, ref.*) ^ @as(c_int, flag1))));
            }
            {
                const ref = &hCrcBuf.*.crcState;
                ref.* = @bitCast(@as(c_short, @truncate(@as(c_int, ref.*) << @intCast(@as(c_int, 1)))));
            }
            if (@as(c_int, flag) != 0) {
                {
                    const ref = &hCrcBuf.*.crcState;
                    ref.* = @bitCast(@as(c_short, @truncate(@as(c_int, ref.*) ^ @as(c_int, hCrcBuf.*.crcPoly))));
                }
            }
        }
    }
}

