    if ((cw >> @intCast(@as(c_int, 18))) == @as(c_int, 0)) {
        pInputStream.*.usedBits -%= @bitCast(@as(c_int, @as(c_int, 19) - @as(c_int, 1)));
        return 60;
    } else if ((cw >> @intCast(@as(c_int, 13))) <= @as(c_int, 59)) {
        tab = (cw >> @intCast(@as(c_int, 13))) - @as(c_int, 32);
    } else if ((cw >> @intCast(@as(c_int, 10))) <= @as(c_int, 505)) {
        tab = ((cw >> @intCast(@as(c_int, 10))) - @as(c_int, 480)) + @as(c_int, 28);
    } else if ((cw >> @intCast(@as(c_int, 7))) <= @as(c_int, 4089)) {
        tab = ((cw >> @intCast(@as(c_int, 7))) - @as(c_int, 4048)) + @as(c_int, 54);
    } else if ((cw >> @intCast(@as(c_int, 5))) <= @as(c_int, 16377)) {
        tab = ((cw >> @intCast(@as(c_int, 5))) - @as(c_int, 16360)) + @as(c_int, 96);
    } else if ((cw >> @intCast(@as(c_int, 3))) <= @as(c_int, 65526)) {
        tab = ((cw >> @intCast(@as(c_int, 3))) - @as(c_int, 65512)) + @as(c_int, 114);
    } else if ((cw >> @intCast(@as(c_int, 1))) <= @as(c_int, 262120)) {
        tab = ((cw >> @intCast(@as(c_int, 1))) - @as(c_int, 262108)) + @as(c_int, 129);
    } else {
        tab = (cw - @as(c_int, 524242)) + @as(c_int, 142);
    }
    tab = @bitCast(@as(c_uint, @truncate((@as([*c]const UInt32, @ptrCast(@alignCast(&huff_tab_scl))) + @as(usize, @bitCast(@as(isize, @intCast(tab))))).*)));
    pInputStream.*.usedBits -%= @bitCast(@as(c_int, @as(c_int, 19) - (tab & @as(c_int, 65535))));
    return tab >> @intCast(@as(c_int, 16));
}

pub fn decode_noise_floorlevels(arg_hFrameData: [*c]SBR_FRAME_DATA) void {
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var env: Int32 = undefined;
    _ = &env;
    var i: Int32 = undefined;
    _ = &i;
    var frameInfo: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.frameInfo));
    _ = &frameInfo;
    var nNfb: Int32 = hFrameData.*.nNfb;
    _ = &nNfb;
    var domain_vec: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.domain_vec2));
    _ = &domain_vec;
    var sbrNoiseFloorLevel_man: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.sbrNoiseFloorLevel_man));
    _ = &sbrNoiseFloorLevel_man;
    var prevNoiseLevel_man: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.prevNoiseLevel_man));
    _ = &prevNoiseLevel_man;
    var nEnv: Int32 = frameInfo[@bitCast(@as(isize, @intCast((frameInfo[@as(c_int, 0)] << @intCast(@as(c_int, 1))) + @as(c_int, 3))))];
    _ = &nEnv;
    {
        env = 0;
        while (env < nEnv) : (env += 1) {
            if (domain_vec[@bitCast(@as(isize, @intCast(env)))] == @as(c_int, 0)) {
                prevNoiseLevel_man[@as(c_int, 0)] = (blk: {
                    const ref = &sbrNoiseFloorLevel_man;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                {
                    i = 1;
                    while (i < nNfb) : (i += 1) {
                        sbrNoiseFloorLevel_man.* += (sbrNoiseFloorLevel_man - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*;
                        prevNoiseLevel_man[@bitCast(@as(isize, @intCast(i)))] = (blk: {
                            const ref = &sbrNoiseFloorLevel_man;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).*;
                    }
                }
            } else {
                {
                    i = 0;
                    while (i < nNfb) : (i += 1) {
                        sbrNoiseFloorLevel_man.* += prevNoiseLevel_man[@bitCast(@as(isize, @intCast(i)))];
                        prevNoiseLevel_man[@bitCast(@as(isize, @intCast(i)))] = (blk: {
                            const ref = &sbrNoiseFloorLevel_man;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).*;
                    }
                }
            }
        }
    }
}

