pub fn deinterleave(arg_interleaved: [*c]Int16, arg_deinterleaved: [*c]Int16, arg_pFrameInfo: [*c]FrameInfo) void {
    var interleaved = arg_interleaved;
    _ = &interleaved;
    var deinterleaved = arg_deinterleaved;
    _ = &deinterleaved;
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var group: Int = undefined;
    _ = &group;
    var sfb: Int = undefined;
    _ = &sfb;
    var win: Int = undefined;
    _ = &win;
    var pGroup: [*c]Int16 = undefined;
    _ = &pGroup;
    var pWin: [*c]Int16 = undefined;
    _ = &pWin;
    var pStart: [*c]Int16 = undefined;
    _ = &pStart;
    var pInterleaved: [*c]Int16 = undefined;
    _ = &pInterleaved;
    var pDeinterleaved: [*c]Int16 = undefined;
    _ = &pDeinterleaved;
    var sfb_inc: Int = undefined;
    _ = &sfb_inc;
    var ngroups: Int = undefined;
    _ = &ngroups;
    var pGroupLen: [*c]Int = undefined;
    _ = &pGroupLen;
    var pSfbPerWin: [*c]Int = undefined;
    _ = &pSfbPerWin;
    var pSfbWidth: [*c]Int = undefined;
    _ = &pSfbWidth;
    pInterleaved = interleaved;
    pDeinterleaved = deinterleaved;
    pSfbPerWin = @ptrCast(@alignCast(&pFrameInfo.*.sfb_per_win));
    ngroups = pFrameInfo.*.num_groups;
    pGroupLen = @ptrCast(@alignCast(&pFrameInfo.*.group_len));
    pGroup = pDeinterleaved;
    {
        group = ngroups;
        while (group > @as(c_int, 0)) : (group -= 1) {
            pSfbWidth = pFrameInfo.*.sfb_width_128;
            sfb_inc = 0;
            pStart = pInterleaved;
            {
                sfb = pSfbPerWin[@bitCast(@as(isize, @intCast(ngroups - group)))];
                while (sfb > @as(c_int, 0)) : (sfb -= 1) {
                    pWin = pGroup;
                    {
                        win = pGroupLen[@bitCast(@as(isize, @intCast(ngroups - group)))];
                        while (win > @as(c_int, 0)) : (win -= 1) {
                            pDeinterleaved = pWin + @as(usize, @bitCast(@as(isize, @intCast(sfb_inc))));
                            _ = memcpy(@ptrCast(@alignCast(pDeinterleaved)), @ptrCast(@alignCast(pInterleaved)), @as(c_ulong, @bitCast(@as(c_long, pSfbWidth.*))) *% @sizeOf(@TypeOf(pInterleaved.*)));
                            pInterleaved += @as(usize, @bitCast(@as(isize, @intCast(pSfbWidth.*))));
                            pWin += @as(usize, @bitCast(@as(isize, @intCast(SN2))));
                        }
                    }
                    sfb_inc += (blk: {
                        const ref = &pSfbWidth;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                }
            }
            pGroup += @as(usize, @bitCast(@as(isize, @intCast(@divExact(@as(c_long, @bitCast(@intFromPtr(pInterleaved) -% @intFromPtr(pStart))), @sizeOf(Int16))))));
        }
    }
}

pub fn differential_Decoding(arg_enable: Int32, arg_aIndex: [*c]Int32, arg_aPrevFrameIndex: [*c]Int32, arg_DtDf: Int32, arg_nrElements: Int32, arg_stride: Int32, arg_minIdx: Int32, arg_maxIdx: Int32) void {
    var enable = arg_enable;
    _ = &enable;
    var aIndex = arg_aIndex;
    _ = &aIndex;
    var aPrevFrameIndex = arg_aPrevFrameIndex;
    _ = &aPrevFrameIndex;
    var DtDf = arg_DtDf;
    _ = &DtDf;
    var nrElements = arg_nrElements;
    _ = &nrElements;
    var stride = arg_stride;
    _ = &stride;
    var minIdx = arg_minIdx;
    _ = &minIdx;
    var maxIdx = arg_maxIdx;
    _ = &maxIdx;
    var i: Int32 = undefined;
    _ = &i;
    var ptr_aIndex: [*c]Int32 = undefined;
    _ = &ptr_aIndex;
    if (enable == @as(c_int, 1)) {
        ptr_aIndex = aIndex;
        if (DtDf == @as(c_int, 0)) {
            ptr_aIndex.* = limitMinMax(ptr_aIndex.*, minIdx, maxIdx);
            ptr_aIndex += 1;
            {
                i = 1;
                while (i < nrElements) : (i += 1) {
                    ptr_aIndex.* = limitMinMax(aIndex[@bitCast(@as(isize, @intCast(i - @as(c_int, 1))))] + ptr_aIndex.*, minIdx, maxIdx);
                    ptr_aIndex += 1;
                }
            }
        } else {
            if (stride == @as(c_int, 1)) {
                {
                    i = 0;
                    while (i < nrElements) : (i += 1) {
                        ptr_aIndex.* = limitMinMax(aPrevFrameIndex[@bitCast(@as(isize, @intCast(i)))] + ptr_aIndex.*, minIdx, maxIdx);
                        ptr_aIndex += 1;
                    }
                }
            } else {
                {
                    i = 0;
                    while (i < nrElements) : (i += 1) {
                        ptr_aIndex.* = limitMinMax(aPrevFrameIndex[@bitCast(@as(isize, @intCast(i << @intCast(@as(c_int, 1)))))] + ptr_aIndex.*, minIdx, maxIdx);
                        ptr_aIndex += 1;
                    }
                }
            }
        }
    } else {
        _ = memset(@ptrCast(@alignCast(aIndex)), 0, @as(c_ulong, @bitCast(@as(c_long, nrElements))) *% @sizeOf(@TypeOf(aIndex.*)));
    }
    if (stride == @as(c_int, 2)) {
        {
            i = (nrElements << @intCast(@as(c_int, 1))) - @as(c_int, 1);
            while (i > @as(c_int, 0)) : (i -= 1) {
                aIndex[@bitCast(@as(isize, @intCast(i)))] = aIndex[@bitCast(@as(isize, @intCast(i >> @intCast(@as(c_int, 1)))))];
            }
        }
    }
}

pub fn digit_reversal_swapping(arg_y: [*c]Int32, arg_x: [*c]Int32) void {
    var y = arg_y;
    _ = &y;
    var x = arg_x;
    _ = &x;
    var i: Int16 = undefined;
    _ = &i;
    var j: Int16 = undefined;
    _ = &j;
    var tmp: [2]Int32 = undefined;
    _ = &tmp;
    var pTable: [*c]const Int16 = undefined;
    _ = &pTable;
    pTable = @ptrCast(@alignCast(&digit_reverse_swap_256));
    {
        var k: Int = 120;
        _ = &k;
        while (k != @as(c_int, 0)) : (k -= 1) {
            i = (blk: {
                const ref = &pTable;
                const tmp_1 = ref.*;
                ref.* += 1;
                break :blk tmp_1;
            }).*;
            j = (blk: {
                const ref = &pTable;
                const tmp_1 = ref.*;
                ref.* += 1;
                break :blk tmp_1;
            }).*;
            tmp[@as(c_int, 0)] = y[@bitCast(@as(isize, @intCast(i)))];
            tmp[@as(c_int, 1)] = y[@bitCast(@as(isize, @intCast(@as(c_int, i) + @as(c_int, 1))))];
            y[@bitCast(@as(isize, @intCast(i)))] = y[@bitCast(@as(isize, @intCast(j)))];
            y[@bitCast(@as(isize, @intCast(@as(c_int, i) + @as(c_int, 1))))] = y[@bitCast(@as(isize, @intCast(@as(c_int, j) + @as(c_int, 1))))];
            y[@bitCast(@as(isize, @intCast(j)))] = tmp[@as(c_int, 0)];
            y[@bitCast(@as(isize, @intCast(@as(c_int, j) + @as(c_int, 1))))] = tmp[@as(c_int, 1)];
            tmp[@as(c_int, 0)] = x[@bitCast(@as(isize, @intCast(j)))];
            tmp[@as(c_int, 1)] = x[@bitCast(@as(isize, @intCast(@as(c_int, j) + @as(c_int, 1))))];
            x[@bitCast(@as(isize, @intCast(j)))] = x[@bitCast(@as(isize, @intCast(i)))];
            x[@bitCast(@as(isize, @intCast(@as(c_int, j) + @as(c_int, 1))))] = x[@bitCast(@as(isize, @intCast(@as(c_int, i) + @as(c_int, 1))))];
            x[@bitCast(@as(isize, @intCast(i)))] = tmp[@as(c_int, 0)];
            x[@bitCast(@as(isize, @intCast(@as(c_int, i) + @as(c_int, 1))))] = tmp[@as(c_int, 1)];
        }
    }
}

