pub fn energy_estimation(arg_aBufR: [*c]Int32, arg_aBufI: [*c]Int32, arg_nrg_est_man: [*c]Int32, arg_nrg_est_exp: [*c]Int32, arg_frame_info: [*c]const Int32, arg_i: Int32, arg_k: Int32, arg_c: Int32, arg_ui2: Int32) void {
    var aBufR = arg_aBufR;
