    _ = &nrg_est_man;
    var nrg_est_exp = arg_nrg_est_exp;
    _ = &nrg_est_exp;
    var frame_info = arg_frame_info;
    _ = &frame_info;
    var i = arg_i;
    _ = &i;
    var k = arg_k;
