    _ = &tmp1;
    var tmp2: Int32 = undefined;
    _ = &tmp2;
    aux1 = aBufR[@bitCast(@as(isize, @intCast((ui2 * @as(c_int, 48)) + k)))];
    aux2 = aBufI[@bitCast(@as(isize, @intCast((ui2 * @as(c_int, 48)) + k)))];
    {
        l = ui2 + @as(c_int, 1);
        while (l < (frame_info[@bitCast(@as(isize, @intCast(@as(c_int, 2) + i)))] << @intCast(@as(c_int, 1)))) : (l += 1) {
            nrg_h = fxp_mac64_Q31(nrg_h, aux1, aux1);
            nrg_h = fxp_mac64_Q31(nrg_h, aux2, aux2);
            aux1 = aBufR[@bitCast(@as(isize, @intCast((l * @as(c_int, 48)) + k)))];
            aux2 = aBufI[@bitCast(@as(isize, @intCast((l * @as(c_int, 48)) + k)))];
        }
    }
    nrg_h = fxp_mac64_Q31(nrg_h, aux1, aux1);
    nrg_h = fxp_mac64_Q31(nrg_h, aux2, aux2);
    if (nrg_h < @as(i64, 0)) {
        nrg_h = 2147483647;
    }
    if (nrg_h != 0) {
        aux1 = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, @truncate(nrg_h >> @intCast(@as(i64, 32)))))))));
        if (aux1 != 0) {
            aux2 = pv_normalize(aux1);
            if (aux2 != 0) {
                aux2 -= 1;
                nrg_h = (pv_shl(nrg_h, @as(i64, aux2))) >> @intCast(@as(i64, 33));
                tmp2 = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, @truncate(nrg_h)))))));
                nrg_est_exp[@bitCast(@as(isize, @intCast(c)))] = @as(c_int, 33) - aux2;
            } else {
                tmp2 = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, aux1 >> @intCast(@as(c_int, 1))))))));
                nrg_est_exp[@bitCast(@as(isize, @intCast(c)))] = 33;
            }
        } else {
            aux1 = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, @truncate(nrg_h >> @intCast(@as(i64, 1)))))))));
            aux2 = pv_normalize(aux1);
            tmp2 = pv_shl(aux1, aux2);
            nrg_est_exp[@bitCast(@as(isize, @intCast(c)))] = -aux2 + @as(c_int, 1);
        }
        tmp1 = l - ui2;
        aux2 = pow2[@bitCast(@as(isize, @intCast(tmp1)))];
        if (tmp1 == (tmp1 & -tmp1)) {
            nrg_est_man[@bitCast(@as(isize, @intCast(c)))] = pv_shr(tmp2, aux2);
