pub fn envelope_application(arg_aBufR: [*c]Int32, arg_aBufI: [*c]Int32, arg_nrg_gain_man: [*c]Int32, arg_nrg_gain_exp: [*c]Int32, arg_noise_level_man: [*c]Int32, arg_noise_level_exp: [*c]Int32, arg_nrg_tone_man: [*c]Int32, arg_nrg_tone_exp: [*c]Int32, arg_fBuf_man: [*c][*c]Int32, arg_fBuf_exp: [*c][*c]Int32, arg_fBufN_man: [*c][*c]Int32, arg_fBufN_exp: [*c][*c]Int32, arg_frame_info: [*c]const Int32, arg_harm_index: [*c]Int32, arg_phase_index: [*c]Int32, arg_i: Int32, arg_lowSubband: Int32, arg_noSubbands: Int32, arg_noNoiseFlag: Int32, arg_band_nrg_tone_detector: Int32, arg_maxSmoothLength: Int32, arg_smooth_length: Int32) void {
