                                    const ref = &n;
                                    const tmp = ref.*;
                                    ref.* += 1;
                                    break :blk tmp;
                                })))
                            ][@bitCast(@as(isize, @intCast(k)))]);
                            tmp_q1 = fxp_mul32_Q30(fBuf_man[@bitCast(@as(isize, @intCast(n)))][@bitCast(@as(isize, @intCast(k)))], @intFromFloat((@as(f32, 0.301503) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 0.301503) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
                            sb_gain_man += pv_shr(tmp_q1, sb_gain_exp - fBuf_exp[@bitCast(@as(isize, @intCast(n)))][@bitCast(@as(isize, @intCast(k)))]);
                            tmp_q1 = fxp_mul32_Q30(fBufN_man[@bitCast(@as(isize, @intCast(n)))][@bitCast(@as(isize, @intCast(k)))], @intFromFloat((@as(f32, 0.301503) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 0.301503) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
                            sb_noise_man += pv_shr(tmp_q1, sb_noise_exp - fBufN_exp[@bitCast(@as(isize, @intCast(n)))][@bitCast(@as(isize, @intCast(k)))]);
                        }
                        aux1 = ptrReal.*;
                        aux2 = ptrImag.*;
                        sb_gain_exp += 32;
                        aux1 = fxp_mul32_Q31(aux1, sb_gain_man);
                        aux2 = fxp_mul32_Q31(aux2, sb_gain_man);
                        if (sb_gain_exp < @as(c_int, 0)) {
                            if (sb_gain_exp > -@as(c_int, 32)) {
                                if (sb_gain_exp > -@as(c_int, 10)) {
                                    ptrReal.* = @import("std").math.shl(i32, aux1, @as(c_int, 10) + sb_gain_exp);
                                    ptrImag.* = @import("std").math.shl(i32, aux2, @as(c_int, 10) + sb_gain_exp);
                                } else {
                                    ptrReal.* = pv_shr(aux1, -sb_gain_exp - @as(c_int, 10));
                                    ptrImag.* = pv_shr(aux2, -sb_gain_exp - @as(c_int, 10));
                                }
                            }
                        } else {
                            ptrReal.* = @import("std").math.shl(i32, aux1, sb_gain_exp + @as(c_int, 10));
                            ptrImag.* = @import("std").math.shl(i32, aux2, sb_gain_exp + @as(c_int, 10));
                        }
                        phase_index.* = (phase_index.* + @as(c_int, 1)) & @as(c_int, 511);
                        if (!(noNoiseFlag != 0)) {
                            var tmp: Int32 = rPxx[@bitCast(@as(isize, @intCast(phase_index.*)))];
                            _ = &tmp;
                            sb_noise_exp += 1;
                            tmp_q1 = fxp_mul32_by_16t(sb_noise_man, tmp);
                            tmp_q2 = fxp_mul32_by_16(sb_noise_man, tmp);
                            if (sb_noise_exp < @as(c_int, 0)) {
                                if (sb_noise_exp > -@as(c_int, 32)) {
                                    if (sb_noise_exp > -@as(c_int, 10)) {
                                        ptrReal.* +%= pv_shl(tmp_q1, @as(c_int, 10) + sb_noise_exp);
                                        ptrImag.* +%= pv_shl(tmp_q2, @as(c_int, 10) + sb_noise_exp);
                                    } else {
                                        ptrReal.* +%= pv_shr(tmp_q1, -sb_noise_exp - @as(c_int, 10));
                                        ptrImag.* +%= pv_shr(tmp_q2, -sb_noise_exp - @as(c_int, 10));
                                    }
                                }
                            } else {
                                ptrReal.* +%= pv_shl(tmp_q1, sb_noise_exp + @as(c_int, 10));
                                ptrImag.* +%= pv_shl(tmp_q2, sb_noise_exp + @as(c_int, 10));
                            }
                        }
                        ptrReal += 1;
                        ptrImag += 1;
                    }
                }
                harm_index.* = (harm_index.* + @as(c_int, 1)) & @as(c_int, 3);
                if ((blk: {
                    const ref = &filter_history;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }) < maxSmoothLength) {
                    ptrReal = fBuf_man[@as(c_int, 0)];
                    ptrImag = fBufN_man[@as(c_int, 0)];
                    {
                        n = 0;
                        while (n < maxSmoothLength) : (n += 1) {
                            fBuf_man[@bitCast(@as(isize, @intCast(n)))] = fBuf_man[@bitCast(@as(isize, @intCast(n + @as(c_int, 1))))];
                            fBufN_man[@bitCast(@as(isize, @intCast(n)))] = fBufN_man[@bitCast(@as(isize, @intCast(n + @as(c_int, 1))))];
                        }
                    }
                    fBuf_man[@bitCast(@as(isize, @intCast(maxSmoothLength)))] = ptrReal;
                    fBufN_man[@bitCast(@as(isize, @intCast(maxSmoothLength)))] = ptrImag;
                    ptrReal = fBuf_exp[@as(c_int, 0)];
                    ptrImag = fBufN_exp[@as(c_int, 0)];
                    {
                        n = 0;
                        while (n < maxSmoothLength) : (n += 1) {
                            fBuf_exp[@bitCast(@as(isize, @intCast(n)))] = fBuf_exp[@bitCast(@as(isize, @intCast(n + @as(c_int, 1))))];
                            fBufN_exp[@bitCast(@as(isize, @intCast(n)))] = fBufN_exp[@bitCast(@as(isize, @intCast(n + @as(c_int, 1))))];
                        }
                    }
                    fBuf_exp[@bitCast(@as(isize, @intCast(maxSmoothLength)))] = ptrReal;
                    fBufN_exp[@bitCast(@as(isize, @intCast(maxSmoothLength)))] = ptrImag;
                }
            }
        }
    }
}

pub fn envelope_application_LC(arg_aBufR: [*c]Int32, arg_nrg_gain_man: [*c]Int32, arg_nrg_gain_exp: [*c]Int32, arg_noise_level_man: [*c]Int32, arg_noise_level_exp: [*c]Int32, arg_nrg_tone_man: [*c]Int32, arg_nrg_tone_exp: [*c]Int32, arg_band_nrg_tone_detector: Int32, arg_frame_info: [*c]const Int32, arg_harm_index: [*c]Int32, arg_phase_index: [*c]Int32, arg_i: Int32, arg_lowSubband: Int32, arg_noSubbands: Int32, arg_noNoiseFlag: Int32) void {
    var aBufR = arg_aBufR;
