    var tmp_q2: Int32 = undefined;
    _ = &tmp_q2;
    var tone_count: Int32 = undefined;
    _ = &tone_count;
    var tmp_16: Int16 = undefined;
    _ = &tmp_16;
    var indexMinus1: Int32 = undefined;
    _ = &indexMinus1;
    var indexPlus1: Int32 = undefined;
    _ = &indexPlus1;
    if (band_nrg_tone_detector != 0) {
        {
            k = 0;
            while (k < noSubbands) : (k += 1) {
                tmp_q2 = -nrg_tone_exp[@bitCast(@as(isize, @intCast(k)))];
                tmp_q1 = nrg_tone_man[@bitCast(@as(isize, @intCast(k)))];
                tmp_q2 = pv_shr(tmp_q1, tmp_q2);
                tmp_q1 = fxp_mul32_by_16(tmp_q2, @intFromFloat((@as(f32, 0.0163) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.0163) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
                nrg_tone_man[@bitCast(@as(isize, @intCast(k)))] = tmp_q2;
                nrg_tone_exp[@bitCast(@as(isize, @intCast(k)))] = tmp_q1;
                noise_level_exp[@bitCast(@as(isize, @intCast(k)))] += 1;
                nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] += 28;
            }
        }
        {
            l = frame_info[@bitCast(@as(isize, @intCast(@as(c_int, 1) + i)))] << @intCast(@as(c_int, 1));
            while (l < (frame_info[@bitCast(@as(isize, @intCast(@as(c_int, 2) + i)))] << @intCast(@as(c_int, 1)))) : (l += 1) {
                ptrReal = aBufR + @as(usize, @bitCast(@as(isize, @intCast(l * @as(c_int, 48)))));
