                            if (!(nrg_tone_man[@bitCast(@as(isize, @intCast(k)))] != 0) and !(noNoiseFlag != 0)) {
                                tmp_16 = rP_LCx[@bitCast(@as(isize, @intCast(phase_index.*)))];
