                                sb_noise_exp = noise_level_exp[@bitCast(@as(isize, @intCast(k)))];
                                tmp_q1 = fxp_mul32_by_16(sb_noise_man, tmp_16);
                                if (sb_noise_exp < @as(c_int, 0)) {
                                    if (sb_noise_exp > -@as(c_int, 32)) {
