                    phase_index.* = (phase_index.* + @as(c_int, 1)) & @as(c_int, 511);
                    tmp_q1 = nrg_tone_exp[@as(c_int, 0)];
                    tmp_q2 = nrg_tone_exp[@as(c_int, 1)];
                    if ((@intFromBool(indexPlus1 != @as(c_int, 0)) ^ @intFromBool((lowSubband & @as(c_int, 1)) != @as(c_int, 0))) != 0) {
                        (ptrReal - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).* -= tmp_q1;
                        ptrReal.* +%= tmp_q2;
                    } else {
                        (ptrReal - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).* += tmp_q1;
                        ptrReal.* -%= tmp_q2;
