                    if (!(nrg_tone_man[@as(c_int, 0)] != 0) and !(noNoiseFlag != 0)) {
                        tmp_16 = rP_LCx[@bitCast(@as(isize, @intCast(phase_index.*)))];
                        sb_noise_man = noise_level_man[@as(c_int, 0)];
