                            }
                        } else {
                            ptrReal.* +%= pv_shl(tmp_q1, sb_noise_exp);
                        }
                    } else {
                        tone_count += 1;
                    }
                    ptrReal += 1;
                    {
                        k = 1;
                        while (k < (noSubbands - @as(c_int, 1))) : (k += 1) {
                            sb_gain_man = nrg_gain_man[@bitCast(@as(isize, @intCast(k)))];
                            tmp_q1 = ptrReal.*;
                            tmp_q2 = nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))];
                            tmp_q1 = fxp_mul32_Q28(tmp_q1, sb_gain_man);
                            if (tmp_q2 < @as(c_int, 0)) {
                                if (tmp_q2 > -@as(c_int, 32)) {
                                    ptrReal.* = pv_shr(tmp_q1, -tmp_q2);
                                }
                            } else {
                                ptrReal.* = @import("std").math.shl(i32, tmp_q1, tmp_q2);
                            }
                            phase_index.* = (phase_index.* + @as(c_int, 1)) & @as(c_int, 511);
                            if (tone_count < @as(c_int, 16)) {
                                tmp_q1 = nrg_tone_exp[@bitCast(@as(isize, @intCast(k - @as(c_int, 1))))];
                                tmp_q2 = nrg_tone_exp[@bitCast(@as(isize, @intCast(k + @as(c_int, 1))))];
                                tmp_q1 -= tmp_q2;
                                if ((@intFromBool(indexPlus1 != @as(c_int, 0)) ^ @intFromBool(((k + lowSubband) & @as(c_int, 1)) != @as(c_int, 0))) != 0) {
                                    ptrReal.* -%= tmp_q1;
                                } else {
                                    ptrReal.* +%= tmp_q1;
                                }
                            }
                            if (!(nrg_tone_man[@bitCast(@as(isize, @intCast(k)))] != 0) and !(noNoiseFlag != 0)) {
                                tmp_16 = rP_LCx[@bitCast(@as(isize, @intCast(phase_index.*)))];
                                sb_noise_man = noise_level_man[@bitCast(@as(isize, @intCast(k)))];
                                sb_noise_exp = noise_level_exp[@bitCast(@as(isize, @intCast(k)))];
                                tmp_q1 = fxp_mul32_by_16(sb_noise_man, tmp_16);
                                if (sb_noise_exp < @as(c_int, 0)) {
                                    if (sb_noise_exp > -@as(c_int, 32)) {
                                        ptrReal.* +%= pv_shr(tmp_q1, -sb_noise_exp);
                                    }
                                } else {
                                    ptrReal.* +%= pv_shl(tmp_q1, sb_noise_exp);
                                }
                            } else {
                                tone_count += 1;
                            }
                            ptrReal += 1;
                        }
                    }
                    sb_gain_man = nrg_gain_man[@bitCast(@as(isize, @intCast(k)))];
                    tmp_q1 = ptrReal.*;
                    tmp_q2 = nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))];
                    tmp_q1 = fxp_mul32_Q28(tmp_q1, sb_gain_man);
                    if (tmp_q2 < @as(c_int, 0)) {
                        if (tmp_q2 > -@as(c_int, 31)) {
                            ptrReal.* = pv_shr(tmp_q1, -tmp_q2);
                        }
                    } else {
