                        tmp_q2 = nrg_tone_exp[@bitCast(@as(isize, @intCast(k)))];
                        if ((@intFromBool(indexMinus1 != @as(c_int, 0)) ^ @intFromBool(((k + lowSubband) & @as(c_int, 1)) != @as(c_int, 0))) != 0) {
