                ptrReal = aBufR + @as(usize, @bitCast(@as(isize, @intCast(l * @as(c_int, 48)))));
                {
                    k = 0;
                    while (k < noSubbands) : (k += 1) {
                        tmp_q1 = ptrReal.*;
                        sb_gain_man = nrg_gain_man[@bitCast(@as(isize, @intCast(k)))];
                        tmp_q2 = nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))];
