}

pub fn esc_iquant_scaling(arg_quantSpec: [*c]const Int16, arg_coef: [*c]Int32, sfbWidth: Int, QFormat: Int, arg_scale: UInt16, arg_maxInput: Int) void {
    var quantSpec = arg_quantSpec;
    _ = &quantSpec;
    var coef = arg_coef;
    _ = &coef;
    _ = &sfbWidth;
    _ = &QFormat;
    var scale = arg_scale;
    _ = &scale;
    var maxInput = arg_maxInput;
    _ = &maxInput;
    var i: Int = undefined;
    _ = &i;
    var x: Int = undefined;
    _ = &x;
    var y: Int = undefined;
    _ = &y;
    var index: Int = undefined;
    _ = &index;
    var shift: Int = undefined;
    _ = &shift;
    var absX: UInt = undefined;
    _ = &absX;
