pub fn extractFrameInfo(arg_hBitBuf: [*c]BIT_BUFFER, arg_h_frame_data: [*c]SBR_FRAME_DATA) SBR_ERROR {
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var h_frame_data = arg_h_frame_data;
    _ = &h_frame_data;
    var absBordLead: Int32 = 0;
    _ = &absBordLead;
    var nRelLead: Int32 = 0;
    _ = &nRelLead;
    var nRelTrail: Int32 = 0;
    _ = &nRelTrail;
    var bs_num_env: Int32 = 0;
    _ = &bs_num_env;
    var bs_num_rel: Int32 = 0;
    _ = &bs_num_rel;
    var bs_var_bord: Int32 = 0;
    _ = &bs_var_bord;
    var bs_var_bord_0: Int32 = 0;
    _ = &bs_var_bord_0;
    var bs_var_bord_1: Int32 = 0;
    _ = &bs_var_bord_1;
    var bs_pointer: Int32 = 0;
    _ = &bs_pointer;
    var bs_pointer_bits: Int32 = undefined;
    _ = &bs_pointer_bits;
    var frameClass: Int32 = undefined;
    _ = &frameClass;
    var temp: Int32 = undefined;
    _ = &temp;
    var env: Int32 = undefined;
    _ = &env;
    var k: Int32 = undefined;
    _ = &k;
    var bs_num_rel_0: Int32 = 0;
    _ = &bs_num_rel_0;
    var bs_num_rel_1: Int32 = 0;
    _ = &bs_num_rel_1;
    var absBordTrail: Int32 = 0;
    _ = &absBordTrail;
    var middleBorder: Int32 = 0;
    _ = &middleBorder;
    var bs_num_noise: Int32 = undefined;
    _ = &bs_num_noise;
    var lA: Int32 = 0;
    _ = &lA;
    var tE: [6]Int32 = undefined;
    _ = &tE;
    var tQ: [3]Int32 = undefined;
    _ = &tQ;
    var f: [6]Int32 = undefined;
    _ = &f;
    var bs_rel_bord: [3]Int32 = undefined;
    _ = &bs_rel_bord;
    var bs_rel_bord_0: [3]Int32 = undefined;
    _ = &bs_rel_bord_0;
    var bs_rel_bord_1: [3]Int32 = undefined;
    _ = &bs_rel_bord_1;
    var relBordLead: [3]Int32 = undefined;
    _ = &relBordLead;
    var relBordTrail: [3]Int32 = undefined;
    _ = &relBordTrail;
    var v_frame_info: [*c]Int32 = @ptrCast(@alignCast(&h_frame_data.*.frameInfo));
    _ = &v_frame_info;
    var err: SBR_ERROR = SBRDEC_OK;
    _ = &err;
    h_frame_data.*.frameClass = blk: {
        const tmp = @as(Int32, @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2)))));
        frameClass = tmp;
        break :blk tmp;
    };
    blk: {
        switch (frameClass) {
            @as(c_int, 0) => {
                temp = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_env = pv_shl(@as(c_int, 1), temp);
                f[@as(c_int, 0)] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
                {
                    env = 1;
                    while (env < bs_num_env) : (env += 1) {
                        f[@bitCast(@as(isize, @intCast(env)))] = f[@as(c_int, 0)];
                    }
                }
                nRelLead = bs_num_env - @as(c_int, 1);
                absBordTrail = 16;
                break :blk;
            },
            @as(c_int, 1) => {
                bs_var_bord = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_rel = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_env = bs_num_rel + @as(c_int, 1);
                {
                    k = 0;
                    while (k < (bs_num_env - @as(c_int, 1))) : (k += 1) {
                        bs_rel_bord[@bitCast(@as(isize, @intCast(k)))] = @bitCast(@as(c_uint, @truncate(pv_shl((buf_getbits(hBitBuf, 2) +% @as(UInt32, 1)), @as(UInt32, 1)))));
                    }
                }
                bs_pointer_bits = bs_pointer_bits_tbl[@bitCast(@as(isize, @intCast(bs_num_env)))];
                bs_pointer = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, bs_pointer_bits))));
                {
                    env = 0;
                    while (env < bs_num_env) : (env += 1) {
                        f[@bitCast(@as(isize, @intCast((bs_num_env - @as(c_int, 1)) - env)))] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
                    }
                }
                absBordTrail = @as(c_int, 16) + bs_var_bord;
                nRelTrail = bs_num_rel;
                break :blk;
            },
            @as(c_int, 2) => {
                bs_var_bord = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_rel = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_env = bs_num_rel + @as(c_int, 1);
                {
                    k = 0;
                    while (k < (bs_num_env - @as(c_int, 1))) : (k += 1) {
                        bs_rel_bord[@bitCast(@as(isize, @intCast(k)))] = @bitCast(@as(c_uint, @truncate(pv_shl((buf_getbits(hBitBuf, 2) +% @as(UInt32, 1)), @as(UInt32, 1)))));
                    }
                }
                bs_pointer_bits = bs_pointer_bits_tbl[@bitCast(@as(isize, @intCast(bs_num_env)))];
                bs_pointer = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, bs_pointer_bits))));
                {
                    env = 0;
                    while (env < bs_num_env) : (env += 1) {
                        f[@bitCast(@as(isize, @intCast(env)))] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
                    }
                }
                absBordTrail = 16;
                absBordLead = bs_var_bord;
                nRelLead = bs_num_rel;
                break :blk;
            },
            @as(c_int, 3) => {
                bs_var_bord_0 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_var_bord_1 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_rel_0 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_rel_1 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
                bs_num_env = (bs_num_rel_0 + bs_num_rel_1) + @as(c_int, 1);
                {
                    k = 0;
                    while (k < bs_num_rel_0) : (k += 1) {
                        bs_rel_bord_0[@bitCast(@as(isize, @intCast(k)))] = @bitCast(@as(c_uint, @truncate(pv_shl((buf_getbits(hBitBuf, 2) +% @as(UInt32, 1)), @as(UInt32, 1)))));
                    }
                }
                {
                    k = 0;
                    while (k < bs_num_rel_1) : (k += 1) {
                        bs_rel_bord_1[@bitCast(@as(isize, @intCast(k)))] = @bitCast(@as(c_uint, @truncate(pv_shl((buf_getbits(hBitBuf, 2) +% @as(UInt32, 1)), @as(UInt32, 1)))));
                    }
                }
                bs_pointer_bits = bs_pointer_bits_tbl[@bitCast(@as(isize, @intCast(bs_num_env)))];
                bs_pointer = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, bs_pointer_bits))));
                {
                    env = 0;
                    while (env < bs_num_env) : (env += 1) {
                        f[@bitCast(@as(isize, @intCast(env)))] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
                    }
                }
                absBordLead = bs_var_bord_0;
                absBordTrail = @as(c_int, 16) + bs_var_bord_1;
                nRelLead = bs_num_rel_0;
                nRelTrail = bs_num_rel_1;
                break :blk;
            },
            else => {},
        }
    }
    blk: {
        switch (frameClass) {
            @as(c_int, 0) => {
                {
                    k = 0;
                    while (k < nRelLead) : (k += 1) {
                        relBordLead[@bitCast(@as(isize, @intCast(k)))] = T_16_ov_bs_num_env_tbl[@bitCast(@as(isize, @intCast(bs_num_env)))];
                    }
                }
                break :blk;
            },
            @as(c_int, 2) => {
                {
                    k = 0;
                    while (k < nRelLead) : (k += 1) {
                        relBordLead[@bitCast(@as(isize, @intCast(k)))] = bs_rel_bord[@bitCast(@as(isize, @intCast(k)))];
                    }
                }
                break :blk;
            },
            @as(c_int, 3) => {
                {
                    k = 0;
                    while (k < nRelLead) : (k += 1) {
                        relBordLead[@bitCast(@as(isize, @intCast(k)))] = bs_rel_bord_0[@bitCast(@as(isize, @intCast(k)))];
                    }
                }
                {
                    k = 0;
                    while (k < nRelTrail) : (k += 1) {
                        relBordTrail[@bitCast(@as(isize, @intCast(k)))] = bs_rel_bord_1[@bitCast(@as(isize, @intCast(k)))];
                    }
                }
                break :blk;
            },
            @as(c_int, 1) => {
                {
                    k = 0;
                    while (k < nRelTrail) : (k += 1) {
                        relBordTrail[@bitCast(@as(isize, @intCast(k)))] = bs_rel_bord[@bitCast(@as(isize, @intCast(k)))];
                    }
                }
                break :blk;
            },
            else => {},
        }
    }
    tE[@as(c_int, 0)] = absBordLead;
    tE[@bitCast(@as(isize, @intCast(bs_num_env)))] = absBordTrail;
    {
        env = 1;
        while (env <= nRelLead) : (env += 1) {
            tE[@bitCast(@as(isize, @intCast(env)))] = absBordLead;
            {
                k = 0;
                while (k <= (env - @as(c_int, 1))) : (k += 1) {
                    tE[@bitCast(@as(isize, @intCast(env)))] += relBordLead[@bitCast(@as(isize, @intCast(k)))];
                }
            }
        }
    }
    {
        env = nRelLead + @as(c_int, 1);
        while (env < bs_num_env) : (env += 1) {
            tE[@bitCast(@as(isize, @intCast(env)))] = absBordTrail;
            {
                k = 0;
                while (k <= ((bs_num_env - env) - @as(c_int, 1))) : (k += 1) {
                    tE[@bitCast(@as(isize, @intCast(env)))] -= relBordTrail[@bitCast(@as(isize, @intCast(k)))];
                }
            }
        }
    }
    blk: {
        switch (frameClass) {
            @as(c_int, 0) => {
                middleBorder = bs_num_env >> @intCast(@as(c_int, 1));
                break :blk;
            },
            @as(c_int, 2) => {
                blk_1: {
                    switch (bs_pointer) {
                        @as(c_int, 0) => {
                            middleBorder = 1;
                            break :blk_1;
                        },
                        @as(c_int, 1) => {
                            middleBorder = bs_num_env - @as(c_int, 1);
                            break :blk_1;
                        },
                        else => {
                            middleBorder = bs_pointer - @as(c_int, 1);
                            break :blk_1;
                        },
                    }
                }
                break :blk;
            },
            @as(c_int, 1), @as(c_int, 3) => {
                blk_1: {
                    switch (bs_pointer) {
                        @as(c_int, 0), @as(c_int, 1) => {
                            middleBorder = bs_num_env - @as(c_int, 1);
                            break :blk_1;
                        },
                        else => {
                            middleBorder = (bs_num_env + @as(c_int, 1)) - bs_pointer;
                            break :blk_1;
                        },
                    }
                }
                break :blk;
            },
            else => {},
        }
    }
    tQ[@as(c_int, 0)] = tE[@as(c_int, 0)];
    if (bs_num_env > @as(c_int, 1)) {
        tQ[@as(c_int, 1)] = tE[@bitCast(@as(isize, @intCast(middleBorder)))];
        tQ[@as(c_int, 2)] = tE[@bitCast(@as(isize, @intCast(bs_num_env)))];
        bs_num_noise = 2;
    } else {
        tQ[@as(c_int, 1)] = tE[@bitCast(@as(isize, @intCast(bs_num_env)))];
        bs_num_noise = 1;
    }
    if ((tE[@bitCast(@as(isize, @intCast(bs_num_env)))] < tE[@as(c_int, 0)]) or (tE[@as(c_int, 0)] < @as(c_int, 0))) {
        err = SBRDEC_INVALID_BITSTREAM;
    }
    blk: {
        switch (frameClass) {
            @as(c_int, 0) => {
                lA = -@as(c_int, 1);
                break :blk;
            },
            @as(c_int, 2) => {
                blk_1: {
                    switch (bs_pointer) {
                        @as(c_int, 0), @as(c_int, 1) => {
                            lA = -@as(c_int, 1);
                            break :blk_1;
                        },
                        else => {
                            lA = bs_pointer - @as(c_int, 1);
                            break :blk_1;
                        },
                    }
                }
                break :blk;
            },
            @as(c_int, 1), @as(c_int, 3) => {
                blk_1: {
                    switch (bs_pointer) {
                        @as(c_int, 0) => {
                            lA = -@as(c_int, 1);
                            break :blk_1;
                        },
                        else => {
                            lA = (bs_num_env + @as(c_int, 1)) - bs_pointer;
                            break :blk_1;
                        },
                    }
                }
                break :blk;
            },
            else => {},
        }
    }
    v_frame_info[@as(c_int, 0)] = bs_num_env;
    _ = memcpy(@ptrCast(@alignCast(v_frame_info + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1))))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&tE))))), @as(c_ulong, @bitCast(@as(c_long, bs_num_env + @as(c_int, 1)))) *% @sizeOf(Int32));
    _ = memcpy(@ptrCast(@alignCast(((v_frame_info + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))) + @as(usize, @bitCast(@as(isize, @intCast(bs_num_env))))) + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1))))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&f))))), @as(c_ulong, @bitCast(@as(c_long, bs_num_env))) *% @sizeOf(Int32));
    temp = (@as(c_int, 1) + bs_num_env) << @intCast(@as(c_int, 1));
    v_frame_info[@bitCast(@as(isize, @intCast(temp)))] = lA;
    v_frame_info[@bitCast(@as(isize, @intCast(temp + @as(c_int, 1))))] = bs_num_noise;
    _ = memcpy(@ptrCast(@alignCast((v_frame_info + @as(usize, @bitCast(@as(isize, @intCast(temp))))) + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2))))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&tQ))))), @as(c_ulong, @bitCast(@as(c_long, bs_num_noise + @as(c_int, 1)))) *% @sizeOf(Int32));
    return err;
}

pub fn fft_rx4_long(arg_Data: [*c]Int32, arg_peak_value: [*c]Int32) void {
    var Data = arg_Data;
    _ = &Data;
    var peak_value = arg_peak_value;
    _ = &peak_value;
    var n1: Int = undefined;
    _ = &n1;
    var n2: Int = undefined;
    _ = &n2;
    var j: Int = undefined;
    _ = &j;
    var k: Int = undefined;
    _ = &k;
    var i: Int = undefined;
    _ = &i;
    var t1: Int32 = undefined;
    _ = &t1;
    var t2: Int32 = undefined;
    _ = &t2;
    var r1: Int32 = undefined;
    _ = &r1;
    var r2: Int32 = undefined;
    _ = &r2;
    var r3: Int32 = undefined;
    _ = &r3;
    var r4: Int32 = undefined;
    _ = &r4;
    var s1: Int32 = undefined;
    _ = &s1;
    var s2: Int32 = undefined;
    _ = &s2;
    var s3: Int32 = undefined;
    _ = &s3;
    var pData1: [*c]Int32 = undefined;
    _ = &pData1;
    var pData2: [*c]Int32 = undefined;
    _ = &pData2;
    var pData3: [*c]Int32 = undefined;
    _ = &pData3;
    var pData4: [*c]Int32 = undefined;
    _ = &pData4;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var temp3: Int32 = undefined;
    _ = &temp3;
    var temp4: Int32 = undefined;
    _ = &temp4;
    var max: Int32 = undefined;
    _ = &max;
    var exp_jw1: Int32 = undefined;
    _ = &exp_jw1;
    var exp_jw2: Int32 = undefined;
    _ = &exp_jw2;
    var exp_jw3: Int32 = undefined;
    _ = &exp_jw3;
    var pw: [*c]const Int32 = &W_256rx4;
    _ = &pw;
    n2 = 256;
    {
        k = 256;
        while (k > @as(c_int, 4)) : (k >>= @intCast(@as(c_int, 2))) {
            n1 = n2;
            n2 >>= @intCast(@as(c_int, 2));
            {
                i = 0;
                while (i < @as(c_int, 256)) : (i += n1) {
                    pData1 = &Data[@bitCast(@as(isize, @intCast(i << @intCast(@as(c_int, 1)))))];
                    pData2 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                    temp1 = pData1.*;
                    temp2 = pData2.*;
                    r1 = temp1 + temp2;
                    r2 = temp1 - temp2;
                    pData3 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n1 >> @intCast(@as(c_int, 1))))));
                    pData4 = pData3 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                    temp3 = (blk: {
                        const ref = &pData3;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    temp4 = (blk: {
                        const ref = &pData4;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    t1 = temp3 + temp4;
                    (blk: {
                        const ref = &pData1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = r1 + t1;
                    t2 = temp3 - temp4;
                    (blk: {
                        const ref = &pData2;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = r1 - t1;
                    temp1 = pData1.*;
                    temp2 = pData2.*;
                    s1 = temp1 + temp2;
                    temp3 = pData3.*;
                    s2 = temp1 - temp2;
                    temp4 = pData4.*;
                    (blk: {
                        const ref = &pData3;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* = s2 - t2;
                    (blk: {
                        const ref = &pData4;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* = s2 + t2;
                    t1 = temp3 + temp4;
                    pData1.* = s1 + t1;
                    pData2.* = s1 - t1;
                    r1 = temp3 - temp4;
                    pData4.* = r2 - r1;
                    pData3.* = r2 + r1;
                }
            }
            {
                j = 1;
                while (j < n2) : (j += 1) {
                    exp_jw1 = (blk: {
                        const ref = &pw;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    exp_jw2 = (blk: {
                        const ref = &pw;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    exp_jw3 = (blk: {
                        const ref = &pw;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    {
                        i = j;
                        while (i < @as(c_int, 256)) : (i += n1) {
                            pData1 = &Data[@bitCast(@as(isize, @intCast(i << @intCast(@as(c_int, 1)))))];
                            pData2 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                            temp1 = pData1.*;
                            temp2 = (blk: {
                                const ref = &pData2;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*;
                            r1 = temp1 + temp2;
                            r2 = temp1 - temp2;
                            pData3 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n1 >> @intCast(@as(c_int, 1))))));
                            pData4 = pData3 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                            temp3 = (blk: {
                                const ref = &pData3;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*;
                            temp4 = (blk: {
                                const ref = &pData4;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*;
                            r3 = temp3 + temp4;
                            r4 = temp3 - temp4;
                            (blk: {
                                const ref = &pData1;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = r1 + r3;
                            r1 = (r1 - r3) << @intCast(@as(c_int, 1));
                            temp2 = pData2.*;
                            temp1 = pData1.*;
                            s1 = temp1 + temp2;
                            s2 = temp1 - temp2;
                            s3 = (s2 + r4) << @intCast(@as(c_int, 1));
                            s2 = (s2 - r4) << @intCast(@as(c_int, 1));
                            temp3 = pData3.*;
                            temp4 = pData4.*;
                            t1 = temp3 + temp4;
                            t2 = temp3 - temp4;
                            pData1.* = s1 + t1;
                            s1 = (s1 - t1) << @intCast(@as(c_int, 1));
                            (blk: {
                                const ref = &pData2;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).* = cmplx_mul32_by_16(s1, -r1, exp_jw2);
                            r3 = (r2 - t2) << @intCast(@as(c_int, 1));
                            pData2.* = cmplx_mul32_by_16(r1, s1, exp_jw2);
                            r2 = (r2 + t2) << @intCast(@as(c_int, 1));
                            (blk: {
                                const ref = &pData3;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).* = cmplx_mul32_by_16(s2, -r2, exp_jw1);
                            pData3.* = cmplx_mul32_by_16(r2, s2, exp_jw1);
                            (blk: {
                                const ref = &pData4;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).* = cmplx_mul32_by_16(s3, -r3, exp_jw3);
                            pData4.* = cmplx_mul32_by_16(r3, s3, exp_jw3);
                        }
                    }
                }
            }
        }
    }
    max = 0;
    pData1 = Data - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 7)))));
    {
        i = @as(c_int, 256) >> @intCast(@as(c_int, 2));
        while (i != @as(c_int, 0)) : (i -= 1) {
            pData1 += @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 7)))));
            pData2 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 4)))));
            temp1 = pData1.*;
            temp2 = (blk: {
                const ref = &pData2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            r1 = temp1 + temp2;
            r2 = temp1 - temp2;
            pData3 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))));
            pData4 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 6)))));
            temp1 = (blk: {
                const ref = &pData3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp2 = (blk: {
                const ref = &pData4;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            t1 = temp1 + temp2;
            t2 = temp1 - temp2;
            temp1 = r1 + t1;
            r1 = r1 - t1;
            (blk: {
                const ref = &pData1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp1;
            max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
            temp2 = pData2.*;
            temp1 = pData1.*;
            s1 = temp1 + temp2;
            s2 = temp1 - temp2;
            temp1 = pData3.*;
            temp2 = pData4.*;
            s3 = s2 + t2;
            s2 = s2 - t2;
            t1 = temp1 + temp2;
            t2 = temp1 - temp2;
            temp1 = s1 + t1;
            pData1.* = temp1;
            temp2 = s1 - t1;
            max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
            (blk: {
                const ref = &pData2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp2;
            max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
            pData2.* = r1;
            max |= (r1 >> @intCast(@as(c_int, 31))) ^ r1;
            (blk: {
                const ref = &pData3;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = s2;
            max |= (s2 >> @intCast(@as(c_int, 31))) ^ s2;
            (blk: {
                const ref = &pData4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = s3;
            max |= (s3 >> @intCast(@as(c_int, 31))) ^ s3;
            temp1 = r2 - t2;
            pData4.* = temp1;
            temp2 = r2 + t2;
            pData3.* = temp2;
            max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
            max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
        }
    }
    peak_value.* = max;
    return;
}

pub fn fft_rx4_short(arg_Data: [*c]Int32, arg_peak_value: [*c]Int32) Int {
    var Data = arg_Data;
    _ = &Data;
    var peak_value = arg_peak_value;
    _ = &peak_value;
    var n1: Int = undefined;
    _ = &n1;
    var n2: Int = undefined;
    _ = &n2;
    var n3: Int = undefined;
    _ = &n3;
    var j: Int = undefined;
    _ = &j;
    var k: Int = undefined;
    _ = &k;
    var i: Int = undefined;
    _ = &i;
    var exp_jw1: Int32 = undefined;
    _ = &exp_jw1;
    var exp_jw2: Int32 = undefined;
    _ = &exp_jw2;
    var exp_jw3: Int32 = undefined;
    _ = &exp_jw3;
    var t1: Int32 = undefined;
    _ = &t1;
    var t2: Int32 = undefined;
    _ = &t2;
    var r1: Int32 = undefined;
    _ = &r1;
    var r2: Int32 = undefined;
    _ = &r2;
    var r3: Int32 = undefined;
    _ = &r3;
    var s1: Int32 = undefined;
    _ = &s1;
    var s2: Int32 = undefined;
    _ = &s2;
    var s3: Int32 = undefined;
    _ = &s3;
    var pData1: [*c]Int32 = undefined;
    _ = &pData1;
    var pData2: [*c]Int32 = undefined;
    _ = &pData2;
    var pData3: [*c]Int32 = undefined;
    _ = &pData3;
    var pData4: [*c]Int32 = undefined;
    _ = &pData4;
    var pw: [*c]const Int32 = undefined;
    _ = &pw;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var temp3: Int32 = undefined;
    _ = &temp3;
    var temp4: Int32 = undefined;
    _ = &temp4;
    var max: Int32 = undefined;
    _ = &max;
    var exp: Int = undefined;
    _ = &exp;
    var exponent: Int = 0;
    _ = &exponent;
    var shift: Int = undefined;
    _ = &shift;
    max = peak_value.*;
    exp = 0;
    if (max > @as(c_int, 32768)) {
        exp = @as(c_int, 8) - pv_normalize(max);
        exponent = exp;
    }
    n2 = 64;
    pw = &W_64rx4;
    shift = 2;
    {
        k = 64;
        while (k > @as(c_int, 4)) : (k >>= @intCast(@as(c_int, 2))) {
            n1 = n2;
            n2 >>= @intCast(@as(c_int, 2));
            n3 = n1 >> @intCast(@as(c_int, 1));
            exp -= 2;
            {
                i = 0;
                while (i < @as(c_int, 64)) : (i += n1) {
                    pData1 = &Data[@bitCast(@as(isize, @intCast(i << @intCast(@as(c_int, 1)))))];
                    pData3 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n3))));
                    pData2 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                    pData4 = pData3 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                    temp1 = pData1.*;
                    temp2 = pData2.*;
                    temp1 >>= @intCast(shift);
                    temp2 >>= @intCast(shift);
                    r1 = temp1 + temp2;
                    r2 = temp1 - temp2;
                    temp3 = (blk: {
                        const ref = &pData3;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    temp4 = (blk: {
                        const ref = &pData4;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    temp3 >>= @intCast(shift);
                    temp4 >>= @intCast(shift);
                    t1 = temp3 + temp4;
                    t2 = temp3 - temp4;
                    (blk: {
                        const ref = &pData1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = pv_shr((r1 + t1), exp);
                    (blk: {
                        const ref = &pData2;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = pv_shr((r1 - t1), exp);
                    temp1 = pData1.*;
                    temp2 = pData2.*;
                    temp1 >>= @intCast(shift);
                    temp2 >>= @intCast(shift);
                    s1 = temp1 + temp2;
                    s2 = temp1 - temp2;
                    temp3 = pData3.*;
                    temp4 = pData4.*;
                    temp3 >>= @intCast(shift);
                    temp4 >>= @intCast(shift);
                    t1 = temp3 + temp4;
                    r1 = temp3 - temp4;
                    pData1.* = pv_shr((s1 + t1), exp);
                    pData2.* = pv_shr((s1 - t1), exp);
                    (blk: {
                        const ref = &pData4;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* = pv_shr((s2 + t2), exp);
                    pData4.* = pv_shr((r2 - r1), exp);
                    (blk: {
                        const ref = &pData3;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* = pv_shr((s2 - t2), exp);
                    pData3.* = pv_shr((r2 + r1), exp);
                }
            }
            {
                j = 1;
                while (j < n2) : (j += 1) {
                    exp_jw1 = (blk: {
                        const ref = &pw;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    exp_jw2 = (blk: {
                        const ref = &pw;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    exp_jw3 = (blk: {
                        const ref = &pw;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    {
                        i = j;
                        while (i < @as(c_int, 64)) : (i += n1) {
                            pData1 = &Data[@bitCast(@as(isize, @intCast(i << @intCast(@as(c_int, 1)))))];
                            pData3 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n3))));
                            pData2 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                            pData4 = pData3 + @as(usize, @bitCast(@as(isize, @intCast(n1))));
                            temp1 = pData1.*;
                            temp2 = (blk: {
                                const ref = &pData2;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*;
                            temp1 >>= @intCast(shift);
                            temp2 >>= @intCast(shift);
                            r1 = temp1 + temp2;
                            r2 = temp1 - temp2;
                            temp3 = (blk: {
                                const ref = &pData3;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*;
                            temp4 = (blk: {
                                const ref = &pData4;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*;
                            temp3 >>= @intCast(shift);
                            temp4 >>= @intCast(shift);
                            t1 = temp3 + temp4;
                            t2 = temp3 - temp4;
                            (blk: {
                                const ref = &pData1;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = pv_shr((r1 + t1), exp);
                            r1 = pv_shr((r1 - t1), exp);
                            temp1 = pData1.*;
                            temp2 = pData2.*;
                            temp1 >>= @intCast(shift);
                            temp2 >>= @intCast(shift);
                            s1 = temp1 + temp2;
                            s2 = temp1 - temp2;
                            s3 = pv_shr((s2 + t2), exp);
                            s2 = pv_shr((s2 - t2), exp);
                            temp3 = pData3.*;
                            temp4 = pData4.*;
                            temp3 >>= @intCast(shift);
                            temp4 >>= @intCast(shift);
                            t1 = temp3 + temp4;
                            t2 = temp3 - temp4;
                            pData1.* = pv_shr((s1 + t1), exp);
                            s1 = pv_shr((s1 - t1), exp);
                            (blk: {
                                const ref = &pData2;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).* = cmplx_mul32_by_16(s1, -r1, exp_jw2) << @intCast(@as(c_int, 1));
                            pData2.* = cmplx_mul32_by_16(r1, s1, exp_jw2) << @intCast(@as(c_int, 1));
                            r3 = pv_shr((r2 - t2), exp);
                            r2 = pv_shr((r2 + t2), exp);
                            (blk: {
                                const ref = &pData3;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).* = cmplx_mul32_by_16(s2, -r2, exp_jw1) << @intCast(@as(c_int, 1));
                            pData3.* = cmplx_mul32_by_16(r2, s2, exp_jw1) << @intCast(@as(c_int, 1));
                            (blk: {
                                const ref = &pData4;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).* = cmplx_mul32_by_16(s3, -r3, exp_jw3) << @intCast(@as(c_int, 1));
                            pData4.* = cmplx_mul32_by_16(r3, s3, exp_jw3) << @intCast(@as(c_int, 1));
                        }
                    }
                }
            }
            exp = 2;
            shift = 0;
        }
    }
    max = 0;
    pData1 = Data - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 7)))));
    {
        i = @as(c_int, 64) >> @intCast(@as(c_int, 2));
        while (i != @as(c_int, 0)) : (i -= 1) {
            pData1 += @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 7)))));
            pData3 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))));
            pData2 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 4)))));
            pData4 = pData1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 6)))));
            temp1 = pData1.*;
            temp2 = (blk: {
                const ref = &pData2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            r1 = temp1 + temp2;
            r2 = temp1 - temp2;
            temp1 = (blk: {
                const ref = &pData3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp2 = (blk: {
                const ref = &pData4;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            t1 = temp1 + temp2;
            t2 = temp1 - temp2;
            temp1 = r1 + t1;
            r1 = r1 - t1;
            (blk: {
                const ref = &pData1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp1;
            max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
            temp1 = pData1.*;
            temp2 = pData2.*;
            s1 = temp1 + temp2;
            s2 = temp1 - temp2;
            s3 = s2 + t2;
            s2 = s2 - t2;
            temp1 = pData3.*;
            temp2 = pData4.*;
            t1 = temp1 + temp2;
            t2 = temp1 - temp2;
            temp1 = s1 + t1;
            temp2 = s1 - t1;
            pData1.* = temp1;
            (blk: {
                const ref = &pData2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp2;
            max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
            max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
            pData2.* = r1;
            (blk: {
                const ref = &pData3;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = s2;
            (blk: {
                const ref = &pData4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = s3;
            max |= (r1 >> @intCast(@as(c_int, 31))) ^ r1;
            max |= (s2 >> @intCast(@as(c_int, 31))) ^ s2;
            max |= (s3 >> @intCast(@as(c_int, 31))) ^ s3;
            temp1 = r2 - t2;
            temp2 = r2 + t2;
            pData4.* = temp1;
            pData3.* = temp2;
            max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
            max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
        }
    }
    peak_value.* = max;
    return exponent;
}

pub fn find_adts_syncword(arg_pSyncword: [*c]UInt32, arg_pInputStream: [*c]BITS, arg_syncword_length: Int, arg_syncword_mask: UInt32) Int {
    var pSyncword = arg_pSyncword;
    _ = &pSyncword;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var syncword_length = arg_syncword_length;
    _ = &syncword_length;
    var syncword_mask = arg_syncword_mask;
    _ = &syncword_mask;
    var status: Int = 0;
    _ = &status;
    var search_length: UInt = undefined;
    _ = &search_length;
    var adts_header: UInt32 = 0;
    _ = &adts_header;
    var test_for_syncword: UInt32 = undefined;
    _ = &test_for_syncword;
    var syncword: UInt32 = pSyncword.*;
    _ = &syncword;
    if (@as(Int, @bitCast(@as(c_uint, @truncate(pInputStream.*.usedBits)))) < (@as(Int, @bitCast(@as(c_uint, @truncate(pInputStream.*.availableBits)))) - syncword_length)) {
        search_length = pInputStream.*.availableBits -% pInputStream.*.usedBits;
        search_length -%= @bitCast(@as(c_int, syncword_length));
        adts_header = getbits(@bitCast(@as(c_int, syncword_length)), pInputStream);
        test_for_syncword = adts_header & syncword_mask;
        test_for_syncword ^= syncword;
        while ((test_for_syncword != @as(UInt32, 0)) and (search_length > @as(UInt, 0))) {
            search_length -%= 1;
            adts_header <<= @intCast(@as(UInt32, 1));
            adts_header |= getbits(1, pInputStream);
            test_for_syncword = adts_header & syncword_mask;
            test_for_syncword ^= syncword;
        }
        if (search_length == @as(UInt, 0)) {
            status = -@as(c_int, 1);
        }
        pInputStream.*.byteAlignOffset = @bitCast(@as(c_uint, @truncate((pInputStream.*.usedBits -% @as(UInt, @bitCast(@as(c_int, syncword_length)))) & @as(UInt, 7))));
    } else {
        status = -@as(c_int, 1);
    }
    pSyncword.* = adts_header;
    return status;
}

