pub fn fwd_long_complex_rot(arg_Data_in: [*c]Int32, arg_Data_out: [*c]Int32, arg_max: Int32) Int {
    var Data_in = arg_Data_in;
    _ = &Data_in;
    var Data_out = arg_Data_out;
    _ = &Data_out;
    var max = arg_max;
    _ = &max;
    var i: Int = undefined;
    _ = &i;
    var p_rotate: [*c]const Int32 = undefined;
    _ = &p_rotate;
    var temp_re: Int32 = undefined;
    _ = &temp_re;
    var temp_im: Int32 = undefined;
    _ = &temp_im;
    var pData_in_ref1: [*c]Int32 = undefined;
    _ = &pData_in_ref1;
    var pData_in_ref2: [*c]Int32 = undefined;
    _ = &pData_in_ref2;
    var exp_jw: Int32 = undefined;
    _ = &exp_jw;
    var temp_re_32: Int32 = undefined;
    _ = &temp_re_32;
    var temp_im_32: Int32 = undefined;
    _ = &temp_im_32;
    var pData_out_1: [*c]Int32 = undefined;
    _ = &pData_out_1;
    var pData_out_2: [*c]Int32 = undefined;
    _ = &pData_out_2;
    var pData_out_3: [*c]Int32 = undefined;
    _ = &pData_out_3;
    var pData_out_4: [*c]Int32 = undefined;
    _ = &pData_out_4;
    var pData_in_1: [*c]Int32 = undefined;
    _ = &pData_in_1;
    var pData_in_2: [*c]Int32 = undefined;
    _ = &pData_in_2;
    var exp: Int = undefined;
    _ = &exp;
    p_rotate = @ptrCast(@alignCast(&exp_rotation_N_2048));
    pData_in_ref1 = Data_in;
    pData_in_ref2 = &Data_in[@as(c_int, 256) << @intCast(@as(c_int, 1))];
    pData_out_1 = Data_out;
    pData_out_2 = &Data_out[@as(c_int, 1024) - @as(c_int, 1)];
    pData_out_3 = &Data_out[@as(c_int, 1024)];
    pData_out_4 = &Data_out[(@as(c_int, 1024) << @intCast(@as(c_int, 1))) - @as(c_int, 1)];
    exp = @as(c_int, 16) - pv_normalize(max);
    if (exp < @as(c_int, 0)) {
        exp = 0;
    }
    pData_in_1 = pData_in_ref1;
    pData_in_2 = pData_in_ref2;
    {
        i = 256;
        while (i != @as(c_int, 0)) : (i -= 1) {
            exp_jw = (blk: {
                const ref = &p_rotate;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp_re = pv_shr((blk: {
                const ref = &pData_in_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, exp);
            temp_im = pv_shr((blk: {
                const ref = &pData_in_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, exp);
            temp_re_32 = cmplx_mul32_by_16(temp_re, temp_im, exp_jw);
            temp_im_32 = cmplx_mul32_by_16(temp_im, -temp_re, exp_jw);
            (blk: {
                const ref = &pData_out_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = -temp_re_32;
            (blk: {
                const ref = &pData_out_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp_im_32;
            (blk: {
                const ref = &pData_out_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = -temp_im_32;
            (blk: {
                const ref = &pData_out_4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp_re_32;
            pData_out_1 += 1;
            pData_out_2 -= 1;
            pData_out_3 += 1;
            pData_out_4 -= 1;
            exp_jw = (blk: {
                const ref = &p_rotate;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp_re = pv_shr((blk: {
                const ref = &pData_in_2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, exp);
            temp_im = pv_shr((blk: {
                const ref = &pData_in_2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, exp);
            temp_re_32 = cmplx_mul32_by_16(temp_re, temp_im, exp_jw);
            temp_im_32 = cmplx_mul32_by_16(temp_im, -temp_re, exp_jw);
            (blk: {
                const ref = &pData_out_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = -temp_re_32;
            (blk: {
                const ref = &pData_out_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp_im_32;
            (blk: {
                const ref = &pData_out_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = -temp_im_32;
            (blk: {
                const ref = &pData_out_4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp_re_32;
            pData_out_1 += 1;
            pData_out_2 -= 1;
            pData_out_3 += 1;
            pData_out_4 -= 1;
        }
    }
    return exp + @as(c_int, 1);
}

pub fn fwd_short_complex_rot(arg_Data_in: [*c]Int32, arg_Data_out: [*c]Int32, arg_max: Int32) Int {
    var Data_in = arg_Data_in;
    _ = &Data_in;
    var Data_out = arg_Data_out;
    _ = &Data_out;
    var max = arg_max;
    _ = &max;
    var i: Int = undefined;
    _ = &i;
    var I: Int16 = undefined;
    _ = &I;
    var pTable: [*c]const Int16 = undefined;
    _ = &pTable;
    var p_rotate: [*c]const Int32 = undefined;
    _ = &p_rotate;
    var pData_in_1: [*c]Int32 = undefined;
    _ = &pData_in_1;
    var exp: Int = undefined;
    _ = &exp;
    var temp_re: Int32 = undefined;
    _ = &temp_re;
    var temp_im: Int32 = undefined;
    _ = &temp_im;
    var cos_n: Int32 = undefined;
    _ = &cos_n;
    var sin_n: Int32 = undefined;
    _ = &sin_n;
    var temp_re_32: Int32 = undefined;
    _ = &temp_re_32;
    var temp_im_32: Int32 = undefined;
    _ = &temp_im_32;
    var pData_in_ref: [*c]Int32 = undefined;
    _ = &pData_in_ref;
    var pData_out_1: [*c]Int32 = undefined;
    _ = &pData_out_1;
    var pData_out_2: [*c]Int32 = undefined;
    _ = &pData_out_2;
    var pData_out_3: [*c]Int32 = undefined;
    _ = &pData_out_3;
    var pData_out_4: [*c]Int32 = undefined;
    _ = &pData_out_4;
    pTable = &digit_reverse_64;
    p_rotate = @ptrCast(@alignCast(&exp_rotation_N_256));
    pData_in_ref = Data_in;
    exp = @as(c_int, 16) - pv_normalize(max);
    if (exp < @as(c_int, 0)) {
        exp = 0;
    }
    pData_out_1 = Data_out;
    pData_out_2 = &Data_out[(@as(c_int, 64) << @intCast(@as(c_int, 1))) - @as(c_int, 1)];
    pData_out_3 = &Data_out[@as(c_int, 64) << @intCast(@as(c_int, 1))];
    pData_out_4 = &Data_out[(@as(c_int, 64) << @intCast(@as(c_int, 2))) - @as(c_int, 1)];
    {
        i = 64;
        while (i != @as(c_int, 0)) : (i -= 1) {
            I = (blk: {
                const ref = &pTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            pData_in_1 = pData_in_ref + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, I)))));
            sin_n = (blk: {
                const ref = &p_rotate;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            cos_n = sin_n >> @intCast(@as(c_int, 16));
            sin_n = sin_n & @as(c_int, 65535);
            temp_re = pv_shr((blk: {
                const ref = &pData_in_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, exp);
            temp_im = pv_shr(pData_in_1.*, exp);
            temp_re_32 = ((temp_re * cos_n) + (temp_im * sin_n)) >> @intCast(@as(c_int, 16));
            temp_im_32 = ((temp_im * cos_n) - (temp_re * sin_n)) >> @intCast(@as(c_int, 16));
            (blk: {
                const ref = &pData_out_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = -temp_re_32;
            (blk: {
                const ref = &pData_out_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp_im_32;
            (blk: {
                const ref = &pData_out_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = -temp_im_32;
            (blk: {
                const ref = &pData_out_4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = temp_re_32;
            pData_out_1 += 1;
            pData_out_2 -= 1;
            pData_out_3 += 1;
            pData_out_4 -= 1;
        }
    }
    return exp;
}

