pub fn gen_rand_vector(arg_random_array: [*c]Int32, band_length: Int, arg_pSeed: [*c]Int32, power_scale: Int) Int {
    var random_array = arg_random_array;
    _ = &random_array;
    _ = &band_length;
    var pSeed = arg_pSeed;
    _ = &pSeed;
    _ = &power_scale;
    var k: Int = undefined;
    _ = &k;
    var power_adj: UInt = undefined;
    _ = &power_adj;
    var q_adjust: Int = 30;
    _ = &q_adjust;
    var temp: Int32 = undefined;
    _ = &temp;
    var seed: Int32 = undefined;
    _ = &seed;
    var power: Int32 = undefined;
    _ = &power;
    var pArray: [*c]Int32 = &random_array[@as(c_int, 0)];
    _ = &pArray;
    var inv_sqrt_power: Int32 = undefined;
    _ = &inv_sqrt_power;
    var pInvSqrtCoeff: [*c]const Int = undefined;
    _ = &pInvSqrtCoeff;
    power = 0;
    seed = pSeed.*;
    if ((band_length < @as(c_int, 0)) or (band_length > @as(c_int, 1024))) {
        return q_adjust;
    }
    {
        k = band_length >> @intCast(@as(c_int, 1));
        while (k != @as(c_int, 0)) : (k -= 1) {
            {
                const ref = &seed;
                ref.* = @truncate(@as(c_long, ref.*) * @as(c_long, 1664525));
            }
            {
                const ref = &seed;
                ref.* = @truncate(@as(c_long, ref.*) + @as(c_long, 1013904223));
            }
            temp = seed >> @intCast(@as(c_int, 16));
            {
                const ref = &seed;
                ref.* = @truncate(@as(c_long, ref.*) * @as(c_long, 1664525));
            }
            {
                const ref = &seed;
                ref.* = @truncate(@as(c_long, ref.*) + @as(c_long, 1013904223));
            }
            power += (temp * temp) >> @intCast(@as(c_int, 6));
            (blk: {
                const ref = &pArray;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp;
            temp = seed >> @intCast(@as(c_int, 16));
            power += (temp * temp) >> @intCast(@as(c_int, 6));
            (blk: {
                const ref = &pArray;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp;
        }
    }
    pSeed.* = seed;
    k = 0;
    if (power != 0) {
        while (power > @as(c_int, 32767)) {
            power >>= @intCast(@as(c_int, 1));
            k += 1;
        }
        k -= 13;
        power_adj = scale_mod_4[@bitCast(@as(isize, @intCast(power_scale & @as(c_int, 3))))];
        if (k < @as(c_int, 0)) {
            k = -k;
            if ((k & @as(c_int, 1)) != 0) {
                power_adj = pv_shr((power_adj *% @as(UInt32, 23170)), @as(UInt32, 14));
            }
            q_adjust -= k >> @intCast(@as(c_int, 1));
        } else if (k > @as(c_int, 0)) {
            if ((k & @as(c_int, 1)) != 0) {
                power_adj = pv_shr((power_adj *% @as(UInt32, 11585)), @as(UInt32, 14));
            }
            q_adjust += k >> @intCast(@as(c_int, 1));
        }
        pInvSqrtCoeff = @ptrCast(@alignCast(&inv_sqrt_coeff));
        inv_sqrt_power = ((blk: {
            const ref = &pInvSqrtCoeff;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).* * power) >> @intCast(@as(c_int, 15));
        inv_sqrt_power += (blk: {
            const ref = &pInvSqrtCoeff;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        inv_sqrt_power = (inv_sqrt_power * power) >> @intCast(@as(c_int, 15));
        inv_sqrt_power += (blk: {
            const ref = &pInvSqrtCoeff;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        inv_sqrt_power = (inv_sqrt_power * power) >> @intCast(@as(c_int, 15));
        inv_sqrt_power += (blk: {
            const ref = &pInvSqrtCoeff;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        inv_sqrt_power = (inv_sqrt_power * power) >> @intCast(@as(c_int, 15));
        inv_sqrt_power += pInvSqrtCoeff.*;
        inv_sqrt_power = @bitCast(@as(c_uint, @truncate(pv_shr((@as(UInt, @bitCast(@as(c_int, inv_sqrt_power))) *% power_adj), @as(UInt, 13)))));
        pArray = &random_array[@as(c_int, 0)];
        {
            k = band_length >> @intCast(@as(c_int, 1));
            while (k != @as(c_int, 0)) : (k -= 1) {
                temp = pArray.* * inv_sqrt_power;
                (blk: {
                    const ref = &pArray;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = temp;
                temp = pArray.* * inv_sqrt_power;
                (blk: {
                    const ref = &pArray;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = temp;
            }
        }
    }
    q_adjust -= power_scale >> @intCast(@as(c_int, 2));
    return q_adjust;
}

pub fn get17_n_lessbits(neededBits: UInt, arg_pInputStream: [*c]BITS) UInt32 {
    _ = &neededBits;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var returnValue: UInt32 = undefined;
    _ = &returnValue;
    var offset: UInt = undefined;
    _ = &offset;
    var bitIndex: UInt = undefined;
    _ = &bitIndex;
    var pElem: [*c]UChar = undefined;
    _ = &pElem;
    offset = pv_shr(pInputStream.*.usedBits, @as(UInt, @bitCast(@as(c_int, @as(c_int, 3)))));
    pElem = pInputStream.*.pBuffer + offset;
    offset = pInputStream.*.inputBufferCurrentLength -% offset;
    if (offset > @as(UInt, 2)) {
        returnValue = ((pv_shl(@as(UInt32, pElem.*), @as(UInt32, 16))) | (pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*), @as(UInt32, 8)))) | @as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))))).*);
    } else {
        returnValue = 0;
        blk: {
            switch (offset) {
                @as(UInt, 2) => {
                    returnValue = pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*), @as(UInt32, 8));
                    returnValue |= pv_shl(@as(UInt32, pElem.*), @as(UInt32, 16));
                    break :blk;
                },
                @as(UInt, 1) => {
                    returnValue |= pv_shl(@as(UInt32, pElem.*), @as(UInt32, 16));
                    break :blk;
                },
                else => {
                    break :blk;
                },
            }
        }
    }
    bitIndex = pInputStream.*.usedBits & @as(UInt, @bitCast(@as(c_int, (@as(c_int, 1) << @intCast(@as(c_int, 3))) - @as(c_int, 1))));
    returnValue = @as(UInt32, 16777215) & (pv_shl(returnValue, bitIndex));
    returnValue = pv_shr(returnValue, @as(UInt, 24) -% neededBits);
    pInputStream.*.usedBits +%= neededBits;
    return returnValue;
}

pub fn get1bits(arg_pInputStream: [*c]BITS) UInt {
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var returnValue: UInt = undefined;
    _ = &returnValue;
    var offset: UInt = undefined;
    _ = &offset;
    var bitIndex: UInt = undefined;
    _ = &bitIndex;
    var pElem: [*c]UChar = undefined;
    _ = &pElem;
    offset = pv_shr(pInputStream.*.usedBits, @as(UInt, @bitCast(@as(c_int, @as(c_int, 3)))));
    pElem = pInputStream.*.pBuffer + offset;
    returnValue = if (offset < pInputStream.*.inputBufferCurrentLength) @as(UInt, pElem.*) else @as(UInt, 0);
    bitIndex = (blk: {
        const ref = &pInputStream.*.usedBits;
        const tmp = ref.*;
        ref.* +%= 1;
        break :blk tmp;
    }) & @as(UInt, @bitCast(@as(c_int, (@as(c_int, 1) << @intCast(@as(c_int, 3))) - @as(c_int, 1))));
    returnValue = @as(UInt, 255) & (pv_shl(returnValue, bitIndex));
    return pv_shr(returnValue, @as(UInt, 7));
}

pub fn get9_n_lessbits(neededBits: UInt, arg_pInputStream: [*c]BITS) UInt {
    _ = &neededBits;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var returnValue: UInt = undefined;
    _ = &returnValue;
    var offset: UInt = undefined;
    _ = &offset;
    var bitIndex: UInt = undefined;
    _ = &bitIndex;
    var pElem: [*c]UChar = undefined;
    _ = &pElem;
    offset = pv_shr(pInputStream.*.usedBits, @as(UInt, @bitCast(@as(c_int, @as(c_int, 3)))));
    pElem = pInputStream.*.pBuffer + offset;
    offset = pInputStream.*.inputBufferCurrentLength -% offset;
    if (offset > @as(UInt, 1)) {
        returnValue = (pv_shl(@as(UInt32, pElem.*), @as(UInt32, 8))) | @as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*);
    } else {
        blk: {
            switch (offset) {
                @as(UInt, 1) => {
                    returnValue = pv_shl(@as(UInt32, pElem.*), @as(UInt32, 8));
                    break :blk;
                },
                else => {
                    returnValue = 0;
                    break :blk;
                },
            }
        }
    }
    bitIndex = pInputStream.*.usedBits & @as(UInt, @bitCast(@as(c_int, (@as(c_int, 1) << @intCast(@as(c_int, 3))) - @as(c_int, 1))));
    pInputStream.*.usedBits +%= neededBits;
    returnValue = @as(UInt, 65535) & (pv_shl(returnValue, bitIndex));
    return pv_shr(returnValue, @as(UInt, 16) -% neededBits);
}

pub fn get_GA_specific_config(pVars: [*c]tDec_Int_File, arg_pInputStream: [*c]BITS, arg_channel_config: UInt, audioObjectType: tMP4AudioObjectType) Int {
    _ = &pVars;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var channel_config = arg_channel_config;
    _ = &channel_config;
    _ = &audioObjectType;
    var status: Int = 0;
    _ = &status;
    var dependsOnCoreCoder: UInt = undefined;
    _ = &dependsOnCoreCoder;
    var extFlag: UInt = undefined;
    _ = &extFlag;
    var extFlag3: Int = undefined;
    _ = &extFlag3;
    _ = get1bits(pInputStream);
    dependsOnCoreCoder = get1bits(pInputStream);
    if (dependsOnCoreCoder != @as(UInt, 0)) {
        status = 1;
    }
    extFlag = get1bits(pInputStream);
    pVars.*.mc_info.implicit_channeling = 1;
    if (status == @as(c_int, 0)) {
        if (channel_config == @as(UInt, 0)) {
            status = get_prog_config(pVars, &pVars.*.scratch.scratch_prog_config);
            if (status != @as(c_int, 0)) {
                pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)] = 0;
                pVars.*.mc_info.nch = 1;
                pVars.*.prog_config.front.ele_tag[@as(c_int, 0)] = 0;
                status = 0;
            }
        } else {
            channel_config -%= 1;
            pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)] = @bitCast(@as(c_uint, @truncate(channel_config)));
            pVars.*.prog_config.front.ele_tag[@as(c_int, 0)] = 0;
            status = set_mc_info(&pVars.*.mc_info, audioObjectType, pVars.*.prog_config.sampling_rate_idx, pVars.*.prog_config.front.ele_tag[@as(c_int, 0)], pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)], @ptrCast(@alignCast(&pVars.*.winmap)), @ptrCast(@alignCast(&pVars.*.SFBWidth128)));
        }
    }
    if ((audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_AAC_SCALABLE)) or (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_ER_AAC_SCALABLE))) {
        status = 1;
    }
    if (extFlag != 0) {
        if (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_ER_BSAC)) {
            status = 1;
        }
        if (((audioObjectType > @as(tMP4AudioObjectType, 16)) and (audioObjectType < @as(tMP4AudioObjectType, 22))) or (audioObjectType == @as(tMP4AudioObjectType, 23))) {
            status = 1;
        }
        extFlag3 = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
        if (extFlag3 != 0) {
            status = 1;
        }
    }
    return status;
}

pub fn get_adif_header(arg_pVars: [*c]tDec_Int_File, arg_pScratchPCE: [*c]ProgConfig) Int {
    var pVars = arg_pVars;
    _ = &pVars;
    var pScratchPCE = arg_pScratchPCE;
    _ = &pScratchPCE;
    var i: Int = undefined;
    _ = &i;
    var temp: UInt32 = undefined;
    _ = &temp;
    var numConfigElementsMinus1: Int = undefined;
    _ = &numConfigElementsMinus1;
    var bitStreamType: Int = undefined;
    _ = &bitStreamType;
    var theIDFromFile: UInt32 = undefined;
    _ = &theIDFromFile;
    var pInputStream: [*c]BITS = &pVars.*.inputStream;
    _ = &pInputStream;
    var pHeader: [*c]ADIF_Header = &pVars.*.scratch.adif_header;
    _ = &pHeader;
    var status: Int = 0;
    _ = &status;
    theIDFromFile = get17_n_lessbits(@bitCast(@as(c_int, @as(c_int, 2) * LEN_BYTE)), pInputStream);
    temp = get17_n_lessbits(@bitCast(@as(c_int, @as(c_int, 2) * LEN_BYTE)), pInputStream);
    theIDFromFile = (pv_shl(theIDFromFile, @as(UInt32, @bitCast(@as(c_int, @as(c_int, 2) * LEN_BYTE))))) | temp;
    if (theIDFromFile != @as(UInt32, @bitCast(@as(c_int, @as(c_int, 1094994246))))) {
        pInputStream.*.usedBits -%= @bitCast(@as(c_int, @as(c_int, 4) * LEN_BYTE));
        status = -@as(c_int, 1);
    } else {
        temp = get1bits(pInputStream);
        if (temp != @as(UInt32, 0)) {
            {
                i = LEN_COPYRT_ID;
                while (i > @as(c_int, 0)) : (i -= 1) {
                    _ = get9_n_lessbits(LEN_BYTE, pInputStream);
                }
            }
        }
        _ = get9_n_lessbits(@bitCast(@as(c_int, LEN_ORIG + LEN_HOME)), pInputStream);
        bitStreamType = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
        pHeader.*.bitrate = @bitCast(@as(c_uint, @truncate(getbits(LEN_BIT_RATE, pInputStream))));
        numConfigElementsMinus1 = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_NUM_PCE, pInputStream))));
        {
            i = numConfigElementsMinus1;
            while ((i >= @as(c_int, 0)) and (status == @as(c_int, 0))) : (i -= 1) {
                if (bitStreamType == @as(c_int, 0)) {
                    _ = getbits(LEN_ADIF_BF, pInputStream);
                }
                pVars.*.adif_test = 1;
                status = get_prog_config(pVars, pScratchPCE);
                if (((pVars.*.prog_config.sampling_rate_idx >= @as(c_int, 6)) and (@as(c_int, @intFromBool(pVars.*.aacPlusEnabled)) == @as(c_int, 1))) and (pVars.*.mc_info.audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_AAC_LC))) {
                    pVars.*.mc_info.upsamplingFactor = 2;
                    pVars.*.prog_config.sampling_rate_idx -= 3;
                    pVars.*.mc_info.sbrPresentFlag = 1;
                    pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 0)].syncState = UPSAMPLING;
                    pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 1)].syncState = UPSAMPLING;
                }
            }
        }
    }
    return status;
}

pub fn get_adts_header(arg_pVars: [*c]tDec_Int_File, arg_pSyncword: [*c]UInt32, arg_pInvoke: [*c]Int, arg_CorrectlyReadFramesCount: Int) Int {
    var pVars = arg_pVars;
    _ = &pVars;
    var pSyncword = arg_pSyncword;
    _ = &pSyncword;
    var pInvoke = arg_pInvoke;
    _ = &pInvoke;
    var CorrectlyReadFramesCount = arg_CorrectlyReadFramesCount;
    _ = &CorrectlyReadFramesCount;
    var adts_header: UInt32 = undefined;
    _ = &adts_header;
    var lower_16: UInt = undefined;
    _ = &lower_16;
    var status: Int = 0;
    _ = &status;
    var channel_configuration: UInt = undefined;
    _ = &channel_configuration;
    if (pInvoke.* > CorrectlyReadFramesCount) {
        status = find_adts_syncword(pSyncword, &pVars.*.inputStream, 28, 268435455);
    } else {
        pSyncword.* = 32760;
        status = find_adts_syncword(pSyncword, &pVars.*.inputStream, 15, 32763);
        adts_header = getbits(@bitCast(@as(c_int, @as(c_int, 28) - @as(c_int, 15))), &pVars.*.inputStream);
        pSyncword.* <<= @intCast(@as(UInt32, @bitCast(@as(c_int, @as(c_int, 28) - @as(c_int, 15)))));
        pSyncword.* |= adts_header;
        pVars.*.prog_config.CRC_absent = @bitCast(@as(c_uint, @truncate((pv_shr(adts_header, @as(UInt32, 12))) & @as(UInt, 1))));
        lower_16 = adts_header;
        pVars.*.prog_config.profile = @bitCast(@as(c_uint, @truncate((pv_shr(lower_16, @as(UInt, 10))) & @as(UInt, 3))));
        if (pVars.*.prog_config.profile == MP4AUDIO_AAC_SSR) {
            status = 1;
        }
        pVars.*.prog_config.sampling_rate_idx = @bitCast(@as(c_uint, @truncate((pv_shr(lower_16, @as(UInt, 6))) & @as(UInt, 15))));
        channel_configuration = (pv_shr(lower_16, @as(UInt, 2))) & @as(UInt, 7);
        if (channel_configuration > @as(UInt, 2)) {
            status = 1;
        }
        if (channel_configuration != 0) {
            channel_configuration -%= 1;
        }
        pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)] = @bitCast(@as(c_uint, @truncate(channel_configuration)));
        pVars.*.prog_config.front.num_ele = 1;
        pVars.*.prog_config.front.ele_tag[@as(c_int, 0)] = 0;
        pVars.*.prog_config.mono_mix.present = 0;
        pVars.*.prog_config.stereo_mix.present = 0;
        pVars.*.prog_config.matrix_mix.present = 0;
        if (status == @as(c_int, 0)) {
            status = set_mc_info(&pVars.*.mc_info, @bitCast(pVars.*.prog_config.profile + @as(c_int, 1)), pVars.*.prog_config.sampling_rate_idx, pVars.*.prog_config.front.ele_tag[@as(c_int, 0)], pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)], @ptrCast(@alignCast(&pVars.*.winmap)), @ptrCast(@alignCast(&pVars.*.SFBWidth128)));
        }
        if ((pVars.*.prog_config.sampling_rate_idx >= @as(c_int, 6)) and (@as(c_int, @intFromBool(pVars.*.aacPlusEnabled)) == @as(c_int, 1))) {
            pVars.*.mc_info.upsamplingFactor = 2;
            pVars.*.prog_config.sampling_rate_idx -= 3;
            pVars.*.mc_info.sbrPresentFlag = 1;
            pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 0)].syncState = SBR_ACTIVE;
            pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 1)].syncState = SBR_ACTIVE;
        }
        if (status == @as(c_int, 0)) {
            pInvoke.* += 1;
        } else {
            pInvoke.* = 0;
        }
    }
    adts_header = getbits(28, &pVars.*.inputStream);
    pVars.*.prog_config.frame_length = @bitCast(@as(c_uint, @truncate((pv_shr(adts_header, @as(UInt32, 13))) & @as(UInt, 8191))));
    lower_16 = adts_header;
    pVars.*.prog_config.buffer_fullness = @bitCast(@as(c_uint, @truncate((pv_shr(lower_16, @as(UInt, 2))) & @as(UInt, 2047))));
    pVars.*.prog_config.headerless_frames = @bitCast(@as(c_uint, @truncate(lower_16 & @as(UInt, 3))));
    if (pVars.*.prog_config.CRC_absent == @as(c_int, 0)) {
        pVars.*.prog_config.CRC_check = getbits(16, &pVars.*.inputStream);
    }
    return status;
}

pub fn get_audio_specific_config(pVars: [*c]tDec_Int_File) Int {
    _ = &pVars;
    var temp: UInt = undefined;
    _ = &temp;
    var audioObjectType: tMP4AudioObjectType = undefined;
    _ = &audioObjectType;
    var channel_config: UInt = undefined;
    _ = &channel_config;
    var syncExtensionType: UInt = undefined;
    _ = &syncExtensionType;
    var extensionAudioObjectType: UInt = 0;
    _ = &extensionAudioObjectType;
    var extensionSamplingFrequencyIndex: UInt = 0;
    _ = &extensionSamplingFrequencyIndex;
    var pInputStream: [*c]BITS = undefined;
    _ = &pInputStream;
    var status: Int = undefined;
    _ = &status;
    status = 0;
    pInputStream = &pVars.*.inputStream;
    pVars.*.mc_info.upsamplingFactor = 1;
    temp = get9_n_lessbits(@bitCast(@as(c_int, LEN_OBJ_TYPE + LEN_SAMP_RATE_IDX)), pInputStream);
    audioObjectType = pv_shr((temp & @as(UInt, 496)), @as(UInt, 4));
    pVars.*.mc_info.ExtendedAudioObjectType = audioObjectType;
    pVars.*.prog_config.sampling_rate_idx = @bitCast(@as(c_uint, @truncate(temp & @as(UInt, 15))));
    if (pVars.*.prog_config.sampling_rate_idx > @as(c_int, 11)) {
        if (pVars.*.prog_config.sampling_rate_idx == @as(c_int, 15)) {
            _ = getbits(LEN_SAMP_RATE, pInputStream);
        }
        status = 1;
    }
    channel_config = get9_n_lessbits(LEN_CHAN_CONFIG, pInputStream);
    if ((channel_config > @as(UInt, 2)) and !pVars.*.aacConfigUtilityEnabled) {
        status = 1;
    }
    if ((audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_SBR)) or (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_PS))) {
        pVars.*.mc_info.ExtendedAudioObjectType = MP4AUDIO_SBR;
        pVars.*.mc_info.sbrPresentFlag = 1;
        if (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_PS)) {
            pVars.*.mc_info.psPresentFlag = 1;
            pVars.*.mc_info.ExtendedAudioObjectType = MP4AUDIO_PS;
        }
        extensionSamplingFrequencyIndex = get9_n_lessbits(LEN_SAMP_RATE_IDX, pInputStream);
        if (extensionSamplingFrequencyIndex == @as(UInt, 15)) {
            _ = getbits(LEN_SAMP_RATE, pInputStream);
        }
        audioObjectType = get9_n_lessbits(LEN_OBJ_TYPE, pInputStream);
    }
    if (((audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_AAC_LC)) or (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_LTP))) and (status == @as(c_int, 0))) {
        status = get_GA_specific_config(pVars, pInputStream, channel_config, audioObjectType);
        if ((pVars.*.mc_info.audioObjectType != @as(tMP4AudioObjectType, MP4AUDIO_AAC_LC)) and (pVars.*.mc_info.audioObjectType != @as(tMP4AudioObjectType, MP4AUDIO_LTP))) {
            return 1;
        }
    } else {
        return 1;
    }
    if (extensionAudioObjectType != @as(UInt, MP4AUDIO_SBR)) {
        syncExtensionType = get17_n_lessbits(LEN_SYNC_EXTENSION_TYPE, pInputStream);
        if (syncExtensionType == @as(UInt, 695)) {
            extensionAudioObjectType = get9_n_lessbits(LEN_OBJ_TYPE, pInputStream);
            if (extensionAudioObjectType == @as(UInt, MP4AUDIO_SBR)) {
                pVars.*.mc_info.sbrPresentFlag = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
                if (pVars.*.mc_info.sbrPresentFlag == @as(c_int, 1)) {
                    extensionSamplingFrequencyIndex = get9_n_lessbits(LEN_SAMP_RATE_IDX, pInputStream);
                    if (@as(c_int, @intFromBool(pVars.*.aacPlusEnabled)) == @as(c_int, 1)) {
                        pVars.*.mc_info.upsamplingFactor = if ((samp_rate_info[extensionSamplingFrequencyIndex].samp_rate >> @intCast(@as(c_int, 1))) == samp_rate_info[@bitCast(@as(isize, @intCast(pVars.*.prog_config.sampling_rate_idx)))].samp_rate) @as(c_int, 2) else @as(c_int, 1);
                        if (@as(Int, @bitCast(@as(c_uint, @truncate(extensionSamplingFrequencyIndex)))) == pVars.*.prog_config.sampling_rate_idx) {
                            if (pVars.*.prog_config.sampling_rate_idx < @as(c_int, 6)) {
                                pVars.*.aacPlusEnabled = @as(c_int, 0) != 0;
                            }
                            pVars.*.mc_info.bDownSampledSbr = @as(c_int, 1) != 0;
                        }
                        pVars.*.prog_config.sampling_rate_idx = @bitCast(@as(c_uint, @truncate(extensionSamplingFrequencyIndex)));
                    }
                    if (extensionSamplingFrequencyIndex == @as(UInt, 15)) {
                        _ = getbits(LEN_SAMP_RATE, pInputStream);
                    }
                    syncExtensionType = get17_n_lessbits(LEN_SYNC_EXTENSION_TYPE, pInputStream);
                    if (syncExtensionType == @as(UInt, 1352)) {
                        pVars.*.mc_info.psPresentFlag = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
                        if (pVars.*.mc_info.psPresentFlag != 0) {
                            extensionAudioObjectType = MP4AUDIO_PS;
                        }
                    } else {
                        pVars.*.inputStream.usedBits -%= LEN_SYNC_EXTENSION_TYPE;
                    }
                    pVars.*.mc_info.ExtendedAudioObjectType = extensionAudioObjectType;
                }
            }
        } else if (!(status != 0)) {
            pVars.*.inputStream.usedBits -%= LEN_SYNC_EXTENSION_TYPE;
            if (((pVars.*.prog_config.sampling_rate_idx >= @as(c_int, 6)) and (@as(c_int, @intFromBool(pVars.*.aacPlusEnabled)) == @as(c_int, 1))) and (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_AAC_LC))) {
                pVars.*.mc_info.upsamplingFactor = 2;
                pVars.*.prog_config.sampling_rate_idx -= 3;
                pVars.*.mc_info.sbrPresentFlag = 1;
                pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 0)].syncState = SBR_NOT_INITIALIZED;
                pVars.*.sbrDecoderData.SbrChannel[@as(c_int, 1)].syncState = SBR_NOT_INITIALIZED;
            }
        }
    } else {
        if (@as(c_int, @intFromBool(pVars.*.aacPlusEnabled)) == @as(c_int, 1)) {
            pVars.*.mc_info.upsamplingFactor = if ((samp_rate_info[extensionSamplingFrequencyIndex].samp_rate >> @intCast(@as(c_int, 1))) == samp_rate_info[@bitCast(@as(isize, @intCast(pVars.*.prog_config.sampling_rate_idx)))].samp_rate) @as(c_int, 2) else @as(c_int, 1);
            if (@as(Int, @bitCast(@as(c_uint, @truncate(extensionSamplingFrequencyIndex)))) == pVars.*.prog_config.sampling_rate_idx) {
                if (pVars.*.prog_config.sampling_rate_idx < @as(c_int, 6)) {
                    pVars.*.aacPlusEnabled = @as(c_int, 0) != 0;
                }
                pVars.*.mc_info.bDownSampledSbr = @as(c_int, 1) != 0;
            }
            pVars.*.prog_config.sampling_rate_idx = @bitCast(@as(c_uint, @truncate(extensionSamplingFrequencyIndex)));
        }
    }
    return status;
}

pub fn get_dse(arg_DataStreamBytes: [*c]Char, arg_pInputStream: [*c]BITS) void {
    var DataStreamBytes = arg_DataStreamBytes;
    _ = &DataStreamBytes;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var i: Int = undefined;
    _ = &i;
    var data_byte_align_flag: Int = undefined;
    _ = &data_byte_align_flag;
    var count: UInt = undefined;
    _ = &count;
    var esc_count: Int = undefined;
    _ = &esc_count;
    var pDataStreamBytes: [*c]Char = undefined;
    _ = &pDataStreamBytes;
    pDataStreamBytes = DataStreamBytes;
    _ = get9_n_lessbits(LEN_TAG, pInputStream);
    data_byte_align_flag = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
    count = get9_n_lessbits(LEN_D_CNT, pInputStream);
    if (count == @as(UInt, @bitCast(@as(c_int, (pv_shl(@as(c_int, 1), LEN_D_CNT)) - @as(c_int, 1))))) {
        esc_count = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_D_ESC, pInputStream))));
        count +%= @bitCast(@as(c_int, esc_count));
    }
    if (data_byte_align_flag != 0) {
        byte_align(pInputStream);
    }
    {
        i = @bitCast(@as(c_uint, @truncate(count)));
        while (i != @as(c_int, 0)) : (i -= 1) {
            (blk: {
                const ref = &pDataStreamBytes;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = @bitCast(@as(u8, @truncate(get9_n_lessbits(LEN_BYTE, pInputStream))));
        }
    }
    return;
}

pub fn get_ele_list(arg_pElementList: [*c]EleList, arg_pInputStream: [*c]BITS, enableCPE: Bool) void {
    var pElementList = arg_pElementList;
    _ = &pElementList;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    _ = &enableCPE;
    var index: Int = undefined;
    _ = &index;
    var pEleIsCPE: [*c]Int = undefined;
    _ = &pEleIsCPE;
    var pEleTag: [*c]Int = undefined;
    _ = &pEleTag;
    pEleIsCPE = &pElementList.*.ele_is_cpe[@as(c_int, 0)];
    pEleTag = &pElementList.*.ele_tag[@as(c_int, 0)];
    {
        index = pElementList.*.num_ele;
        while (index > @as(c_int, 0)) : (index -= 1) {
            if (enableCPE != @as(c_int, 0)) {
                (blk: {
                    const ref = &pEleIsCPE;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
            } else {
                (blk: {
                    const ref = &pEleIsCPE;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = 0;
            }
            (blk: {
                const ref = &pEleTag;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_TAG, pInputStream))));
        }
    }
    return;
}

pub fn get_ics_info(audioObjectType: tMP4AudioObjectType, arg_pInputStream: [*c]BITS, common_window: Bool, arg_pWindowSequence: [*c]WINDOW_SEQUENCE, arg_pWindowShape: [*c]WINDOW_SHAPE, arg_group: [*c]Int, arg_p_max_sfb: [*c]Int, arg_p_winmap: [*c][*c]FrameInfo, arg_pFirstLTPStatus: [*c]LT_PRED_STATUS, arg_pSecondLTPStatus: [*c]LT_PRED_STATUS) Int {
    _ = &audioObjectType;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    _ = &common_window;
    var pWindowSequence = arg_pWindowSequence;
    _ = &pWindowSequence;
    var pWindowShape = arg_pWindowShape;
    _ = &pWindowShape;
    var group = arg_group;
    _ = &group;
    var p_max_sfb = arg_p_max_sfb;
    _ = &p_max_sfb;
    var p_winmap = arg_p_winmap;
    _ = &p_winmap;
    var pFirstLTPStatus = arg_pFirstLTPStatus;
    _ = &pFirstLTPStatus;
    var pSecondLTPStatus = arg_pSecondLTPStatus;
    _ = &pSecondLTPStatus;
    var windowSequence: WINDOW_SEQUENCE = undefined;
    _ = &windowSequence;
    var temp: UInt = undefined;
    _ = &temp;
    var predictor_data_present: Bool = undefined;
    _ = &predictor_data_present;
    var local_max_sfb: UInt = undefined;
    _ = &local_max_sfb;
    var allowed_max_sfb: UInt = undefined;
    _ = &allowed_max_sfb;
    var status: Int = 0;
    _ = &status;
    var first_ltp_data_present: Bool = 0;
    _ = &first_ltp_data_present;
    var second_ltp_data_present: Bool = 0;
    _ = &second_ltp_data_present;
    temp = get9_n_lessbits(@bitCast(@as(c_int, (LEN_ICS_RESERV + LEN_WIN_SEQ) + LEN_WIN_SH)), pInputStream);
    windowSequence = (pv_shr(temp, @as(UInt, LEN_WIN_SH))) & @as(UInt, @bitCast(@as(c_int, (pv_shl(@as(c_int, 1), LEN_WIN_SEQ)) - @as(c_int, 1))));
    pWindowShape.* = temp & @as(UInt, @bitCast(@as(c_int, (pv_shl(@as(c_int, 1), LEN_WIN_SH)) - @as(c_int, 1))));
    allowed_max_sfb = @bitCast(@as(c_int, p_winmap[windowSequence].*.sfb_per_win[@as(c_int, 0)]));
    if (windowSequence == @as(WINDOW_SEQUENCE, EIGHT_SHORT_SEQUENCE)) {
        local_max_sfb = get9_n_lessbits(LEN_MAX_SFBS, pInputStream);
        getgroup(group, pInputStream);
        if (local_max_sfb > allowed_max_sfb) {
            status = 1;
        }
    } else {
        group[@as(c_int, 0)] = 1;
        temp = get9_n_lessbits(@bitCast(@as(c_int, LEN_MAX_SFBL + @as(c_int, 1))), pInputStream);
        local_max_sfb = @bitCast(@as(c_int, @as(Int, @bitCast(@as(c_uint, @truncate(pv_shr(temp, @as(UInt, @bitCast(@as(c_int, @as(c_int, 1)))))))))));
        predictor_data_present = @bitCast(@as(c_uint, @truncate(temp & @as(UInt, @bitCast(@as(c_int, (@as(c_int, 1) << @intCast(@as(c_int, 1))) - @as(c_int, 1)))))));
        if (local_max_sfb > allowed_max_sfb) {
            status = 1;
        } else if (audioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_LTP)) {
            if (predictor_data_present != @as(c_int, 0)) {
                first_ltp_data_present = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
                if (first_ltp_data_present != @as(c_int, 0)) {
                    lt_decode(windowSequence, pInputStream, @bitCast(@as(c_uint, @truncate(local_max_sfb))), pFirstLTPStatus);
                }
                if (common_window != @as(c_int, 0)) {
                    second_ltp_data_present = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
                    if (second_ltp_data_present != @as(c_int, 0)) {
                        lt_decode(windowSequence, pInputStream, @bitCast(@as(c_uint, @truncate(local_max_sfb))), pSecondLTPStatus);
                    }
                }
            }
        } else {
            if (predictor_data_present != @as(c_int, 0)) {
                status = 1;
            }
        }
    }
    pFirstLTPStatus.*.ltp_data_present = first_ltp_data_present;
    if (common_window != @as(c_int, 0)) {
        pSecondLTPStatus.*.ltp_data_present = second_ltp_data_present;
    }
    p_max_sfb.* = @bitCast(@as(c_uint, @truncate(local_max_sfb)));
    pWindowSequence.* = windowSequence;
    return status;
}

pub fn get_prog_config(arg_pVars: [*c]tDec_Int_File, arg_pScratchPCE: [*c]ProgConfig) Int {
    var pVars = arg_pVars;
    _ = &pVars;
    var pScratchPCE = arg_pScratchPCE;
    _ = &pScratchPCE;
    var i: Int = undefined;
    _ = &i;
    var tag: UInt = undefined;
    _ = &tag;
    var numChars: Int = undefined;
    _ = &numChars;
    var temp: UInt = undefined;
    _ = &temp;
    var flag: Bool = undefined;
    _ = &flag;
    var status: Int = 0;
    _ = &status;
    var pInputStream: [*c]BITS = &pVars.*.inputStream;
    _ = &pInputStream;
    tag = get9_n_lessbits(LEN_TAG, pInputStream);
    pScratchPCE.*.profile = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_PROFILE, pInputStream))));
    pScratchPCE.*.sampling_rate_idx = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_SAMP_IDX, pInputStream))));
    if (!(pVars.*.adif_test != 0) and (pScratchPCE.*.sampling_rate_idx != pVars.*.prog_config.sampling_rate_idx)) {
        pInputStream.*.usedBits -%= @bitCast(@as(c_int, (LEN_TAG + LEN_PROFILE) + LEN_SAMP_IDX));
        return @as(c_int, 1);
    }
    temp = get9_n_lessbits(LEN_NUM_ELE, pInputStream);
    pScratchPCE.*.front.num_ele = @bitCast(@as(c_uint, @truncate(temp)));
    temp = get9_n_lessbits(LEN_NUM_ELE, pInputStream);
    pScratchPCE.*.side.num_ele = @bitCast(@as(c_uint, @truncate(temp)));
    temp = get9_n_lessbits(LEN_NUM_ELE, pInputStream);
    pScratchPCE.*.back.num_ele = @bitCast(@as(c_uint, @truncate(temp)));
    temp = get9_n_lessbits(LEN_NUM_LFE, pInputStream);
    pScratchPCE.*.lfe.num_ele = @bitCast(@as(c_uint, @truncate(temp)));
    temp = get9_n_lessbits(LEN_NUM_DAT, pInputStream);
    pScratchPCE.*.data.num_ele = @bitCast(@as(c_uint, @truncate(temp)));
    temp = get9_n_lessbits(LEN_NUM_CCE, pInputStream);
    pScratchPCE.*.coupling.num_ele = @bitCast(@as(c_uint, @truncate(temp)));
    flag = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
    pScratchPCE.*.mono_mix.present = flag;
    if (flag != @as(c_int, 0)) {
        temp = get9_n_lessbits(LEN_TAG, pInputStream);
        pScratchPCE.*.mono_mix.ele_tag = @bitCast(@as(c_uint, @truncate(temp)));
    }
    flag = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
    pScratchPCE.*.stereo_mix.present = flag;
    if (flag != @as(c_int, 0)) {
        temp = get9_n_lessbits(LEN_TAG, pInputStream);
        pScratchPCE.*.stereo_mix.ele_tag = @bitCast(@as(c_uint, @truncate(temp)));
    }
    flag = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
    pScratchPCE.*.matrix_mix.present = flag;
    if (flag != @as(c_int, 0)) {
        temp = get9_n_lessbits(LEN_MMIX_IDX, pInputStream);
        pScratchPCE.*.matrix_mix.ele_tag = @bitCast(@as(c_uint, @truncate(temp)));
        temp = get1bits(pInputStream);
        pScratchPCE.*.matrix_mix.pseudo_enab = @bitCast(@as(c_uint, @truncate(temp)));
    }
    get_ele_list(&pScratchPCE.*.front, pInputStream, 1);
    get_ele_list(&pScratchPCE.*.side, pInputStream, 1);
    get_ele_list(&pScratchPCE.*.back, pInputStream, 1);
    get_ele_list(&pScratchPCE.*.lfe, pInputStream, 0);
    get_ele_list(&pScratchPCE.*.data, pInputStream, 0);
    get_ele_list(&pScratchPCE.*.coupling, pInputStream, 1);
    byte_align(pInputStream);
    numChars = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_COMMENT_BYTES, pInputStream))));
    {
        i = numChars;
        while (i > @as(c_int, 0)) : (i -= 1) {
            pScratchPCE.*.comments[@bitCast(@as(isize, @intCast(i)))] = @bitCast(@as(u8, @truncate(get9_n_lessbits(LEN_BYTE, pInputStream))));
        }
    }
    if (pVars.*.current_program < @as(c_int, 0)) {
        pVars.*.current_program = @bitCast(@as(c_uint, @truncate(tag)));
    }
    if (tag == @as(UInt, @bitCast(@as(c_int, pVars.*.current_program)))) {
        _ = memcpy(@ptrCast(@alignCast(&pVars.*.prog_config)), @ptrCast(@alignCast(pScratchPCE)), @sizeOf(ProgConfig));
        status = set_mc_info(&pVars.*.mc_info, @bitCast(pVars.*.prog_config.profile + @as(c_int, 1)), pVars.*.prog_config.sampling_rate_idx, pVars.*.prog_config.front.ele_tag[@as(c_int, 0)], pVars.*.prog_config.front.ele_is_cpe[@as(c_int, 0)], @ptrCast(@alignCast(&pVars.*.winmap)), @ptrCast(@alignCast(&pVars.*.SFBWidth128)));
    }
    return status;
}

pub fn get_pulse_data(arg_pPulseInfo: [*c]PulseInfo, arg_pInputStream: [*c]BITS) Int {
    var pPulseInfo = arg_pPulseInfo;
    _ = &pPulseInfo;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var i: Int = undefined;
    _ = &i;
    var pPulseOffset: [*c]Int = undefined;
    _ = &pPulseOffset;
    var pPulseAmp: [*c]Int = undefined;
    _ = &pPulseAmp;
    var status: Int = 0;
    _ = &status;
    var temp: UInt = undefined;
    _ = &temp;
    temp = get9_n_lessbits(@bitCast(@as(c_int, LEN_PULSE_NPULSE + LEN_PULSE_ST_SFB)), pInputStream);
    pPulseInfo.*.number_pulse = @bitCast(@as(c_uint, @truncate(@as(UInt, 1) +% (pv_shr(temp, @as(UInt, LEN_PULSE_ST_SFB))))));
    pPulseInfo.*.pulse_start_sfb = @bitCast(@as(c_uint, @truncate(temp & @as(UInt, @bitCast(@as(c_int, (pv_shl(@as(c_int, 1), LEN_PULSE_ST_SFB)) - @as(c_int, 1)))))));
    pPulseOffset = &pPulseInfo.*.pulse_offset[@as(c_int, 0)];
    pPulseAmp = &pPulseInfo.*.pulse_amp[@as(c_int, 0)];
    {
        i = pPulseInfo.*.number_pulse;
        while (i > @as(c_int, 0)) : (i -= 1) {
            temp = get9_n_lessbits(@bitCast(@as(c_int, LEN_PULSE_POFF + LEN_PULSE_PAMP)), pInputStream);
            (blk: {
                const ref = &pPulseOffset;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = @bitCast(@as(c_uint, @truncate(pv_shr(temp, @as(UInt, LEN_PULSE_PAMP)))));
            (blk: {
                const ref = &pPulseAmp;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = @bitCast(@as(c_uint, @truncate(temp & @as(UInt, @bitCast(@as(c_int, (pv_shl(@as(c_int, 1), LEN_PULSE_PAMP)) - @as(c_int, 1)))))));
        }
    }
    return status;
}

pub fn get_sbr_bitstream(arg_sbrBitStream: [*c]SBRBITSTREAM, arg_pInputStream: [*c]BITS) void {
    var sbrBitStream = arg_sbrBitStream;
    _ = &sbrBitStream;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var count: Int32 = undefined;
    _ = &count;
    var esc_count: Int32 = undefined;
    _ = &esc_count;
    var Extention_Type: Int32 = undefined;
    _ = &Extention_Type;
    var i: Int32 = undefined;
    _ = &i;
    count = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_F_CNT, pInputStream))));
    if (count == @as(c_int, 15)) {
        esc_count = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_F_ESC, pInputStream))));
        count = esc_count + @as(c_int, 14);
    }
    Extention_Type = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_F_CNT, pInputStream))));
    if (((((Extention_Type == @as(c_int, 13)) or (Extention_Type == @as(c_int, 14))) and (count < @as(c_int, 1024))) and (count != 0)) and (sbrBitStream.*.NrElements < @as(c_int, 1))) {
        sbrBitStream.*.sbrElement[@bitCast(@as(isize, @intCast(sbrBitStream.*.NrElements)))].ExtensionType = Extention_Type;
        sbrBitStream.*.sbrElement[@bitCast(@as(isize, @intCast(sbrBitStream.*.NrElements)))].Payload = count;
        sbrBitStream.*.sbrElement[@bitCast(@as(isize, @intCast(sbrBitStream.*.NrElements)))].Data[@as(c_int, 0)] = @truncate(get9_n_lessbits(LEN_F_CNT, pInputStream));
        {
            i = 1;
            while (i < count) : (i += 1) {
                sbrBitStream.*.sbrElement[@bitCast(@as(isize, @intCast(sbrBitStream.*.NrElements)))].Data[@bitCast(@as(isize, @intCast(i)))] = @truncate(get9_n_lessbits(8, pInputStream));
            }
        }
        sbrBitStream.*.NrElements += 1;
    } else {
        pInputStream.*.usedBits +%= @bitCast(@as(c_int, (count - @as(c_int, 1)) * LEN_BYTE));
        pInputStream.*.usedBits +%= 4;
    }
}

pub fn get_sbr_startfreq(fs: Int32, start_freq: Int32) Int {
    _ = &fs;
    _ = &start_freq;
    var k0_min: Int = 0;
    _ = &k0_min;
    var index: Int32 = undefined;
    _ = &index;
    blk: {
        switch (fs) {
            @as(c_int, 16000) => {
                index = 0;
                k0_min = 24;
                break :blk;
            },
            @as(c_int, 22050) => {
                index = 1;
                k0_min = 17;
                break :blk;
            },
            @as(c_int, 24000) => {
                index = 2;
                k0_min = 16;
                break :blk;
            },
            @as(c_int, 32000) => {
                index = 3;
                k0_min = 16;
                break :blk;
            },
            @as(c_int, 44100) => {
                index = 4;
                k0_min = 12;
                break :blk;
            },
            @as(c_int, 48000) => {
                index = 4;
                k0_min = 11;
                break :blk;
            },
            @as(c_int, 64000) => {
                index = 4;
                k0_min = 10;
                break :blk;
            },
            @as(c_int, 88200), @as(c_int, 96000) => {
                index = 5;
                k0_min = 7;
                break :blk;
            },
            else => {
                index = 6;
            },
        }
    }
    return k0_min + v_offset[@bitCast(@as(isize, @intCast(index)))][@bitCast(@as(isize, @intCast(start_freq)))];
}

pub fn get_sbr_stopfreq(fs: Int32, stop_freq: Int32) Int {
    _ = &fs;
    _ = &stop_freq;
    var i: Int = undefined;
    _ = &i;
    blk: {
        switch (fs) {
            @as(c_int, 48000) => {
                i = 0;
                break :blk;
            },
            @as(c_int, 32000), @as(c_int, 24000) => {
                i = 2;
                break :blk;
            },
            @as(c_int, 22050) => {
                i = 3;
                break :blk;
            },
            @as(c_int, 16000) => {
                i = 4;
                break :blk;
            },
            else => {
                i = 1;
                break :blk;
            },
        }
    }
    return @as(Int, sbr_stopfreq_tbl[@bitCast(@as(isize, @intCast(i)))][@bitCast(@as(isize, @intCast(stop_freq)))]);
}

pub fn get_tns(max_bands: Int, pInputStream: [*c]BITS, wnd_seq: WINDOW_SEQUENCE, pFrameInfo: [*c]const FrameInfo, pMC_Info: [*c]const MC_Info, pTnsFrameInfo: [*c]TNS_frame_info, arg_scratchTnsDecCoefMem: [*c]Int32) void {
    _ = &max_bands;
    _ = &pInputStream;
    _ = &wnd_seq;
    _ = &pFrameInfo;
    _ = &pMC_Info;
    _ = &pTnsFrameInfo;
    var scratchTnsDecCoefMem = arg_scratchTnsDecCoefMem;
    _ = &scratchTnsDecCoefMem;
    const pSFB_top: [*c]const Int16 = pFrameInfo.*.win_sfb_top[@as(c_int, 0)];
    _ = &pSFB_top;
    var f: Int = undefined;
    _ = &f;
    var t: Int = undefined;
    _ = &t;
    var win: Int = undefined;
    _ = &win;
    var tempInt: UInt = undefined;
    _ = &tempInt;
    var num_filt_bits: Int = undefined;
    _ = &num_filt_bits;
    var num_order_bits: Int = undefined;
    _ = &num_order_bits;
    var num_start_band_bits: Int = undefined;
    _ = &num_start_band_bits;
    var top: Int = undefined;
    _ = &top;
    var res: Int = undefined;
    _ = &res;
    var res_index: Int = undefined;
    _ = &res_index;
    var compress: Int = undefined;
    _ = &compress;
    var sfb_per_win: Int = undefined;
    _ = &sfb_per_win;
    var pLpcCoef: [*c]Int32 = undefined;
    _ = &pLpcCoef;
    var pStartLpcCoef: [*c]Int32 = undefined;
    _ = &pStartLpcCoef;
    var s_mask: Int = undefined;
    _ = &s_mask;
    var n_mask: Int = undefined;
    _ = &n_mask;
    var tns_bands: Int = undefined;
    _ = &tns_bands;
    var max_order: UInt = undefined;
    _ = &max_order;
    var coef_res: Int = undefined;
    _ = &coef_res;
    var pFilt: [*c]TNSfilt = undefined;
    _ = &pFilt;
    if (wnd_seq != @as(WINDOW_SEQUENCE, EIGHT_SHORT_SEQUENCE)) {
        num_filt_bits = 2;
        num_order_bits = 5;
        num_start_band_bits = 6;
        tns_bands = tns_max_bands_tbl_long_wndw[@bitCast(@as(isize, @intCast(pMC_Info.*.sampling_rate_idx)))];
        if (pMC_Info.*.sampling_rate_idx > @as(c_int, 4)) {
            max_order = 20;
        } else {
            max_order = 12;
        }
    } else {
        num_filt_bits = 1;
        num_order_bits = 3;
        num_start_band_bits = 4;
        tns_bands = tns_max_bands_tbl_short_wndw[@bitCast(@as(isize, @intCast(pMC_Info.*.sampling_rate_idx)))];
        max_order = 7;
    }
    if (max_bands < tns_bands) {
        tns_bands = max_bands;
    }
    sfb_per_win = pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
    win = 0;
    pLpcCoef = @ptrCast(@alignCast(&pTnsFrameInfo.*.lpc_coef));
    pFilt = @ptrCast(@alignCast(&pTnsFrameInfo.*.filt));
    while (true) {
        tempInt = get9_n_lessbits(@bitCast(@as(c_int, num_filt_bits)), pInputStream);
        pTnsFrameInfo.*.n_filt[@bitCast(@as(isize, @intCast(win)))] = @bitCast(@as(c_uint, @truncate(tempInt)));
        if (tempInt != @as(UInt, 0)) {
            res = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
            coef_res = blk: {
                const ref = &res;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            };
            top = sfb_per_win;
            {
                f = pTnsFrameInfo.*.n_filt[@bitCast(@as(isize, @intCast(win)))];
                while (f > @as(c_int, 0)) : (f -= 1) {
                    tempInt = @bitCast(@as(c_int, if (top < tns_bands) top else tns_bands));
                    pFilt.*.stop_coef = if (tempInt > @as(UInt, 0)) @as(c_int, pSFB_top[tempInt -% @as(UInt, 1)]) else @as(c_int, 0);
                    pFilt.*.stop_band = @bitCast(@as(c_uint, @truncate(tempInt)));
                    // AAC TNS lengths can extend below the lowest scalefactor
                    // band. Clamp the bottom before indexing the band table.
                    const length = get9_n_lessbits(@intCast(num_start_band_bits), pInputStream);
                    top = if (length >= @as(UInt, @intCast(top))) 0 else top - @as(Int, @intCast(length));
                    tempInt = @bitCast(@as(c_int, if (top < tns_bands) top else tns_bands));
                    pFilt.*.start_coef = if (tempInt > @as(UInt, 0)) @as(c_int, pSFB_top[tempInt -% @as(UInt, 1)]) else @as(c_int, 0);
                    pFilt.*.start_band = @bitCast(@as(c_uint, @truncate(tempInt)));
                    tempInt = get9_n_lessbits(@bitCast(@as(c_int, num_order_bits)), pInputStream);
                    pFilt.*.order = tempInt;
                    if (tempInt != @as(UInt, 0)) {
                        if (tempInt > max_order) {
                            pFilt.*.order = max_order;
                        }
                        tempInt = get1bits(pInputStream);
                        pFilt.*.direction = -@as(Int, @bitCast(@as(c_uint, @truncate(tempInt)))) | @as(c_int, 1);
                        compress = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
                        res_index = res - compress;
                        s_mask = pv_shl(@as(c_int, 2), res_index);
                        res_index += 2;
                        pStartLpcCoef = pLpcCoef;
                        {
                            t = @bitCast(@as(c_uint, @truncate(pFilt.*.order)));
                            while (t > @as(c_int, 0)) : (t -= 1) {
                                tempInt = get9_n_lessbits(@bitCast(@as(c_int, res_index)), pInputStream);
                                n_mask = -(@as(Int, @bitCast(@as(c_uint, @truncate(tempInt)))) & s_mask);
                                (blk: {
                                    const ref = &pLpcCoef;
                                    const tmp = ref.*;
                                    ref.* += 1;
                                    break :blk tmp;
                                }).* = @bitCast(@as(c_uint, @truncate(tempInt | @as(UInt, @bitCast(@as(c_int, n_mask))))));
                            }
                        }
                        tempInt = @bitCast(@as(c_int, pFilt.*.stop_coef - pFilt.*.start_coef));
                        if (tempInt > @as(UInt, 0)) {
                            pFilt.*.q_lpc = tns_decode_coef(@bitCast(@as(c_uint, @truncate(pFilt.*.order))), coef_res, pStartLpcCoef, scratchTnsDecCoefMem);
                        }
                    }
                    pFilt += 1;
                }
            }
        }
        win += 1;
        if (!(win < pFrameInfo.*.num_win)) break;
    }
    return;
}

pub fn getbits(neededBits: UInt, arg_pInputStream: [*c]BITS) UInt32 {
    _ = &neededBits;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var returnValue: UInt32 = 0;
    _ = &returnValue;
    var offset: UInt = undefined;
    _ = &offset;
    var bitIndex: UInt = undefined;
    _ = &bitIndex;
    var pElem: [*c]UChar = undefined;
    _ = &pElem;
    offset = pv_shr(pInputStream.*.usedBits, @as(UInt, @bitCast(@as(c_int, @as(c_int, 3)))));
    pElem = pInputStream.*.pBuffer + offset;
    offset = pInputStream.*.inputBufferCurrentLength -% offset;
    if (offset > @as(UInt, 3)) {
        returnValue = (((pv_shl(@as(UInt32, pElem.*), @as(UInt32, 24))) | (pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*), @as(UInt32, 16)))) | (pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))))).*), @as(UInt32, 8)))) | @as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 3)))))).*);
    } else {
        blk: {
            switch (offset) {
                @as(UInt, 3) => {
                    returnValue = pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))))).*), @as(UInt32, 8));
                    returnValue |= pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*), @as(UInt32, 16));
                    returnValue |= pv_shl(@as(UInt32, pElem.*), @as(UInt32, 24));
                    break :blk;
                },
                @as(UInt, 2) => {
                    returnValue |= pv_shl(@as(UInt32, (pElem + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*), @as(UInt32, 16));
                    returnValue |= pv_shl(@as(UInt32, pElem.*), @as(UInt32, 24));
                    break :blk;
                },
                @as(UInt, 1) => {
                    returnValue |= pv_shl(@as(UInt32, pElem.*), @as(UInt32, 24));
                    break :blk;
                },
                else => {
                    break :blk;
                },
            }
        }
    }
    bitIndex = pInputStream.*.usedBits & @as(UInt, @bitCast(@as(c_int, (@as(c_int, 1) << @intCast(@as(c_int, 3))) - @as(c_int, 1))));
    returnValue = pv_shl(returnValue, bitIndex);
    returnValue = pv_shr(returnValue, @as(UInt, 32) -% neededBits);
    pInputStream.*.usedBits +%= neededBits;
    return returnValue;
}

pub fn getfill(arg_pInputStream: [*c]BITS) void {
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var cnt: Int = undefined;
    _ = &cnt;
    var esc_cnt: Int = undefined;
    _ = &esc_cnt;
    cnt = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_F_CNT, pInputStream))));
    if (cnt == ((pv_shl(@as(c_int, 1), LEN_F_CNT)) - @as(c_int, 1))) {
        esc_cnt = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_F_ESC, pInputStream))));
        cnt += esc_cnt - @as(c_int, 1);
    }
    pInputStream.*.usedBits +%= @bitCast(@as(c_int, cnt * LEN_BYTE));
}

pub fn getgroup(arg_group: [*c]Int, arg_pInputStream: [*c]BITS) void {
    var group = arg_group;
    _ = &group;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var win: Int = undefined;
    _ = &win;
    var pGroup: [*c]Int = undefined;
    _ = &pGroup;
    var mask: UInt = undefined;
    _ = &mask;
    var groupBits: UInt = undefined;
    _ = &groupBits;
    pGroup = group;
    mask = 64;
    groupBits = get9_n_lessbits(7, pInputStream);
    {
        win = 1;
        while (win < @as(c_int, 8)) : (win += 1) {
            if ((groupBits & mask) == @as(UInt, 0)) {
                (blk: {
                    const ref = &pGroup;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = win;
            }
            mask >>= @intCast(@as(UInt, 1));
        }
    }
    pGroup.* = win;
}

pub fn getics(arg_pInputStream: [*c]BITS, arg_common_window: Int, arg_pVars: [*c]tDec_Int_File, arg_pChVars: [*c]tDec_Int_Chan, arg_group: [*c]Int, arg_pMax_sfb: [*c]Int, arg_pCodebookMap: [*c]Int, arg_pTnsFrameInfo: [*c]TNS_frame_info, arg_pWinMap: [*c][*c]FrameInfo, arg_pPulseInfo: [*c]PulseInfo, arg_sect: [*c]SectInfo) Int {
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var common_window = arg_common_window;
    _ = &common_window;
    var pVars = arg_pVars;
    _ = &pVars;
    var pChVars = arg_pChVars;
    _ = &pChVars;
    var group = arg_group;
    _ = &group;
    var pMax_sfb = arg_pMax_sfb;
    _ = &pMax_sfb;
    var pCodebookMap = arg_pCodebookMap;
    _ = &pCodebookMap;
    var pTnsFrameInfo = arg_pTnsFrameInfo;
    _ = &pTnsFrameInfo;
    var pWinMap = arg_pWinMap;
    _ = &pWinMap;
    var pPulseInfo = arg_pPulseInfo;
    _ = &pPulseInfo;
    var sect = arg_sect;
    _ = &sect;
    var status: Int = 0;
    _ = &status;
    var nsect: Int = 0;
    _ = &nsect;
    var i: Int = undefined;
    _ = &i;
    var cb: Int = undefined;
    _ = &cb;
    var sectWidth: Int = undefined;
    _ = &sectWidth;
    var sectStart: Int = undefined;
    _ = &sectStart;
    var totSfb: Int = undefined;
    _ = &totSfb;
    var pGroup: [*c]Int = undefined;
    _ = &pGroup;
    var pFrameInfo: [*c]FrameInfo = undefined;
    _ = &pFrameInfo;
    var global_gain: Int = undefined;
    _ = &global_gain;
    var present: Bool = undefined;
    _ = &present;
    pGroup = group;
    global_gain = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_SCL_PCM, pInputStream))));
    if (common_window == @as(c_int, 0)) {
        status = get_ics_info(pVars.*.mc_info.audioObjectType, pInputStream, common_window, &pChVars.*.wnd, &pChVars.*.wnd_shape_this_bk, group, pMax_sfb, pWinMap, &pChVars.*.pShareWfxpCoef.*.lt_status, null);
    }
    pFrameInfo = pWinMap[pChVars.*.wnd];
    if (pMax_sfb.* > @as(c_int, 0)) {
        i = 0;
        totSfb = 0;
        while (true) {
            totSfb += 1;
            if (!((blk: {
                const ref = &pGroup;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* < pFrameInfo.*.num_win)) break;
        }
        totSfb *= pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
        nsect = huffcb(sect, pInputStream, @ptrCast(@alignCast(&pFrameInfo.*.sectbits)), totSfb, pFrameInfo.*.sfb_per_win[@as(c_int, 0)], pMax_sfb.*);
        if (nsect == @as(c_int, 0)) {
            status = 1;
        }
        sectStart = 0;
        {
            i = 0;
            while (i < nsect) : (i += 1) {
                cb = sect[@bitCast(@as(isize, @intCast(i)))].sect_cb;
                sectWidth = sect[@bitCast(@as(isize, @intCast(i)))].sect_end - sectStart;
                sectStart += sectWidth;
                while (sectWidth > @as(c_int, 0)) {
                    (blk: {
                        const ref = &pCodebookMap;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = cb;
                    sectWidth -= 1;
                }
            }
        }
    } else {
        _ = memset(@ptrCast(@alignCast(pCodebookMap)), ZERO_HCB, @as(c_ulong, MAXBANDS) *% @sizeOf(@TypeOf(pCodebookMap.*)));
    }
    if (pFrameInfo.*.islong == @as(c_int, 0)) {
        calc_gsfb_table(pFrameInfo, group);
    }
    if (status == @as(c_int, 0)) {
        status = hufffac(pFrameInfo, pInputStream, group, nsect, sect, global_gain, @ptrCast(@alignCast(&pChVars.*.pShareWfxpCoef.*.factors)), @ptrCast(@alignCast(&pVars.*.scratch.huffbook_used)));
    }
    if (status == @as(c_int, 0)) {
        present = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
        pPulseInfo.*.pulse_data_present = present;
        if (present != @as(c_int, 0)) {
            if (pFrameInfo.*.islong == @as(c_int, 1)) {
                status = get_pulse_data(pPulseInfo, pInputStream);
            } else {
                status = 1;
            }
        }
    }
    if (status == @as(c_int, 0)) {
        present = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
        pTnsFrameInfo.*.tns_data_present = present;
        if (present != @as(c_int, 0)) {
            get_tns(pChVars.*.pShareWfxpCoef.*.max_sfb, pInputStream, pChVars.*.wnd, pFrameInfo, &pVars.*.mc_info, pTnsFrameInfo, @ptrCast(@alignCast(&pVars.*.scratch.tns_decode_coef)));
        } else {
            {
                i = pFrameInfo.*.num_win - @as(c_int, 1);
                while (i >= @as(c_int, 0)) : (i -= 1) {
                    pTnsFrameInfo.*.n_filt[@bitCast(@as(isize, @intCast(i)))] = 0;
                }
            }
        }
    }
    if (status == @as(c_int, 0)) {
        present = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
        if (present != @as(c_int, 0)) {
            status = 1;
        }
    }
    if (status == @as(c_int, 0)) {
        status = huffspec_fxp(pFrameInfo, pInputStream, nsect, sect, @ptrCast(@alignCast(&pChVars.*.pShareWfxpCoef.*.factors)), pChVars.*.fxpCoef, @ptrCast(@alignCast(&pVars.*.share.a.quantSpec)), @ptrCast(@alignCast(&pVars.*.scratch.tmp_spec)), pWinMap[ONLY_LONG_WINDOW], pPulseInfo, @ptrCast(@alignCast(&pChVars.*.pShareWfxpCoef.*.qFormat)));
    }
    return status;
}

pub fn getmask(arg_pFrameInfo: [*c]FrameInfo, arg_pInputStream: [*c]BITS, arg_group: [*c]Int, arg_max_sfb: Int, arg_mask: [*c]Int) Int {
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var group = arg_group;
    _ = &group;
    var max_sfb = arg_max_sfb;
    _ = &max_sfb;
    var mask = arg_mask;
    _ = &mask;
    var win: Int = undefined;
    _ = &win;
    var sfb: Int = undefined;
    _ = &sfb;
    var mask_present: Int = undefined;
    _ = &mask_present;
    var pMask: [*c]Int = undefined;
    _ = &pMask;
    var pGroup: [*c]Int = undefined;
    _ = &pGroup;
    var nwin: Int = undefined;
    _ = &nwin;
    var nCall: Int = undefined;
    _ = &nCall;
    var nToDo: Int = undefined;
    _ = &nToDo;
    var tempMask: UInt32 = undefined;
    _ = &tempMask;
    var bitmask: UInt32 = undefined;
    _ = &bitmask;
    pMask = mask;
    pGroup = group;
    mask_present = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_MASK_PRES, pInputStream))));
    blk: {
        switch (mask_present) {
            MASK_NOT_PRESENT => {
                break :blk;
            },
            MASK_ALL_FRAME => {
                nwin = pFrameInfo.*.num_win;
                {
                    win = 0;
                    while (win < nwin) : (win = (blk_1: {
                        const ref = &pGroup;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk_1 tmp;
                    }).*) {
                        {
                            sfb = pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(win)))];
                            while (sfb > @as(c_int, 0)) : (sfb -= 1) {
                                (blk_1: {
                                    const ref = &pMask;
                                    const tmp = ref.*;
                                    ref.* += 1;
                                    break :blk_1 tmp;
                                }).* = 1;
                            }
                        }
                    }
                }
                break :blk;
            },
            MASK_FROM_BITSTREAM => {
                nwin = pFrameInfo.*.num_win;
                {
                    win = 0;
                    while (win < nwin) : (win = (blk_1: {
                        const ref = &pGroup;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk_1 tmp;
                    }).*) {
                        nToDo = max_sfb;
                        while (nToDo > @as(c_int, 0)) {
                            nCall = nToDo;
                            if (nCall > @as(c_int, 25)) {
                                nCall = @as(c_int, 25);
                            }
                            tempMask = getbits(@bitCast(@as(c_int, nCall)), pInputStream);
                            bitmask = pv_shl(@as(UInt32, @bitCast(@as(c_int, @as(c_int, 1)))), @as(UInt32, @bitCast(@as(c_int, nCall - @as(c_int, 1)))));
                            {
                                sfb = nCall;
                                while (sfb > @as(c_int, 0)) : (sfb -= 1) {
                                    (blk_1: {
                                        const ref = &pMask;
                                        const tmp = ref.*;
                                        ref.* += 1;
                                        break :blk_1 tmp;
                                    }).* = @bitCast(@as(c_uint, @truncate(pv_shr((tempMask & bitmask), @as(UInt32, @bitCast(@as(c_int, sfb - @as(c_int, 1))))))));
                                    bitmask >>= @intCast(@as(UInt32, 1));
                                }
                            }
                            nToDo -= nCall;
                        }
                        nCall = pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(win)))] - max_sfb;
                        if (nCall >= @as(c_int, 0)) {
                            _ = memset(@ptrCast(@alignCast(pMask)), 0, @as(c_ulong, @bitCast(@as(c_long, nCall))) *% @sizeOf(@TypeOf(pMask.*)));
                            pMask += @as(usize, @bitCast(@as(isize, @intCast(nCall))));
                        } else {
                            mask_present = MASK_ERROR;
                            break;
                        }
                    }
                }
                break :blk;
            },
            else => {
                break :blk;
            },
        }
    }
    return mask_present;
}

