pub fn high_freq_coeff(arg_sourceBufferReal: [*c][32]Int32, arg_sourceBufferImag: [*c][32]Int32, arg_alphar: [*c][*c]Int32, arg_alphai: [*c][*c]Int32, arg_v_k_master: [*c]Int32) void {
    var sourceBufferReal = arg_sourceBufferReal;
    _ = &sourceBufferReal;
    var sourceBufferImag = arg_sourceBufferImag;
    _ = &sourceBufferImag;
    var alphar = arg_alphar;
    _ = &alphar;
    var alphai = arg_alphai;
    _ = &alphai;
    var v_k_master = arg_v_k_master;
    _ = &v_k_master;
