                temp1r = 0;
                temp1i = 0;
                alphar[@as(c_int, 1)][@bitCast(@as(isize, @intCast(loBand)))] = 0;
                alphai[@as(c_int, 1)][@bitCast(@as(isize, @intCast(loBand)))] = 0;
            } else {
                temp1r = fxp_mul32_Q29(ac.r01r, ac.r12r);
                temp1r = fxp_msu32_Q29(ac.r01i, ac.r12i, temp1r);
