                temp1i = pv_shr(quotient.quotient, @as(c_int, 2) + quotient.shift_factor);
                alphar[@as(c_int, 1)][@bitCast(@as(isize, @intCast(loBand)))] = temp1r;
                alphai[@as(c_int, 1)][@bitCast(@as(isize, @intCast(loBand)))] = temp1i;
            }
            if (ac.r11r == @as(c_int, 0)) {
                temp0r = 0;
                temp0i = 0;
                alphar[@as(c_int, 0)][@bitCast(@as(isize, @intCast(loBand)))] = 0;
                alphai[@as(c_int, 0)][@bitCast(@as(isize, @intCast(loBand)))] = 0;
            } else {
                temp0r = -((ac.r01r + fxp_mul32_Q28(temp1r, ac.r12r)) + fxp_mul32_Q28(temp1i, ac.r12i));
                temp0i = -((ac.r01i + fxp_mul32_Q28(temp1i, ac.r12r)) - fxp_mul32_Q28(temp1r, ac.r12i));
