pub fn huffcb(arg_pSect: [*c]SectInfo, arg_pInputStream: [*c]BITS, arg_sectbits: [*c]Int, arg_tot_sfb: Int, arg_sfb_per_win: Int, arg_max_sfb: Int) Int {
    var pSect = arg_pSect;
    _ = &pSect;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var sectbits = arg_sectbits;
    _ = &sectbits;
    var tot_sfb = arg_tot_sfb;
    _ = &tot_sfb;
    var sfb_per_win = arg_sfb_per_win;
    _ = &sfb_per_win;
    var max_sfb = arg_max_sfb;
    _ = &max_sfb;
    var base: Int = undefined;
    _ = &base;
    var sect_len_incr: Int = undefined;
    _ = &sect_len_incr;
    var esc_val: Int = undefined;
    _ = &esc_val;
    var bits: Int = undefined;
    _ = &bits;
    var num_sect: Int = undefined;
    _ = &num_sect;
    var active_sfb: Int = undefined;
    _ = &active_sfb;
    var group_base: Int = undefined;
    _ = &group_base;
    bits = sectbits[@as(c_int, 0)];
    esc_val = (pv_shl(@as(c_int, 1), bits)) - @as(c_int, 1);
    num_sect = 0;
    base = 0;
    group_base = 0;
    while ((base < tot_sfb) and (num_sect < tot_sfb)) {
        pSect.*.sect_cb = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(LEN_CB, pInputStream))));
        sect_len_incr = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(@bitCast(@as(c_int, bits)), pInputStream))));
        while ((sect_len_incr == esc_val) and (base < tot_sfb)) {
            base += esc_val;
            sect_len_incr = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(@bitCast(@as(c_int, bits)), pInputStream))));
        }
        base += sect_len_incr;
        pSect.*.sect_end = base;
        pSect += 1;
        num_sect += 1;
        active_sfb = base - group_base;
        if ((active_sfb == max_sfb) and (active_sfb < tot_sfb)) {
            base += sfb_per_win - max_sfb;
            pSect.*.sect_cb = 0;
            pSect.*.sect_end = base;
            num_sect += 1;
            pSect += 1;
            group_base = base;
        } else if (active_sfb > max_sfb) {
            break;
        }
    }
    if ((base != tot_sfb) or (num_sect > tot_sfb)) {
        num_sect = 0;
    }
    return num_sect;
}

pub fn huffdecode(arg_id_syn_ele: Int, arg_pInputStream: [*c]BITS, arg_pVars: [*c]tDec_Int_File, arg_pChVars: [*c][*c]tDec_Int_Chan) Int {
    var id_syn_ele = arg_id_syn_ele;
    _ = &id_syn_ele;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var pVars = arg_pVars;
    _ = &pVars;
    var pChVars = arg_pChVars;
    _ = &pChVars;
    var ch: Int = undefined;
    _ = &ch;
    var common_window: Int = undefined;
    _ = &common_window;
    var hasmask: Int = undefined;
    _ = &hasmask;
    var status: Int = 0;
    _ = &status;
    var num_channels: Int = 0;
    _ = &num_channels;
    var pMcInfo: [*c]MC_Info = undefined;
    _ = &pMcInfo;
    var pChLeftShare: [*c]per_chan_share_w_fxpCoef = undefined;
    _ = &pChLeftShare;
    var pChRightShare: [*c]per_chan_share_w_fxpCoef = undefined;
    _ = &pChRightShare;
    _ = get9_n_lessbits(LEN_TAG, pInputStream);
    common_window = 0;
    if (id_syn_ele == ID_CPE) {
        common_window = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
    }
    pMcInfo = &pVars.*.mc_info;
    if (pMcInfo.*.ch_info[@as(c_int, 0)].cpe != id_syn_ele) {
        if (pVars.*.mc_info.implicit_channeling != 0) {
            pMcInfo.*.ch_info[@as(c_int, 0)].cpe = id_syn_ele & @as(c_int, 1);
            pMcInfo.*.nch = (id_syn_ele & @as(c_int, 1)) + @as(c_int, 1);
        } else {
            status = 1;
        }
    }
    if (status == @as(c_int, 0)) {
        if (id_syn_ele == ID_SCE) {
            num_channels = 1;
            pVars.*.hasmask = 0;
        } else if (id_syn_ele == ID_CPE) {
            pChLeftShare = pChVars[@as(c_int, 0)].*.pShareWfxpCoef;
            pChRightShare = pChVars[@as(c_int, 1)].*.pShareWfxpCoef;
            num_channels = 2;
            if (common_window != @as(c_int, 0)) {
                status = get_ics_info(pVars.*.mc_info.audioObjectType, pInputStream, common_window, &pChVars[@as(c_int, 0)].*.wnd, &pChVars[@as(c_int, 0)].*.wnd_shape_this_bk, @ptrCast(@alignCast(&pChLeftShare.*.group)), &pChLeftShare.*.max_sfb, @ptrCast(@alignCast(&pVars.*.winmap)), &pChLeftShare.*.lt_status, &pChRightShare.*.lt_status);
                if (status == @as(c_int, 0)) {
                    pChVars[@as(c_int, 1)].*.wnd = pChVars[@as(c_int, 0)].*.wnd;
                    pChVars[@as(c_int, 1)].*.wnd_shape_this_bk = pChVars[@as(c_int, 0)].*.wnd_shape_this_bk;
                    pChRightShare.*.max_sfb = pChLeftShare.*.max_sfb;
                    _ = memcpy(@ptrCast(@alignCast(@as([*c]Int, @ptrCast(@alignCast(&pChRightShare.*.group))))), @ptrCast(@alignCast(@as([*c]Int, @ptrCast(@alignCast(&pChLeftShare.*.group))))), @as(c_ulong, NSHORT) *% @sizeOf(@TypeOf(pChLeftShare.*.group[@as(c_int, 0)])));
                    hasmask = getmask(pVars.*.winmap[pChVars[@as(c_int, 0)].*.wnd], pInputStream, @ptrCast(@alignCast(&pChLeftShare.*.group)), pChLeftShare.*.max_sfb, @ptrCast(@alignCast(&pVars.*.mask)));
                    if (hasmask == MASK_ERROR) {
                        status = 1;
                    }
                    pVars.*.hasmask = hasmask;
                }
            } else {
                pVars.*.hasmask = 0;
            }
        }
    }
    ch = 0;
    while ((ch < num_channels) and (status == @as(c_int, 0))) {
        pChLeftShare = pChVars[@bitCast(@as(isize, @intCast(ch)))].*.pShareWfxpCoef;
        status = getics(pInputStream, common_window, pVars, pChVars[@bitCast(@as(isize, @intCast(ch)))], @ptrCast(@alignCast(&pChLeftShare.*.group)), &pChLeftShare.*.max_sfb, @ptrCast(@alignCast(&pChLeftShare.*.cb_map)), &pChLeftShare.*.tns, @ptrCast(@alignCast(&pVars.*.winmap)), &pVars.*.share.a.pulseInfo, @ptrCast(@alignCast(&pVars.*.share.a.sect)));
        ch += 1;
    }
    return status;
}

pub fn hufffac(arg_pFrameInfo: [*c]FrameInfo, arg_pInputStream: [*c]BITS, arg_pGroup: [*c]Int, arg_nsect: Int, arg_pSect: [*c]SectInfo, arg_global_gain: Int, arg_pFactors: [*c]Int, arg_huffBookUsed: [*c]Int) Int {
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var pGroup = arg_pGroup;
    _ = &pGroup;
    var nsect = arg_nsect;
    _ = &nsect;
    var pSect = arg_pSect;
    _ = &pSect;
    var global_gain = arg_global_gain;
    _ = &global_gain;
    var pFactors = arg_pFactors;
    _ = &pFactors;
    var huffBookUsed = arg_huffBookUsed;
    _ = &huffBookUsed;
    var sect_idx: Int = undefined;
    _ = &sect_idx;
    var group_end: Int = undefined;
    _ = &group_end;
    var group_win: Int = undefined;
    _ = &group_win;
    var cw_index: Int = undefined;
    _ = &cw_index;
    var nsfb_win: Int = undefined;
    _ = &nsfb_win;
    var sfb: Int = undefined;
    _ = &sfb;
    var sect_cb: Int = undefined;
    _ = &sect_cb;
    var fac: Int = undefined;
    _ = &fac;
    var is_pos: Int = undefined;
    _ = &is_pos;
    var noise_pcm_flag: Int = 1;
    _ = &noise_pcm_flag;
    var dpcm_noise_nrg: Int = undefined;
    _ = &dpcm_noise_nrg;
    var noise_nrg: Int = undefined;
    _ = &noise_nrg;
    var status: Int = 0;
    _ = &status;
    var pHuffBookUsed: [*c]Int = &huffBookUsed[@as(c_int, 0)];
    _ = &pHuffBookUsed;
    _ = memset(@ptrCast(@alignCast(pFactors)), ZERO_HCB, @as(c_ulong, MAXBANDS) *% @sizeOf(@TypeOf(pFactors.*)));
    if (nsect != 0) {
        if (nsect == @as(c_int, 1)) {
            sect_cb = pSect.*.sect_cb;
            {
                sfb = pSect.*.sect_end >> @intCast(@as(c_int, 2));
                while (sfb != @as(c_int, 0)) : (sfb -= 1) {
                    (blk: {
                        const ref = &pHuffBookUsed;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = sect_cb;
                    (blk: {
                        const ref = &pHuffBookUsed;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = sect_cb;
                    (blk: {
                        const ref = &pHuffBookUsed;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = sect_cb;
                    (blk: {
                        const ref = &pHuffBookUsed;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = sect_cb;
                }
            }
            {
                sfb = pSect.*.sect_end & @as(c_int, 3);
                while (sfb != @as(c_int, 0)) : (sfb -= 1) {
                    (blk: {
                        const ref = &pHuffBookUsed;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = sect_cb;
                }
            }
        } else {
            var sect_start: Int = 0;
            _ = &sect_start;
            {
                sect_idx = nsect;
                while (sect_idx > @as(c_int, 0)) : (sect_idx -= 1) {
                    sect_cb = pSect.*.sect_cb;
                    {
                        sfb = sect_start;
                        while (sfb < pSect.*.sect_end) : (sfb += 1) {
                            pHuffBookUsed[@bitCast(@as(isize, @intCast(sfb)))] = sect_cb;
                        }
                    }
                    pSect += 1;
                    sect_start = sfb;
                }
            }
        }
    } else {
        _ = memset(@ptrCast(@alignCast(pHuffBookUsed)), ZERO_HCB, @as(c_ulong, MAXBANDS) *% @sizeOf(@TypeOf(pHuffBookUsed.*)));
    }
    pHuffBookUsed = &huffBookUsed[@as(c_int, 0)];
    fac = global_gain;
    is_pos = 0;
    noise_nrg = global_gain - NOISE_OFFSET;
    group_win = 0;
    group_end = 0;
    while ((group_end < pFrameInfo.*.num_win) and (status == @as(c_int, 0))) {
        nsfb_win = pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(group_end)))];
        group_end = (blk: {
            const ref = &pGroup;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        {
            sfb = 0;
            while (sfb < nsfb_win) : (sfb += 1) {
                blk: {
                    switch (pHuffBookUsed[@bitCast(@as(isize, @intCast(sfb)))]) {
                        ZERO_HCB => {
                            break :blk;
                        },
                        INTENSITY_HCB, INTENSITY_HCB2 => {
                            cw_index = decode_huff_scl(pInputStream);
                            is_pos += cw_index - MIDFAC;
                            pFactors[@bitCast(@as(isize, @intCast(sfb)))] = is_pos;
                            break :blk;
                        },
                        NOISE_HCB => {
                            if (noise_pcm_flag == @as(c_int, 1)) {
                                noise_pcm_flag = 0;
                                dpcm_noise_nrg = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(NOISE_PCM_BITS, pInputStream))));
                                dpcm_noise_nrg -= NOISE_PCM_OFFSET;
                            } else {
                                dpcm_noise_nrg = decode_huff_scl(pInputStream);
                                dpcm_noise_nrg -= MIDFAC;
                            }
                            noise_nrg += dpcm_noise_nrg;
                            pFactors[@bitCast(@as(isize, @intCast(sfb)))] = noise_nrg;
                            break :blk;
                        },
                        BOOKSCL => {
                            status = 1;
                            sfb = nsfb_win;
                            break :blk;
                        },
                        else => {
                            cw_index = decode_huff_scl(pInputStream);
                            fac += cw_index - MIDFAC;
                            if ((fac >= (@as(c_int, 2) * TEXP)) or (fac < @as(c_int, 0))) {
                                status = 1;
                            } else {
                                pFactors[@bitCast(@as(isize, @intCast(sfb)))] = fac;
                            }
                        },
                    }
                }
            }
        }
        if (pFrameInfo.*.islong == @as(c_int, 0)) {
            {
                group_win += 1;
                while (group_win < group_end) : (group_win += 1) {
                    {
                        sfb = 0;
                        while (sfb < nsfb_win) : (sfb += 1) {
                            pFactors[@bitCast(@as(isize, @intCast(sfb + nsfb_win)))] = pFactors[@bitCast(@as(isize, @intCast(sfb)))];
                        }
                    }
                    pFactors += @as(usize, @bitCast(@as(isize, @intCast(nsfb_win))));
                }
            }
        }
        pHuffBookUsed += @as(usize, @bitCast(@as(isize, @intCast(nsfb_win))));
        pFactors += @as(usize, @bitCast(@as(isize, @intCast(nsfb_win))));
    }
    return status;
}

pub fn huffspec_fxp(arg_pFrameInfo: [*c]FrameInfo, arg_pInputStream: [*c]BITS, arg_nsect: Int, arg_pSectInfo: [*c]SectInfo, arg_factors: [*c]Int, arg_coef: [*c]Int32, arg_quantSpec: [*c]Int16, arg_tmp_spec: [*c]Int16, arg_pLongFrameInfo: [*c]const FrameInfo, arg_pPulseInfo: [*c]PulseInfo, arg_qFormat: [*c]Int) Int {
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    var nsect = arg_nsect;
    _ = &nsect;
    var pSectInfo = arg_pSectInfo;
    _ = &pSectInfo;
    var factors = arg_factors;
    _ = &factors;
    var coef = arg_coef;
    _ = &coef;
    var quantSpec = arg_quantSpec;
    _ = &quantSpec;
    var tmp_spec = arg_tmp_spec;
    _ = &tmp_spec;
    var pLongFrameInfo = arg_pLongFrameInfo;
    _ = &pLongFrameInfo;
    var pPulseInfo = arg_pPulseInfo;
    _ = &pPulseInfo;
    var qFormat = arg_qFormat;
    _ = &qFormat;
    var pHcb: [*c]const Hcb = undefined;
    _ = &pHcb;
    var i: Int = undefined;
    _ = &i;
    var sfb: Int = undefined;
    _ = &sfb;
    var idx_count: Int = undefined;
    _ = &idx_count;
    var sect_cb: Int = undefined;
    _ = &sect_cb;
    var dim: Int = undefined;
    _ = &dim;
    var idx: Int = undefined;
    _ = &idx;
    var stop_idx: Int = undefined;
    _ = &stop_idx;
    var sect_start: Int = undefined;
    _ = &sect_start;
    var sect_end: Int = undefined;
    _ = &sect_end;
    var pSfbStart: [*c]Int = undefined;
    _ = &pSfbStart;
    var pSfb: [*c]Int = undefined;
    _ = &pSfb;
    var pQuantSpec: [*c]Int16 = undefined;
    _ = &pQuantSpec;
    var max: Int = 0;
    _ = &max;
    var nsfb: Int = undefined;
    _ = &nsfb;
    var tot_sfb: Int = undefined;
    _ = &tot_sfb;
    var fac: Int = undefined;
    _ = &fac;
    var pCoef: [*c]Int32 = undefined;
    _ = &pCoef;
    var scale: UInt16 = undefined;
    _ = &scale;
    var power_scale_div_4: Int = undefined;
    _ = &power_scale_div_4;
    var sfbWidth: Int = undefined;
    _ = &sfbWidth;
    var pUnpack_idx: ?*const fn (quant_spec: [*c]Int16, codeword_indx: Int, pHuffCodebook: [*c]const Hcb, pInputStream: [*c]BITS, max: [*c]Int) void = undefined;
    _ = &pUnpack_idx;
    var pDec_huff_tab: ?*const fn ([*c]BITS) Int = null;
    _ = &pDec_huff_tab;
    var temp: UInt32 = undefined;
    _ = &temp;
    var binaryDigits: Int = undefined;
    _ = &binaryDigits;
    var QFormat: Int = undefined;
    _ = &QFormat;
    sect_start = 0;
    stop_idx = 0;
    pSfbStart = @ptrCast(@alignCast(&pFrameInfo.*.frame_sfb_top));
    if (@as(?*anyopaque, @ptrCast(@alignCast(pSfbStart))) == @as(?*anyopaque, null)) {
        return -@as(c_int, 1);
    }
    pSfb = pSfbStart;
    {
        i = nsect;
        while (i > @as(c_int, 0)) : (i -= 1) {
            sect_cb = pSectInfo.*.sect_cb;
            if ((sect_cb > @as(c_int, 15)) or (sect_cb < @as(c_int, 0))) {
                return -@as(c_int, 1);
            }
            sect_end = pSectInfo.*.sect_end;
            if (sect_end < @as(c_int, 0)) {
                return -@as(c_int, 1);
            }
            pSectInfo += 1;
            if (((sect_cb - @as(c_int, 1)) & @as(c_int, 12)) != @as(c_int, 12)) {
                if (sect_cb > BY4BOOKS) {
                    dim = 2;
                } else {
                    dim = 4;
                }
                pHcb = &hcbbook_binary[@bitCast(@as(isize, @intCast(sect_cb)))];
                if (sect_cb == ESCBOOK) {
                    pUnpack_idx = &unpack_idx_esc;
                } else if (pHcb.*.signed_cb == @as(c_int, 0)) {
                    pUnpack_idx = &unpack_idx_sgn;
                } else {
                    pUnpack_idx = &unpack_idx;
                }
                blk: {
                    switch (sect_cb) {
                        @as(c_int, 1) => {
                            pDec_huff_tab = decode_huff_cw_tab1;
                            break :blk;
                        },
                        @as(c_int, 2) => {
                            pDec_huff_tab = decode_huff_cw_tab2;
                            break :blk;
                        },
                        @as(c_int, 3) => {
                            pDec_huff_tab = decode_huff_cw_tab3;
                            break :blk;
                        },
                        @as(c_int, 4) => {
                            pDec_huff_tab = decode_huff_cw_tab4;
                            break :blk;
                        },
                        @as(c_int, 5) => {
                            pDec_huff_tab = decode_huff_cw_tab5;
                            break :blk;
                        },
                        @as(c_int, 6) => {
                            pDec_huff_tab = decode_huff_cw_tab6;
                            break :blk;
                        },
                        @as(c_int, 7) => {
                            pDec_huff_tab = decode_huff_cw_tab7;
                            break :blk;
                        },
                        @as(c_int, 8) => {
                            pDec_huff_tab = decode_huff_cw_tab8;
                            break :blk;
                        },
                        @as(c_int, 9) => {
                            pDec_huff_tab = decode_huff_cw_tab9;
                            break :blk;
                        },
                        @as(c_int, 10) => {
                            pDec_huff_tab = decode_huff_cw_tab10;
                            break :blk;
                        },
                        @as(c_int, 11) => {
                            pDec_huff_tab = decode_huff_cw_tab11;
                            break :blk;
                        },
                        else => {
                            return -@as(c_int, 1);
                        },
                    }
                }
                pQuantSpec = quantSpec + @as(usize, @bitCast(@as(isize, @intCast(stop_idx))));
                {
                    sfb = sect_start;
                    while (sfb < sect_end) : (sfb += 1) {
                        idx_count = pSfb.* - stop_idx;
                        stop_idx = (blk: {
                            const ref = &pSfb;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).*;
                        while ((idx_count > @as(c_int, 0)) and (idx_count < @as(c_int, 1024))) {
                            idx = pDec_huff_tab.?(pInputStream);
                            pUnpack_idx.?(pQuantSpec, idx, pHcb, pInputStream, &max);
                            pQuantSpec += @as(usize, @bitCast(@as(isize, @intCast(dim))));
                            idx_count -= dim;
                        }
                    }
                }
            } else {
                pSfb = pSfbStart + @as(usize, @bitCast(@as(isize, @intCast(sect_end))));
                idx_count = (pSfb - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).* - stop_idx;
                if ((idx_count > @as(c_int, 1024)) or (idx_count < @as(c_int, 0))) {
                    return -@as(c_int, 1);
                }
                _ = memset(@ptrCast(@alignCast(&quantSpec[@bitCast(@as(isize, @intCast(stop_idx)))])), 0, @as(c_ulong, @bitCast(@as(c_long, idx_count))) *% @sizeOf(@TypeOf(quantSpec[@as(c_int, 0)])));
                _ = memset(@ptrCast(@alignCast(&tmp_spec[@bitCast(@as(isize, @intCast(stop_idx)))])), 0, @as(c_ulong, @bitCast(@as(c_long, idx_count))) *% @sizeOf(@TypeOf(tmp_spec[@as(c_int, 0)])));
                stop_idx = (pSfb - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*;
            }
            sect_start = sect_end;
        }
    }
    if (pFrameInfo.*.islong != @as(c_int, 0)) {
