    tmp6 = fxp_mul32_by_16(vec[@as(c_int, 5)] << @intCast(@as(c_int, 1)), @as(Int16, @intFromFloat((@as(f32, 0.899976) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.899976) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))));
    tmp8 = fxp_mul32_Q29(vec[@as(c_int, 7)], @intFromFloat((@as(f32, 2.562916) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 2.562916) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
    tmp7 = tmp2 + tmp8;
    tmp5 = fxp_mul32_by_16((tmp2 - tmp8) << @intCast(@as(c_int, 1)), @as(Int16, @intFromFloat((@as(f32, 0.541196) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.541196) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))));
    tmp8 = tmp4 + tmp6;
    tmp6 = fxp_mul32_Q29(tmp4 - tmp6, @intFromFloat((@as(f32, 1.306563) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 1.306563) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
    tmp0 = tmp7 + tmp8;
    tmp2 = fxp_mul32_by_16((tmp7 - tmp8) << @intCast(@as(c_int, 1)), @as(Int16, @intFromFloat((@as(f32, 0.707107) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.707107) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))));
    tmp3 = fxp_mul32_by_16((tmp5 - tmp6) << @intCast(@as(c_int, 1)), @as(Int16, @intFromFloat((@as(f32, 0.707107) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.707107) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))));
    tmp1 = (tmp5 + tmp6) + tmp3;
    tmp5 = tmp0 + tmp1;
    tmp6 = tmp1 + tmp2;
    tmp7 = tmp2 + tmp3;
    vec[@as(c_int, 7)] = vec[@as(c_int, 0)] - tmp5;
    vec[@as(c_int, 0)] += tmp5;
    vec[@as(c_int, 6)] = vec[@as(c_int, 1)] - tmp6;
    vec[@as(c_int, 1)] += tmp6;
    vec[@as(c_int, 5)] = vec[@as(c_int, 2)] - tmp7;
    vec[@as(c_int, 2)] += tmp7;
    vec[@as(c_int, 4)] = vec[@as(c_int, 3)] - tmp3;
    vec[@as(c_int, 3)] += tmp3;
}

pub fn imdct_fxp(arg_data_quant: [*c]Int32, arg_freq_2_time_buffer: [*c]Int32, n: Int, arg_Q_format: Int, arg_max: Int32) Int {
    var data_quant = arg_data_quant;
    _ = &data_quant;
    var freq_2_time_buffer = arg_freq_2_time_buffer;
    _ = &freq_2_time_buffer;
    _ = &n;
    var Q_format = arg_Q_format;
    _ = &Q_format;
    var max = arg_max;
    _ = &max;
    var exp_jw: Int32 = undefined;
    _ = &exp_jw;
    var shift: Int = 0;
    _ = &shift;
    var p_rotate: [*c]const Int32 = undefined;
    _ = &p_rotate;
    var p_rotate_2: [*c]const Int32 = undefined;
    _ = &p_rotate_2;
    var p_data_1: [*c]Int32 = undefined;
    _ = &p_data_1;
    var p_data_2: [*c]Int32 = undefined;
    _ = &p_data_2;
    var temp_re32: Int32 = undefined;
    _ = &temp_re32;
    var temp_im32: Int32 = undefined;
    _ = &temp_im32;
    var shift1: Int = 0;
    _ = &shift1;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var k: Int = undefined;
    _ = &k;
    var n_2: Int = n >> @intCast(@as(c_int, 1));
    _ = &n_2;
    var n_4: Int = n >> @intCast(@as(c_int, 2));
    _ = &n_4;
    if (max != @as(c_int, 0)) {
        blk: {
            switch (n) {
                @as(c_int, 256) => {
                    p_rotate = @ptrCast(@alignCast(&exp_rotation_N_256));
                    shift = 21;
                    break :blk;
                },
                @as(c_int, 2048) => {
                    p_rotate = @ptrCast(@alignCast(&exp_rotation_N_2048));
                    shift = 24;
                    break :blk;
                },
                else => {
                    return @as(c_int, 10);
                },
            }
        }
        p_data_1 = data_quant;
        p_data_2 = &data_quant[@bitCast(@as(isize, @intCast(n_2 - @as(c_int, 1))))];
        p_rotate_2 = &p_rotate[@bitCast(@as(isize, @intCast(n_4 - @as(c_int, 1))))];
        shift1 = pv_normalize(max) - @as(c_int, 1);
        Q_format -= @as(c_int, 16) - shift1;
        max = 0;
        if (shift1 >= @as(c_int, 0)) {
            temp_re32 = pv_shl((blk: {
                const ref = &p_data_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, shift1);
            temp_im32 = pv_shl((blk: {
                const ref = &p_data_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).*, shift1);
            {
                k = n_4 >> @intCast(@as(c_int, 1));
                while (k != @as(c_int, 0)) : (k -= 1) {
                    exp_jw = (blk: {
                        const ref = &p_rotate;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    temp1 = cmplx_mul32_by_16(temp_im32, -temp_re32, exp_jw);
                    temp2 = -cmplx_mul32_by_16(temp_re32, temp_im32, exp_jw);
                    temp_im32 = pv_shl((blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).*, shift1);
                    temp_re32 = pv_shl((blk: {
                        const ref = &p_data_2;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).*, shift1);
                    (blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = temp1;
                    (blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = temp2;
                    max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
                    max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
                    exp_jw = (blk: {
                        const ref = &p_rotate_2;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).*;
                    temp1 = cmplx_mul32_by_16(temp_im32, -temp_re32, exp_jw);
                    temp2 = -cmplx_mul32_by_16(temp_re32, temp_im32, exp_jw);
                    temp_re32 = pv_shl((blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*, shift1);
                    temp_im32 = pv_shl((blk: {
                        const ref = &p_data_2;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).*, shift1);
                    (p_data_2 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))))).* = temp1;
                    (p_data_2 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 3)))))).* = temp2;
                    max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
                    max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
                }
            }
        } else {
            temp_re32 = (blk: {
                const ref = &p_data_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* >> @intCast(@as(c_int, 1));
            temp_im32 = (blk: {
                const ref = &p_data_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* >> @intCast(@as(c_int, 1));
            {
                k = n_4 >> @intCast(@as(c_int, 1));
                while (k != @as(c_int, 0)) : (k -= 1) {
                    exp_jw = (blk: {
                        const ref = &p_rotate;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    temp1 = cmplx_mul32_by_16(temp_im32, -temp_re32, exp_jw);
                    temp2 = -cmplx_mul32_by_16(temp_re32, temp_im32, exp_jw);
                    temp_im32 = (blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* >> @intCast(@as(c_int, 1));
                    temp_re32 = (blk: {
                        const ref = &p_data_2;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* >> @intCast(@as(c_int, 1));
                    (blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = temp1;
                    (blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = temp2;
                    max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
                    max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
                    exp_jw = (blk: {
                        const ref = &p_rotate_2;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).*;
                    temp1 = cmplx_mul32_by_16(temp_im32, -temp_re32, exp_jw);
                    temp2 = -cmplx_mul32_by_16(temp_re32, temp_im32, exp_jw);
                    temp_re32 = (blk: {
                        const ref = &p_data_1;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* >> @intCast(@as(c_int, 1));
                    temp_im32 = (blk: {
                        const ref = &p_data_2;
                        const tmp = ref.*;
                        ref.* -= 1;
                        break :blk tmp;
                    }).* >> @intCast(@as(c_int, 1));
                    (p_data_2 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 3)))))).* = temp2;
                    (p_data_2 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))))).* = temp1;
                    max |= (temp1 >> @intCast(@as(c_int, 31))) ^ temp1;
                    max |= (temp2 >> @intCast(@as(c_int, 31))) ^ temp2;
                }
            }
        }
        if (n != @as(c_int, 256)) {
            shift -= mix_radix_fft(data_quant, &max);
            shift -= inv_long_complex_rot(data_quant, max);
        } else {
            shift -= fft_rx4_short(data_quant, &max);
            shift -= inv_short_complex_rot(data_quant, freq_2_time_buffer, max);
            _ = memcpy(@ptrCast(@alignCast(data_quant)), @ptrCast(@alignCast(freq_2_time_buffer)), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 128)))) *% @sizeOf(@TypeOf(data_quant.*)));
        }
    } else {
        Q_format = 31;
    }
    return shift + Q_format;
}

pub fn indexLow2High(arg_offset: Int32, arg_index: Int32, arg_res: Int32) Int32 {
    var offset = arg_offset;
    _ = &offset;
    var index = arg_index;
    _ = &index;
    var res = arg_res;
    _ = &res;
    if (res == @as(c_int, 0)) {
        if (offset >= @as(c_int, 0)) {
            if (index < offset) {
                return index;
            } else {
                return (index << @intCast(@as(c_int, 1))) - offset;
            }
        } else {
            offset = -offset;
            if (index < offset) {
                return (index << @intCast(@as(c_int, 1))) + index;
            } else {
                return (index << @intCast(@as(c_int, 1))) + offset;
            }
        }
    } else {
        return index;
    }
}

pub fn infoinit(samp_rate_idx: Int, arg_ppWin_seq_info: [*c][*c]FrameInfo, arg_pSfbwidth128: [*c]Int) Int {
    _ = &samp_rate_idx;
    var ppWin_seq_info = arg_ppWin_seq_info;
    _ = &ppWin_seq_info;
    var pSfbwidth128 = arg_pSfbwidth128;
    _ = &pSfbwidth128;
    var i: Int = undefined;
    _ = &i;
    var sfb_idx: Int = undefined;
    _ = &sfb_idx;
    var sfb_sbk: Int = undefined;
    _ = &sfb_sbk;
    var bins_sbk: Int = undefined;
    _ = &bins_sbk;
    var win_seq: Int = undefined;
    _ = &win_seq;
    var start_idx: Int = undefined;
    _ = &start_idx;
    var end_idx: Int = undefined;
    _ = &end_idx;
    var nsfb_short: Int = undefined;
    _ = &nsfb_short;
    var sfbands: [*c]Int16 = undefined;
    _ = &sfbands;
    var pFrameInfo: [*c]FrameInfo = undefined;
    _ = &pFrameInfo;
    var pSi: [*c]const SR_Info = &samp_rate_info[@bitCast(@as(isize, @intCast(samp_rate_idx)))];
    _ = &pSi;
    var pt_SFbands1024: [*c]const Int16 = null;
    _ = &pt_SFbands1024;
    var pt_SFbands128: [*c]const Int16 = null;
    _ = &pt_SFbands128;
    blk: {
        switch (pSi.*.samp_rate) {
            @as(c_int, 96000), @as(c_int, 88200) => {
                pt_SFbands1024 = &sfb_96_1024;
                pt_SFbands128 = &sfb_64_128;
                break :blk;
            },
            @as(c_int, 64000) => {
                pt_SFbands1024 = &sfb_64_1024;
                pt_SFbands128 = &sfb_64_128;
                break :blk;
            },
            @as(c_int, 48000), @as(c_int, 44100) => {
                pt_SFbands1024 = &sfb_48_1024;
                pt_SFbands128 = &sfb_48_128;
                break :blk;
            },
            @as(c_int, 32000) => {
                pt_SFbands1024 = &sfb_32_1024;
                pt_SFbands128 = &sfb_48_128;
                break :blk;
            },
            @as(c_int, 24000), @as(c_int, 22050) => {
                pt_SFbands1024 = &sfb_24_1024;
                pt_SFbands128 = &sfb_24_128;
                break :blk;
            },
            @as(c_int, 16000), @as(c_int, 12000), @as(c_int, 11025) => {
                pt_SFbands1024 = &sfb_16_1024;
                pt_SFbands128 = &sfb_16_128;
                break :blk;
            },
            @as(c_int, 8000) => {
                pt_SFbands1024 = &sfb_8_1024;
                pt_SFbands128 = &sfb_8_128;
                break :blk;
            },
            else => {
                return -@as(c_int, 1);
            },
        }
    }
    pFrameInfo = ppWin_seq_info[ONLY_LONG_WINDOW];
    pFrameInfo.*.islong = 1;
    pFrameInfo.*.num_win = 1;
    pFrameInfo.*.coef_per_frame = LN2;
    pFrameInfo.*.sfb_per_win[@as(c_int, 0)] = pSi.*.nsfb1024;
    pFrameInfo.*.sectbits[@as(c_int, 0)] = LONG_SECT_BITS;
    pFrameInfo.*.win_sfb_top[@as(c_int, 0)] = @ptrCast(@alignCast(@constCast(pt_SFbands1024)));
    pFrameInfo.*.sfb_width_128 = null;
    pFrameInfo.*.num_groups = 1;
    pFrameInfo.*.group_len[@as(c_int, 0)] = 1;
    pFrameInfo = ppWin_seq_info[EIGHT_SHORT_WINDOW];
    pFrameInfo.*.islong = 0;
    pFrameInfo.*.num_win = NSHORT;
    pFrameInfo.*.coef_per_frame = LN2;
    {
        i = 0;
        while (i < pFrameInfo.*.num_win) : (i += 1) {
            pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(i)))] = pSi.*.nsfb128;
            pFrameInfo.*.sectbits[@bitCast(@as(isize, @intCast(i)))] = SHORT_SECT_BITS;
            pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(i)))] = @ptrCast(@alignCast(@constCast(pt_SFbands128)));
        }
    }
    pFrameInfo.*.sfb_width_128 = pSfbwidth128;
    {
        i = 0;
        start_idx = 0;
        nsfb_short = pSi.*.nsfb128;
        while (i < nsfb_short) : (i += 1) {
            end_idx = pt_SFbands128[@bitCast(@as(isize, @intCast(i)))];
            pSfbwidth128[@bitCast(@as(isize, @intCast(i)))] = end_idx - start_idx;
            start_idx = end_idx;
        }
    }
    {
        win_seq = 0;
        while (win_seq < NUM_WIN_SEQ) : (win_seq += 1) {
            if (ppWin_seq_info[@bitCast(@as(isize, @intCast(win_seq)))] != @as([*c]FrameInfo, @ptrFromInt(@as(usize, @intCast(@as(c_int, 0)))))) {
                pFrameInfo = ppWin_seq_info[@bitCast(@as(isize, @intCast(win_seq)))];
                pFrameInfo.*.sfb_per_frame = 0;
                sfb_sbk = 0;
                bins_sbk = 0;
                {
                    i = 0;
                    while (i < pFrameInfo.*.num_win) : (i += 1) {
                        pFrameInfo.*.coef_per_win[@bitCast(@as(isize, @intCast(i)))] = @divTrunc(pFrameInfo.*.coef_per_frame, pFrameInfo.*.num_win);
                        pFrameInfo.*.sfb_per_frame += pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(i)))];
                        sfbands = pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(i)))];
                        {
                            sfb_idx = 0;
                            while (sfb_idx < pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(i)))]) : (sfb_idx += 1) {
                                pFrameInfo.*.frame_sfb_top[@bitCast(@as(isize, @intCast(sfb_idx + sfb_sbk)))] = @as(c_int, sfbands[@bitCast(@as(isize, @intCast(sfb_idx)))]) + bins_sbk;
                            }
                        }
                        bins_sbk += pFrameInfo.*.coef_per_win[@bitCast(@as(isize, @intCast(i)))];
                        sfb_sbk += pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(i)))];
                    }
                }
            }
        }
    }
    return 0;
}

pub fn init_sbr_dec(arg_codecSampleRate: Int32, arg_upsampleFac: Int, arg_sbrDec: [*c]SBR_DEC, arg_hFrameData: [*c]SBR_FRAME_DATA) Int32 {
    var codecSampleRate = arg_codecSampleRate;
    _ = &codecSampleRate;
    var upsampleFac = arg_upsampleFac;
    _ = &upsampleFac;
    var sbrDec = arg_sbrDec;
    _ = &sbrDec;
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var outFrameSize: Int32 = undefined;
    _ = &outFrameSize;
    var coreCodecFrameSize: Int32 = 1024;
    _ = &coreCodecFrameSize;
    var i: Int32 = undefined;
    _ = &i;
    sbrDec.*.sbStopCodec = upsampleFac << @intCast(@as(c_int, 5));
    sbrDec.*.prevLowSubband = upsampleFac << @intCast(@as(c_int, 5));
    sbrDec.*.outSampleRate = @as(c_int, 2) * codecSampleRate;
    outFrameSize = upsampleFac * coreCodecFrameSize;
    hFrameData.*.nSfb[@as(c_int, 0)] = 0;
    hFrameData.*.nSfb[@as(c_int, 1)] = 0;
    hFrameData.*.offset = 0;
    hFrameData.*.nNfb = hFrameData.*.sbr_header.noNoiseBands;
    hFrameData.*.prevEnvIsShort = -@as(c_int, 1);
    {
        i = 0;
        while (i < @as(c_int, 5)) : (i += 1) {
            hFrameData.*.fBuf_man[@bitCast(@as(isize, @intCast(i)))] = @ptrCast(@alignCast(&hFrameData.*.fBuffer_man[@bitCast(@as(isize, @intCast(i)))]));
            hFrameData.*.fBufN_man[@bitCast(@as(isize, @intCast(i)))] = @ptrCast(@alignCast(&hFrameData.*.fBufferN_man[@bitCast(@as(isize, @intCast(i)))]));
            hFrameData.*.fBuf_exp[@bitCast(@as(isize, @intCast(i)))] = @ptrCast(@alignCast(&hFrameData.*.fBuffer_exp[@bitCast(@as(isize, @intCast(i)))]));
            hFrameData.*.fBufN_exp[@bitCast(@as(isize, @intCast(i)))] = @ptrCast(@alignCast(&hFrameData.*.fBufferN_exp[@bitCast(@as(isize, @intCast(i)))]));
        }
    }
    _ = memset(@ptrCast(@alignCast(@as([*c]INVF_MODE, @ptrCast(@alignCast(&hFrameData.*.sbr_invf_mode_prev))))), 0, @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 2) * @as(c_int, 5)))) *% @sizeOf(INVF_MODE));
    sbrDec.*.noCols = 32;
    sbrDec.*.bufWriteOffs = @as(c_int, 6) + @as(c_int, 2);
    sbrDec.*.bufReadOffs = 2;
    sbrDec.*.qmfBufLen = sbrDec.*.noCols + sbrDec.*.bufWriteOffs;
    sbrDec.*.lowBandAddSamples = 288;
    sbrDec.*.startIndexCodecQmf = 0;
    sbrDec.*.lowSubband = 32;
    return outFrameSize;
}

pub const intensity_factor: [4]Int16 = [4]Int16{
    32767,
    27554,
    23170,
    19484,
};

pub fn intensity_right(scalefactor: Int, coef_per_win: Int, sfb_per_win: Int, wins_in_group: Int, band_length: Int, codebook: Int, ms_used: Bool, arg_q_formatLeft: [*c]const Int, arg_q_formatRight: [*c]Int, arg_coefLeft: [*c]const Int32, arg_coefRight: [*c]Int32) void {
    _ = &scalefactor;
    _ = &coef_per_win;
    _ = &sfb_per_win;
    _ = &wins_in_group;
    _ = &band_length;
    _ = &codebook;
    _ = &ms_used;
    var q_formatLeft = arg_q_formatLeft;
    _ = &q_formatLeft;
    var q_formatRight = arg_q_formatRight;
    _ = &q_formatRight;
    var coefLeft = arg_coefLeft;
    _ = &coefLeft;
    var coefRight = arg_coefRight;
    _ = &coefRight;
    var pCoefLeft: [*c]const Int32 = coefLeft;
    _ = &pCoefLeft;
    var pCoefRight: [*c]Int32 = coefRight;
    _ = &pCoefRight;
