pub fn limitMinMax(arg_i: Int32, arg_min: Int32, arg_max: Int32) Int32 {
    var i = arg_i;
    _ = &i;
    var min = arg_min;
    _ = &min;
    var max = arg_max;
    _ = &max;
    if (i < max) {
        if (i > min) {
            return i;
        } else {
            return min;
        }
    } else {
        return max;
    }
}

