pub fn long_term_prediction(arg_win_seq: WINDOW_SEQUENCE, weight_index: Int, arg_delay: [*c]const Int, arg_buffer: [*c]const Int16, buffer_offset: Int, arg_time_quant: [*c]const Int32, arg_predicted_samples: [*c]Int32, frame_length: Int) Int {
    var win_seq = arg_win_seq;
    _ = &win_seq;
    _ = &weight_index;
    var delay = arg_delay;
    _ = &delay;
    var buffer = arg_buffer;
    _ = &buffer;
    _ = &buffer_offset;
    var time_quant = arg_time_quant;
    _ = &time_quant;
    var predicted_samples = arg_predicted_samples;
    _ = &predicted_samples;
    _ = &frame_length;
    var pBuffer: [*c]const Int16 = undefined;
    _ = &pBuffer;
    var pTimeQuant: [*c]const Int32 = time_quant;
    _ = &pTimeQuant;
    var pPredicted_samples: [*c]Int32 = undefined;
    _ = &pPredicted_samples;
    var @"test": Int32 = undefined;
    _ = &@"test";
    var datum: Int32 = undefined;
    _ = &datum;
    var weight: UInt = undefined;
    _ = &weight;
    var block_length: Int = undefined;
    _ = &block_length;
    var shift: Int = undefined;
    _ = &shift;
    var k: Int = undefined;
    _ = &k;
    var ltp_buffer_index: Int = undefined;
    _ = &ltp_buffer_index;
    var jump_point: Int = undefined;
    _ = &jump_point;
    var lag: Int = undefined;
    _ = &lag;
    var num_samples: Int = undefined;
    _ = &num_samples;
    var max: Int32 = 0;
    _ = &max;
    pPredicted_samples = &predicted_samples[@as(c_int, 0)];
    weight = pv_global_codebook[@bitCast(@as(isize, @intCast(weight_index)))];
    if (win_seq != @as(WINDOW_SEQUENCE, EIGHT_SHORT_SEQUENCE)) {
        block_length = frame_length << @intCast(@as(c_int, 1));
        lag = delay[@as(c_int, 0)];
        ltp_buffer_index = block_length - lag;
        if (lag < frame_length) {
            num_samples = frame_length + lag;
        } else {
            num_samples = block_length;
        }
        block_length -= num_samples;
        jump_point = frame_length - ltp_buffer_index;
        if (jump_point > @as(c_int, 0)) {
            pBuffer = &buffer[@bitCast(@as(isize, @intCast(ltp_buffer_index + buffer_offset)))];
            {
                k = jump_point;
                while (k > @as(c_int, 0)) : (k -= 1) {
                    @"test" = @as(Int32, @bitCast(@as(c_uint, @truncate(weight)))) * @as(c_int, (blk: {
                        const ref = &pBuffer;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*);
                    (blk: {
                        const ref = &pPredicted_samples;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = @"test";
                    max |= (@"test" >> @intCast(@as(c_int, 31))) ^ @"test";
                }
            }
            num_samples -= jump_point;
            ltp_buffer_index += jump_point;
        }
        jump_point = (@as(c_int, 2) * frame_length) - ltp_buffer_index;
        pBuffer = &buffer[@bitCast(@as(isize, @intCast(ltp_buffer_index - buffer_offset)))];
        if (num_samples < jump_point) {
            jump_point = num_samples;
        }
        {
            k = jump_point;
            while (k > @as(c_int, 0)) : (k -= 1) {
                @"test" = @as(Int32, @bitCast(@as(c_uint, @truncate(weight)))) * @as(c_int, (blk: {
                    const ref = &pBuffer;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*);
                (blk: {
                    const ref = &pPredicted_samples;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = @"test";
                max |= (@"test" >> @intCast(@as(c_int, 31))) ^ @"test";
            }
        }
        num_samples -= jump_point;
        ltp_buffer_index += jump_point;
        {
            k = num_samples;
            while (k > @as(c_int, 0)) : (k -= 1) {
                datum = (blk: {
                    const ref = &pTimeQuant;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* >> @intCast(@as(c_int, 10));
                @"test" = @bitCast(@as(c_uint, @truncate(@as(UInt, @bitCast(@as(c_int, datum))) *% weight)));
                (blk: {
                    const ref = &pPredicted_samples;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = @"test";
                max |= (@"test" >> @intCast(@as(c_int, 31))) ^ @"test";
            }
        }
        _ = memset(@ptrCast(@alignCast(pPredicted_samples)), 0, @as(c_ulong, @bitCast(@as(c_long, block_length))) *% @sizeOf(@TypeOf(pPredicted_samples.*)));
    }
    shift = @as(c_int, 16) - pv_normalize(max);
    if (shift < @as(c_int, 0)) {
        shift = 0;
    }
    return shift;
}

pub fn long_term_synthesis(arg_win_seq: WINDOW_SEQUENCE, arg_sfb_per_win: Int, arg_win_sfb_top: [*c]Int16, arg_win_prediction_used: [*c]Int, arg_sfb_prediction_used: [*c]Int, arg_current_frame: [*c]Int32, arg_q_format: [*c]Int, arg_predicted_spectral: [*c]Int32, arg_pred_q_format: Int, arg_coef_per_win: Int, arg_short_window_num: Int, arg_reconstruct_sfb_num: Int) void {
    var win_seq = arg_win_seq;
    _ = &win_seq;
    var sfb_per_win = arg_sfb_per_win;
    _ = &sfb_per_win;
    var win_sfb_top = arg_win_sfb_top;
    _ = &win_sfb_top;
    var win_prediction_used = arg_win_prediction_used;
