    var pCurrent_frame: [*c]Int32 = undefined;
    _ = &pCurrent_frame;
    var pCurrent_frame_start: [*c]Int32 = undefined;
    _ = &pCurrent_frame_start;
    var pSfb_prediction_used: [*c]Int = undefined;
    _ = &pSfb_prediction_used;
    var pWinSfbTop: [*c]Int16 = undefined;
    _ = &pWinSfbTop;
    var pQ_format: [*c]Int = undefined;
    _ = &pQ_format;
    var pQ_format_start: [*c]Int = undefined;
    _ = &pQ_format_start;
    var temp: Int32 = undefined;
    _ = &temp;
    var i: Int = undefined;
    _ = &i;
    var j: Int = undefined;
    _ = &j;
    var quarter_sfb_width: Int = undefined;
    _ = &quarter_sfb_width;
    var num_sfb: Int = undefined;
    _ = &num_sfb;
    var shift_factor: Int = undefined;
    _ = &shift_factor;
    var max: UInt32 = undefined;
    _ = &max;
    var tmpInt32: Int32 = undefined;
    _ = &tmpInt32;
    var tmpInt: Int = undefined;
    _ = &tmpInt;
    var adjusted_pred_q: Int = undefined;
    _ = &adjusted_pred_q;
    var pred_shift: Int = undefined;
    _ = &pred_shift;
    pPredicted_spectral = &predicted_spectral[@as(c_int, 0)];
    pPredicted_spectral_start = pPredicted_spectral;
    pSfb_prediction_used = &sfb_prediction_used[@as(c_int, 0)];
    if (win_seq != @as(WINDOW_SEQUENCE, EIGHT_SHORT_SEQUENCE)) {
        sfb_offset = 0;
        pWinSfbTop = &win_sfb_top[@as(c_int, 0)];
        pQ_format = &q_format[@as(c_int, 0)];
        {
            i = sfb_per_win;
            while (i > @as(c_int, 0)) : (i -= 1) {
                if ((blk: {
                    const ref = &pSfb_prediction_used;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* != @as(c_int, 0)) {
                    pPredicted_offset = pPredicted_spectral_start + @as(usize, @bitCast(@as(isize, @intCast(sfb_offset))));
                    pCurrent_frame = &current_frame[@bitCast(@as(isize, @intCast(sfb_offset)))];
                    quarter_sfb_width = (@as(c_int, pWinSfbTop.*) - sfb_offset) >> @intCast(@as(c_int, 2));
                    max = 0;
                    pPredicted_spectral = pPredicted_offset;
                    {
                        j = @as(c_int, pWinSfbTop.*) - sfb_offset;
                        while (j > @as(c_int, 0)) : (j -= 1) {
                            tmpInt32 = (blk: {
                                const ref = &pPredicted_spectral;
