                                        (blk: {
                                            const ref = &pCurrent_frame;
                                            const tmp = ref.*;
                                            ref.* += 1;
                                            break :blk tmp;
                                        }).* = temp + ((blk: {
                                            const ref = &pPredicted_spectral;
                                            const tmp = ref.*;
                                            ref.* += 1;
                                            break :blk tmp;
                                        }).* >> @intCast(@as(c_int, 1)));
                                        temp = pv_shr(pCurrent_frame.*, shift_factor);
                                        (blk: {
                                            const ref = &pCurrent_frame;
                                            const tmp = ref.*;
                                            ref.* += 1;
                                            break :blk tmp;
                                        }).* = temp + ((blk: {
                                            const ref = &pPredicted_spectral;
                                            const tmp = ref.*;
                                            ref.* += 1;
                                            break :blk tmp;
                                        }).* >> @intCast(@as(c_int, 1)));
                                    }
                                }
                            }
                            pQ_format.* = adjusted_pred_q - @as(c_int, 1);
                        } else if (shift_factor >= @as(c_int, 31)) {
                            {
                                j = quarter_sfb_width;
                                while (j > @as(c_int, 0)) : (j -= 1) {
                                    (blk: {
                                        const ref = &pCurrent_frame;
                                        const tmp = ref.*;
