pub fn lt_decode(win_type: WINDOW_SEQUENCE, arg_pInputStream: [*c]BITS, max_sfb: Int, arg_pLt_pred: [*c]LT_PRED_STATUS) void {
    _ = &win_type;
    var pInputStream = arg_pInputStream;
    _ = &pInputStream;
    _ = &max_sfb;
    var pLt_pred = arg_pLt_pred;
    _ = &pLt_pred;
    var wnd_num: Int = undefined;
    _ = &wnd_num;
    var k: Int = undefined;
    _ = &k;
    var last_band: Int = undefined;
    _ = &last_band;
    var prev_subblock: Int = undefined;
    _ = &prev_subblock;
    var prev_subblock_nonzero: Int = undefined;
    _ = &prev_subblock_nonzero;
    var temp_reg: Int = undefined;
    _ = &temp_reg;
    var pWinPredictionUsed: [*c]Bool = @ptrCast(@alignCast(&pLt_pred.*.win_prediction_used));
    _ = &pWinPredictionUsed;
    var pSfbPredictionUsed: [*c]Bool = @ptrCast(@alignCast(&pLt_pred.*.sfb_prediction_used));
    _ = &pSfbPredictionUsed;
    var pTempPtr: [*c]Int = undefined;
    _ = &pTempPtr;
    var pDelay: [*c]Int = @ptrCast(@alignCast(&pLt_pred.*.delay));
    _ = &pDelay;
    pDelay[@as(c_int, 0)] = @bitCast(@as(c_uint, @truncate(get17_n_lessbits(11, pInputStream))));
    pLt_pred.*.weight_index = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(3, pInputStream))));
    last_band = max_sfb;
    if (win_type != @as(WINDOW_SEQUENCE, EIGHT_SHORT_SEQUENCE)) {
        if (last_band > @as(c_int, 40)) {
            last_band = 40;
        }
        {
            k = last_band;
            while (k > @as(c_int, 0)) : (k -= 1) {
                (blk: {
                    const ref = &pSfbPredictionUsed;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
            }
        }
        {
            k = max_sfb - last_band;
            while (k > @as(c_int, 0)) : (k -= 1) {
                (blk: {
                    const ref = &pSfbPredictionUsed;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = 0;
            }
        }
    } else {
        if (last_band > @as(c_int, 13)) {
            last_band = 13;
        }
        prev_subblock = pDelay[@as(c_int, 0)];
        pTempPtr = &pSfbPredictionUsed[@as(c_int, 0)];
        wnd_num = @as(c_int, 8);
        prev_subblock_nonzero = prev_subblock;
        prev_subblock += 16;
        while (true) {
            wnd_num -= 1;
            temp_reg = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
            (blk: {
                const ref = &pWinPredictionUsed;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp_reg;
            if (temp_reg != @as(c_int, 0)) {
                (blk: {
                    const ref = &pDelay;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = prev_subblock_nonzero;
                {
                    k = last_band;
                    while (k > @as(c_int, 0)) : (k -= 1) {
                        (blk: {
                            const ref = &pTempPtr;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).* = 1;
                    }
                }
                {
                    k = max_sfb - last_band;
                    while (k > @as(c_int, 0)) : (k -= 1) {
                        (blk: {
                            const ref = &pTempPtr;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).* = 0;
                    }
                }
                break;
            } else {
                pDelay += 1;
                pTempPtr += @as(usize, @bitCast(@as(isize, @intCast(max_sfb))));
            }
            if (!(wnd_num > @as(c_int, 0))) break;
        }
        while (wnd_num > @as(c_int, 0)) {
            temp_reg = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
            (blk: {
                const ref = &pWinPredictionUsed;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp_reg;
            if (temp_reg != @as(c_int, 0)) {
                temp_reg = @bitCast(@as(c_uint, @truncate(get1bits(pInputStream))));
                if (temp_reg != @as(c_int, 0)) {
                    temp_reg = @bitCast(@as(c_uint, @truncate(get9_n_lessbits(5, pInputStream))));
                    (blk: {
                        const ref = &pDelay;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = prev_subblock - temp_reg;
                } else {
                    (blk: {
                        const ref = &pDelay;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = prev_subblock_nonzero;
                }
                {
                    k = last_band;
                    while (k > @as(c_int, 0)) : (k -= 1) {
                        (blk: {
                            const ref = &pTempPtr;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).* = 1;
                    }
                }
                {
                    k = max_sfb - last_band;
                    while (k > @as(c_int, 0)) : (k -= 1) {
                        (blk: {
                            const ref = &pTempPtr;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).* = 0;
                    }
                }
            } else {
                pDelay += 1;
                pTempPtr += @as(usize, @bitCast(@as(isize, @intCast(max_sfb))));
            }
            wnd_num -= 1;
        }
    }
}

pub fn map34IndexTo20(arg_aIndex: [*c]Int32) void {
    var aIndex = arg_aIndex;
    _ = &aIndex;
    aIndex[@as(c_int, 0)] = @divTrunc((aIndex[@as(c_int, 0)] << @intCast(@as(c_int, 1))) + aIndex[@as(c_int, 1)], @as(c_int, 3));
    aIndex[@as(c_int, 1)] = @divTrunc(aIndex[@as(c_int, 1)] + (aIndex[@as(c_int, 2)] << @intCast(@as(c_int, 1))), @as(c_int, 3));
    aIndex[@as(c_int, 2)] = @divTrunc((aIndex[@as(c_int, 3)] << @intCast(@as(c_int, 1))) + aIndex[@as(c_int, 4)], @as(c_int, 3));
    aIndex[@as(c_int, 3)] = @divTrunc(aIndex[@as(c_int, 4)] + (aIndex[@as(c_int, 5)] << @intCast(@as(c_int, 1))), @as(c_int, 3));
    aIndex[@as(c_int, 4)] = (aIndex[@as(c_int, 6)] + aIndex[@as(c_int, 7)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 5)] = (aIndex[@as(c_int, 8)] + aIndex[@as(c_int, 9)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 6)] = aIndex[@as(c_int, 10)];
    aIndex[@as(c_int, 7)] = aIndex[@as(c_int, 11)];
    aIndex[@as(c_int, 8)] = (aIndex[@as(c_int, 12)] + aIndex[@as(c_int, 13)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 9)] = (aIndex[@as(c_int, 14)] + aIndex[@as(c_int, 15)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 10)] = aIndex[@as(c_int, 16)];
    aIndex[@as(c_int, 11)] = aIndex[@as(c_int, 17)];
    aIndex[@as(c_int, 12)] = aIndex[@as(c_int, 18)];
    aIndex[@as(c_int, 13)] = aIndex[@as(c_int, 19)];
    aIndex[@as(c_int, 14)] = (aIndex[@as(c_int, 20)] + aIndex[@as(c_int, 21)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 15)] = (aIndex[@as(c_int, 22)] + aIndex[@as(c_int, 23)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 16)] = (aIndex[@as(c_int, 24)] + aIndex[@as(c_int, 25)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 17)] = (aIndex[@as(c_int, 26)] + aIndex[@as(c_int, 27)]) >> @intCast(@as(c_int, 1));
    aIndex[@as(c_int, 18)] = (((aIndex[@as(c_int, 28)] + aIndex[@as(c_int, 29)]) + aIndex[@as(c_int, 30)]) + aIndex[@as(c_int, 31)]) >> @intCast(@as(c_int, 2));
    aIndex[@as(c_int, 19)] = (aIndex[@as(c_int, 32)] + aIndex[@as(c_int, 33)]) >> @intCast(@as(c_int, 1));
}

pub fn mapLowResEnergyVal(arg_currVal: Int32, arg_prevData: [*c]Int32, arg_offset: Int32, arg_index: Int32, arg_res: Int32) void {
    var currVal = arg_currVal;
    _ = &currVal;
    var prevData = arg_prevData;
    _ = &prevData;
    var offset = arg_offset;
    _ = &offset;
    var index = arg_index;
    _ = &index;
    var res = arg_res;
    _ = &res;
    var tmp: Int32 = undefined;
    _ = &tmp;
    if (res == @as(c_int, 0)) {
        if (offset >= @as(c_int, 0)) {
            if (index < offset) {
                prevData[@bitCast(@as(isize, @intCast(index)))] = currVal;
            } else {
                tmp = (index << @intCast(@as(c_int, 1))) - offset;
                prevData[@bitCast(@as(isize, @intCast(tmp)))] = currVal;
                prevData[@bitCast(@as(isize, @intCast(tmp + @as(c_int, 1))))] = currVal;
            }
        } else {
            offset = -offset;
            if (index < offset) {
                tmp = (index << @intCast(@as(c_int, 1))) + index;
                prevData[@bitCast(@as(isize, @intCast(tmp)))] = currVal;
                prevData[@bitCast(@as(isize, @intCast(tmp + @as(c_int, 1))))] = currVal;
                prevData[@bitCast(@as(isize, @intCast(tmp + @as(c_int, 2))))] = currVal;
            } else {
                tmp = (index << @intCast(@as(c_int, 1))) + offset;
                prevData[@bitCast(@as(isize, @intCast(tmp)))] = currVal;
                prevData[@bitCast(@as(isize, @intCast(tmp + @as(c_int, 1))))] = currVal;
            }
        }
    } else {
        prevData[@bitCast(@as(isize, @intCast(index)))] = currVal;
    }
}

pub fn mdct_32(arg_vec: [*c]Int32) void {
    var vec = arg_vec;
    _ = &vec;
    var i: Int = undefined;
    _ = &i;
    var pt_vec: [*c]Int32 = vec;
    _ = &pt_vec;
    var tmp1: Int32 = undefined;
    _ = &tmp1;
    var tmp2: Int32 = undefined;
    _ = &tmp2;
    var pt_CosTable: [*c]const Int32 = @ptrCast(@alignCast(&CosTable_32));
    _ = &pt_CosTable;
    {
        i = 5;
        while (i != @as(c_int, 0)) : (i -= 1) {
            pt_vec.* = fxp_mul32_Q31(pt_vec.* << @intCast(@as(c_int, 1)), (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q31(pt_vec.* << @intCast(@as(c_int, 1)), (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q31(pt_vec.* << @intCast(@as(c_int, 1)), (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q31(pt_vec.* << @intCast(@as(c_int, 1)), (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
        }
    }
    {
        i = 3;
        while (i != @as(c_int, 0)) : (i -= 1) {
            pt_vec.* = fxp_mul32_Q27(pt_vec.*, (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q27(pt_vec.*, (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q27(pt_vec.*, (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q27(pt_vec.*, (blk: {
                const ref = &pt_CosTable;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
        }
    }
    (pt_vec - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).* <<= @intCast(@as(c_int, 1));
    dct_32(vec);
    pt_vec = &vec[@as(c_int, 31)];
    tmp1 = (blk: {
        const ref = &pt_vec;
        const tmp = ref.*;
        ref.* -= 1;
        break :blk tmp;
    }).*;
    {
        i = 5;
        while (i != @as(c_int, 0)) : (i -= 1) {
            tmp2 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* += tmp1;
            tmp1 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* += tmp2;
            tmp2 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* += tmp1;
            tmp1 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* += tmp2;
            tmp2 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* += tmp1;
            tmp1 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* += tmp2;
        }
    }
    pt_vec.* += tmp1;
}

pub fn mdct_fxp(arg_data_quant: [*c]Int32, arg_Q_FFTarray: [*c]Int32, arg_n: Int) Int {
    var data_quant = arg_data_quant;
    _ = &data_quant;
    var Q_FFTarray = arg_Q_FFTarray;
    _ = &Q_FFTarray;
    var n = arg_n;
    _ = &n;
    var temp_re: Int32 = undefined;
    _ = &temp_re;
    var temp_im: Int32 = undefined;
    _ = &temp_im;
    var temp_re_32: Int32 = undefined;
    _ = &temp_re_32;
    var temp_im_32: Int32 = undefined;
    _ = &temp_im_32;
    var cos_n: Int16 = undefined;
    _ = &cos_n;
    var sin_n: Int16 = undefined;
    _ = &sin_n;
    var exp_jw: Int32 = undefined;
    _ = &exp_jw;
    var shift: Int = undefined;
    _ = &shift;
    var p_rotate: [*c]const Int32 = undefined;
    _ = &p_rotate;
    var p_data_1: [*c]Int32 = undefined;
    _ = &p_data_1;
    var p_data_2: [*c]Int32 = undefined;
    _ = &p_data_2;
    var p_data_3: [*c]Int32 = undefined;
    _ = &p_data_3;
    var p_data_4: [*c]Int32 = undefined;
    _ = &p_data_4;
    var p_Q_FFTarray: [*c]Int32 = undefined;
    _ = &p_Q_FFTarray;
    var max1: Int32 = undefined;
    _ = &max1;
    var k: Int = undefined;
    _ = &k;
    var n_2: Int = n >> @intCast(@as(c_int, 1));
    _ = &n_2;
    var n_4: Int = n >> @intCast(@as(c_int, 2));
    _ = &n_4;
    var n_8: Int = n >> @intCast(@as(c_int, 3));
    _ = &n_8;
    var n_3_4: Int = @as(c_int, 3) * n_4;
    _ = &n_3_4;
    blk: {
        switch (n) {
            @as(c_int, 256) => {
                p_rotate = @ptrCast(@alignCast(@as([*c]const Int, @ptrCast(@alignCast(&exp_rotation_N_256)))));
                break :blk;
            },
            @as(c_int, 2048) => {
                p_rotate = @ptrCast(@alignCast(@as([*c]const Int, @ptrCast(@alignCast(&exp_rotation_N_2048)))));
                break :blk;
            },
            else => {
                return @as(c_int, 10);
            },
        }
    }
    p_data_1 = &data_quant[@bitCast(@as(isize, @intCast(n_3_4)))];
    p_data_2 = &data_quant[@bitCast(@as(isize, @intCast(n_3_4 - @as(c_int, 1))))];
    p_data_3 = &data_quant[@bitCast(@as(isize, @intCast(n_4)))];
    p_data_4 = &data_quant[@bitCast(@as(isize, @intCast(n_4 - @as(c_int, 1))))];
    p_Q_FFTarray = Q_FFTarray;
    max1 = 0;
    {
        k = n_8;
        while (k > @as(c_int, 0)) : (k -= 1) {
            temp_re = ((blk: {
                const ref = &p_data_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* + (blk: {
                const ref = &p_data_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).*) >> @intCast(@as(c_int, 1));
            temp_im = ((blk: {
                const ref = &p_data_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* - (blk: {
                const ref = &p_data_4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).*) >> @intCast(@as(c_int, 1));
            exp_jw = (blk: {
                const ref = &p_rotate;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            cos_n = @truncate(exp_jw >> @intCast(@as(c_int, 16)));
            sin_n = @truncate(exp_jw & @as(c_int, 65535));
            temp_re_32 = (temp_re * @as(c_int, cos_n)) + (temp_im * @as(c_int, sin_n));
            temp_im_32 = (temp_im * @as(c_int, cos_n)) - (temp_re * @as(c_int, sin_n));
            (blk: {
                const ref = &p_Q_FFTarray;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp_re_32;
            (blk: {
                const ref = &p_Q_FFTarray;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp_im_32;
            max1 |= (temp_re_32 >> @intCast(@as(c_int, 31))) ^ temp_re_32;
            max1 |= (temp_im_32 >> @intCast(@as(c_int, 31))) ^ temp_im_32;
            p_data_1 += 1;
            p_data_2 -= 1;
            p_data_4 -= 1;
            p_data_3 += 1;
        }
    }
    p_data_1 = &data_quant[@bitCast(@as(isize, @intCast(n - @as(c_int, 1))))];
    p_data_2 = &data_quant[@bitCast(@as(isize, @intCast(n_2 - @as(c_int, 1))))];
    p_data_3 = &data_quant[@bitCast(@as(isize, @intCast(n_2)))];
    p_data_4 = data_quant;
    {
        k = n_8;
        while (k > @as(c_int, 0)) : (k -= 1) {
            temp_re = ((blk: {
                const ref = &p_data_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* - (blk: {
                const ref = &p_data_4;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*) >> @intCast(@as(c_int, 1));
            temp_im = ((blk: {
                const ref = &p_data_1;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* + (blk: {
                const ref = &p_data_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*) >> @intCast(@as(c_int, 1));
            p_data_2 -= 1;
            p_data_1 -= 1;
            p_data_4 += 1;
            p_data_3 += 1;
            exp_jw = (blk: {
                const ref = &p_rotate;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            cos_n = @truncate(exp_jw >> @intCast(@as(c_int, 16)));
            sin_n = @truncate(exp_jw & @as(c_int, 65535));
            temp_re_32 = (temp_re * @as(c_int, cos_n)) + (temp_im * @as(c_int, sin_n));
            temp_im_32 = (temp_im * @as(c_int, cos_n)) - (temp_re * @as(c_int, sin_n));
            (blk: {
                const ref = &p_Q_FFTarray;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp_re_32;
            (blk: {
                const ref = &p_Q_FFTarray;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp_im_32;
            max1 |= (temp_re_32 >> @intCast(@as(c_int, 31))) ^ temp_re_32;
            max1 |= (temp_im_32 >> @intCast(@as(c_int, 31))) ^ temp_im_32;
        }
    }
    p_Q_FFTarray = Q_FFTarray;
    if (max1 != 0) {
        if (n != @as(c_int, 256)) {
            shift = mix_radix_fft(Q_FFTarray, &max1);
            shift += fwd_long_complex_rot(Q_FFTarray, data_quant, max1);
        } else {
            shift = fft_rx4_short(Q_FFTarray, &max1);
            shift += fwd_short_complex_rot(Q_FFTarray, data_quant, max1);
        }
    } else {
        shift = -@as(c_int, 31);
    }
    return @as(c_int, 12) - shift;
}

pub fn mdst_32(arg_vec: [*c]Int32, arg_scratch_mem: [*c]Int32) void {
    var vec = arg_vec;
    _ = &vec;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var i: Int = undefined;
    _ = &i;
    var pt_cos: [*c]const Int32 = @ptrCast(@alignCast(&CosTable_32));
    _ = &pt_cos;
    var pt_vec: [*c]Int32 = vec;
    _ = &pt_vec;
    var tmp1: Int32 = undefined;
    _ = &tmp1;
    var tmp2: Int32 = undefined;
    _ = &tmp2;
    var tmp3: Int32 = undefined;
    _ = &tmp3;
    tmp3 = (blk: {
        const ref = &pt_vec;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    tmp2 = pt_vec.*;
    {
        i = 5;
        while (i != @as(c_int, 0)) : (i -= 1) {
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* += tmp3;
            tmp1 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* += tmp2;
            tmp3 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* += tmp1;
            tmp2 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* += tmp3;
            tmp1 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* += tmp2;
            tmp3 = pt_vec.*;
            (blk: {
                const ref = &pt_vec;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* += tmp1;
            tmp2 = pt_vec.*;
        }
    }
    pt_vec.* += tmp3;
    dst_32(vec, scratch_mem);
    pt_vec = vec;
    {
        i = 5;
        while (i != @as(c_int, 0)) : (i -= 1) {
            pt_vec.* = fxp_mul32_Q31((pt_vec.* << @intCast(@as(c_int, 1))) + tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q31((pt_vec.* << @intCast(@as(c_int, 1))) - tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q31((pt_vec.* << @intCast(@as(c_int, 1))) + tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q31((pt_vec.* << @intCast(@as(c_int, 1))) - tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
        }
    }
    tmp2 >>= @intCast(@as(c_int, 1));
    {
        i = 3;
        while (i != @as(c_int, 0)) : (i -= 1) {
            pt_vec.* = fxp_mul32_Q27(pt_vec.* + tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q27(pt_vec.* - tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q27(pt_vec.* + tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
            pt_vec.* = fxp_mul32_Q27(pt_vec.* - tmp2, (blk: {
                const ref = &pt_cos;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*);
            pt_vec += 1;
        }
    }
    (pt_vec - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).* <<= @intCast(@as(c_int, 1));
}

pub fn mix_radix_fft(arg_Data: [*c]Int32, arg_peak_value: [*c]Int32) Int {
    var Data = arg_Data;
    _ = &Data;
    var peak_value = arg_peak_value;
    _ = &peak_value;
    var p_w: [*c]const Int32 = undefined;
    _ = &p_w;
    var pData_1: [*c]Int32 = undefined;
    _ = &pData_1;
    var pData_2: [*c]Int32 = undefined;
    _ = &pData_2;
    var pData_3: [*c]Int32 = undefined;
    _ = &pData_3;
    var pData_4: [*c]Int32 = undefined;
    _ = &pData_4;
    var exp_jw: Int32 = undefined;
    _ = &exp_jw;
    var max1: Int32 = undefined;
    _ = &max1;
    var max2: Int32 = undefined;
    _ = &max2;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var temp3: Int32 = undefined;
    _ = &temp3;
    var temp4: Int32 = undefined;
    _ = &temp4;
    var diff1: Int32 = undefined;
    _ = &diff1;
    var diff2: Int32 = undefined;
    _ = &diff2;
    var i: Int = undefined;
    _ = &i;
    var exp: Int = undefined;
    _ = &exp;
    max1 = peak_value.*;
    p_w = &w_512rx2;
    pData_1 = Data;
    pData_3 = Data + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 512) >> @intCast(@as(c_int, 1))))));
    exp = @as(c_int, 8) - pv_normalize(max1);
    if (exp < @as(c_int, 4)) {
        exp = 4;
    }
    temp1 = pData_3.*;
    pData_4 = pData_3 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 512)))));
    temp2 = (blk: {
        const ref = &pData_4;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    diff1 = pv_shr((temp1 - temp2), exp);
    (blk: {
        const ref = &pData_3;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).* = pv_shr((temp1 + temp2), exp);
    temp3 = pData_3.*;
    temp4 = pData_4.*;
    (blk: {
        const ref = &pData_4;
        const tmp = ref.*;
        ref.* -= 1;
        break :blk tmp;
    }).* = -diff1;
    (blk: {
        const ref = &pData_3;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).* = pv_shr((temp3 + temp4), exp);
    pData_4.* = pv_shr((temp3 - temp4), exp);
    temp1 = pData_1.*;
    pData_2 = pData_1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 512)))));
    temp2 = (blk: {
        const ref = &pData_2;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    temp4 = pData_2.*;
    (blk: {
        const ref = &pData_1;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).* = pv_shr((temp1 + temp2), exp);
    temp3 = pData_1.*;
    diff1 = pv_shr((temp1 - temp2), exp);
    (blk: {
        const ref = &pData_1;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).* = pv_shr((temp3 + temp4), exp);
    (blk: {
        const ref = &pData_2;
        const tmp = ref.*;
        ref.* -= 1;
        break :blk tmp;
    }).* = pv_shr((temp3 - temp4), exp);
    pData_2.* = diff1;
    temp1 = pData_3.*;
    pData_4 = pData_3 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 512)))));
    temp2 = (blk: {
        const ref = &pData_4;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    {
        i = (@as(c_int, 512) >> @intCast(@as(c_int, 2))) - @as(c_int, 1);
        while (i != @as(c_int, 0)) : (i -= 1) {
            diff1 = pv_shr((temp1 - temp2), exp - @as(c_int, 4));
            (blk: {
                const ref = &pData_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = pv_shr((temp1 + temp2), exp);
            temp3 = pData_3.*;
            temp4 = pData_4.*;
            exp_jw = (blk: {
                const ref = &p_w;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            diff2 = pv_shr((temp3 - temp4), exp - @as(c_int, 4));
            (blk: {
                const ref = &pData_3;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = pv_shr((temp3 + temp4), exp);
            (blk: {
                const ref = &pData_4;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = -cmplx_mul32_by_16(diff1, diff2, exp_jw) >> @intCast(@as(c_int, 3));
            pData_4.* = cmplx_mul32_by_16(diff2, -diff1, exp_jw) >> @intCast(@as(c_int, 3));
            temp1 = pData_1.*;
            pData_2 = pData_1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 512)))));
            temp2 = (blk: {
                const ref = &pData_2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp4 = pData_2.*;
            (blk: {
                const ref = &pData_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = pv_shr((temp1 + temp2), exp);
            temp3 = pData_1.*;
            diff1 = pv_shr((temp1 - temp2), exp - @as(c_int, 4));
            diff2 = pv_shr((temp3 - temp4), exp - @as(c_int, 4));
            (blk: {
                const ref = &pData_1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = pv_shr((temp3 + temp4), exp);
            (blk: {
                const ref = &pData_2;
                const tmp = ref.*;
                ref.* -= 1;
                break :blk tmp;
            }).* = cmplx_mul32_by_16(diff2, -diff1, exp_jw) >> @intCast(@as(c_int, 3));
            pData_2.* = cmplx_mul32_by_16(diff1, diff2, exp_jw) >> @intCast(@as(c_int, 3));
            temp1 = pData_3.*;
            pData_4 = pData_3 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 512)))));
            temp2 = (blk: {
                const ref = &pData_4;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
        }
    }
    fft_rx4_long(Data, &max1);
    fft_rx4_long(&Data[@as(c_int, 512)], &max2);
    digit_reversal_swapping(Data, &Data[@as(c_int, 512)]);
    peak_value.* = max1 | max2;
    return exp;
}

pub fn ms_synt(wins_in_group: Int, coef_per_win: Int, num_bands: Int, band_length: Int, arg_coefLeft: [*c]Int32, arg_coefRight: [*c]Int32, arg_q_formatLeft: [*c]Int, arg_q_formatRight: [*c]Int) void {
    _ = &wins_in_group;
    _ = &coef_per_win;
    _ = &num_bands;
    _ = &band_length;
    var coefLeft = arg_coefLeft;
    _ = &coefLeft;
    var coefRight = arg_coefRight;
    _ = &coefRight;
    var q_formatLeft = arg_q_formatLeft;
    _ = &q_formatLeft;
    var q_formatRight = arg_q_formatRight;
    _ = &q_formatRight;
    var pCoefL: [*c]Int32 = coefLeft;
    _ = &pCoefL;
    var pCoefR: [*c]Int32 = coefRight;
    _ = &pCoefR;
    var start_indx: Int = 0;
    _ = &start_indx;
    if ((band_length < @as(c_int, 0)) or (band_length > @as(c_int, 1024))) {
        return;
    }
    var nextWinPtrUpdate: Int = coef_per_win - band_length;
    _ = &nextWinPtrUpdate;
    {
        var win_indx: Int = wins_in_group;
        _ = &win_indx;
        while (win_indx > @as(c_int, 0)) : (win_indx -= 1) {
            if (q_formatRight[@bitCast(@as(isize, @intCast(start_indx)))] < @as(c_int, 31)) {
                var tempInt: Int = q_formatLeft[@bitCast(@as(isize, @intCast(start_indx)))] - q_formatRight[@bitCast(@as(isize, @intCast(start_indx)))];
                _ = &tempInt;
                if (tempInt > @as(c_int, 0)) {
                    var shift_left_chan: Int = @as(c_int, 1) + tempInt;
                    _ = &shift_left_chan;
                    q_formatLeft[@bitCast(@as(isize, @intCast(start_indx)))] = blk: {
                        const ref = (q_formatRight + @as(usize, @bitCast(@as(isize, @intCast(start_indx)))));
                        ref.* -= 1;
                        break :blk ref.*;
                    };
                    var temp_left: Int32 = pv_shr(pCoefL.*, shift_left_chan);
                    _ = &temp_left;
                    var temp_right: Int32 = pCoefR.* >> @intCast(@as(c_int, 1));
                    _ = &temp_right;
                    {
                        var i: Int = band_length;
                        _ = &i;
                        while (i != @as(c_int, 0)) : (i -= 1) {
                            (blk: {
                                const ref = &pCoefL;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = temp_left + temp_right;
                            (blk: {
                                const ref = &pCoefR;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = temp_left - temp_right;
                            temp_left = pv_shr(pCoefL.*, shift_left_chan);
                            temp_right = pCoefR.* >> @intCast(@as(c_int, 1));
                        }
                    }
                } else {
                    var shift_right_chan: Int = @as(c_int, 1) - tempInt;
                    _ = &shift_right_chan;
                    q_formatRight[@bitCast(@as(isize, @intCast(start_indx)))] = blk: {
                        const ref = (q_formatLeft + @as(usize, @bitCast(@as(isize, @intCast(start_indx)))));
                        ref.* -= 1;
                        break :blk ref.*;
                    };
                    var temp_left: Int32 = pCoefL.* >> @intCast(@as(c_int, 1));
                    _ = &temp_left;
                    var temp_right: Int32 = pv_shr(pCoefR.*, shift_right_chan);
                    _ = &temp_right;
                    {
                        var i: Int = band_length;
                        _ = &i;
                        while (i != @as(c_int, 0)) : (i -= 1) {
                            (blk: {
                                const ref = &pCoefL;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = temp_left + temp_right;
                            (blk: {
                                const ref = &pCoefR;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = temp_left - temp_right;
                            temp_left = pCoefL.* >> @intCast(@as(c_int, 1));
                            temp_right = pv_shr(pCoefR.*, shift_right_chan);
                        }
                    }
                }
            } else {
                q_formatRight[@bitCast(@as(isize, @intCast(start_indx)))] = q_formatLeft[@bitCast(@as(isize, @intCast(start_indx)))];
                _ = memcpy(@ptrCast(@alignCast(pCoefR)), @ptrCast(@alignCast(pCoefL)), @as(c_ulong, @bitCast(@as(c_long, band_length))) *% @sizeOf(@TypeOf(pCoefR.*)));
                pCoefR += @as(usize, @bitCast(@as(isize, @intCast(band_length))));
                pCoefL += @as(usize, @bitCast(@as(isize, @intCast(band_length))));
            }
            pCoefL += @as(usize, @bitCast(@as(isize, @intCast(nextWinPtrUpdate))));
            pCoefR += @as(usize, @bitCast(@as(isize, @intCast(nextWinPtrUpdate))));
            start_indx += num_bands;
        }
    }
    return;
}

