pub fn pns_corr(scale: Int, coef_per_win: Int, sfb_per_win: Int, wins_in_group: Int, band_length: Int, q_formatLeft: Int, arg_q_formatRight: [*c]Int, arg_coefLeft: [*c]const Int32, arg_coefRight: [*c]Int32) void {
    _ = &scale;
    _ = &coef_per_win;
    _ = &sfb_per_win;
    _ = &wins_in_group;
    _ = &band_length;
    _ = &q_formatLeft;
    var q_formatRight = arg_q_formatRight;
    _ = &q_formatRight;
    var coefLeft = arg_coefLeft;
    _ = &coefLeft;
    var coefRight = arg_coefRight;
    _ = &coefRight;
    var tempInt: Int = undefined;
    _ = &tempInt;
    var nextWinPtrUpdate: Int = undefined;
    _ = &nextWinPtrUpdate;
    var q_format: Int = undefined;
    _ = &q_format;
    var start_indx: Int = undefined;
    _ = &start_indx;
    var win_indx: Int = undefined;
    _ = &win_indx;
    var pCoefLeft: [*c]const Int32 = undefined;
    _ = &pCoefLeft;
    var pCoefRight: [*c]Int32 = undefined;
    _ = &pCoefRight;
    var multiplier: UInt = undefined;
    _ = &multiplier;
    q_format = q_formatLeft - (scale >> @intCast(@as(c_int, 2)));
    q_format -= 1;
    multiplier = hcb2_scale_mod_4[@bitCast(@as(isize, @intCast(scale & @as(c_int, 3))))];
    pCoefLeft = coefLeft;
    pCoefRight = coefRight;
    nextWinPtrUpdate = coef_per_win - band_length;
    start_indx = 0;
    {
        win_indx = wins_in_group;
        while (win_indx > @as(c_int, 0)) : (win_indx -= 1) {
            q_formatRight[@bitCast(@as(isize, @intCast(start_indx)))] = q_format;
            start_indx += sfb_per_win;
            {
                tempInt = band_length;
                while (tempInt > @as(c_int, 0)) : (tempInt -= 1) {
                    (blk: {
                        const ref = &pCoefRight;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = @bitCast(@as(c_uint, @truncate(@as(UInt, @bitCast(@as(c_int, (blk: {
                        const ref = &pCoefLeft;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* >> @intCast(@as(c_int, 16))))) *% multiplier)));
                }
            }
            pCoefRight += @as(usize, @bitCast(@as(isize, @intCast(nextWinPtrUpdate))));
            pCoefLeft += @as(usize, @bitCast(@as(isize, @intCast(nextWinPtrUpdate))));
        }
    }
    return;
}

pub fn pns_intensity_right(hasmask: Int, pFrameInfo: [*c]const FrameInfo, arg_group: [*c]const Int, arg_mask_map: [*c]const Bool, arg_codebook_map: [*c]const Int, arg_factorsL: [*c]const Int, arg_factorsR: [*c]const Int, arg_sfb_prediction_used: [*c]Int, ltp_data_present: Bool, arg_coefLeft: [*c]Int32, arg_coefRight: [*c]Int32, arg_q_formatLeft: [*c]Int, arg_q_formatRight: [*c]Int, pCurrentSeed: [*c]Int32) void {
    _ = &hasmask;
    _ = &pFrameInfo;
    var group = arg_group;
    _ = &group;
    var mask_map = arg_mask_map;
    _ = &mask_map;
    var codebook_map = arg_codebook_map;
    _ = &codebook_map;
    var factorsL = arg_factorsL;
    _ = &factorsL;
    var factorsR = arg_factorsR;
    _ = &factorsR;
    var sfb_prediction_used = arg_sfb_prediction_used;
    _ = &sfb_prediction_used;
    _ = &ltp_data_present;
    var coefLeft = arg_coefLeft;
    _ = &coefLeft;
    var coefRight = arg_coefRight;
    _ = &coefRight;
    var q_formatLeft = arg_q_formatLeft;
    _ = &q_formatLeft;
    var q_formatRight = arg_q_formatRight;
    _ = &q_formatRight;
    _ = &pCurrentSeed;
    var pCoefRight: [*c]Int32 = undefined;
    _ = &pCoefRight;
    var pWindow_CoefR: [*c]Int32 = undefined;
    _ = &pWindow_CoefR;
    var pCoefLeft: [*c]Int32 = undefined;
    _ = &pCoefLeft;
    var tot_sfb: Int = undefined;
    _ = &tot_sfb;
    var start_indx: Int = undefined;
    _ = &start_indx;
    var sfb: Int = undefined;
    _ = &sfb;
    var band_length: Int = undefined;
    _ = &band_length;
    var band_start: Int = undefined;
    _ = &band_start;
    var band_stop: Int = undefined;
    _ = &band_stop;
    var coef_per_win: Int = undefined;
    _ = &coef_per_win;
    var codebook: Int = undefined;
    _ = &codebook;
    var partition: Int = undefined;
    _ = &partition;
    var window_start: Int = undefined;
    _ = &window_start;
    var sfb_per_win: Int = undefined;
    _ = &sfb_per_win;
    var wins_in_group: Int = undefined;
    _ = &wins_in_group;
    var win_indx: Int = undefined;
    _ = &win_indx;
    var pBand: [*c]const Int16 = undefined;
    _ = &pBand;
    var pFactorsLeft: [*c]const Int = factorsL;
    _ = &pFactorsLeft;
    var pFactorsRight: [*c]const Int = factorsR;
    _ = &pFactorsRight;
    var pCodebookMap: [*c]const Int = codebook_map;
    _ = &pCodebookMap;
    var pGroup: [*c]const Int = group;
    _ = &pGroup;
    var pMaskMap: [*c]const Bool = mask_map;
    _ = &pMaskMap;
    var mask_enabled: Bool = undefined;
    _ = &mask_enabled;
    pCoefRight = coefRight;
    pCoefLeft = coefLeft;
    window_start = 0;
    tot_sfb = 0;
    start_indx = 0;
    coef_per_win = pFrameInfo.*.coef_per_win[@as(c_int, 0)];
    sfb_per_win = pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
    while (true) {
        pBand = pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(window_start)))];
        partition = (blk: {
            const ref = &pGroup;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        band_start = 0;
        wins_in_group = partition - window_start;
        {
            sfb = sfb_per_win;
            while (sfb > @as(c_int, 0)) : (sfb -= 1) {
                band_stop = (blk: {
                    const ref = &pBand;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                codebook = (blk: {
                    const ref = &pCodebookMap;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                mask_enabled = (blk: {
                    const ref = &pMaskMap;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*;
                band_length = band_stop - band_start;
                if (codebook == NOISE_HCB) {
                    sfb_prediction_used[@bitCast(@as(isize, @intCast(tot_sfb)))] &= ltp_data_present;
                    if (sfb_prediction_used[@bitCast(@as(isize, @intCast(tot_sfb)))] == @as(c_int, 0)) {
                        mask_enabled &= hasmask;
                        if (mask_enabled == @as(c_int, 0)) {
                            pWindow_CoefR = (pCoefRight + @as(usize, @bitCast(@as(isize, @intCast(band_start)))));
                            start_indx = tot_sfb;
                            {
                                win_indx = wins_in_group;
                                while (win_indx > @as(c_int, 0)) : (win_indx -= 1) {
                                    q_formatRight[@bitCast(@as(isize, @intCast(start_indx)))] = gen_rand_vector(pWindow_CoefR, band_length, pCurrentSeed, pFactorsRight.*);
                                    pWindow_CoefR += @as(usize, @bitCast(@as(isize, @intCast(coef_per_win))));
                                    start_indx += sfb_per_win;
                                }
                            }
                        } else {
                            pns_corr(pFactorsRight.* - pFactorsLeft.*, coef_per_win, sfb_per_win, wins_in_group, band_length, q_formatLeft[@bitCast(@as(isize, @intCast(tot_sfb)))], (q_formatRight + @as(usize, @bitCast(@as(isize, @intCast(tot_sfb))))), (pCoefLeft + @as(usize, @bitCast(@as(isize, @intCast(band_start))))), (pCoefRight + @as(usize, @bitCast(@as(isize, @intCast(band_start))))));
                        }
                    }
                } else if (codebook >= INTENSITY_HCB2) {
                    mask_enabled &= hasmask;
                    intensity_right(pFactorsRight.*, coef_per_win, sfb_per_win, wins_in_group, band_length, codebook, mask_enabled, (q_formatLeft + @as(usize, @bitCast(@as(isize, @intCast(tot_sfb))))), (q_formatRight + @as(usize, @bitCast(@as(isize, @intCast(tot_sfb))))), (pCoefLeft + @as(usize, @bitCast(@as(isize, @intCast(band_start))))), (pCoefRight + @as(usize, @bitCast(@as(isize, @intCast(band_start))))));
                }
                band_start = band_stop;
                tot_sfb += 1;
                pFactorsLeft += 1;
                pFactorsRight += 1;
            }
        }
        pCoefRight += @as(usize, @bitCast(@as(isize, @intCast(coef_per_win * wins_in_group))));
        pCoefLeft += @as(usize, @bitCast(@as(isize, @intCast(coef_per_win * (blk: {
            const ref = &wins_in_group;
            const tmp = ref.*;
            ref.* -= 1;
            break :blk tmp;
        })))));
        tot_sfb += sfb_per_win * wins_in_group;
        pFactorsRight += @as(usize, @bitCast(@as(isize, @intCast(sfb_per_win * wins_in_group))));
        pFactorsLeft += @as(usize, @bitCast(@as(isize, @intCast(sfb_per_win * wins_in_group))));
        window_start = partition;
        if (!(partition < pFrameInfo.*.num_win)) break;
    }
    return;
}

pub fn pns_left(arg_pFrameInfo: [*c]const FrameInfo, arg_group: [*c]const Int, arg_codebook_map: [*c]const Int, arg_factors: [*c]const Int, arg_sfb_prediction_used: [*c]const Int, ltp_data_present: Bool, arg_spectral_coef: [*c]Int32, arg_q_format: [*c]Int, arg_pCurrentSeed: [*c]Int32) void {
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var group = arg_group;
    _ = &group;
    var codebook_map = arg_codebook_map;
    _ = &codebook_map;
    var factors = arg_factors;
    _ = &factors;
    var sfb_prediction_used = arg_sfb_prediction_used;
    _ = &sfb_prediction_used;
    _ = &ltp_data_present;
    var spectral_coef = arg_spectral_coef;
    _ = &spectral_coef;
    var q_format = arg_q_format;
    _ = &q_format;
    var pCurrentSeed = arg_pCurrentSeed;
    _ = &pCurrentSeed;
    var tot_sfb: Int = undefined;
    _ = &tot_sfb;
    var start_indx: Int = undefined;
    _ = &start_indx;
    var sfb: Int = undefined;
    _ = &sfb;
    var band_stop: Int = undefined;
    _ = &band_stop;
    var pBand: [*c]const Int16 = undefined;
    _ = &pBand;
    var pCodebookMap: [*c]const Int = &codebook_map[@as(c_int, 0)];
    _ = &pCodebookMap;
    var pGroup: [*c]const Int = &group[@as(c_int, 0)];
    _ = &pGroup;
    var pFactors: [*c]const Int = &factors[@as(c_int, 0)];
    _ = &pFactors;
    var tempInt: Int = undefined;
    _ = &tempInt;
    var pWindow_Coef: [*c]Int32 = undefined;
    _ = &pWindow_Coef;
    var spec: [*c]Int32 = undefined;
    _ = &spec;
    var partition: Int = undefined;
    _ = &partition;
    var win_indx: Int = undefined;
    _ = &win_indx;
    tot_sfb = 0;
    spec = spectral_coef;
    win_indx = 0;
    partition = 0;
    while (true) {
        var num_bands: Int = pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(partition)))];
        _ = &num_bands;
        pBand = pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(partition)))];
        partition = (blk: {
            const ref = &pGroup;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        while (true) {
            var band_start: Int = 0;
            _ = &band_start;
            {
                sfb = 0;
                while (sfb < num_bands) : (sfb += 1) {
                    band_stop = pBand[@bitCast(@as(isize, @intCast(sfb)))];
                    var band_length: Int = band_stop - band_start;
                    _ = &band_length;
                    if (pCodebookMap[@bitCast(@as(isize, @intCast(sfb)))] == NOISE_HCB) {
                        tempInt = sfb_prediction_used[@bitCast(@as(isize, @intCast(tot_sfb)))] & ltp_data_present;
                        if (tempInt == @as(c_int, 0)) {
                            pWindow_Coef = spec + @as(usize, @bitCast(@as(isize, @intCast(band_start))));
                            tempInt = pFactors[@bitCast(@as(isize, @intCast(sfb)))];
                            start_indx = blk: {
                                const ref = &tot_sfb;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            };
                            q_format[@bitCast(@as(isize, @intCast(start_indx)))] = gen_rand_vector(pWindow_Coef, band_length, pCurrentSeed, tempInt);
                        }
                    } else {
                        tot_sfb += 1;
                    }
                    band_start = band_stop;
                }
            }
            spec += @as(usize, @bitCast(@as(isize, @intCast(pFrameInfo.*.coef_per_win[
                @bitCast(@as(isize, @intCast(blk: {
                    const ref = &win_indx;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                })))
            ]))));
            pFactors += @as(usize, @bitCast(@as(isize, @intCast(num_bands))));
            if (!(win_indx < partition)) break;
        }
        pCodebookMap += @as(usize, @bitCast(@as(isize, @intCast(pFrameInfo.*.sfb_per_win[@bitCast(@as(isize, @intCast(win_indx - @as(c_int, 1))))]))));
        if (!(partition < pFrameInfo.*.num_win)) break;
    }
    return;
}

