pub fn ps_all_pass_fract_delay_filter_type_I(arg_delayBufIndex: [*c]UInt32, arg_sb_delay: Int32, arg_ppFractDelayPhaseFactorSer: [*c]const Int32, arg_pppRealDelayRBufferSer: [*c][*c][*c]Int32, arg_pppImagDelayRBufferSer: [*c][*c][*c]Int32, arg_rIn: [*c]Int32, arg_iIn: [*c]Int32) void {
