    pt_iTmp = &pppImagDelayRBufferSer[@as(c_int, 0)][
        (blk: {
            const ref = &delayBufIndex;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*
    ][@bitCast(@as(isize, @intCast(sb_delay)))];
    cmplx = (blk: {
        const ref = &ppFractDelayPhaseFactorSer;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    tmp_r = pt_rTmp.* << @intCast(@as(c_int, 1));
    tmp_i = pt_iTmp.* << @intCast(@as(c_int, 1));
    rTmp = cmplx_mul32_by_16(tmp_r, -tmp_i, cmplx);
