    iTmp = cmplx_mul32_by_16(tmp_i, tmp_r, cmplx);
    iTmp = fxp_mac32_by_16(-iIn.* << @intCast(@as(c_int, 1)), rTmp0, iTmp);
    pt_iTmp.* = fxp_mac32_by_16(iTmp << @intCast(@as(c_int, 1)), rTmp0, iIn.*);
    iIn.* = iTmp;
    rTmp = fxp_mac32_by_16(-rIn.* << @intCast(@as(c_int, 1)), rTmp0, rTmp);
    pt_rTmp.* = fxp_mac32_by_16(rTmp << @intCast(@as(c_int, 1)), rTmp0, rIn.*);
    rIn.* = rTmp;
    pt_rTmp = &pppRealDelayRBufferSer[@as(c_int, 1)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    pt_iTmp = &pppImagDelayRBufferSer[@as(c_int, 1)][
        (blk: {
            const ref = &delayBufIndex;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*
    ][@bitCast(@as(isize, @intCast(sb_delay)))];
    cmplx = (blk: {
        const ref = &ppFractDelayPhaseFactorSer;
        const tmp = ref.*;
