    tmp_i = pt_iTmp.* << @intCast(@as(c_int, 1));
    rTmp = cmplx_mul32_by_16(tmp_r, -tmp_i, cmplx);
    rTmp0 = @intFromFloat((@as(f32, 0.564718) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.564718) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)));
    iTmp = cmplx_mul32_by_16(tmp_i, tmp_r, cmplx);
    iTmp = fxp_mac32_by_16(-iIn.* << @intCast(@as(c_int, 1)), rTmp0, iTmp);
    pt_iTmp.* = fxp_mac32_by_16(iTmp << @intCast(@as(c_int, 1)), rTmp0, iIn.*);
    iIn.* = iTmp;
    rTmp = fxp_mac32_by_16(-rIn.* << @intCast(@as(c_int, 1)), rTmp0, rTmp);
    pt_rTmp.* = fxp_mac32_by_16(rTmp << @intCast(@as(c_int, 1)), rTmp0, rIn.*);
    rIn.* = rTmp;
    pt_rTmp = &pppRealDelayRBufferSer[@as(c_int, 2)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    pt_iTmp = &pppImagDelayRBufferSer[@as(c_int, 2)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    cmplx = ppFractDelayPhaseFactorSer.*;
    tmp_r = pt_rTmp.* << @intCast(@as(c_int, 1));
    tmp_i = pt_iTmp.* << @intCast(@as(c_int, 1));
    rTmp = cmplx_mul32_by_16(tmp_r, -tmp_i, cmplx);
    rTmp0 = @intFromFloat((@as(f32, 0.979083) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 15))))) + (if (@as(f32, 0.979083) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)));
    iTmp = cmplx_mul32_by_16(tmp_i, tmp_r, cmplx);
    iTmp = fxp_mac32_by_16(-iIn.*, rTmp0, iTmp);
    pt_iTmp.* = fxp_mac32_by_16(iTmp, rTmp0, iIn.*);
    iIn.* = iTmp << @intCast(@as(c_int, 2));
    rTmp = fxp_mac32_by_16(-rIn.*, rTmp0, rTmp);
    pt_rTmp.* = fxp_mac32_by_16(rTmp, rTmp0, rIn.*);
    rIn.* = rTmp << @intCast(@as(c_int, 2));
}

pub fn ps_all_pass_fract_delay_filter_type_II(arg_delayBufIndex: [*c]UInt32, arg_sb_delay: Int32, arg_ppFractDelayPhaseFactorSer: [*c]const Int32, arg_pppRealDelayRBufferSer: [*c][*c][*c]Int32, arg_pppImagDelayRBufferSer: [*c][*c][*c]Int32, arg_rIn: [*c]Int32, arg_iIn: [*c]Int32, arg_decayScaleFactor: Int32) void {
    var delayBufIndex = arg_delayBufIndex;
    _ = &delayBufIndex;
    var sb_delay = arg_sb_delay;
    _ = &sb_delay;
    var ppFractDelayPhaseFactorSer = arg_ppFractDelayPhaseFactorSer;
    _ = &ppFractDelayPhaseFactorSer;
    var pppRealDelayRBufferSer = arg_pppRealDelayRBufferSer;
    _ = &pppRealDelayRBufferSer;
    var pppImagDelayRBufferSer = arg_pppImagDelayRBufferSer;
    _ = &pppImagDelayRBufferSer;
    var rIn = arg_rIn;
    _ = &rIn;
    var iIn = arg_iIn;
    _ = &iIn;
    var decayScaleFactor = arg_decayScaleFactor;
    _ = &decayScaleFactor;
    var cmplx: Int32 = undefined;
    _ = &cmplx;
    var rTmp0: Int16 = undefined;
    _ = &rTmp0;
    var rTmp: Int32 = undefined;
    _ = &rTmp;
    var iTmp: Int32 = undefined;
    _ = &iTmp;
    var pt_rTmp: [*c]Int32 = undefined;
    _ = &pt_rTmp;
    var pt_iTmp: [*c]Int32 = undefined;
    _ = &pt_iTmp;
    var pt_delay: [*c]const Int16 = undefined;
    _ = &pt_delay;
    var tmp_r: Int32 = undefined;
    _ = &tmp_r;
    var tmp_i: Int32 = undefined;
    _ = &tmp_i;
    pt_rTmp = &pppRealDelayRBufferSer[@as(c_int, 0)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    pt_iTmp = &pppImagDelayRBufferSer[@as(c_int, 0)][
        (blk: {
            const ref = &delayBufIndex;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*
    ][@bitCast(@as(isize, @intCast(sb_delay)))];
    cmplx = (blk: {
        const ref = &ppFractDelayPhaseFactorSer;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    pt_delay = @ptrCast(@alignCast(&aRevLinkDecaySerCoeff[@bitCast(@as(isize, @intCast(decayScaleFactor)))]));
    tmp_r = pt_rTmp.* << @intCast(@as(c_int, 1));
    tmp_i = pt_iTmp.* << @intCast(@as(c_int, 1));
    rTmp = cmplx_mul32_by_16(tmp_r, -tmp_i, cmplx);
    rTmp0 = (blk: {
        const ref = &pt_delay;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    iTmp = cmplx_mul32_by_16(tmp_i, tmp_r, cmplx);
    iTmp = fxp_mac32_by_16(-iIn.* << @intCast(@as(c_int, 1)), rTmp0, iTmp);
    pt_iTmp.* = fxp_mac32_by_16(iTmp << @intCast(@as(c_int, 1)), rTmp0, iIn.*);
    iIn.* = iTmp;
    rTmp = fxp_mac32_by_16(-rIn.* << @intCast(@as(c_int, 1)), rTmp0, rTmp);
    pt_rTmp.* = fxp_mac32_by_16(rTmp << @intCast(@as(c_int, 1)), rTmp0, rIn.*);
    rIn.* = rTmp;
    pt_rTmp = &pppRealDelayRBufferSer[@as(c_int, 1)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    pt_iTmp = &pppImagDelayRBufferSer[@as(c_int, 1)][
        (blk: {
            const ref = &delayBufIndex;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*
    ][@bitCast(@as(isize, @intCast(sb_delay)))];
    cmplx = (blk: {
        const ref = &ppFractDelayPhaseFactorSer;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    tmp_r = pt_rTmp.* << @intCast(@as(c_int, 1));
    tmp_i = pt_iTmp.* << @intCast(@as(c_int, 1));
    rTmp = cmplx_mul32_by_16(tmp_r, -tmp_i, cmplx);
    rTmp0 = (blk: {
        const ref = &pt_delay;
        const tmp = ref.*;
        ref.* += 1;
        break :blk tmp;
    }).*;
    iTmp = cmplx_mul32_by_16(tmp_i, tmp_r, cmplx);
    iTmp = fxp_mac32_by_16(-iIn.* << @intCast(@as(c_int, 1)), rTmp0, iTmp);
    pt_iTmp.* = fxp_mac32_by_16(iTmp << @intCast(@as(c_int, 1)), rTmp0, iIn.*);
    iIn.* = iTmp;
    rTmp = fxp_mac32_by_16(-rIn.* << @intCast(@as(c_int, 1)), rTmp0, rTmp);
    pt_rTmp.* = fxp_mac32_by_16(rTmp << @intCast(@as(c_int, 1)), rTmp0, rIn.*);
    rIn.* = rTmp;
    pt_rTmp = &pppRealDelayRBufferSer[@as(c_int, 2)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    pt_iTmp = &pppImagDelayRBufferSer[@as(c_int, 2)][delayBufIndex.*][@bitCast(@as(isize, @intCast(sb_delay)))];
    cmplx = ppFractDelayPhaseFactorSer.*;
    tmp_r = pt_rTmp.* << @intCast(@as(c_int, 1));
    tmp_i = pt_iTmp.* << @intCast(@as(c_int, 1));
    rTmp = cmplx_mul32_by_16(tmp_r, -tmp_i, cmplx);
    rTmp0 = pt_delay.*;
    iTmp = cmplx_mul32_by_16(tmp_i, tmp_r, cmplx);
    iTmp = fxp_mac32_by_16(-iIn.*, rTmp0, iTmp);
    pt_iTmp.* = fxp_mac32_by_16(iTmp, rTmp0, iIn.*);
    iIn.* = iTmp << @intCast(@as(c_int, 2));
    rTmp = fxp_mac32_by_16(-rIn.*, rTmp0, rTmp);
    pt_rTmp.* = fxp_mac32_by_16(rTmp, rTmp0, rIn.*);
    rIn.* = rTmp << @intCast(@as(c_int, 2));
}

pub fn ps_allocate_decoder(self: [*c]SBRDECODER_DATA, no_subsamples: UInt32) Int32 {
    if (no_subsamples == 0) return 1;
    const ps = self.*.hParametricStereoDec;
    ps.*.noSubSamples = no_subsamples;
    ps.*.invNoSubSamples = @intCast(@as(u32, 1 << 30) / no_subsamples);
    _ = initNativeHybrid(ps);
    const store = &ps.*.native_delays;
    store.* = @import("std").mem.zeroes(NativePsDelays);
    ps.*.aPeakDecayFast = &store.decay[0];
    ps.*.aPrevNrg = &store.decay[1];
    ps.*.aPrevPeakDiff = &store.decay[2];
    ps.*.mHybridRealLeft = &store.hybrid[0];
    ps.*.mHybridImagLeft = &store.hybrid[1];
    ps.*.mHybridRealRight = &store.hybrid[2];
    ps.*.mHybridImagRight = &store.hybrid[3];
    ps.*.delayBufIndex = 0;
    for (&ps.*.aNoSampleDelay, 0..) |*delay, i| delay.* = if (i < 12) 14 else 1;
    var offset: usize = 0;
    for (0..61) |i| {
        const delay: usize = if (i < 20) 2 else if (i < 32) 14 else 1;
        store.qmf_real_ptrs[i] = store.qmf_real[offset..].ptr;
        store.qmf_imag_ptrs[i] = store.qmf_imag[offset..].ptr;
        offset += delay;
    }
    @import("std").debug.assert(offset == store.qmf_real.len);
    ps.*.aaRealDelayBufferQmf = &store.qmf_real_ptrs;
    ps.*.aaImagDelayBufferQmf = &store.qmf_imag_ptrs;
    for (0..10) |i| {
        store.sub_real_ptrs[i] = &store.sub_real[i];
        store.sub_imag_ptrs[i] = &store.sub_imag[i];
    }
    ps.*.aaRealDelayBufferSubQmf = &store.sub_real_ptrs;
    ps.*.aaImagDelayBufferSubQmf = &store.sub_imag_ptrs;
    offset = 0;
    for (0..3) |link| {
        const delay: usize = @intCast(aRevLinkDelaySer[link]);
        ps.*.aDelayRBufIndexSer[link] = 0;
        for (0..delay) |j| {
            store.serial_qmf_real_ptrs[link][j] = store.serial_qmf_real[(offset + j) * 20 ..].ptr;
            store.serial_qmf_imag_ptrs[link][j] = store.serial_qmf_imag[(offset + j) * 20 ..].ptr;
            store.serial_sub_real_ptrs[link][j] = store.serial_sub_real[(offset + j) * 10 ..].ptr;
            store.serial_sub_imag_ptrs[link][j] = store.serial_sub_imag[(offset + j) * 10 ..].ptr;
        }
        ps.*.aaaRealDelayRBufferSerQmf[link] = &store.serial_qmf_real_ptrs[link];
        ps.*.aaaImagDelayRBufferSerQmf[link] = &store.serial_qmf_imag_ptrs[link];
        ps.*.aaaRealDelayRBufferSerSubQmf[link] = &store.serial_sub_real_ptrs[link];
        ps.*.aaaImagDelayRBufferSerSubQmf[link] = &store.serial_sub_imag_ptrs[link];
        offset += delay;
    }
    @import("std").debug.assert(offset == 12);
    @memset(&ps.*.h11Prev, 1 << 30);
    @memset(&ps.*.h12Prev, 1 << 30);
    return 0;
}

pub fn ps_applied(arg_h_ps_dec: [*c]STRUCT_PS_DEC, arg_rIntBufferLeft: [*c][64]Int32, arg_iIntBufferLeft: [*c][64]Int32, arg_rIntBufferRight: [*c]Int32, arg_iIntBufferRight: [*c]Int32, arg_scratch_mem: [*c]Int32, arg_band: Int32) void {
    var h_ps_dec = arg_h_ps_dec;
    _ = &h_ps_dec;
    var rIntBufferLeft = arg_rIntBufferLeft;
    _ = &rIntBufferLeft;
    var iIntBufferLeft = arg_iIntBufferLeft;
    _ = &iIntBufferLeft;
    var rIntBufferRight = arg_rIntBufferRight;
    _ = &rIntBufferRight;
    var iIntBufferRight = arg_iIntBufferRight;
    _ = &iIntBufferRight;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var band = arg_band;
    _ = &band;
    ps_hybrid_analysis(rIntBufferLeft, iIntBufferLeft, h_ps_dec.*.mHybridRealLeft, h_ps_dec.*.mHybridImagLeft, h_ps_dec.*.hHybrid, scratch_mem, band);
    ps_decorrelate(h_ps_dec, @ptrCast(@alignCast(&rIntBufferLeft.*)), @ptrCast(@alignCast(&iIntBufferLeft.*)), rIntBufferRight, iIntBufferRight, scratch_mem);
    ps_stereo_processing(h_ps_dec, @ptrCast(@alignCast(&rIntBufferLeft.*)), @ptrCast(@alignCast(&iIntBufferLeft.*)), rIntBufferRight, iIntBufferRight);
    ps_hybrid_synthesis(@ptrCast(@alignCast(h_ps_dec.*.mHybridRealLeft)), @ptrCast(@alignCast(h_ps_dec.*.mHybridImagLeft)), @ptrCast(@alignCast(&rIntBufferLeft.*)), @ptrCast(@alignCast(&iIntBufferLeft.*)), h_ps_dec.*.hHybrid);
    ps_hybrid_synthesis(@ptrCast(@alignCast(h_ps_dec.*.mHybridRealRight)), @ptrCast(@alignCast(h_ps_dec.*.mHybridImagRight)), rIntBufferRight, iIntBufferRight, h_ps_dec.*.hHybrid);
}

pub fn ps_bstr_decoding(arg_ps_dec: [*c]STRUCT_PS_DEC) void {
    var ps_dec = arg_ps_dec;
    _ = &ps_dec;
    var env: UInt32 = undefined;
    _ = &env;
    var noIidSteps: Int32 = undefined;
    _ = &noIidSteps;
    if (!(ps_dec.*.bPsDataAvail != 0)) {
        ps_dec.*.noEnv = 0;
    }
    noIidSteps = if (ps_dec.*.bFineIidQ != 0) @as(c_int, 15) else @as(c_int, 7);
    {
        env = 0;
        while (env < ps_dec.*.noEnv) : (env +%= 1) {
            var aPrevIidIndex: [*c]Int32 = undefined;
            _ = &aPrevIidIndex;
            var aPrevIccIndex: [*c]Int32 = undefined;
            _ = &aPrevIccIndex;
            if (env == @as(UInt32, 0)) {
                aPrevIidIndex = @ptrCast(@alignCast(&ps_dec.*.aIidPrevFrameIndex));
                aPrevIccIndex = @ptrCast(@alignCast(&ps_dec.*.aIccPrevFrameIndex));
            } else {
                aPrevIidIndex = @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[env -% @as(UInt32, 1)]));
                aPrevIccIndex = @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[env -% @as(UInt32, 1)]));
            }
            differential_Decoding(@bitCast(@as(c_uint, @truncate(ps_dec.*.bEnableIid))), @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[env])), aPrevIidIndex, @bitCast(@as(c_uint, @truncate(ps_dec.*.abIidDtFlag[env]))), aNoIidBins[ps_dec.*.freqResIid], if (ps_dec.*.freqResIid != 0) @as(c_int, 1) else @as(c_int, 2), -noIidSteps, noIidSteps);
            differential_Decoding(@bitCast(@as(c_uint, @truncate(ps_dec.*.bEnableIcc))), @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[env])), aPrevIccIndex, @bitCast(@as(c_uint, @truncate(ps_dec.*.abIccDtFlag[env]))), aNoIccBins[ps_dec.*.freqResIcc], if (ps_dec.*.freqResIcc != 0) @as(c_int, 1) else @as(c_int, 2), 0, @as(c_int, 8) - @as(c_int, 1));
        }
    }
    if (ps_dec.*.noEnv == @as(UInt32, 0)) {
        ps_dec.*.noEnv = 1;
        if (ps_dec.*.bEnableIid != 0) {
            _ = memmove(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIidPrevFrameIndex))))), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIidPrevFrameIndex))).*)));
        } else {
            _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), 0, @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][34]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex))).*))).*)));
        }
        if (ps_dec.*.bEnableIcc != 0) {
            _ = memmove(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIccPrevFrameIndex))))), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIccPrevFrameIndex))).*)));
        } else {
            _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), 0, @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][34]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex))).*))).*)));
        }
    }
    _ = memmove(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIidPrevFrameIndex))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIidPrevFrameIndex))).*)));
    _ = memmove(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIccPrevFrameIndex))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aIccPrevFrameIndex))).*)));
    ps_dec.*.bPsDataAvail = 0;
    if (ps_dec.*.bFrameClass == @as(UInt32, 0)) {
        var shift: Int32 = undefined;
        _ = &shift;
        shift = @bitCast(@as(c_uint, @truncate(pv_shr(ps_dec.*.noEnv, @as(UInt32, 1)))));
        ps_dec.*.aEnvStartStop[@as(c_int, 0)] = 0;
        {
            env = 1;
            while (env < ps_dec.*.noEnv) : (env +%= 1) {
                ps_dec.*.aEnvStartStop[env] = pv_shr((env *% ps_dec.*.noSubSamples), @as(UInt32, @bitCast(@as(c_int, shift))));
            }
        }
        ps_dec.*.aEnvStartStop[ps_dec.*.noEnv] = ps_dec.*.noSubSamples;
    } else {
        ps_dec.*.aEnvStartStop[@as(c_int, 0)] = 0;
        if (ps_dec.*.aEnvStartStop[ps_dec.*.noEnv] < ps_dec.*.noSubSamples) {
            ps_dec.*.noEnv +%= 1;
            ps_dec.*.aEnvStartStop[ps_dec.*.noEnv] = ps_dec.*.noSubSamples;
            _ = memmove(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[ps_dec.*.noEnv]))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][34]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIidIndex))).*))).*)));
            _ = memmove(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[ps_dec.*.noEnv]))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex[ps_dec.*.noEnv -% @as(UInt32, 1)]))))), @as(c_ulong, @bitCast(@as(c_long, @as(c_int, 34)))) *% @sizeOf(@TypeOf(@as([*c]Int32, @ptrCast(@alignCast(&@as([*c][34]Int32, @ptrCast(@alignCast(&ps_dec.*.aaIccIndex))).*))).*)));
        }
        {
            env = 1;
            while (env < ps_dec.*.noEnv) : (env +%= 1) {
                var thr: UInt32 = undefined;
                _ = &thr;
                thr = (ps_dec.*.noSubSamples -% ps_dec.*.noEnv) +% env;
                if (ps_dec.*.aEnvStartStop[env] > thr) {
                    ps_dec.*.aEnvStartStop[env] = thr;
                } else {
                    thr = ps_dec.*.aEnvStartStop[env -% @as(UInt32, 1)] +% @as(UInt32, 1);
                    if (ps_dec.*.aEnvStartStop[env] < thr) {
                        ps_dec.*.aEnvStartStop[env] = thr;
                    }
                }
            }
        }
    }
    {
        env = 0;
        while (env < ps_dec.*.noEnv) : (env +%= 1) {
            if (ps_dec.*.freqResIid == @as(UInt32, 2)) {
                map34IndexTo20(@ptrCast(@alignCast(&ps_dec.*.aaIidIndex[env])));
            }
            if (ps_dec.*.freqResIcc == @as(UInt32, 2)) {
                map34IndexTo20(@ptrCast(@alignCast(&ps_dec.*.aaIccIndex[env])));
            }
        }
    }
}

pub fn ps_decorrelate(arg_h_ps_dec: [*c]STRUCT_PS_DEC, arg_rIntBufferLeft: [*c]Int32, arg_iIntBufferLeft: [*c]Int32, arg_rIntBufferRight: [*c]Int32, arg_iIntBufferRight: [*c]Int32, arg_scratch_mem: [*c]Int32) void {
    var h_ps_dec = arg_h_ps_dec;
    _ = &h_ps_dec;
    var rIntBufferLeft = arg_rIntBufferLeft;
    _ = &rIntBufferLeft;
    var iIntBufferLeft = arg_iIntBufferLeft;
    _ = &iIntBufferLeft;
    var rIntBufferRight = arg_rIntBufferRight;
    _ = &rIntBufferRight;
    var iIntBufferRight = arg_iIntBufferRight;
    _ = &iIntBufferRight;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var sb: Int32 = undefined;
    _ = &sb;
    var maxsb: Int32 = undefined;
    _ = &maxsb;
    var gr: Int32 = undefined;
    _ = &gr;
    var sb_delay: Int32 = undefined;
    _ = &sb_delay;
    var bin: Int32 = undefined;
    _ = &bin;
    var aLeftReal: [*c]Int32 = undefined;
    _ = &aLeftReal;
    var aLeftImag: [*c]Int32 = undefined;
    _ = &aLeftImag;
    var aRightReal: [*c]Int32 = undefined;
    _ = &aRightReal;
    var aRightImag: [*c]Int32 = undefined;
    _ = &aRightImag;
    var aTransRatio: [*c]Int32 = scratch_mem;
    _ = &aTransRatio;
    var pppRealDelayRBufferSer: [*c][*c][*c]Int32 = undefined;
    _ = &pppRealDelayRBufferSer;
    var pppImagDelayRBufferSer: [*c][*c][*c]Int32 = undefined;
    _ = &pppImagDelayRBufferSer;
    var ppRealDelayBuffer: [*c][*c]Int32 = undefined;
    _ = &ppRealDelayBuffer;
    var ppImagDelayBuffer: [*c][*c]Int32 = undefined;
    _ = &ppImagDelayBuffer;
    var ppFractDelayPhaseFactorSer: [*c][3]Int32 = undefined;
    _ = &ppFractDelayPhaseFactorSer;
    ps_pwr_transient_detection(h_ps_dec, rIntBufferLeft, iIntBufferLeft, aTransRatio);
    aLeftReal = h_ps_dec.*.mHybridRealLeft;
    aLeftImag = h_ps_dec.*.mHybridImagLeft;
    aRightReal = h_ps_dec.*.mHybridRealRight;
    aRightImag = h_ps_dec.*.mHybridImagRight;
    pppRealDelayRBufferSer = @ptrCast(@alignCast(&h_ps_dec.*.aaaRealDelayRBufferSerSubQmf));
    pppImagDelayRBufferSer = @ptrCast(@alignCast(&h_ps_dec.*.aaaImagDelayRBufferSerSubQmf));
    ppRealDelayBuffer = h_ps_dec.*.aaRealDelayBufferSubQmf;
    ppImagDelayBuffer = h_ps_dec.*.aaImagDelayBufferSubQmf;
    ppFractDelayPhaseFactorSer = @ptrCast(@alignCast(&aaFractDelayPhaseFactorSerSubQmf));
    {
        gr = 0;
        while (gr < @as(c_int, 10)) : (gr += 1) {
            var rIn: Int32 = undefined;
            _ = &rIn;
            var iIn: Int32 = undefined;
            _ = &iIn;
            var pt_rTmp: [*c]Int32 = undefined;
            _ = &pt_rTmp;
            var pt_iTmp: [*c]Int32 = undefined;
            _ = &pt_iTmp;
            var rTmp: Int32 = undefined;
            _ = &rTmp;
            var cmplx: Int32 = undefined;
            _ = &cmplx;
            var tmp1: Int32 = undefined;
            _ = &tmp1;
            var tmp2: Int32 = undefined;
            _ = &tmp2;
            sb = groupBorders[@bitCast(@as(isize, @intCast(gr)))];
            pt_rTmp = &ppRealDelayBuffer[@bitCast(@as(isize, @intCast(sb)))][@bitCast(@as(isize, @intCast(h_ps_dec.*.delayBufIndex)))];
            pt_iTmp = &ppImagDelayBuffer[@bitCast(@as(isize, @intCast(sb)))][@bitCast(@as(isize, @intCast(h_ps_dec.*.delayBufIndex)))];
            tmp1 = aLeftReal[@bitCast(@as(isize, @intCast(sb)))];
            tmp2 = aLeftImag[@bitCast(@as(isize, @intCast(sb)))];
            rIn = pt_rTmp.* >> @intCast(@as(c_int, 1));
            iIn = pt_iTmp.* >> @intCast(@as(c_int, 1));
            pt_rTmp.* = tmp1;
            pt_iTmp.* = tmp2;
            cmplx = aFractDelayPhaseFactorSubQmf[@bitCast(@as(isize, @intCast(sb)))];
