        while (i != @as(c_int, 0)) : (i -= 1) {
            temp1 = (blk: {
                const ref = &pt_Z;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp2 = (blk: {
                const ref = &pt_Q;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp3 = (blk: {
                const ref = &pt_Z;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            temp4 = (blk: {
                const ref = &pt_Q;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            (blk: {
                const ref = &pt_r1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp1 + temp2;
            (blk: {
                const ref = &pt_i1;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp3 + temp4;
            (blk: {
                const ref = &pt_r2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp1 - temp2;
            (blk: {
                const ref = &pt_i2;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = temp3 - temp4;
        }
    }
}

pub fn ps_hybrid_analysis(arg_mQmfReal: [*c][64]Int32, arg_mQmfImag: [*c][64]Int32, arg_mHybridReal: [*c]Int32, arg_mHybridImag: [*c]Int32, arg_pHybrid: [*c]HYBRID, arg_scratch_mem: [*c]Int32, arg_i: Int32) void {
    var mQmfReal = arg_mQmfReal;
    _ = &mQmfReal;
    var mQmfImag = arg_mQmfImag;
    _ = &mQmfImag;
    var mHybridReal = arg_mHybridReal;
    _ = &mHybridReal;
    var mHybridImag = arg_mHybridImag;
    _ = &mHybridImag;
    var pHybrid = arg_pHybrid;
    _ = &pHybrid;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var i = arg_i;
    _ = &i;
    var band: Int32 = undefined;
    _ = &band;
    var hybridRes: HYBRID_RES = undefined;
    _ = &hybridRes;
    var chOffset: Int32 = 0;
    _ = &chOffset;
    var ptr_mHybrid_Re: [*c]Int32 = undefined;
    _ = &ptr_mHybrid_Re;
    var ptr_mHybrid_Im: [*c]Int32 = undefined;
    _ = &ptr_mHybrid_Im;
    var pt_mQmfBufferReal: [*c]Int32 = undefined;
    _ = &pt_mQmfBufferReal;
    var pt_mQmfBufferImag: [*c]Int32 = undefined;
    _ = &pt_mQmfBufferImag;
    pt_mQmfBufferReal = &scratch_mem[@bitCast(@as(isize, @intCast(@as(c_int, 32) + i)))];
    {
        band = 0;
        while (band < pHybrid.*.nQmfBands) : (band += 1) {
            pt_mQmfBufferImag = pt_mQmfBufferReal + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 44)))));
            pt_mQmfBufferReal[@as(c_int, 12)] = mQmfReal[@as(c_int, 6)][@bitCast(@as(isize, @intCast(band)))];
            pt_mQmfBufferImag[@as(c_int, 12)] = mQmfImag[@as(c_int, 6)][@bitCast(@as(isize, @intCast(band)))];
            ptr_mHybrid_Re = &mHybridReal[@bitCast(@as(isize, @intCast(chOffset)))];
            ptr_mHybrid_Im = &mHybridImag[@bitCast(@as(isize, @intCast(chOffset)))];
            hybridRes = @bitCast(pHybrid.*.pResolution[@bitCast(@as(isize, @intCast(band)))]);
            blk: {
                switch (hybridRes) {
                    @as(HYBRID_RES, HYBRID_2_REAL) => {
                        two_ch_filtering(pt_mQmfBufferReal, pt_mQmfBufferImag, ptr_mHybrid_Re, ptr_mHybrid_Im);
                        chOffset += 2;
                        break :blk;
                    },
                    @as(HYBRID_RES, HYBRID_8_CPLX) => {
                        eight_ch_filtering(pt_mQmfBufferReal, pt_mQmfBufferImag, pHybrid.*.mTempReal, pHybrid.*.mTempImag, scratch_mem);
                        _ = memmove(@ptrCast(@alignCast(ptr_mHybrid_Re)), @ptrCast(@alignCast(pHybrid.*.mTempReal)), @as(c_ulong, 4) *% @sizeOf(@TypeOf(pHybrid.*.mTempReal.*)));
                        ptr_mHybrid_Re += @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))));
                        (blk_1: {
                            const ref = &ptr_mHybrid_Re;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk_1 tmp;
                        }).* += pHybrid.*.mTempReal[@as(c_int, 5)];
                        (blk_1: {
                            const ref = &ptr_mHybrid_Re;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk_1 tmp;
                        }).* += pHybrid.*.mTempReal[@as(c_int, 4)];
                        (blk_1: {
                            const ref = &ptr_mHybrid_Re;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk_1 tmp;
                        }).* = pHybrid.*.mTempReal[@as(c_int, 6)];
                        ptr_mHybrid_Re.* = pHybrid.*.mTempReal[@as(c_int, 7)];
                        _ = memmove(@ptrCast(@alignCast(ptr_mHybrid_Im)), @ptrCast(@alignCast(pHybrid.*.mTempImag)), @as(c_ulong, 4) *% @sizeOf(@TypeOf(pHybrid.*.mTempImag.*)));
                        ptr_mHybrid_Im += @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 2)))));
                        (blk_1: {
                            const ref = &ptr_mHybrid_Im;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk_1 tmp;
                        }).* += pHybrid.*.mTempImag[@as(c_int, 5)];
                        (blk_1: {
                            const ref = &ptr_mHybrid_Im;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk_1 tmp;
                        }).* += pHybrid.*.mTempImag[@as(c_int, 4)];
                        (blk_1: {
                            const ref = &ptr_mHybrid_Im;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk_1 tmp;
                        }).* = pHybrid.*.mTempImag[@as(c_int, 6)];
                        ptr_mHybrid_Im.* = pHybrid.*.mTempImag[@as(c_int, 7)];
                        chOffset += 6;
                        break :blk;
                    },
                    else => {
                        {}
                    },
                }
            }
            pt_mQmfBufferReal = pt_mQmfBufferImag + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 44)))));
        }
    }
}

pub fn ps_hybrid_filter_bank_allocation(arg_phHybrid: [*c][*c]HYBRID, arg_noBands: Int32, arg_pResolution: [*c]const Int32, arg_pPtr: [*c][*c]Int32) Int32 {
    var phHybrid = arg_phHybrid;
    _ = &phHybrid;
    var noBands = arg_noBands;
    _ = &noBands;
    var pResolution = arg_pResolution;
    _ = &pResolution;
    var pPtr = arg_pPtr;
    _ = &pPtr;
    var i: Int32 = undefined;
    _ = &i;
    var tmp: Int32 = undefined;
    _ = &tmp;
    var maxNoChannels: Int32 = 0;
    _ = &maxNoChannels;
    var hs: [*c]HYBRID = undefined;
    _ = &hs;
    var ptr: [*c]Int32 = pPtr.*;
    _ = &ptr;
    phHybrid.* = null;
    hs = @ptrCast(@alignCast(ptr));
    ptr += @sizeOf(HYBRID) / @sizeOf(@TypeOf(ptr.*));
    hs.*.pResolution = ptr;
    ptr += (@as(c_ulong, @bitCast(@as(c_long, noBands))) *% @sizeOf(Int32)) / @sizeOf(@TypeOf(ptr.*));
    {
        i = 0;
        while (i < noBands) : (i += 1) {
            hs.*.pResolution[@bitCast(@as(isize, @intCast(i)))] = pResolution[@bitCast(@as(isize, @intCast(i)))];
            if (((pResolution[@bitCast(@as(isize, @intCast(i)))] != HYBRID_8_CPLX) and (pResolution[@bitCast(@as(isize, @intCast(i)))] != HYBRID_2_REAL)) and (pResolution[@bitCast(@as(isize, @intCast(i)))] != HYBRID_4_CPLX)) {
                return 1;
            }
            if (pResolution[@bitCast(@as(isize, @intCast(i)))] > maxNoChannels) {
                maxNoChannels = pResolution[@bitCast(@as(isize, @intCast(i)))];
            }
        }
    }
    hs.*.nQmfBands = noBands;
    hs.*.qmfBufferMove = @as(c_int, 13) - @as(c_int, 1);
    hs.*.mQmfBufferReal = @ptrCast(@alignCast(ptr));
    ptr += (@as(c_ulong, @bitCast(@as(c_long, noBands))) *% @sizeOf(@TypeOf(ptr))) / @sizeOf(@TypeOf(ptr.*));
    hs.*.mQmfBufferImag = @ptrCast(@alignCast(ptr));
    ptr += (@as(c_ulong, @bitCast(@as(c_long, noBands))) *% @sizeOf(@TypeOf(ptr))) / @sizeOf(@TypeOf(ptr.*));
    tmp = hs.*.qmfBufferMove;
    {
        i = 0;
        while (i < noBands) : (i += 1) {
            hs.*.mQmfBufferReal[@bitCast(@as(isize, @intCast(i)))] = ptr;
            ptr += @as(usize, @bitCast(@as(isize, @intCast(tmp))));
            hs.*.mQmfBufferImag[@bitCast(@as(isize, @intCast(i)))] = ptr;
            ptr += @as(usize, @bitCast(@as(isize, @intCast(tmp))));
        }
    }
    hs.*.mTempReal = ptr;
    ptr += @as(usize, @bitCast(@as(isize, @intCast(maxNoChannels))));
    hs.*.mTempImag = ptr;
    ptr += @as(usize, @bitCast(@as(isize, @intCast(maxNoChannels))));
    phHybrid.* = hs;
    pPtr.* = ptr;
    return 0;
}

pub fn ps_hybrid_synthesis(arg_mHybridReal: [*c]const Int32, arg_mHybridImag: [*c]const Int32, arg_mQmfReal: [*c]Int32, arg_mQmfImag: [*c]Int32, arg_hHybrid: [*c]HYBRID) void {
    var mHybridReal = arg_mHybridReal;
    _ = &mHybridReal;
    var mHybridImag = arg_mHybridImag;
    _ = &mHybridImag;
    var mQmfReal = arg_mQmfReal;
    _ = &mQmfReal;
    var mQmfImag = arg_mQmfImag;
    _ = &mQmfImag;
    var hHybrid = arg_hHybrid;
    _ = &hHybrid;
    var k: Int32 = undefined;
    _ = &k;
    var band: Int32 = undefined;
    _ = &band;
    var hybridRes: HYBRID_RES = undefined;
    _ = &hybridRes;
    var real: Int32 = undefined;
    _ = &real;
    var imag: Int32 = undefined;
    _ = &imag;
    var ptr_mQmfReal: [*c]Int32 = mQmfReal;
    _ = &ptr_mQmfReal;
    var ptr_mQmfImag: [*c]Int32 = mQmfImag;
    _ = &ptr_mQmfImag;
    var ptr_mHybrid_Re: [*c]const Int32 = mHybridReal;
    _ = &ptr_mHybrid_Re;
    var ptr_mHybrid_Im: [*c]const Int32 = mHybridImag;
    _ = &ptr_mHybrid_Im;
    {
        band = 0;
        while (band < hHybrid.*.nQmfBands) : (band += 1) {
            hybridRes = @bitCast((if (hHybrid.*.pResolution[@bitCast(@as(isize, @intCast(band)))] < @as(c_int, 6)) hHybrid.*.pResolution[@bitCast(@as(isize, @intCast(band)))] else @as(c_int, 6)) - @as(c_int, 2));
            real = (blk: {
                const ref = &ptr_mHybrid_Re;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            real += (blk: {
                const ref = &ptr_mHybrid_Re;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            imag = (blk: {
                const ref = &ptr_mHybrid_Im;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            imag += (blk: {
                const ref = &ptr_mHybrid_Im;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            {
                k = @bitCast(pv_shr(hybridRes, @as(HYBRID_RES, 1)));
                while (k != @as(c_int, 0)) : (k -= 1) {
                    real += (blk: {
                        const ref = &ptr_mHybrid_Re;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    real += (blk: {
                        const ref = &ptr_mHybrid_Re;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    imag += (blk: {
                        const ref = &ptr_mHybrid_Im;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    imag += (blk: {
                        const ref = &ptr_mHybrid_Im;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                }
            }
            (blk: {
                const ref = &ptr_mQmfReal;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = real;
            (blk: {
                const ref = &ptr_mQmfImag;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = imag;
        }
    }
}

pub fn ps_init_stereo_mixing(arg_pms: [*c]STRUCT_PS_DEC, arg_env: Int32, arg_usb: Int32) Int32 {
    var pms = arg_pms;
    _ = &pms;
    var env = arg_env;
    _ = &env;
    var usb = arg_usb;
    _ = &usb;
    var group: Int32 = undefined;
    _ = &group;
    var bin: Int32 = undefined;
    _ = &bin;
    var noIidSteps: Int32 = undefined;
    _ = &noIidSteps;
    var tmp: Int32 = undefined;
    _ = &tmp;
    var invEnvLength: Int32 = undefined;
    _ = &invEnvLength;
    var pScaleFactors: [*c]const Int32 = undefined;
    _ = &pScaleFactors;
    var scaleR: Int32 = undefined;
    _ = &scaleR;
    var scaleL: Int32 = undefined;
    _ = &scaleL;
    var cos_alpha: Int32 = undefined;
    _ = &cos_alpha;
    var sin_alpha: Int32 = undefined;
    _ = &sin_alpha;
    var beta: Int32 = undefined;
    _ = &beta;
    var cos_beta: Int32 = undefined;
    _ = &cos_beta;
    var sin_beta: Int32 = undefined;
    _ = &sin_beta;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var ptr_tmp: [*c]Int32 = undefined;
    _ = &ptr_tmp;
    var h11: Int32 = undefined;
    _ = &h11;
    var h12: Int32 = undefined;
    _ = &h12;
    var h21: Int32 = undefined;
    _ = &h21;
    var h22: Int32 = undefined;
    _ = &h22;
    if (pms.*.bFineIidQ != 0) {
        noIidSteps = @as(c_int, 15);
        pScaleFactors = @ptrCast(@alignCast(&scaleFactorsFine));
    } else {
        noIidSteps = @as(c_int, 7);
        pScaleFactors = @ptrCast(@alignCast(&scaleFactors));
    }
    if (env == @as(c_int, 0)) {
        pms.*.lastUsb = pms.*.usb;
        pms.*.usb = usb;
        if ((usb != pms.*.lastUsb) and (pms.*.lastUsb != @as(c_int, 0))) {
            return -@as(c_int, 1);
        }
    }
    invEnvLength = @bitCast(@as(c_uint, @truncate(pms.*.aEnvStartStop[@bitCast(@as(isize, @intCast(env + @as(c_int, 1))))] -% pms.*.aEnvStartStop[@bitCast(@as(isize, @intCast(env)))])));
    if (invEnvLength == @as(Int32, @bitCast(@as(c_uint, @truncate(pms.*.noSubSamples))))) {
        invEnvLength = pms.*.invNoSubSamples;
    } else {
        invEnvLength = @divTrunc(@as(Int32, @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))), invEnvLength);
    }
    if (invEnvLength == @as(c_int, 32)) {
        {
            group = 0;
            while (group < (@as(c_int, 10) + @as(c_int, 12))) : (group += 1) {
                bin = bins2groupMap[@bitCast(@as(isize, @intCast(group)))];
                tmp = pms.*.aaIidIndex[@bitCast(@as(isize, @intCast(env)))][@bitCast(@as(isize, @intCast(bin)))];
                scaleR = pScaleFactors[@bitCast(@as(isize, @intCast(noIidSteps + tmp)))];
                scaleL = pScaleFactors[@bitCast(@as(isize, @intCast(noIidSteps - tmp)))];
                tmp = pms.*.aaIccIndex[@bitCast(@as(isize, @intCast(env)))][@bitCast(@as(isize, @intCast(bin)))];
                cos_alpha = cos_alphas[@bitCast(@as(isize, @intCast(tmp)))];
                sin_alpha = sin_alphas[@bitCast(@as(isize, @intCast(tmp)))];
                beta = fxp_mul32_Q30(scaled_alphas[@bitCast(@as(isize, @intCast(tmp)))], scaleR - scaleL);
                cos_beta = pv_cosine(beta);
                sin_beta = pv_sine(beta);
                temp1 = fxp_mul32_Q30(cos_beta, cos_alpha);
                temp2 = fxp_mul32_Q30(sin_beta, sin_alpha);
                h11 = fxp_mul32_Q30(scaleL, temp1 - temp2);
                h12 = fxp_mul32_Q30(scaleR, temp1 + temp2);
                temp1 = fxp_mul32_Q30(sin_beta, cos_alpha);
                temp2 = fxp_mul32_Q30(cos_beta, sin_alpha);
                h21 = fxp_mul32_Q30(scaleL, temp1 + temp2);
                h22 = fxp_mul32_Q30(scaleR, temp1 - temp2);
                ptr_tmp = &pms.*.h11Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.H11[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                pms.*.deltaH11[@bitCast(@as(isize, @intCast(group)))] = (h11 - ptr_tmp.*) >> @intCast(@as(c_int, 5));
                ptr_tmp.* = h11;
                ptr_tmp = &pms.*.h12Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.H12[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                pms.*.deltaH12[@bitCast(@as(isize, @intCast(group)))] = (h12 - ptr_tmp.*) >> @intCast(@as(c_int, 5));
                ptr_tmp.* = h12;
                ptr_tmp = &pms.*.h21Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.H21[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                pms.*.deltaH21[@bitCast(@as(isize, @intCast(group)))] = (h21 - ptr_tmp.*) >> @intCast(@as(c_int, 5));
                ptr_tmp.* = h21;
                ptr_tmp = &pms.*.h22Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.H22[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                pms.*.deltaH22[@bitCast(@as(isize, @intCast(group)))] = (h22 - ptr_tmp.*) >> @intCast(@as(c_int, 5));
                ptr_tmp.* = h22;
            }
        }
    } else {
        {
            group = 0;
            while (group < (@as(c_int, 10) + @as(c_int, 12))) : (group += 1) {
                bin = bins2groupMap[@bitCast(@as(isize, @intCast(group)))];
                tmp = pms.*.aaIidIndex[@bitCast(@as(isize, @intCast(env)))][@bitCast(@as(isize, @intCast(bin)))];
                scaleR = pScaleFactors[@bitCast(@as(isize, @intCast(noIidSteps + tmp)))];
                scaleL = pScaleFactors[@bitCast(@as(isize, @intCast(noIidSteps - tmp)))];
                tmp = pms.*.aaIccIndex[@bitCast(@as(isize, @intCast(env)))][@bitCast(@as(isize, @intCast(bin)))];
                cos_alpha = cos_alphas[@bitCast(@as(isize, @intCast(tmp)))];
                sin_alpha = sin_alphas[@bitCast(@as(isize, @intCast(tmp)))];
                beta = fxp_mul32_Q30(scaled_alphas[@bitCast(@as(isize, @intCast(tmp)))], scaleR - scaleL);
                cos_beta = pv_cosine(beta);
                sin_beta = pv_sine(beta);
                temp1 = fxp_mul32_Q30(cos_beta, cos_alpha);
                temp2 = fxp_mul32_Q30(sin_beta, sin_alpha);
                h11 = fxp_mul32_Q30(scaleL, temp1 - temp2);
                h12 = fxp_mul32_Q30(scaleR, temp1 + temp2);
                temp1 = fxp_mul32_Q30(sin_beta, cos_alpha);
                temp2 = fxp_mul32_Q30(cos_beta, sin_alpha);
                h21 = fxp_mul32_Q30(scaleL, temp1 + temp2);
                h22 = fxp_mul32_Q30(scaleR, temp1 - temp2);
                ptr_tmp = &pms.*.h11Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.deltaH11[@bitCast(@as(isize, @intCast(group)))] = fxp_mul32_Q30(h11 - ptr_tmp.*, invEnvLength);
                pms.*.H11[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                ptr_tmp.* = h11;
                ptr_tmp = &pms.*.h12Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.deltaH12[@bitCast(@as(isize, @intCast(group)))] = fxp_mul32_Q30(h12 - ptr_tmp.*, invEnvLength);
                pms.*.H12[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                ptr_tmp.* = h12;
                ptr_tmp = &pms.*.h21Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.deltaH21[@bitCast(@as(isize, @intCast(group)))] = fxp_mul32_Q30(h21 - ptr_tmp.*, invEnvLength);
                pms.*.H21[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                ptr_tmp.* = h21;
                ptr_tmp = &pms.*.h22Prev[@bitCast(@as(isize, @intCast(group)))];
                pms.*.deltaH22[@bitCast(@as(isize, @intCast(group)))] = fxp_mul32_Q30(h22 - ptr_tmp.*, invEnvLength);
                pms.*.H22[@bitCast(@as(isize, @intCast(group)))] = ptr_tmp.*;
                ptr_tmp.* = h22;
            }
        }
    }
    return @as(c_int, 0);
}

pub fn ps_pwr_transient_detection(arg_h_ps_dec: [*c]STRUCT_PS_DEC, arg_rIntBufferLeft: [*c]Int32, arg_iIntBufferLeft: [*c]Int32, arg_aTransRatio: [*c]Int32) void {
    var h_ps_dec = arg_h_ps_dec;
    _ = &h_ps_dec;
    var rIntBufferLeft = arg_rIntBufferLeft;
    _ = &rIntBufferLeft;
    var iIntBufferLeft = arg_iIntBufferLeft;
    _ = &iIntBufferLeft;
    var aTransRatio = arg_aTransRatio;
    _ = &aTransRatio;
    var sb: Int32 = undefined;
    _ = &sb;
    var maxsb: Int32 = undefined;
    _ = &maxsb;
    var gr: Int32 = undefined;
    _ = &gr;
    var bin: Int32 = undefined;
    _ = &bin;
    var aLeftReal: [*c]Int32 = undefined;
    _ = &aLeftReal;
    var aLeftImag: [*c]Int32 = undefined;
    _ = &aLeftImag;
    var temp_r: Int32 = undefined;
    _ = &temp_r;
    var temp_i: Int32 = undefined;
    _ = &temp_i;
    var accu: Int32 = undefined;
    _ = &accu;
    var aPower: [*c]Int32 = aTransRatio;
    _ = &aPower;
    var result: Quotient = undefined;
    _ = &result;
    var nrg: Int32 = undefined;
    _ = &nrg;
    var ptr_aPrevNrg: [*c]Int32 = undefined;
    _ = &ptr_aPrevNrg;
