    accu = fxp_mul32_Q31(temp_r, temp_r);
    aPower[@as(c_int, 4)] = fxp_mac32_Q31(accu, temp_i, temp_i) >> @intCast(@as(c_int, 1));
    temp_r = aLeftReal[@as(c_int, 8)];
    temp_i = aLeftImag[@as(c_int, 8)];
    accu = fxp_mul32_Q31(temp_r, temp_r);
    aPower[@as(c_int, 6)] = fxp_mac32_Q31(accu, temp_i, temp_i) >> @intCast(@as(c_int, 1));
    temp_r = aLeftReal[@as(c_int, 9)];
    temp_i = aLeftImag[@as(c_int, 9)];
    accu = fxp_mul32_Q31(temp_r, temp_r);
    aPower[@as(c_int, 7)] = fxp_mac32_Q31(accu, temp_i, temp_i) >> @intCast(@as(c_int, 1));
