            }
        }
    }
}

pub fn ps_read_data(arg_ps_dec: [*c]STRUCT_PS_DEC, arg_hBitBuf: [*c]BIT_BUFFER, arg_nBitsLeft: Int32) Int32 {
    var ps_dec = arg_ps_dec;
    _ = &ps_dec;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var nBitsLeft = arg_nBitsLeft;
    _ = &nBitsLeft;
    var gr: Int = undefined;
    _ = &gr;
    var env: UInt32 = undefined;
    _ = &env;
    var dtFlag: UInt32 = undefined;
    _ = &dtFlag;
    var startbits: Int32 = undefined;
    _ = &startbits;
    var CurrentTable: SbrHuffman = undefined;
    _ = &CurrentTable;
    if (!(ps_dec != null)) {
        return 0;
    }
    startbits = GetNrBitsAvailable(hBitBuf);
    if (buf_get_1bit(hBitBuf) != 0) {
        ps_dec.*.bEnableIid = buf_get_1bit(hBitBuf);
        if (ps_dec.*.bEnableIid != 0) {
            ps_dec.*.freqResIid = buf_getbits(hBitBuf, 3);
            if (ps_dec.*.freqResIid > @as(UInt32, 2)) {
                ps_dec.*.bFineIidQ = 1;
                ps_dec.*.freqResIid -%= 3;
            } else {
                ps_dec.*.bFineIidQ = 0;
            }
        }
        ps_dec.*.bEnableIcc = buf_get_1bit(hBitBuf);
        if (ps_dec.*.bEnableIcc != 0) {
            ps_dec.*.freqResIcc = buf_getbits(hBitBuf, 3);
            if (ps_dec.*.freqResIcc > @as(UInt32, 2)) {
                ps_dec.*.freqResIcc -%= 3;
            }
        }
        ps_dec.*.bEnableExt = buf_get_1bit(hBitBuf);
    }
    ps_dec.*.bFrameClass = buf_get_1bit(hBitBuf);
    if (ps_dec.*.bFrameClass == @as(UInt32, 0)) {
        ps_dec.*.noEnv = @bitCast(@as(c_int, aFixNoEnvDecode[buf_getbits(hBitBuf, 2)]));
    } else {
        ps_dec.*.noEnv = @as(UInt32, 1) +% buf_getbits(hBitBuf, 2);
        {
            env = 1;
            while (env < (ps_dec.*.noEnv +% @as(UInt32, 1))) : (env +%= 1) {
                ps_dec.*.aEnvStartStop[env] = buf_getbits(hBitBuf, 5) +% @as(UInt32, 1);
            }
        }
    }
    if ((ps_dec.*.freqResIid > @as(UInt32, 2)) or (ps_dec.*.freqResIcc > @as(UInt32, 2))) {
        ps_dec.*.bPsDataAvail = 0;
        nBitsLeft -= startbits - GetNrBitsAvailable(hBitBuf);
        while (nBitsLeft != 0) {
            var i: c_int = nBitsLeft;
            _ = &i;
            if (i > @as(c_int, 8)) {
                i = 8;
            }
            _ = buf_getbits(hBitBuf, i);
            nBitsLeft -= i;
        }
        return startbits - GetNrBitsAvailable(hBitBuf);
    }
    if (ps_dec.*.bEnableIid != 0) {
        {
            env = 0;
            while (env < ps_dec.*.noEnv) : (env +%= 1) {
                dtFlag = buf_get_1bit(hBitBuf);
                if (!(dtFlag != 0)) {
                    if (ps_dec.*.bFineIidQ != 0) {
                        CurrentTable = @ptrCast(@alignCast(&aBookPsIidFineFreqDecode));
                    } else {
                        CurrentTable = @ptrCast(@alignCast(&aBookPsIidFreqDecode));
                    }
                } else {
                    if (ps_dec.*.bFineIidQ != 0) {
                        CurrentTable = @ptrCast(@alignCast(&aBookPsIidFineTimeDecode));
                    } else {
                        CurrentTable = @ptrCast(@alignCast(&aBookPsIidTimeDecode));
                    }
                }
                {
                    gr = 0;
                    while (gr < aNoIidBins[ps_dec.*.freqResIid]) : (gr += 1) {
                        ps_dec.*.aaIidIndex[env][@bitCast(@as(isize, @intCast(gr)))] = sbr_decode_huff_cw(CurrentTable, hBitBuf);
                    }
                }
                ps_dec.*.abIidDtFlag[env] = dtFlag;
            }
        }
    }
    if (ps_dec.*.bEnableIcc != 0) {
        {
            env = 0;
            while (env < ps_dec.*.noEnv) : (env +%= 1) {
                dtFlag = buf_get_1bit(hBitBuf);
                if (!(dtFlag != 0)) {
                    CurrentTable = @ptrCast(@alignCast(&aBookPsIccFreqDecode));
                } else {
                    CurrentTable = @ptrCast(@alignCast(&aBookPsIccTimeDecode));
                }
                {
                    gr = 0;
                    while (gr < aNoIccBins[ps_dec.*.freqResIcc]) : (gr += 1) {
                        ps_dec.*.aaIccIndex[env][@bitCast(@as(isize, @intCast(gr)))] = sbr_decode_huff_cw(CurrentTable, hBitBuf);
                    }
                }
                ps_dec.*.abIccDtFlag[env] = dtFlag;
            }
        }
    }
    if (ps_dec.*.bEnableExt != 0) {
        var cnt: c_int = undefined;
        _ = &cnt;
        cnt = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 4))));
        if (cnt == @as(c_int, 15)) {
            cnt += @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 8))));
        }
        hBitBuf.*.nrBitsRead +%= @bitCast(@as(c_int, cnt << @intCast(@as(c_int, 3))));
    }
    ps_dec.*.bPsDataAvail = 1;
    return startbits - GetNrBitsAvailable(hBitBuf);
}

pub fn ps_stereo_processing(arg_pms: [*c]STRUCT_PS_DEC, arg_qmfLeftReal: [*c]Int32, arg_qmfLeftImag: [*c]Int32, arg_qmfRightReal: [*c]Int32, arg_qmfRightImag: [*c]Int32) void {
