    var h11: Int16 = undefined;
    _ = &h11;
    var h12: Int16 = undefined;
    _ = &h12;
    var h21: Int16 = undefined;
    _ = &h21;
    var h22: Int16 = undefined;
    _ = &h22;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var temp2: Int32 = undefined;
    _ = &temp2;
    var temp3: Int32 = undefined;
    _ = &temp3;
    usb = pms.*.usb;
    hybrLeftReal = pms.*.mHybridRealLeft;
    hybrLeftImag = pms.*.mHybridImagLeft;
    hybrRightReal = pms.*.mHybridRealRight;
    hybrRightImag = pms.*.mHybridImagRight;
    {
        group = 0;
        while (group < @as(c_int, 10)) : (group += 1) {
