            temp2 = pms.*.deltaH12[@bitCast(@as(isize, @intCast(group)))];
            pms.*.H11[@bitCast(@as(isize, @intCast(group)))] += temp1;
            h11 = @truncate(pms.*.H11[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            pms.*.H12[@bitCast(@as(isize, @intCast(group)))] += temp2;
            h12 = @truncate(pms.*.H12[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            temp1 = pms.*.deltaH21[@bitCast(@as(isize, @intCast(group)))];
            temp2 = pms.*.deltaH22[@bitCast(@as(isize, @intCast(group)))];
            pms.*.H21[@bitCast(@as(isize, @intCast(group)))] += temp1;
            h21 = @truncate(pms.*.H21[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            pms.*.H22[@bitCast(@as(isize, @intCast(group)))] += temp2;
            h22 = @truncate(pms.*.H22[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            index = groupBorders[@bitCast(@as(isize, @intCast(group)))];
            ptr_hybrLeftReal = &hybrLeftReal[@bitCast(@as(isize, @intCast(index)))];
            ptr_hybrRightReal = &hybrRightReal[@bitCast(@as(isize, @intCast(index)))];
            temp1 = ptr_hybrLeftReal.* << @intCast(@as(c_int, 1));
            temp2 = ptr_hybrRightReal.* << @intCast(@as(c_int, 1));
            temp3 = fxp_mul32_by_16(temp1, h11);
            ptr_hybrLeftReal.* = fxp_mac32_by_16(temp2, h21, temp3) << @intCast(@as(c_int, 1));
            temp3 = fxp_mul32_by_16(temp1, h12);
            ptr_hybrRightReal.* = fxp_mac32_by_16(temp2, h22, temp3) << @intCast(@as(c_int, 1));
            ptr_hybrLeftImag = &hybrLeftImag[@bitCast(@as(isize, @intCast(index)))];
            ptr_hybrRightImag = &hybrRightImag[@bitCast(@as(isize, @intCast(index)))];
            temp1 = ptr_hybrLeftImag.* << @intCast(@as(c_int, 1));
            temp2 = ptr_hybrRightImag.* << @intCast(@as(c_int, 1));
            temp3 = fxp_mul32_by_16(temp1, h11);
            ptr_hybrLeftImag.* = fxp_mac32_by_16(temp2, h21, temp3) << @intCast(@as(c_int, 1));
            temp3 = fxp_mul32_by_16(temp1, h12);
            ptr_hybrRightImag.* = fxp_mac32_by_16(temp2, h22, temp3) << @intCast(@as(c_int, 1));
        }
    }
    temp1 = pms.*.deltaH11[@as(c_int, 10)];
    temp2 = pms.*.deltaH12[@as(c_int, 10)];
    pms.*.H11[@as(c_int, 10)] += temp1;
    h11 = @truncate(pms.*.H11[@as(c_int, 10)] >> @intCast(@as(c_int, 16)));
    pms.*.H12[@as(c_int, 10)] += temp2;
    h12 = @truncate(pms.*.H12[@as(c_int, 10)] >> @intCast(@as(c_int, 16)));
    temp1 = pms.*.deltaH21[@as(c_int, 10)];
    temp2 = pms.*.deltaH22[@as(c_int, 10)];
    pms.*.H21[@as(c_int, 10)] += temp1;
    h21 = @truncate(pms.*.H21[@as(c_int, 10)] >> @intCast(@as(c_int, 16)));
    pms.*.H22[@as(c_int, 10)] += temp2;
    h22 = @truncate(pms.*.H22[@as(c_int, 10)] >> @intCast(@as(c_int, 16)));
    ptr_hybrLeftReal = &qmfLeftReal[@as(c_int, 3)];
    ptr_hybrRightReal = &qmfRightReal[@as(c_int, 3)];
    temp1 = ptr_hybrLeftReal.* << @intCast(@as(c_int, 1));
    temp2 = ptr_hybrRightReal.* << @intCast(@as(c_int, 1));
    temp3 = fxp_mul32_by_16(temp1, h11);
    ptr_hybrLeftReal.* = fxp_mac32_by_16(temp2, h21, temp3) << @intCast(@as(c_int, 1));
    temp3 = fxp_mul32_by_16(temp1, h12);
    ptr_hybrRightReal.* = fxp_mac32_by_16(temp2, h22, temp3) << @intCast(@as(c_int, 1));
    ptr_hybrLeftImag = &qmfLeftImag[@as(c_int, 3)];
    ptr_hybrRightImag = &qmfRightImag[@as(c_int, 3)];
    temp1 = ptr_hybrLeftImag.* << @intCast(@as(c_int, 1));
    temp2 = ptr_hybrRightImag.* << @intCast(@as(c_int, 1));
    temp3 = fxp_mul32_by_16(temp1, h11);
    ptr_hybrLeftImag.* = fxp_mac32_by_16(temp2, h21, temp3) << @intCast(@as(c_int, 1));
    temp3 = fxp_mul32_by_16(temp1, h12);
    ptr_hybrRightImag.* = fxp_mac32_by_16(temp2, h22, temp3) << @intCast(@as(c_int, 1));
    {
        group = @as(c_int, 10) + @as(c_int, 1);
        while (group < (@as(c_int, 10) + @as(c_int, 12))) : (group += 1) {
            temp1 = pms.*.deltaH11[@bitCast(@as(isize, @intCast(group)))];
            temp2 = pms.*.deltaH12[@bitCast(@as(isize, @intCast(group)))];
            pms.*.H11[@bitCast(@as(isize, @intCast(group)))] += temp1;
            h11 = @truncate(pms.*.H11[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            pms.*.H12[@bitCast(@as(isize, @intCast(group)))] += temp2;
            h12 = @truncate(pms.*.H12[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            temp1 = pms.*.deltaH21[@bitCast(@as(isize, @intCast(group)))];
            temp2 = pms.*.deltaH22[@bitCast(@as(isize, @intCast(group)))];
            pms.*.H21[@bitCast(@as(isize, @intCast(group)))] += temp1;
            h21 = @truncate(pms.*.H21[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            pms.*.H22[@bitCast(@as(isize, @intCast(group)))] += temp2;
            h22 = @truncate(pms.*.H22[@bitCast(@as(isize, @intCast(group)))] >> @intCast(@as(c_int, 16)));
            index = groupBorders[@bitCast(@as(isize, @intCast(group)))];
            maxSubband = groupBorders[@bitCast(@as(isize, @intCast(group + @as(c_int, 1))))];
            maxSubband = if (usb < maxSubband) usb else maxSubband;
            ptr_hybrLeftReal = &qmfLeftReal[@bitCast(@as(isize, @intCast(index)))];
            ptr_hybrRightReal = &qmfRightReal[@bitCast(@as(isize, @intCast(index)))];
            {
