                        const ref = &ptr_hybrLeftReal;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = fxp_mac32_by_16(temp2, h21, temp3) << @intCast(@as(c_int, 1));
                    temp3 = fxp_mul32_by_16(temp1, h12);
                    (blk: {
                        const ref = &ptr_hybrRightReal;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = fxp_mac32_by_16(temp2, h22, temp3) << @intCast(@as(c_int, 1));
                }
            }
