            ptr_hybrRightImag = &qmfRightImag[@bitCast(@as(isize, @intCast(index)))];
            {
                subband = index;
                while (subband < maxSubband) : (subband += 1) {
                    temp1 = ptr_hybrLeftImag.* << @intCast(@as(c_int, 1));
                    temp2 = ptr_hybrRightImag.* << @intCast(@as(c_int, 1));
                    temp3 = fxp_mul32_by_16(temp1, h11);
                    (blk: {
                        const ref = &ptr_hybrLeftImag;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = fxp_mac32_by_16(temp2, h21, temp3) << @intCast(@as(c_int, 1));
