                    (blk: {
                        const ref = &ptr_hybrRightImag;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* = fxp_mac32_by_16(temp2, h22, temp3) << @intCast(@as(c_int, 1));
                }
            }
        }
    }
