pub fn pulse_nc(arg_coef: [*c]Int16, arg_pPulseInfo: [*c]const PulseInfo, arg_pLongFrameInfo: [*c]const FrameInfo, arg_max: [*c]Int) void {
    var coef = arg_coef;
    _ = &coef;
    var pPulseInfo = arg_pPulseInfo;
    _ = &pPulseInfo;
    var pLongFrameInfo = arg_pLongFrameInfo;
    _ = &pLongFrameInfo;
    var max = arg_max;
    _ = &max;
