pub fn pv_sqrt(arg_man: Int32, arg_exp: Int32, arg_result: [*c]Root_sq, arg_sqrt_cache: [*c]Int32) void {
    var man = arg_man;
    _ = &man;
    var exp = arg_exp;
    _ = &exp;
    var result = arg_result;
    _ = &result;
    var sqrt_cache = arg_sqrt_cache;
    _ = &sqrt_cache;
    var y: Int32 = undefined;
    _ = &y;
    var xx: Int32 = undefined;
    _ = &xx;
    var nn: Int32 = undefined;
    _ = &nn;
    var i: Int32 = undefined;
    _ = &i;
    var pt_table: [*c]const Int32 = @ptrCast(@alignCast(&sqrt_table));
    _ = &pt_table;
    if ((sqrt_cache[@as(c_int, 0)] == man) and (sqrt_cache[@as(c_int, 1)] == exp)) {
        result.*.root = sqrt_cache[@as(c_int, 2)];
        result.*.shift_factor = @as(Int16, @truncate(sqrt_cache[@as(c_int, 3)]));
    } else {
        sqrt_cache[@as(c_int, 0)] = man;
        sqrt_cache[@as(c_int, 1)] = exp;
        if (man > @as(c_int, 0)) {
            xx = man;
            if (man >= @as(Int32, @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))))) {
                nn = exp + @as(c_int, 1);
                while ((blk: {
                    const ref = &xx;
                    ref.* >>= @intCast(@as(c_int, 1));
                    break :blk ref.*;
                }) > @as(Int32, @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))))) {
                    nn += 1;
                }
            } else if (man < @as(Int32, @intFromFloat((@as(f32, 0.5) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + (if (@as(f32, 0.5) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))))) {
                nn = exp - @as(c_int, 1);
                while ((blk: {
                    const ref = &xx;
                    ref.* <<= @intCast(@as(c_int, 1));
                    break :blk ref.*;
                }) < @as(Int32, @intFromFloat((@as(f32, 0.5) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + (if (@as(f32, 0.5) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))))) {
                    nn -= 1;
                }
            } else {
                nn = exp;
            }
            y = fxp_mul32_Q28((blk: {
                const ref = &pt_table;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*, xx);
            {
                i = 3;
                while (i != @as(c_int, 0)) : (i -= 1) {
                    y += (blk: {
                        const ref = &pt_table;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    y = fxp_mul32_Q28(y, xx);
                    y += (blk: {
                        const ref = &pt_table;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    y = fxp_mul32_Q28(y, xx);
                }
            }
            y += (blk: {
                const ref = &pt_table;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            y = fxp_mul32_Q28(y, xx) + (blk: {
                const ref = &pt_table;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            if (nn >= @as(c_int, 0)) {
                if ((nn & @as(c_int, 1)) != 0) {
                    y = fxp_mul32_Q29(y, @intFromFloat((@as(f32, 1.414214) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + (if (@as(f32, 1.414214) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
                    result.*.shift_factor = (nn >> @intCast(@as(c_int, 1))) - @as(c_int, 28);
                } else {
                    result.*.shift_factor = (nn >> @intCast(@as(c_int, 1))) - @as(c_int, 29);
                }
            } else {
                if ((nn & @as(c_int, 1)) != 0) {
                    y = fxp_mul32_Q28(y, @intFromFloat((@as(f32, 0.707107) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + (if (@as(f32, 0.707107) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
                }
                result.*.shift_factor = -(-nn >> @intCast(@as(c_int, 1))) - @as(c_int, 29);
            }
            result.*.root = y;
        } else {
            result.*.root = 0;
            result.*.shift_factor = 0;
        }
    }
    sqrt_cache[@as(c_int, 2)] = result.*.root;
    sqrt_cache[@as(c_int, 3)] = result.*.shift_factor;
}

pub fn q_normalize(arg_qFormat: [*c]Int, arg_pFrameInfo: [*c]const FrameInfo, arg_abs_max_per_window: [*c]Int32, arg_coef: [*c]Int32) Int {
    var qFormat = arg_qFormat;
    _ = &qFormat;
    var pFrameInfo = arg_pFrameInfo;
    _ = &pFrameInfo;
    var abs_max_per_window = arg_abs_max_per_window;
    _ = &abs_max_per_window;
    var coef = arg_coef;
    _ = &coef;
    var sfb: Int = undefined;
    _ = &sfb;
    var nsfb: Int = undefined;
    _ = &nsfb;
    var win: Int = undefined;
    _ = &win;
    var nwin: Int = undefined;
    _ = &nwin;
    var sfbWidth: Int = undefined;
    _ = &sfbWidth;
    var shift_amt: Int = undefined;
    _ = &shift_amt;
    var min_q: Int = 1000;
    _ = &min_q;
    var stop_idx: Int = 0;
    _ = &stop_idx;
    var pSfbPerWin: [*c]const Int = undefined;
    _ = &pSfbPerWin;
    var pWinSfbTop: [*c]const Int16 = undefined;
    _ = &pWinSfbTop;
    var pQformat: [*c]Int = undefined;
    _ = &pQformat;
    var pCoef: [*c]Int32 = undefined;
    _ = &pCoef;
    nwin = pFrameInfo.*.num_win;
    pQformat = &qFormat[@as(c_int, 0)];
    pSfbPerWin = &pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
    {
        win = nwin;
        while (win != @as(c_int, 0)) : (win -= 1) {
            nsfb = (blk: {
                const ref = &pSfbPerWin;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            if ((nsfb < @as(c_int, 0)) or (nsfb > MAXBANDS)) {
                break;
            }
            {
                sfb = nsfb;
                while (sfb != @as(c_int, 0)) : (sfb -= 1) {
                    var qformat: Int = (blk: {
                        const ref = &pQformat;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    _ = &qformat;
                    if (qformat < min_q) {
                        min_q = qformat;
                    }
                }
            }
        }
    }
    pQformat = &qFormat[@as(c_int, 0)];
    pSfbPerWin = &pFrameInfo.*.sfb_per_win[@as(c_int, 0)];
    pCoef = &coef[@as(c_int, 0)];
    {
        win = 0;
        while (win < nwin) : (win += 1) {
            var max: Int32 = 0;
            _ = &max;
            stop_idx = 0;
            nsfb = (blk: {
                const ref = &pSfbPerWin;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).*;
            if ((nsfb < @as(c_int, 0)) or (nsfb > MAXBANDS)) {
                break;
            }
            pWinSfbTop = &pFrameInfo.*.win_sfb_top[@bitCast(@as(isize, @intCast(win)))][@as(c_int, 0)];
            {
                sfb = nsfb;
                while (sfb != @as(c_int, 0)) : (sfb -= 1) {
                    var tmp1: Int = undefined;
                    _ = &tmp1;
                    var tmp2: Int = undefined;
                    _ = &tmp2;
                    tmp1 = (blk: {
                        const ref = &pWinSfbTop;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    tmp2 = (blk: {
                        const ref = &pQformat;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*;
                    sfbWidth = tmp1 - stop_idx;
                    if (sfbWidth < @as(c_int, 2)) {
                        break;
                    }
                    stop_idx += sfbWidth;
                    shift_amt = tmp2 - min_q;
                    if (shift_amt == @as(c_int, 0)) {
                        var tmp1_1: Int32 = undefined;
                        _ = &tmp1_1;
                        var tmp2_2: Int32 = undefined;
                        _ = &tmp2_2;
                        tmp1_1 = (blk: {
                            const ref = &pCoef;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).*;
                        tmp2_2 = (blk: {
                            const ref = &pCoef;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).*;
                        {
                            var i: Int = (sfbWidth >> @intCast(@as(c_int, 1))) - @as(c_int, 1);
                            _ = &i;
                            while (i != @as(c_int, 0)) : (i -= 1) {
                                max |= (tmp1_1 >> @intCast(@as(c_int, 31))) ^ tmp1_1;
                                max |= (tmp2_2 >> @intCast(@as(c_int, 31))) ^ tmp2_2;
                                tmp1_1 = (blk: {
                                    const ref = &pCoef;
                                    const tmp = ref.*;
                                    ref.* += 1;
                                    break :blk tmp;
                                }).*;
                                tmp2_2 = (blk: {
                                    const ref = &pCoef;
                                    const tmp = ref.*;
                                    ref.* += 1;
                                    break :blk tmp;
                                }).*;
                            }
                        }
                        max |= (tmp1_1 >> @intCast(@as(c_int, 31))) ^ tmp1_1;
                        max |= (tmp2_2 >> @intCast(@as(c_int, 31))) ^ tmp2_2;
                    } else {
                        if (shift_amt < @as(c_int, 31)) {
                            var tmp1_1: Int32 = undefined;
                            _ = &tmp1_1;
                            var tmp2_2: Int32 = undefined;
                            _ = &tmp2_2;
                            tmp1_1 = pv_shr((blk: {
                                const ref = &pCoef;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*, shift_amt);
                            tmp2_2 = pv_shr((blk: {
                                const ref = &pCoef;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).*, shift_amt);
                            {
                                var i: Int = (sfbWidth >> @intCast(@as(c_int, 1))) - @as(c_int, 1);
                                _ = &i;
                                while (i != @as(c_int, 0)) : (i -= 1) {
                                    (blk: {
                                        const ref = &pCoef;
                                        const tmp = ref.*;
                                        ref.* += 1;
                                        break :blk tmp;
                                    }).* = tmp1_1;
                                    (blk: {
                                        const ref = &pCoef;
                                        const tmp = ref.*;
                                        ref.* += 1;
                                        break :blk tmp;
                                    }).* = tmp2_2;
                                    max |= (tmp1_1 >> @intCast(@as(c_int, 31))) ^ tmp1_1;
                                    max |= (tmp2_2 >> @intCast(@as(c_int, 31))) ^ tmp2_2;
                                    tmp1_1 = pv_shr((blk: {
                                        const ref = &pCoef;
                                        const tmp = ref.*;
                                        ref.* += 1;
                                        break :blk tmp;
                                    }).*, shift_amt);
                                    tmp2_2 = pv_shr((blk: {
                                        const ref = &pCoef;
                                        const tmp = ref.*;
                                        ref.* -= 1;
                                        break :blk tmp;
                                    }).*, shift_amt);
                                }
                            }
                            (blk: {
                                const ref = &pCoef;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = tmp1_1;
                            (blk: {
                                const ref = &pCoef;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).* = tmp2_2;
                            max |= (tmp1_1 >> @intCast(@as(c_int, 31))) ^ tmp1_1;
                            max |= (tmp2_2 >> @intCast(@as(c_int, 31))) ^ tmp2_2;
                        } else {
                            _ = memset(@ptrCast(@alignCast(pCoef)), 0, @sizeOf(Int32) *% @as(c_ulong, @bitCast(@as(c_long, sfbWidth))));
                            pCoef += @as(usize, @bitCast(@as(isize, @intCast(sfbWidth))));
                        }
                    }
                    abs_max_per_window[@bitCast(@as(isize, @intCast(win)))] = max;
                }
            }
        }
    }
    return min_q;
}

