pub fn sbr_aliasing_reduction(arg_degreeAlias: [*c]Int32, arg_nrg_gain_man: [*c]Int32, arg_nrg_gain_exp: [*c]Int32, arg_nrg_est_man: [*c]Int32, arg_nrg_est_exp: [*c]Int32, arg_dontUseTheseGainValues: [*c]Int32, arg_noSubbands: Int32, arg_lowSubband: Int32, arg_sqrt_cache: [*c][4]Int32, arg_groupVector: [*c]Int32) void {
    var degreeAlias = arg_degreeAlias;
    _ = &degreeAlias;
    var nrg_gain_man = arg_nrg_gain_man;
    _ = &nrg_gain_man;
    var nrg_gain_exp = arg_nrg_gain_exp;
    _ = &nrg_gain_exp;
    var nrg_est_man = arg_nrg_est_man;
    _ = &nrg_est_man;
    var nrg_est_exp = arg_nrg_est_exp;
    _ = &nrg_est_exp;
    var dontUseTheseGainValues = arg_dontUseTheseGainValues;
    _ = &dontUseTheseGainValues;
    var noSubbands = arg_noSubbands;
    _ = &noSubbands;
    var lowSubband = arg_lowSubband;
    _ = &lowSubband;
    var sqrt_cache = arg_sqrt_cache;
    _ = &sqrt_cache;
    var groupVector = arg_groupVector;
    _ = &groupVector;
    var temp1: Int32 = undefined;
    _ = &temp1;
    var est_total: Int32 = undefined;
    _ = &est_total;
    var ref_total_man: Int32 = undefined;
    _ = &ref_total_man;
    var ref_total_exp: Int32 = undefined;
    _ = &ref_total_exp;
    var tmp_q1: Int32 = undefined;
    _ = &tmp_q1;
    var tmp_q2: Int32 = undefined;
    _ = &tmp_q2;
    var tmp_q3: Int32 = undefined;
    _ = &tmp_q3;
    var tmp_q4: Int32 = undefined;
    _ = &tmp_q4;
    var bst_man: Int32 = undefined;
    _ = &bst_man;
    var bst_exp: Int32 = undefined;
    _ = &bst_exp;
    var quotient: struct_intg_div = undefined;
    _ = &quotient;
    var root_sq: struct_intg_sqrt = undefined;
    _ = &root_sq;
    var group: Int32 = undefined;
    _ = &group;
    var grouping: Int32 = 0;
    _ = &grouping;
    var index: Int32 = 0;
    _ = &index;
    var noGroups: Int32 = undefined;
    _ = &noGroups;
    var k: Int32 = undefined;
    _ = &k;
    {
        k = 0;
        while (k < (noSubbands - @as(c_int, 1))) : (k += 1) {
            if ((degreeAlias[@bitCast(@as(isize, @intCast((k + lowSubband) + @as(c_int, 1))))] != 0) and (dontUseTheseGainValues[@bitCast(@as(isize, @intCast(k)))] == @as(c_int, 0))) {
                if (grouping == @as(c_int, 0)) {
                    groupVector[@bitCast(@as(isize, @intCast(index)))] = k + lowSubband;
                    grouping = 1;
                    index += 1;
                }
            } else {
                if (grouping != 0) {
                    groupVector[@bitCast(@as(isize, @intCast(index)))] = k + lowSubband;
                    if (!(dontUseTheseGainValues[@bitCast(@as(isize, @intCast(k)))] != 0)) {
                        groupVector[@bitCast(@as(isize, @intCast(index)))] += 1;
                    }
                    grouping = 0;
                    index += 1;
                }
            }
        }
    }
    if (grouping != 0) {
        groupVector[@bitCast(@as(isize, @intCast(index)))] = noSubbands + lowSubband;
        index += 1;
    }
    noGroups = index >> @intCast(@as(c_int, 1));
    {
        group = 0;
        while (group < noGroups) : (group += 1) {
            var startGroup: c_int = groupVector[@bitCast(@as(isize, @intCast(group << @intCast(@as(c_int, 1)))))] - lowSubband;
            _ = &startGroup;
            var stopGroup: c_int = groupVector[@bitCast(@as(isize, @intCast((group << @intCast(@as(c_int, 1))) + @as(c_int, 1))))] - lowSubband;
            _ = &stopGroup;
            est_total = 0;
            ref_total_man = 0;
            tmp_q1 = -@as(c_int, 100);
            tmp_q2 = -@as(c_int, 100);
            {
                k = startGroup;
                while (k < stopGroup) : (k += 1) {
                    if (tmp_q1 < nrg_est_exp[@bitCast(@as(isize, @intCast(k)))]) {
                        tmp_q1 = nrg_est_exp[@bitCast(@as(isize, @intCast(k)))];
                    }
                    if (tmp_q2 < (nrg_est_exp[@bitCast(@as(isize, @intCast(k)))] + (nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] << @intCast(@as(c_int, 1))))) {
                        tmp_q2 = nrg_est_exp[@bitCast(@as(isize, @intCast(k)))] + (nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] << @intCast(@as(c_int, 1)));
                    }
                }
            }
            k -= startGroup;
            tmp_q2 += @as(c_int, 59) - pv_normalize(k);
            {
                k = startGroup;
                while (k < stopGroup) : (k += 1) {
                    est_total += pv_shr(nrg_est_man[@bitCast(@as(isize, @intCast(k)))], tmp_q1 - nrg_est_exp[@bitCast(@as(isize, @intCast(k)))]);
                    if ((tmp_q2 - (nrg_est_exp[@bitCast(@as(isize, @intCast(k)))] + (nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] << @intCast(@as(c_int, 1))))) < @as(c_int, 60)) {
                        nrg_gain_man[@bitCast(@as(isize, @intCast(k)))] = fxp_mul32_Q28(nrg_gain_man[@bitCast(@as(isize, @intCast(k)))], nrg_gain_man[@bitCast(@as(isize, @intCast(k)))]);
                        nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] = (nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] << @intCast(@as(c_int, 1))) + @as(c_int, 28);
                        tmp_q3 = fxp_mul32_Q28(nrg_gain_man[@bitCast(@as(isize, @intCast(k)))], nrg_est_man[@bitCast(@as(isize, @intCast(k)))]);
                        ref_total_man += pv_shr(tmp_q3, tmp_q2 - (nrg_est_exp[@bitCast(@as(isize, @intCast(k)))] + nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))]));
                    }
                }
            }
            ref_total_exp = tmp_q2 + @as(c_int, 28);
            pv_div(ref_total_man, est_total, &quotient);
            tmp_q2 += (-tmp_q1 - quotient.shift_factor) - @as(c_int, 2);
            {
                k = startGroup;
                while (k < stopGroup) : (k += 1) {
                    var alpha: Int32 = undefined;
                    _ = &alpha;
                    temp1 = k + lowSubband;
                    if (k < (noSubbands - @as(c_int, 1))) {
                        alpha = if (degreeAlias[@bitCast(@as(isize, @intCast(temp1 + @as(c_int, 1))))] > degreeAlias[@bitCast(@as(isize, @intCast(temp1)))]) degreeAlias[@bitCast(@as(isize, @intCast(temp1 + @as(c_int, 1))))] else degreeAlias[@bitCast(@as(isize, @intCast(temp1)))];
                    } else {
                        alpha = degreeAlias[@bitCast(@as(isize, @intCast(temp1)))];
                    }
                    tmp_q1 = if (tmp_q2 > nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))]) tmp_q2 else nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))];
                    tmp_q1 += 1;
                    tmp_q3 = fxp_mul32_Q30(alpha, quotient.quotient);
                    tmp_q4 = fxp_mul32_Q30(@as(Int32, @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))) - alpha, nrg_gain_man[@bitCast(@as(isize, @intCast(k)))]);
                    nrg_gain_man[@bitCast(@as(isize, @intCast(k)))] = (pv_shr(tmp_q3, tmp_q1 - tmp_q2)) + (pv_shr(tmp_q4, tmp_q1 - nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))]));
                    nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] = tmp_q1;
                }
            }
            bst_exp = -@as(c_int, 100);
            {
                k = startGroup;
                while (k < stopGroup) : (k += 1) {
                    if (bst_exp < (nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] + nrg_est_exp[@bitCast(@as(isize, @intCast(k)))])) {
                        bst_exp = nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] + nrg_est_exp[@bitCast(@as(isize, @intCast(k)))];
                    }
                }
            }
            k -= startGroup;
            while (k != @as(c_int, 0)) {
                k >>= @intCast(@as(c_int, 1));
                bst_exp += 1;
            }
            bst_man = 0;
            {
                k = startGroup;
                while (k < stopGroup) : (k += 1) {
                    tmp_q2 = fxp_mul32_Q28(nrg_gain_man[@bitCast(@as(isize, @intCast(k)))], nrg_est_man[@bitCast(@as(isize, @intCast(k)))]);
                    bst_man += pv_shr(tmp_q2, (bst_exp - nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))]) - nrg_est_exp[@bitCast(@as(isize, @intCast(k)))]);
                }
            }
            bst_exp += 28;
            if (bst_man != 0) {
                pv_div(ref_total_man, bst_man, &quotient);
                bst_exp = ((ref_total_exp - bst_exp) - quotient.shift_factor) - @as(c_int, 30);
                bst_man = quotient.quotient;
                {
                    k = startGroup;
                    while (k < stopGroup) : (k += 1) {
                        tmp_q1 = fxp_mul32_Q30(bst_man, nrg_gain_man[@bitCast(@as(isize, @intCast(k)))]);
                        pv_sqrt(tmp_q1, (bst_exp + nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))]) + @as(c_int, 60), &root_sq, @ptrCast(@alignCast(&sqrt_cache[@as(c_int, 0)])));
                        nrg_gain_man[@bitCast(@as(isize, @intCast(k)))] = root_sq.root;
                        nrg_gain_exp[@bitCast(@as(isize, @intCast(k)))] = root_sq.shift_factor;
                    }
                }
            } else {
                _ = memset(@ptrCast(@alignCast(&nrg_gain_man[@bitCast(@as(isize, @intCast(startGroup)))])), 0, @as(c_ulong, @bitCast(@as(c_long, stopGroup - startGroup))) *% @sizeOf(@TypeOf(nrg_gain_man[@as(c_int, 0)])));
                _ = memset(@ptrCast(@alignCast(&nrg_gain_exp[@bitCast(@as(isize, @intCast(startGroup)))])), 0, @as(c_ulong, @bitCast(@as(c_long, stopGroup - startGroup))) *% @sizeOf(@TypeOf(nrg_gain_exp[@as(c_int, 0)])));
            }
        }
    }
}

pub fn sbr_applied(arg_self: [*c]SBRDECODER_DATA, arg_stream: [*c]SBRBITSTREAM, arg_ch_left: [*c]Int16, arg_ch_right: [*c]Int16, arg_timeData: [*c]Int16, arg_sbrDec: [*c]SBR_DEC, arg_pVars: [*c]tDec_Int_File, arg_numChannels: Int32) SBR_ERROR {
    var self = arg_self;
    _ = &self;
    var stream = arg_stream;
    _ = &stream;
    var ch_left = arg_ch_left;
    _ = &ch_left;
    var ch_right = arg_ch_right;
    _ = &ch_right;
    var timeData = arg_timeData;
    _ = &timeData;
    var sbrDec = arg_sbrDec;
    _ = &sbrDec;
    var pVars = arg_pVars;
    _ = &pVars;
    var numChannels = arg_numChannels;
    _ = &numChannels;
    var err: SBR_ERROR = SBRDEC_OK;
    _ = &err;
    var eleChannels: Int32 = 0;
    _ = &eleChannels;
    var SbrChannel: [*c]SBR_CHANNEL = @ptrCast(@alignCast(&self.*.SbrChannel));
    _ = &SbrChannel;
    if (stream.*.NrElements != 0) {
        err = sbr_read_data(self, sbrDec, stream);
        if (err != @as(SBR_ERROR, SBRDEC_OK)) {
            self.*.SbrChannel[@as(c_int, 0)].syncState = UPSAMPLING;
            if (eleChannels == @as(c_int, 2)) {
                self.*.SbrChannel[@as(c_int, 1)].syncState = UPSAMPLING;
            }
        }
        if ((SbrChannel[@as(c_int, 0)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)) and (self.*.setStreamType != 0)) {
            self.*.setStreamType = 0;
            var sbrEnablePS: Int = self.*.hParametricStereoDec.*.psDetected;
            _ = &sbrEnablePS;
            pVars.*.mc_info.psPresentFlag = sbrEnablePS;
            if (sbrEnablePS != 0) {
                pVars.*.mc_info.ExtendedAudioObjectType = MP4AUDIO_PS;
                _ = ps_allocate_decoder(self, 32);
                sbrDec.*.LC_aacP_DecoderFlag = 0;
            } else {
                if (pVars.*.mc_info.ExtendedAudioObjectType != @as(tMP4AudioObjectType, MP4AUDIO_PS)) {
                    pVars.*.mc_info.ExtendedAudioObjectType = MP4AUDIO_SBR;
                    if (pVars.*.mc_info.nch > @as(c_int, 1)) {
                        sbrDec.*.LC_aacP_DecoderFlag = 0;
                    } else {
                        sbrDec.*.LC_aacP_DecoderFlag = 0;
                    }
                } else {
                    sbrEnablePS = 1;
                    pVars.*.mc_info.psPresentFlag = sbrEnablePS;
                }
            }
        } else {
            if (pVars.*.mc_info.ExtendedAudioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_AAC_LC)) {
                pVars.*.mc_info.ExtendedAudioObjectType = MP4AUDIO_SBR;
            }
            if (pVars.*.mc_info.nch > @as(c_int, 1)) {
                sbrDec.*.LC_aacP_DecoderFlag = 0;
            } else {
                sbrDec.*.LC_aacP_DecoderFlag = 0;
            }
            err = SBRDEC_OK;
        }
        eleChannels = if (stream.*.sbrElement[@as(c_int, 0)].ElementID == SBR_ID_CPE) @as(c_int, 2) else @as(c_int, 1);
        if (SbrChannel[@as(c_int, 0)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)) {
            sbr_decode_envelope(&SbrChannel[@as(c_int, 0)].frameData);
            decode_noise_floorlevels(&SbrChannel[@as(c_int, 0)].frameData);
            if (!(SbrChannel[@as(c_int, 0)].frameData.coupling != 0)) {
                sbr_requantize_envelope_data(&SbrChannel[@as(c_int, 0)].frameData);
            }
            if (eleChannels == @as(c_int, 2)) {
                sbr_decode_envelope(&SbrChannel[@as(c_int, 1)].frameData);
                decode_noise_floorlevels(&SbrChannel[@as(c_int, 1)].frameData);
                if (SbrChannel[@as(c_int, 1)].frameData.coupling != 0) {
                    sbr_envelope_unmapping(&SbrChannel[@as(c_int, 0)].frameData, &SbrChannel[@as(c_int, 1)].frameData);
                } else {
                    sbr_requantize_envelope_data(&SbrChannel[@as(c_int, 1)].frameData);
                }
            }
        } else {
            _ = init_sbr_dec(sbrDec.*.outSampleRate >> @intCast(@as(c_int, 1)), pVars.*.mc_info.upsamplingFactor, sbrDec, &self.*.SbrChannel[@as(c_int, 0)].frameData);
            if ((eleChannels == @as(c_int, 2)) and (SbrChannel[@as(c_int, 1)].syncState != @as(SBR_SYNC_STATE, SBR_ACTIVE))) {
                _ = init_sbr_dec(sbrDec.*.outSampleRate >> @intCast(@as(c_int, 1)), pVars.*.mc_info.upsamplingFactor, sbrDec, &self.*.SbrChannel[@as(c_int, 1)].frameData);
            }
        }
    }
    if (pVars.*.mc_info.ExtendedAudioObjectType == @as(tMP4AudioObjectType, MP4AUDIO_PS)) {
        ps_bstr_decoding(self.*.hParametricStereoDec);
        var tempInt16Ptr: [*c]Int16 = @ptrCast(@alignCast(&SbrChannel[@as(c_int, 1)].frameData.V));
        _ = &tempInt16Ptr;
        self.*.hParametricStereoDec.*.R_ch_qmf_filter_history = @ptrCast(@alignCast(tempInt16Ptr));
        SbrChannel[@as(c_int, 0)].frameData.sbrQmfBufferReal = @ptrCast(@alignCast(&pVars.*.share.predictedSamples));
        SbrChannel[@as(c_int, 0)].frameData.sbrQmfBufferImag = &pVars.*.fxpCoef[@as(c_int, 0)][@as(c_int, 920)];
        sbr_dec(ch_left, timeData, &SbrChannel[@as(c_int, 0)].frameData, @intFromBool(SbrChannel[@as(c_int, 0)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)), sbrDec, &timeData[@as(c_int, 1)], self.*.hParametricStereoDec, pVars);
    } else {
        SbrChannel[@as(c_int, 0)].frameData.sbrQmfBufferReal = @ptrCast(@alignCast(&pVars.*.fxpCoef[@as(c_int, 0)]));
        SbrChannel[@as(c_int, 0)].frameData.sbrQmfBufferImag = @ptrCast(@alignCast(&pVars.*.fxpCoef[@as(c_int, 1)]));
        sbr_dec(ch_left, timeData, &SbrChannel[@as(c_int, 0)].frameData, @intFromBool(SbrChannel[@as(c_int, 0)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)), sbrDec, null, null, pVars);
        if (numChannels == @as(c_int, 2)) {
            SbrChannel[@as(c_int, 1)].frameData.sbrQmfBufferReal = @ptrCast(@alignCast(&pVars.*.fxpCoef[@as(c_int, 0)]));
            SbrChannel[@as(c_int, 1)].frameData.sbrQmfBufferImag = @ptrCast(@alignCast(&pVars.*.fxpCoef[@as(c_int, 1)]));
            sbr_dec(ch_right, &timeData[@as(c_int, 1)], &SbrChannel[@as(c_int, 1)].frameData, @intFromBool(SbrChannel[@as(c_int, 1)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)), sbrDec, null, null, pVars);
        }
    }
    return err;
}

pub fn sbr_crc_check(arg_hBitBuf: [*c]BIT_BUFFER, arg_NrBits: UInt32) Int32 {
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var NrBits = arg_NrBits;
    _ = &NrBits;
    var crcResult: Int32 = 1;
    _ = &crcResult;
    var BitBufferCRC: BIT_BUFFER = undefined;
    _ = &BitBufferCRC;
    var NrCrcBits: UInt32 = undefined;
    _ = &NrCrcBits;
    var crcCheckSum: UInt32 = undefined;
    _ = &crcCheckSum;
    var i: Int32 = undefined;
    _ = &i;
    var CrcBuf: CRC_BUFFER = undefined;
    _ = &CrcBuf;
    var bValue: UInt32 = undefined;
    _ = &bValue;
    var CrcStep: Int32 = undefined;
    _ = &CrcStep;
    var CrcNrBitsRest: Int32 = undefined;
    _ = &CrcNrBitsRest;
    crcCheckSum = buf_getbits(hBitBuf, 10);
    BitBufferCRC.char_ptr = hBitBuf.*.char_ptr;
    BitBufferCRC.buffer_word = hBitBuf.*.buffer_word;
    BitBufferCRC.buffered_bits = hBitBuf.*.buffered_bits;
    BitBufferCRC.nrBitsRead = hBitBuf.*.nrBitsRead;
    BitBufferCRC.bufferLen = hBitBuf.*.bufferLen;
    NrCrcBits = if (NrBits < (BitBufferCRC.bufferLen -% BitBufferCRC.nrBitsRead)) NrBits else BitBufferCRC.bufferLen -% BitBufferCRC.nrBitsRead;
    CrcStep = @bitCast(@as(c_uint, @truncate(NrCrcBits / @as(UInt32, @bitCast(@as(c_int, @as(c_int, MAXCRCSTEP)))))));
    CrcNrBitsRest = @bitCast(@as(c_uint, @truncate(NrCrcBits -% @as(UInt32, @bitCast(@as(c_int, CrcStep * @as(c_int, MAXCRCSTEP)))))));
    CrcBuf.crcState = 0;
    CrcBuf.crcMask = 512;
    CrcBuf.crcPoly = 563;
    {
        i = 0;
        while (i < CrcStep) : (i += 1) {
            bValue = buf_getbits(&BitBufferCRC, MAXCRCSTEP);
            check_crc(&CrcBuf, bValue, MAXCRCSTEP);
        }
    }
    bValue = buf_getbits(&BitBufferCRC, CrcNrBitsRest);
    check_crc(&CrcBuf, bValue, CrcNrBitsRest);
    if (@as(UInt32, @bitCast(@as(c_int, @as(c_int, CrcBuf.crcState) & @as(c_int, 1023)))) != crcCheckSum) {
        crcResult = 0;
    }
    return crcResult;
}

pub fn sbr_create_limiter_bands(arg_limSbc: [*c][13]Int32, arg_gateMode: [*c]Int32, arg_freqTable: [*c]Int, arg_Patch: struct_PATCH, noBands: Int32) void {
    var limSbc = arg_limSbc;
    _ = &limSbc;
    var gateMode = arg_gateMode;
    _ = &gateMode;
    var freqTable = arg_freqTable;
    _ = &freqTable;
    var Patch = arg_Patch;
    _ = &Patch;
    _ = &noBands;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var k: Int32 = undefined;
    _ = &k;
    var isPatchBorder: [2]Int = undefined;
    _ = &isPatchBorder;
    var patchBorders: [7]Int32 = undefined;
    _ = &patchBorders;
    var workLimiterBandTable: [39]Int32 = undefined;
    _ = &workLimiterBandTable;
    var nOctaves: Int32 = undefined;
    _ = &nOctaves;
    const limiterBandsPerOctave: [4]Int32 = [4]Int32{
        @intFromFloat((@as(f32, 0.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 0.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))),
        @intFromFloat((@as(f32, 1.2) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 1.2) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))),
