pub fn sbr_decode_envelope(arg_hFrameData: [*c]SBR_FRAME_DATA) void {
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var i: Int32 = undefined;
    _ = &i;
    var no_of_bands: Int32 = undefined;
    _ = &no_of_bands;
    var band: Int32 = undefined;
    _ = &band;
    var freqRes: Int32 = undefined;
    _ = &freqRes;
    var iEnvelope: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.iEnvelope_man));
    _ = &iEnvelope;
    var sfb_nrg_prev: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.sfb_nrg_prev_man));
    _ = &sfb_nrg_prev;
    var offset: Int32 = hFrameData.*.offset;
    _ = &offset;
    var nSfb: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.nSfb));
    _ = &nSfb;
    var domain_vec: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.domain_vec1));
    _ = &domain_vec;
    var frameInfo: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.frameInfo));
    _ = &frameInfo;
    {
        i = 0;
        while (i < frameInfo[@as(c_int, 0)]) : (i += 1) {
            freqRes = frameInfo[@bitCast(@as(isize, @intCast((frameInfo[@as(c_int, 0)] + i) + @as(c_int, 2))))];
            no_of_bands = nSfb[@bitCast(@as(isize, @intCast(freqRes)))];
            if (domain_vec[@bitCast(@as(isize, @intCast(i)))] == @as(c_int, 0)) {
                mapLowResEnergyVal(iEnvelope.*, sfb_nrg_prev, offset, 0, freqRes);
                iEnvelope += 1;
                {
                    band = 1;
                    while (band < no_of_bands) : (band += 1) {
                        iEnvelope.* += (iEnvelope - @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))).*;
                        mapLowResEnergyVal(iEnvelope.*, sfb_nrg_prev, offset, band, freqRes);
                        iEnvelope += 1;
                    }
                }
            } else {
                {
                    band = 0;
                    while (band < no_of_bands) : (band += 1) {
                        iEnvelope.* += sfb_nrg_prev[@bitCast(@as(isize, @intCast(indexLow2High(offset, band, freqRes))))];
                        mapLowResEnergyVal(iEnvelope.*, sfb_nrg_prev, offset, band, freqRes);
                        iEnvelope += 1;
                    }
                }
            }
        }
    }
}

pub fn sbr_decode_huff_cw(arg_h: SbrHuffman, arg_hBitBuf: [*c]BIT_BUFFER) Int32 {
    var h = arg_h;
    _ = &h;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var bits: Int32 = undefined;
    _ = &bits;
    var index: Char = 0;
    _ = &index;
    while (@as(c_int, index) >= @as(c_int, 0)) {
        bits = @bitCast(@as(c_uint, @truncate(buf_get_1bit(hBitBuf))));
        index = h[@bitCast(@as(isize, @intCast(index)))][@bitCast(@as(isize, @intCast(bits)))];
    }
    return @as(Int32, index) + @as(c_int, 64);
}

pub fn sbr_downsample_lo_res(arg_v_result: [*c]Int32, arg_num_result: Int32, arg_freqBandTableRef: [*c]Int, arg_num_Ref: Int32) void {
    var v_result = arg_v_result;
    _ = &v_result;
    var num_result = arg_num_result;
    _ = &num_result;
    var freqBandTableRef = arg_freqBandTableRef;
    _ = &freqBandTableRef;
    var num_Ref = arg_num_Ref;
    _ = &num_Ref;
    var step: Int32 = undefined;
    _ = &step;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var org_length: Int32 = undefined;
    _ = &org_length;
    var result_length: Int32 = undefined;
    _ = &result_length;
    var v_index: [29]Int32 = undefined;
    _ = &v_index;
    org_length = num_Ref;
    result_length = num_result;
    v_index[@as(c_int, 0)] = 0;
    i = 0;
    while (org_length > @as(c_int, 0)) {
        i += 1;
        step = @divTrunc(org_length, result_length);
        org_length = org_length - step;
        result_length -= 1;
        v_index[@bitCast(@as(isize, @intCast(i)))] = v_index[@bitCast(@as(isize, @intCast(i - @as(c_int, 1))))] + step;
    }
    {
