pub fn sbr_extract_extended_data(arg_hBitBuf: [*c]BIT_BUFFER, arg_hParametricStereoDec: HANDLE_PS_DEC) void {
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var hParametricStereoDec = arg_hParametricStereoDec;
    _ = &hParametricStereoDec;
    var extended_data: Int32 = undefined;
    _ = &extended_data;
    var i: Int32 = undefined;
    _ = &i;
    var nBitsLeft: Int32 = undefined;
    _ = &nBitsLeft;
    var extension_id: Int32 = undefined;
    _ = &extension_id;
    extended_data = @bitCast(@as(c_uint, @truncate(buf_get_1bit(hBitBuf))));
    if (extended_data != 0) {
        var cnt: Int32 = undefined;
        _ = &cnt;
        cnt = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 4))));
        if (cnt == ((@as(c_int, 1) << @intCast(@as(c_int, 4))) - @as(c_int, 1))) {
            {
                const ref = &cnt;
                ref.* = @bitCast(@as(c_uint, @truncate(@as(UInt32, @bitCast(@as(c_int, ref.*))) +% buf_getbits(hBitBuf, 8))));
            }
        }
        nBitsLeft = cnt << @intCast(@as(c_int, 3));
        while (nBitsLeft > @as(c_int, 7)) {
            extension_id = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
            nBitsLeft -= 2;
            blk: {
                switch (extension_id) {
                    @as(c_int, 2) => {
                        if (hParametricStereoDec != @as(HANDLE_PS_DEC, @ptrFromInt(@as(usize, @intCast(@as(c_int, 0)))))) {
                            if (!(hParametricStereoDec.*.psDetected != 0)) {
                                hParametricStereoDec.*.psDetected = 1;
                            }
                            nBitsLeft -= ps_read_data(hParametricStereoDec, hBitBuf, nBitsLeft);
                        }
                        break :blk;
                    },
                    else => {
                        cnt = nBitsLeft >> @intCast(@as(c_int, 3));
                        {
                            i = 0;
                            while (i < cnt) : (i += 1) {
                                _ = buf_getbits(hBitBuf, 8);
                            }
                        }
                        nBitsLeft -= cnt << @intCast(@as(c_int, 3));
                    },
                }
            }
        }
        _ = buf_getbits(hBitBuf, nBitsLeft);
    }
}

pub fn sbr_find_start_andstop_band(samplingFreq: Int32, startFreq: Int32, stopFreq: Int32, arg_lsbM: [*c]Int, arg_usb: [*c]Int) SBR_ERROR {
    _ = &samplingFreq;
    _ = &startFreq;
    _ = &stopFreq;
    var lsbM = arg_lsbM;
    _ = &lsbM;
    var usb = arg_usb;
    _ = &usb;
    lsbM.* = get_sbr_startfreq(samplingFreq, startFreq);
    if (lsbM.* == @as(c_int, 0)) {
        return @bitCast(SBRDEC_ILLEGAL_SCFACTORS);
    }
    if (stopFreq < @as(c_int, 13)) {
        usb.* = get_sbr_stopfreq(samplingFreq, stopFreq);
    } else if (stopFreq == @as(c_int, 13)) {
        usb.* = 64;
    } else if (stopFreq == @as(c_int, 14)) {
        usb.* = lsbM.* << @intCast(@as(c_int, 1));
    } else {
        usb.* = @as(c_int, 3) * lsbM.*;
    }
    if (usb.* > @as(c_int, 64)) {
        usb.* = 64;
    }
    if ((usb.* - lsbM.*) > @as(c_int, 48)) {
        return @bitCast(SBRDEC_INVALID_BITSTREAM);
    }
    if ((samplingFreq == @as(c_int, 44100)) and ((usb.* - lsbM.*) > @as(c_int, 35))) {
        return @bitCast(SBRDEC_INVALID_BITSTREAM);
    }
    if ((samplingFreq >= @as(c_int, 48000)) and ((usb.* - lsbM.*) > @as(c_int, 32))) {
        return @bitCast(SBRDEC_INVALID_BITSTREAM);
    }
    return @bitCast(SBRDEC_OK);
}

