    var targetBufferImag = arg_targetBufferImag;
    _ = &targetBufferImag;
    var invFiltMode = arg_invFiltMode;
    _ = &invFiltMode;
    var prevInvFiltMode = arg_prevInvFiltMode;
    _ = &prevInvFiltMode;
    var invFiltBandTable = arg_invFiltBandTable;
    _ = &invFiltBandTable;
    var noInvFiltBands = arg_noInvFiltBands;
    _ = &noInvFiltBands;
    var highBandStartSb = arg_highBandStartSb;
    _ = &highBandStartSb;
    var v_k_master = arg_v_k_master;
    _ = &v_k_master;
    var numMaster = arg_numMaster;
    _ = &numMaster;
    var fs = arg_fs;
    _ = &fs;
    var frameInfo = arg_frameInfo;
    _ = &frameInfo;
    var degreeAlias = arg_degreeAlias;
    _ = &degreeAlias;
    var scratch_mem = arg_scratch_mem;
    _ = &scratch_mem;
    var BwVector = arg_BwVector;
    _ = &BwVector;
    var BwVectorOld = arg_BwVectorOld;
    _ = &BwVectorOld;
    var Patch = arg_Patch;
    _ = &Patch;
    var LC_flag = arg_LC_flag;
    _ = &LC_flag;
    var highBandStopSb = arg_highBandStopSb;
    _ = &highBandStopSb;
    var i: Int32 = undefined;
    _ = &i;
    var patch: Int32 = undefined;
    _ = &patch;
    var startSample: Int32 = undefined;
    _ = &startSample;
    var stopSample: Int32 = undefined;
    _ = &stopSample;
    var goalSb: Int32 = undefined;
    _ = &goalSb;
    var targetStopBand: Int32 = undefined;
    _ = &targetStopBand;
    var sourceStartBand: Int32 = undefined;
    _ = &sourceStartBand;
    var patchDistance: Int32 = undefined;
    _ = &patchDistance;
    var numBandsInPatch: Int32 = undefined;
    _ = &numBandsInPatch;
    var sbrStartFreqOffset: Int32 = undefined;
    _ = &sbrStartFreqOffset;
    var alphar: [2][*c]Int32 = undefined;
    _ = &alphar;
    var alphai: [2][*c]Int32 = undefined;
    _ = &alphai;
    var lsb: Int32 = v_k_master[@as(c_int, 0)];
    _ = &lsb;
    var usb: Int32 = v_k_master[@bitCast(@as(isize, @intCast(numMaster)))];
    _ = &usb;
    var xoverOffset: Int32 = highBandStartSb - v_k_master[@as(c_int, 0)];
    _ = &xoverOffset;
    var slopeLength: Int = 0;
    _ = &slopeLength;
    var firstSlotOffs: Int32 = frameInfo[@as(c_int, 1)];
    _ = &firstSlotOffs;
    var lastSlotOffs: Int32 = frameInfo[@bitCast(@as(isize, @intCast(frameInfo[@as(c_int, 0)] + @as(c_int, 1))))] - @as(c_int, 16);
    _ = &lastSlotOffs;
    alphar[@as(c_int, 0)] = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 0)]));
    alphar[@as(c_int, 1)] = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 1)]));
    alphai[@as(c_int, 0)] = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 2)]));
    alphai[@as(c_int, 1)] = @ptrCast(@alignCast(&scratch_mem[@as(c_int, 3)]));
    startSample = firstSlotOffs << @intCast(@as(c_int, 1));
    stopSample = (lastSlotOffs << @intCast(@as(c_int, 1))) + @as(c_int, 32);
    sbr_inv_filt_levelemphasis(invFiltMode, prevInvFiltMode, noInvFiltBands, BwVector, BwVectorOld);
    if (LC_flag == @as(c_int, 1)) {
        _ = memset(@ptrCast(@alignCast(&targetBufferReal[@bitCast(@as(isize, @intCast(startSample * @as(c_int, 48))))])), 0, @as(c_ulong, @bitCast(@as(c_long, (stopSample - startSample) * @as(c_int, 48)))) *% @sizeOf(@TypeOf(targetBufferReal[@as(c_int, 0)])));
        high_freq_coeff_LC(sourceBufferReal, @ptrCast(@alignCast(&alphar)), degreeAlias, v_k_master, @ptrCast(@alignCast(&scratch_mem[@as(c_int, 4)])));
    } else {
        _ = memset(@ptrCast(@alignCast(&targetBufferReal[@bitCast(@as(isize, @intCast(startSample * @as(c_int, 48))))])), 0, @as(c_ulong, @bitCast(@as(c_long, (stopSample - startSample) * @as(c_int, 48)))) *% @sizeOf(@TypeOf(targetBufferReal[@as(c_int, 0)])));
        _ = memset(@ptrCast(@alignCast(&targetBufferImag[@bitCast(@as(isize, @intCast(startSample * @as(c_int, 48))))])), 0, @as(c_ulong, @bitCast(@as(c_long, (stopSample - startSample) * @as(c_int, 48)))) *% @sizeOf(@TypeOf(targetBufferImag[@as(c_int, 0)])));
        high_freq_coeff(sourceBufferReal, sourceBufferImag, @ptrCast(@alignCast(&alphar)), @ptrCast(@alignCast(&alphai)), v_k_master);
    }
    blk: {
        switch (fs) {
            @as(c_int, 48000) => {
                goalSb = 43;
                break :blk;
            },
            @as(c_int, 32000) => {
                goalSb = 64;
                break :blk;
            },
            @as(c_int, 24000) => {
                goalSb = 85;
                break :blk;
            },
            @as(c_int, 22050) => {
                goalSb = 93;
                break :blk;
            },
            @as(c_int, 16000) => {
                goalSb = 128;
                break :blk;
            },
            else => {
                goalSb = 46;
                break :blk;
            },
        }
    }
    i = 0;
    if (goalSb > v_k_master[@as(c_int, 0)]) {
        if (goalSb < v_k_master[@bitCast(@as(isize, @intCast(numMaster)))]) {
            while (v_k_master[@bitCast(@as(isize, @intCast(i)))] < goalSb) {
                i += 1;
            }
        } else {
            i = numMaster;
        }
    }
    goalSb = v_k_master[@bitCast(@as(isize, @intCast(i)))];
    sourceStartBand = xoverOffset + @as(c_int, 1);
    targetStopBand = lsb + xoverOffset;
    patch = 0;
    sbrStartFreqOffset = targetStopBand;
    while (targetStopBand < usb) {
        Patch.*.targetStartBand[@bitCast(@as(isize, @intCast(patch)))] = targetStopBand;
        numBandsInPatch = goalSb - targetStopBand;
        if (numBandsInPatch >= (lsb - sourceStartBand)) {
            patchDistance = targetStopBand - sourceStartBand;
            patchDistance = patchDistance & ~@as(c_int, 1);
            numBandsInPatch = lsb - (targetStopBand - patchDistance);
            if ((targetStopBand + numBandsInPatch) > v_k_master[@as(c_int, 0)]) {
                i = numMaster;
                if ((targetStopBand + numBandsInPatch) < v_k_master[@bitCast(@as(isize, @intCast(numMaster)))]) {
                    while (v_k_master[@bitCast(@as(isize, @intCast(i)))] > (targetStopBand + numBandsInPatch)) {
                        i -= 1;
                    }
                }
            } else {
                i = 0;
            }
            numBandsInPatch = v_k_master[@bitCast(@as(isize, @intCast(i)))] - targetStopBand;
        }
        patchDistance = (numBandsInPatch + targetStopBand) - lsb;
        patchDistance = (patchDistance + @as(c_int, 1)) & ~@as(c_int, 1);
        sourceStartBand = 1;
        if ((goalSb - (targetStopBand + numBandsInPatch)) < @as(c_int, 3)) {
            goalSb = usb;
        }
        if ((numBandsInPatch < @as(c_int, 3)) and (patch > @as(c_int, 0))) {
            if (LC_flag == @as(c_int, 1)) {
                _ = memset(@ptrCast(@alignCast(&degreeAlias[@bitCast(@as(isize, @intCast(targetStopBand)))])), 0, @as(c_ulong, @bitCast(@as(c_long, numBandsInPatch))) *% @sizeOf(@TypeOf(degreeAlias.*)));
            }
            break;
        }
        if (numBandsInPatch <= @as(c_int, 0)) {
            continue;
        }
        if (LC_flag == @as(c_int, 1)) {
            high_freq_generation_LC(sourceBufferReal, targetBufferReal, @ptrCast(@alignCast(&alphar)), degreeAlias, invFiltBandTable, targetStopBand, patchDistance, numBandsInPatch, startSample, slopeLength, stopSample, BwVector, sbrStartFreqOffset);
        } else {
            high_freq_generation(sourceBufferReal, sourceBufferImag, targetBufferReal, targetBufferImag, @ptrCast(@alignCast(&alphar)), @ptrCast(@alignCast(&alphai)), invFiltBandTable, targetStopBand, patchDistance, numBandsInPatch, startSample, slopeLength, stopSample, BwVector, sbrStartFreqOffset);
        }
        targetStopBand += numBandsInPatch;
        patch += 1;
    }
    Patch.*.noOfPatches = patch;
    _ = memmove(@ptrCast(@alignCast(BwVectorOld)), @ptrCast(@alignCast(BwVector)), @as(c_ulong, @bitCast(@as(c_long, noInvFiltBands))) *% @sizeOf(@TypeOf(BwVector[@as(c_int, 0)])));
    highBandStopSb.* = goalSb;
}

pub fn sbr_get_additional_data(arg_hFrameData: [*c]SBR_FRAME_DATA, arg_hBitBuf: [*c]BIT_BUFFER) void {
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var i: Int32 = undefined;
    _ = &i;
    var flag: Int32 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    _ = &flag;
    if (flag != 0) {
        {
            i = 0;
            while (i < hFrameData.*.nSfb[@as(c_int, 1)]) : (i += 1) {
                hFrameData.*.addHarmonics[@bitCast(@as(isize, @intCast(i)))] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
            }
        }
    }
}

pub fn sbr_get_cpe(arg_hFrameDataLeft: [*c]SBR_FRAME_DATA, arg_hFrameDataRight: [*c]SBR_FRAME_DATA, arg_hBitBuf: [*c]BIT_BUFFER) SBR_ERROR {
    var hFrameDataLeft = arg_hFrameDataLeft;
    _ = &hFrameDataLeft;
    var hFrameDataRight = arg_hFrameDataRight;
    _ = &hFrameDataRight;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var i: Int32 = undefined;
    _ = &i;
    var bits: Int32 = undefined;
    _ = &bits;
    var err: SBR_ERROR = SBRDEC_OK;
    _ = &err;
    bits = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    if (bits != 0) {
        _ = buf_getbits(hBitBuf, 4);
        _ = buf_getbits(hBitBuf, 4);
    }
    bits = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    if (bits != 0) {
        hFrameDataLeft.*.coupling = COUPLING_LEVEL;
        hFrameDataRight.*.coupling = COUPLING_BAL;
    } else {
        hFrameDataLeft.*.coupling = COUPLING_OFF;
        hFrameDataRight.*.coupling = COUPLING_OFF;
    }
    err = extractFrameInfo(hBitBuf, hFrameDataLeft);
    if (err != @as(SBR_ERROR, SBRDEC_OK)) {
        return err;
    }
    if (hFrameDataLeft.*.coupling != 0) {
        _ = memcpy(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameDataRight.*.frameInfo))))), @ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameDataLeft.*.frameInfo))))), @as(c_ulong, 35) *% @sizeOf(Int32));
        hFrameDataRight.*.nNoiseFloorEnvelopes = hFrameDataLeft.*.nNoiseFloorEnvelopes;
        hFrameDataRight.*.frameClass = hFrameDataLeft.*.frameClass;
        sbr_get_dir_control_data(hFrameDataLeft, hBitBuf);
        sbr_get_dir_control_data(hFrameDataRight, hBitBuf);
        {
            i = 0;
            while (i < hFrameDataLeft.*.nNfb) : (i += 1) {
                hFrameDataLeft.*.sbr_invf_mode_prev[@bitCast(@as(isize, @intCast(i)))] = hFrameDataLeft.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))];
                hFrameDataRight.*.sbr_invf_mode_prev[@bitCast(@as(isize, @intCast(i)))] = hFrameDataRight.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))];
                hFrameDataLeft.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))] = buf_getbits(hBitBuf, 2);
                hFrameDataRight.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))] = hFrameDataLeft.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))];
            }
        }
        sbr_get_envelope(hFrameDataLeft, hBitBuf);
        sbr_get_noise_floor_data(hFrameDataLeft, hBitBuf);
        sbr_get_envelope(hFrameDataRight, hBitBuf);
    } else {
        err = extractFrameInfo(hBitBuf, hFrameDataRight);
        if (err != @as(SBR_ERROR, SBRDEC_OK)) {
            return err;
        }
        sbr_get_dir_control_data(hFrameDataLeft, hBitBuf);
        sbr_get_dir_control_data(hFrameDataRight, hBitBuf);
        {
            i = 0;
            while (i < hFrameDataLeft.*.nNfb) : (i += 1) {
                hFrameDataLeft.*.sbr_invf_mode_prev[@bitCast(@as(isize, @intCast(i)))] = hFrameDataLeft.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))];
                hFrameDataLeft.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))] = buf_getbits(hBitBuf, 2);
            }
        }
        {
            i = 0;
            while (i < hFrameDataRight.*.nNfb) : (i += 1) {
                hFrameDataRight.*.sbr_invf_mode_prev[@bitCast(@as(isize, @intCast(i)))] = hFrameDataRight.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))];
                hFrameDataRight.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))] = buf_getbits(hBitBuf, 2);
            }
        }
        sbr_get_envelope(hFrameDataLeft, hBitBuf);
        sbr_get_envelope(hFrameDataRight, hBitBuf);
        sbr_get_noise_floor_data(hFrameDataLeft, hBitBuf);
    }
    sbr_get_noise_floor_data(hFrameDataRight, hBitBuf);
    _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameDataLeft.*.addHarmonics))))), 0, @as(c_ulong, @bitCast(@as(c_long, hFrameDataLeft.*.nSfb[@as(c_int, 1)]))) *% @sizeOf(Int32));
    _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameDataRight.*.addHarmonics))))), 0, @as(c_ulong, @bitCast(@as(c_long, hFrameDataRight.*.nSfb[@as(c_int, 1)]))) *% @sizeOf(Int32));
    sbr_get_additional_data(hFrameDataLeft, hBitBuf);
    sbr_get_additional_data(hFrameDataRight, hBitBuf);
    sbr_extract_extended_data(hBitBuf, null);
    return SBRDEC_OK;
}

pub fn sbr_get_dir_control_data(arg_h_frame_data: [*c]SBR_FRAME_DATA, arg_hBitBuf: [*c]BIT_BUFFER) void {
    var h_frame_data = arg_h_frame_data;
    _ = &h_frame_data;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var i: Int32 = undefined;
    _ = &i;
    h_frame_data.*.nNoiseFloorEnvelopes = if (h_frame_data.*.frameInfo[@as(c_int, 0)] > @as(c_int, 1)) @as(c_int, 2) else @as(c_int, 1);
    {
        i = 0;
        while (i < h_frame_data.*.frameInfo[@as(c_int, 0)]) : (i += 1) {
            h_frame_data.*.domain_vec1[@bitCast(@as(isize, @intCast(i)))] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
        }
    }
    {
        i = 0;
        while (i < h_frame_data.*.nNoiseFloorEnvelopes) : (i += 1) {
            h_frame_data.*.domain_vec2[@bitCast(@as(isize, @intCast(i)))] = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
        }
    }
}

pub fn sbr_get_envelope(arg_h_frame_data: [*c]SBR_FRAME_DATA, arg_hBitBuf: [*c]BIT_BUFFER) void {
    var h_frame_data = arg_h_frame_data;
    _ = &h_frame_data;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var tmp: Int32 = undefined;
    _ = &tmp;
    var no_band: [5]Int32 = undefined;
    _ = &no_band;
    var delta: Int32 = 0;
    _ = &delta;
    var offset: Int32 = 0;
    _ = &offset;
    var ampRes: Int32 = undefined;
    _ = &ampRes;
    var envDataTableCompFactor: Int32 = undefined;
    _ = &envDataTableCompFactor;
    var start_bits: Int32 = undefined;
    _ = &start_bits;
    var start_bits_balance: Int32 = undefined;
    _ = &start_bits_balance;
    var hcb_t: SbrHuffman = undefined;
    _ = &hcb_t;
    var hcb_f: SbrHuffman = undefined;
    _ = &hcb_f;
    var coupling: COUPLING_MODE = h_frame_data.*.coupling;
    _ = &coupling;
    h_frame_data.*.nScaleFactors = 0;
    if ((h_frame_data.*.frameClass == @as(c_int, 0)) and (h_frame_data.*.frameInfo[@as(c_int, 0)] == @as(c_int, 1))) {
        h_frame_data.*.ampRes = 0;
    } else {
        h_frame_data.*.ampRes = h_frame_data.*.sbr_header.ampResolution;
    }
    ampRes = h_frame_data.*.ampRes;
    if (ampRes == @as(c_int, 1)) {
        start_bits = 6;
        start_bits_balance = 5;
    } else {
        start_bits = 7;
        start_bits_balance = 6;
    }
    {
        i = 0;
        while (i < h_frame_data.*.frameInfo[@as(c_int, 0)]) : (i += 1) {
            no_band[@bitCast(@as(isize, @intCast(i)))] = h_frame_data.*.nSfb[@bitCast(@as(isize, @intCast(h_frame_data.*.frameInfo[@bitCast(@as(isize, @intCast((h_frame_data.*.frameInfo[@as(c_int, 0)] + @as(c_int, 2)) + i)))])))];
            h_frame_data.*.nScaleFactors += no_band[@bitCast(@as(isize, @intCast(i)))];
        }
    }
    if (coupling == @as(COUPLING_MODE, COUPLING_BAL)) {
        envDataTableCompFactor = 1;
        if (ampRes == @as(c_int, 0)) {
            hcb_t = @ptrCast(@alignCast(&bookSbrEnvBalance10T));
            hcb_f = @ptrCast(@alignCast(&bookSbrEnvBalance10F));
        } else {
            hcb_t = @ptrCast(@alignCast(&bookSbrEnvBalance11T));
            hcb_f = @ptrCast(@alignCast(&bookSbrEnvBalance11F));
        }
    } else {
        envDataTableCompFactor = 0;
        if (ampRes == @as(c_int, 0)) {
            hcb_t = @ptrCast(@alignCast(&bookSbrEnvLevel10T));
            hcb_f = @ptrCast(@alignCast(&bookSbrEnvLevel10F));
        } else {
            hcb_t = @ptrCast(@alignCast(&bookSbrEnvLevel11T));
            hcb_f = @ptrCast(@alignCast(&bookSbrEnvLevel11F));
        }
    }
    {
        j = 0;
        while (j < h_frame_data.*.frameInfo[@as(c_int, 0)]) : (j += 1) {
            if (h_frame_data.*.domain_vec1[@bitCast(@as(isize, @intCast(j)))] == @as(c_int, 0)) {
                if (coupling == @as(COUPLING_MODE, COUPLING_BAL)) {
                    tmp = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, start_bits_balance))));
                    h_frame_data.*.iEnvelope_man[@bitCast(@as(isize, @intCast(offset)))] = pv_shl(tmp, envDataTableCompFactor);
                } else {
                    tmp = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, start_bits))));
                    h_frame_data.*.iEnvelope_man[@bitCast(@as(isize, @intCast(offset)))] = tmp;
                }
            }
            {
                i = @as(c_int, 1) - h_frame_data.*.domain_vec1[@bitCast(@as(isize, @intCast(j)))];
                while (i < no_band[@bitCast(@as(isize, @intCast(j)))]) : (i += 1) {
                    if (h_frame_data.*.domain_vec1[@bitCast(@as(isize, @intCast(j)))] == @as(c_int, 0)) {
                        delta = sbr_decode_huff_cw(hcb_f, hBitBuf);
                    } else {
                        delta = sbr_decode_huff_cw(hcb_t, hBitBuf);
                    }
                    h_frame_data.*.iEnvelope_man[@bitCast(@as(isize, @intCast(offset + i)))] = pv_shl(delta, envDataTableCompFactor);
                }
            }
            offset += no_band[@bitCast(@as(isize, @intCast(j)))];
        }
    }
}

pub fn sbr_get_header_data(arg_h_sbr_header: [*c]SBR_HEADER_DATA, arg_hBitBuf: [*c]BIT_BUFFER, arg_syncState: SBR_SYNC_STATE) SBR_HEADER_STATUS {
    var h_sbr_header = arg_h_sbr_header;
    _ = &h_sbr_header;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var syncState = arg_syncState;
    _ = &syncState;
    var lastHeader: SBR_HEADER_DATA = undefined;
    _ = &lastHeader;
    var headerExtra1: Int32 = undefined;
    _ = &headerExtra1;
    var headerExtra2: Int32 = undefined;
    _ = &headerExtra2;
    if (syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)) {
        _ = memcpy(@ptrCast(@alignCast(&lastHeader)), @ptrCast(@alignCast(h_sbr_header)), @sizeOf(SBR_HEADER_DATA));
    } else {
        _ = memset(@ptrCast(@alignCast(&lastHeader)), 0, @sizeOf(SBR_HEADER_DATA));
    }
    h_sbr_header.*.ampResolution = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    h_sbr_header.*.startFreq = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 4))));
    h_sbr_header.*.stopFreq = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 4))));
    h_sbr_header.*.xover_band = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 3))));
    _ = buf_getbits(hBitBuf, 2);
    headerExtra1 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    headerExtra2 = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    if (headerExtra1 != 0) {
        h_sbr_header.*.freqScale = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
        h_sbr_header.*.alterScale = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
        h_sbr_header.*.noise_bands = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
    } else {
        h_sbr_header.*.freqScale = 2;
        h_sbr_header.*.alterScale = 1;
        h_sbr_header.*.noise_bands = 2;
    }
    if (headerExtra2 != 0) {
        h_sbr_header.*.limiterBands = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
        h_sbr_header.*.limiterGains = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 2))));
        h_sbr_header.*.interpolFreq = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
        h_sbr_header.*.smoothingLength = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    } else {
        h_sbr_header.*.limiterBands = 2;
        h_sbr_header.*.limiterGains = 2;
        h_sbr_header.*.interpolFreq = 1;
        h_sbr_header.*.smoothingLength = 1;
    }
    if (syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)) {
        h_sbr_header.*.status = HEADER_OK;
        if ((((((lastHeader.startFreq != h_sbr_header.*.startFreq) or (lastHeader.stopFreq != h_sbr_header.*.stopFreq)) or (lastHeader.xover_band != h_sbr_header.*.xover_band)) or (lastHeader.freqScale != h_sbr_header.*.freqScale)) or (lastHeader.alterScale != h_sbr_header.*.alterScale)) or (lastHeader.noise_bands != h_sbr_header.*.noise_bands)) {
            h_sbr_header.*.status = HEADER_RESET;
        }
    } else {
        h_sbr_header.*.status = HEADER_RESET;
    }
    return h_sbr_header.*.status;
}

pub fn sbr_get_noise_floor_data(arg_h_frame_data: [*c]SBR_FRAME_DATA, arg_hBitBuf: [*c]BIT_BUFFER) void {
    var h_frame_data = arg_h_frame_data;
    _ = &h_frame_data;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var k: Int32 = undefined;
    _ = &k;
    var tmp: Int32 = undefined;
    _ = &tmp;
    var delta: Int32 = undefined;
    _ = &delta;
    var noNoiseBands: Int32 = h_frame_data.*.nNfb;
    _ = &noNoiseBands;
    var envDataTableCompFactor: Int32 = undefined;
    _ = &envDataTableCompFactor;
    var coupling: COUPLING_MODE = h_frame_data.*.coupling;
    _ = &coupling;
    var hcb_noiseF: SbrHuffman = undefined;
    _ = &hcb_noiseF;
    var hcb_noise: SbrHuffman = undefined;
    _ = &hcb_noise;
    if (coupling == @as(COUPLING_MODE, COUPLING_BAL)) {
        hcb_noise = @ptrCast(@alignCast(&bookSbrNoiseBalance11T));
        hcb_noiseF = @ptrCast(@alignCast(&bookSbrEnvBalance11F));
        envDataTableCompFactor = 1;
    } else {
        hcb_noise = @ptrCast(@alignCast(&bookSbrNoiseLevel11T));
        hcb_noiseF = @ptrCast(@alignCast(&bookSbrEnvLevel11F));
        envDataTableCompFactor = 0;
    }
    h_frame_data.*.nNoiseFactors = h_frame_data.*.frameInfo[@bitCast(@as(isize, @intCast((h_frame_data.*.frameInfo[@as(c_int, 0)] << @intCast(@as(c_int, 1))) + @as(c_int, 3))))] * noNoiseBands;
    {
        i = 0;
        while (i < h_frame_data.*.nNoiseFloorEnvelopes) : (i += 1) {
            k = i * noNoiseBands;
            if (h_frame_data.*.domain_vec2[@bitCast(@as(isize, @intCast(i)))] == @as(c_int, 0)) {
                if (coupling == @as(COUPLING_MODE, COUPLING_BAL)) {
                    tmp = @bitCast(@as(c_uint, @truncate(pv_shl(buf_getbits(hBitBuf, 5), @as(UInt32, 1)))));
                    h_frame_data.*.sbrNoiseFloorLevel_man[@bitCast(@as(isize, @intCast(k)))] = tmp;
                    h_frame_data.*.sbrNoiseFloorLevel_exp[@bitCast(@as(isize, @intCast(k)))] = 0;
                } else {
                    tmp = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 5))));
                    h_frame_data.*.sbrNoiseFloorLevel_man[@bitCast(@as(isize, @intCast(k)))] = tmp;
                    h_frame_data.*.sbrNoiseFloorLevel_exp[@bitCast(@as(isize, @intCast(k)))] = 0;
                }
                {
                    j = 1;
                    while (j < noNoiseBands) : (j += 1) {
                        delta = sbr_decode_huff_cw(hcb_noiseF, hBitBuf);
                        h_frame_data.*.sbrNoiseFloorLevel_man[@bitCast(@as(isize, @intCast(k + j)))] = pv_shl(delta, envDataTableCompFactor);
                        h_frame_data.*.sbrNoiseFloorLevel_exp[@bitCast(@as(isize, @intCast(k + j)))] = 0;
                    }
                }
            } else {
                {
                    j = 0;
                    while (j < noNoiseBands) : (j += 1) {
                        delta = sbr_decode_huff_cw(hcb_noise, hBitBuf);
                        h_frame_data.*.sbrNoiseFloorLevel_man[@bitCast(@as(isize, @intCast(k + j)))] = pv_shl(delta, envDataTableCompFactor);
                        h_frame_data.*.sbrNoiseFloorLevel_exp[@bitCast(@as(isize, @intCast(k + j)))] = 0;
                    }
                }
            }
        }
    }
}

pub fn sbr_get_sce(arg_hFrameData: [*c]SBR_FRAME_DATA, arg_hBitBuf: [*c]BIT_BUFFER, arg_hParametricStereoDec: HANDLE_PS_DEC) SBR_ERROR {
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var hBitBuf = arg_hBitBuf;
    _ = &hBitBuf;
    var hParametricStereoDec = arg_hParametricStereoDec;
    _ = &hParametricStereoDec;
    var i: Int32 = undefined;
    _ = &i;
    var bits: Int32 = undefined;
    _ = &bits;
    var err: SBR_ERROR = SBRDEC_OK;
    _ = &err;
    bits = @bitCast(@as(c_uint, @truncate(buf_getbits(hBitBuf, 1))));
    if (bits != 0) {
        _ = buf_getbits(hBitBuf, 4);
    }
    err = extractFrameInfo(hBitBuf, hFrameData);
    if (err != @as(SBR_ERROR, SBRDEC_OK)) {
        return err;
    }
    sbr_get_dir_control_data(hFrameData, hBitBuf);
    {
        i = 0;
        while (i < hFrameData.*.nNfb) : (i += 1) {
            hFrameData.*.sbr_invf_mode_prev[@bitCast(@as(isize, @intCast(i)))] = hFrameData.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))];
            hFrameData.*.sbr_invf_mode[@bitCast(@as(isize, @intCast(i)))] = buf_getbits(hBitBuf, 2);
        }
    }
    sbr_get_envelope(hFrameData, hBitBuf);
    sbr_get_noise_floor_data(hFrameData, hBitBuf);
    _ = memset(@ptrCast(@alignCast(@as([*c]Int32, @ptrCast(@alignCast(&hFrameData.*.addHarmonics))))), 0, @as(c_ulong, @bitCast(@as(c_long, hFrameData.*.nSfb[@as(c_int, 1)]))) *% @sizeOf(Int32));
    sbr_get_additional_data(hFrameData, hBitBuf);
    sbr_extract_extended_data(hBitBuf, hParametricStereoDec);
    hFrameData.*.coupling = COUPLING_OFF;
    return SBRDEC_OK;
}

pub fn sbr_inv_filt_levelemphasis(arg_invFiltMode: [*c]INVF_MODE, arg_prevInvFiltMode: [*c]INVF_MODE, arg_nNfb: Int32, arg_BwVector: [*c]Int32, arg_BwVectorOld: [*c]Int32) void {
    var invFiltMode = arg_invFiltMode;
    _ = &invFiltMode;
    var prevInvFiltMode = arg_prevInvFiltMode;
    _ = &prevInvFiltMode;
    var nNfb = arg_nNfb;
    _ = &nNfb;
    var BwVector = arg_BwVector;
    _ = &BwVector;
    var BwVectorOld = arg_BwVectorOld;
    _ = &BwVectorOld;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var tmp: Int32 = undefined;
    _ = &tmp;
    {
        i = 0;
        while (i < nNfb) : (i += 1) {
            blk: {
                switch (invFiltMode[@bitCast(@as(isize, @intCast(i)))]) {
                    @as(INVF_MODE, INVF_LOW_LEVEL) => {
                        if (prevInvFiltMode[@bitCast(@as(isize, @intCast(i)))] == @as(INVF_MODE, INVF_OFF)) {
                            j = 1;
                        } else {
                            j = 2;
                        }
                        break :blk;
                    },
                    @as(INVF_MODE, INVF_MID_LEVEL) => {
                        j = 3;
                        break :blk;
                    },
                    @as(INVF_MODE, INVF_HIGH_LEVEL) => {
                        j = 4;
                        break :blk;
                    },
                    else => {
                        if (prevInvFiltMode[@bitCast(@as(isize, @intCast(i)))] == @as(INVF_MODE, INVF_LOW_LEVEL)) {
                            j = 1;
                        } else {
                            j = 0;
                        }
                    },
                }
            }
            tmp = InvFiltFactors[@bitCast(@as(isize, @intCast(j)))];
            if (tmp < BwVectorOld[@bitCast(@as(isize, @intCast(i)))]) {
                tmp = (((tmp << @intCast(@as(c_int, 1))) + tmp) + BwVectorOld[@bitCast(@as(isize, @intCast(i)))]) >> @intCast(@as(c_int, 2));
            } else {
                tmp = fxp_mul32_Q29(@intFromFloat((@as(f32, 0.90625) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 0.90625) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))), tmp);
                tmp = fxp_mac32_Q29(@intFromFloat((@as(f32, 0.09375) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 0.09375) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))), BwVectorOld[@bitCast(@as(isize, @intCast(i)))], tmp);
            }
            if (tmp < @as(Int32, @intFromFloat((@as(f32, 0.015625) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 0.015625) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))))) {
                tmp = 0;
            }
            if (tmp >= @as(Int32, @intFromFloat((@as(f32, 0.996094) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 0.996094) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))))) {
                tmp = @intFromFloat((@as(f32, 0.996094) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 29))))) + (if (@as(f32, 0.996094) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)));
            }
            BwVector[@bitCast(@as(isize, @intCast(i)))] = tmp;
        }
    }
}

pub fn sbr_open(arg_sampleRate: Int32, arg_sbrDec: [*c]SBR_DEC, arg_self: [*c]SBRDECODER_DATA, arg_bDownSampledSbr: bool) void {
    var sampleRate = arg_sampleRate;
    _ = &sampleRate;
    var sbrDec = arg_sbrDec;
    _ = &sbrDec;
    var self = arg_self;
    _ = &self;
    var bDownSampledSbr = arg_bDownSampledSbr;
    _ = &bDownSampledSbr;
    var i: Int16 = undefined;
    _ = &i;
    var SbrChannel: [*c]SBR_CHANNEL = undefined;
    _ = &SbrChannel;
    SbrChannel = @ptrCast(@alignCast(&self.*.SbrChannel));
    {
        i = 0;
        while (@as(c_int, i) < @as(c_int, 2)) : (i += 1) {
            _ = memset(@ptrCast(@alignCast(&SbrChannel[@bitCast(@as(isize, @intCast(i)))])), 0, @sizeOf(SBR_CHANNEL));
            _ = memcpy(@ptrCast(@alignCast(&SbrChannel[@bitCast(@as(isize, @intCast(i)))].frameData.sbr_header)), @ptrCast(@alignCast(&defaultHeader)), @sizeOf(SBR_HEADER_DATA));
            if ((sampleRate > @as(c_int, 24000)) or bDownSampledSbr) {
                SbrChannel[@bitCast(@as(isize, @intCast(i)))].frameData.sbr_header.sampleRateMode = SINGLE_RATE;
            }
            SbrChannel[@bitCast(@as(isize, @intCast(i)))].outFrameSize = init_sbr_dec(sampleRate, @bitCast(self.*.SbrChannel[@as(c_int, 0)].frameData.sbr_header.sampleRateMode), sbrDec, &SbrChannel[@bitCast(@as(isize, @intCast(i)))].frameData);
            SbrChannel[@bitCast(@as(isize, @intCast(i)))].syncState = UPSAMPLING;
            SbrChannel[@bitCast(@as(isize, @intCast(i)))].frameData.sUp = 1;
        }
    }
}

pub fn sbr_read_data(arg_self: [*c]SBRDECODER_DATA, arg_sbrDec: [*c]SBR_DEC, arg_stream: [*c]SBRBITSTREAM) SBR_ERROR {
    var self = arg_self;
    _ = &self;
    var sbrDec = arg_sbrDec;
    _ = &sbrDec;
    var stream = arg_stream;
    _ = &stream;
    var sbr_err: SBR_ERROR = SBRDEC_OK;
    _ = &sbr_err;
    var SbrFrameOK: i32 = 1;
    _ = &SbrFrameOK;
    var sbrCRCAlwaysOn: i32 = 0;
    _ = &sbrCRCAlwaysOn;
    var bs_header_flag: UInt32 = 0;
    _ = &bs_header_flag;
    var headerStatus: SBR_HEADER_STATUS = HEADER_OK;
    _ = &headerStatus;
    var SbrChannel: [*c]SBR_CHANNEL = @ptrCast(@alignCast(&self.*.SbrChannel));
    _ = &SbrChannel;
    var zeropadding_bits: i32 = undefined;
    _ = &zeropadding_bits;
    var bitBuf: BIT_BUFFER = undefined;
    _ = &bitBuf;
    bitBuf.buffer_word = 0;
    bitBuf.buffered_bits = 0;
    bitBuf.nrBitsRead = 0;
    bitBuf.char_ptr = @ptrCast(@alignCast(&stream.*.sbrElement[@as(c_int, 0)].Data));
    bitBuf.bufferLen = @bitCast(@as(c_int, stream.*.sbrElement[@as(c_int, 0)].Payload << @intCast(@as(c_int, 3))));
    _ = buf_getbits(&bitBuf, @as(c_int, 4));
    if ((stream.*.sbrElement[@as(c_int, 0)].ExtensionType == @as(c_int, 14)) or (sbrCRCAlwaysOn != 0)) {
        var CRCLen: i32 = (((stream.*.sbrElement[@as(c_int, 0)].Payload - @as(c_int, 1)) << @intCast(@as(c_int, 3))) + @as(c_int, 4)) - @as(c_int, 10);
        _ = &CRCLen;
        SbrFrameOK = sbr_crc_check(&bitBuf, @bitCast(@as(c_int, CRCLen)));
    }
    if (SbrFrameOK != 0) {
        bs_header_flag = buf_getbits(&bitBuf, 1);
        if (bs_header_flag != 0) {
            headerStatus = sbr_get_header_data(&SbrChannel[@as(c_int, 0)].frameData.sbr_header, &bitBuf, SbrChannel[@as(c_int, 0)].syncState);
        }
        blk: {
            switch (stream.*.sbrElement[@as(c_int, 0)].ElementID) {
                SBR_ID_SCE => {
                    if (headerStatus == @as(SBR_HEADER_STATUS, HEADER_RESET)) {
                        sbr_err = sbr_reset_dec(&SbrChannel[@as(c_int, 0)].frameData, sbrDec, @bitCast(self.*.SbrChannel[@as(c_int, 0)].frameData.sbr_header.sampleRateMode));
                        if (sbr_err != @as(SBR_ERROR, SBRDEC_OK)) {
                            break :blk;
                        }
                        SbrChannel[@as(c_int, 0)].syncState = SBR_ACTIVE;
                    }
                    if (SbrChannel[@as(c_int, 0)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)) {
                        sbr_err = sbr_get_sce(&SbrChannel[@as(c_int, 0)].frameData, &bitBuf, self.*.hParametricStereoDec);
                        if (sbr_err != @as(SBR_ERROR, SBRDEC_OK)) {
                            break :blk;
                        }
                    }
                    break :blk;
                },
                SBR_ID_CPE => {
                    if (bs_header_flag != 0) {
                        _ = memcpy(@ptrCast(@alignCast(&SbrChannel[@as(c_int, 1)].frameData.sbr_header)), @ptrCast(@alignCast(&SbrChannel[@as(c_int, 0)].frameData.sbr_header)), @sizeOf(SBR_HEADER_DATA));
                    }
                    if (headerStatus == @as(SBR_HEADER_STATUS, HEADER_RESET)) {
                        {
                            var lr: i32 = 0;
                            _ = &lr;
                            while (lr < @as(c_int, 2)) : (lr += 1) {
                                sbr_err = sbr_reset_dec(&SbrChannel[@bitCast(@as(isize, @intCast(lr)))].frameData, sbrDec, @bitCast(self.*.SbrChannel[@as(c_int, 0)].frameData.sbr_header.sampleRateMode));
                                if (sbr_err != @as(SBR_ERROR, SBRDEC_OK)) {
                                    break;
                                }
                                SbrChannel[@bitCast(@as(isize, @intCast(lr)))].syncState = SBR_ACTIVE;
                            }
                        }
                    }
                    if (SbrChannel[@as(c_int, 0)].syncState == @as(SBR_SYNC_STATE, SBR_ACTIVE)) {
                        sbr_err = sbr_get_cpe(&SbrChannel[@as(c_int, 0)].frameData, &SbrChannel[@as(c_int, 1)].frameData, &bitBuf);
                        if (sbr_err != @as(SBR_ERROR, SBRDEC_OK)) {
                            break :blk;
                        }
                    }
                    break :blk;
                },
                else => {
                    sbr_err = SBRDEC_ILLEGAL_PLUS_ELE_ID;
                    break :blk;
                },
            }
        }
    }
    zeropadding_bits = @bitCast(@as(c_uint, @truncate((@as(UInt32, 8) -% (bitBuf.nrBitsRead & @as(UInt32, 7))) & @as(UInt32, 7))));
    if ((bitBuf.nrBitsRead +% @as(UInt32, @bitCast(@as(c_int, zeropadding_bits)))) > bitBuf.bufferLen) {
        sbr_err = SBRDEC_INVALID_BITSTREAM;
    }
    return sbr_err;
}

pub fn sbr_requantize_envelope_data(arg_hFrameData: [*c]SBR_FRAME_DATA) void {
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var i: Int32 = undefined;
    _ = &i;
    var nScaleFactors: Int32 = hFrameData.*.nScaleFactors;
    _ = &nScaleFactors;
    var nNoiseFactors: Int32 = hFrameData.*.nNoiseFactors;
    _ = &nNoiseFactors;
    var ampRes: Int32 = hFrameData.*.ampRes;
    _ = &ampRes;
    var iEnvelope_man: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.iEnvelope_man));
    _ = &iEnvelope_man;
    var iEnvelope_exp: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.iEnvelope_exp));
    _ = &iEnvelope_exp;
    var sbrNoiseFloorLevel_man: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.sbrNoiseFloorLevel_man));
    _ = &sbrNoiseFloorLevel_man;
    var sbrNoiseFloorLevel_exp: [*c]Int32 = @ptrCast(@alignCast(&hFrameData.*.sbrNoiseFloorLevel_exp));
    _ = &sbrNoiseFloorLevel_exp;
    if (ampRes != 0) {
        {
            i = 0;
            while (i < nScaleFactors) : (i += 1) {
                iEnvelope_exp[@bitCast(@as(isize, @intCast(i)))] = iEnvelope_man[@bitCast(@as(isize, @intCast(i)))] + @as(c_int, 6);
                iEnvelope_man[@bitCast(@as(isize, @intCast(i)))] = @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)));
            }
        }
    } else {
        {
            i = 0;
            while (i < nScaleFactors) : (i += 1) {
                iEnvelope_exp[@bitCast(@as(isize, @intCast(i)))] = (iEnvelope_man[@bitCast(@as(isize, @intCast(i)))] >> @intCast(@as(c_int, 1))) + @as(c_int, 6);
                if ((iEnvelope_man[@bitCast(@as(isize, @intCast(i)))] & @as(c_int, 1)) != 0) {
                    iEnvelope_man[@bitCast(@as(isize, @intCast(i)))] = @intFromFloat((@as(f32, 1.414214) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.414214) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)));
                } else {
                    iEnvelope_man[@bitCast(@as(isize, @intCast(i)))] = @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)));
                }
            }
        }
    }
    {
        i = 0;
        while (i < nNoiseFactors) : (i += 1) {
            sbrNoiseFloorLevel_exp[@bitCast(@as(isize, @intCast(i)))] = @as(c_int, 6) - sbrNoiseFloorLevel_man[@bitCast(@as(isize, @intCast(i)))];
            sbrNoiseFloorLevel_man[@bitCast(@as(isize, @intCast(i)))] = 1073741824;
        }
    }
}

pub fn sbr_reset_dec(arg_hFrameData: [*c]SBR_FRAME_DATA, arg_sbrDec: [*c]SBR_DEC, arg_upsampleFac: Int32) SBR_ERROR {
    var hFrameData = arg_hFrameData;
    _ = &hFrameData;
    var sbrDec = arg_sbrDec;
    _ = &sbrDec;
    var upsampleFac = arg_upsampleFac;
    _ = &upsampleFac;
    var err: SBR_ERROR = SBRDEC_OK;
    _ = &err;
    var lsbM: Int = undefined;
    _ = &lsbM;
    var lsb: Int = undefined;
    _ = &lsb;
    var usb: Int = undefined;
    _ = &usb;
    var i: Int32 = undefined;
    _ = &i;
    var tmp_q1: Int32 = undefined;
    _ = &tmp_q1;
    var headerData: [*c]SBR_HEADER_DATA = &hFrameData.*.sbr_header;
    _ = &headerData;
    var samplingFreq: Int32 = sbrDec.*.outSampleRate;
    _ = &samplingFreq;
    hFrameData.*.reset_flag = 1;
    err = sbr_find_start_andstop_band(samplingFreq, headerData.*.startFreq, headerData.*.stopFreq, &lsbM, &usb);
    if (err != @as(SBR_ERROR, SBRDEC_OK)) {
        return err;
    }
    if (headerData.*.masterStatus == @as(SBR_MASTER_STATUS, MASTER_RESET)) {
        sbr_update_freq_scale(@ptrCast(@alignCast(&sbrDec.*.V_k_master)), &sbrDec.*.Num_Master, lsbM, usb, headerData.*.freqScale, headerData.*.alterScale, 0);
    }
    sbrDec.*.NSfb[@as(c_int, 1)] = sbrDec.*.Num_Master - headerData.*.xover_band;
    {
        i = headerData.*.xover_band;
        while (i <= sbrDec.*.Num_Master) : (i += 1) {
            sbrDec.*.FreqBandTable[@as(c_int, 1)][@bitCast(@as(isize, @intCast(i - headerData.*.xover_band)))] = sbrDec.*.V_k_master[@bitCast(@as(isize, @intCast(i)))];
        }
    }
    if ((sbrDec.*.NSfb[@as(c_int, 1)] & @as(c_int, 1)) == @as(c_int, 0)) {
        sbrDec.*.NSfb[@as(c_int, 0)] = sbrDec.*.NSfb[@as(c_int, 1)] >> @intCast(@as(c_int, 1));
        {
            i = 0;
            while (i <= sbrDec.*.NSfb[@as(c_int, 0)]) : (i += 1) {
                sbrDec.*.FreqBandTable[@as(c_int, 0)][@bitCast(@as(isize, @intCast(i)))] = sbrDec.*.FreqBandTable[@as(c_int, 1)][@bitCast(@as(isize, @intCast(i << @intCast(@as(c_int, 1)))))];
            }
        }
    } else {
        sbrDec.*.NSfb[@as(c_int, 0)] = (sbrDec.*.NSfb[@as(c_int, 1)] + @as(c_int, 1)) >> @intCast(@as(c_int, 1));
        sbrDec.*.FreqBandTable[@as(c_int, 0)][@as(c_int, 0)] = sbrDec.*.FreqBandTable[@as(c_int, 1)][@as(c_int, 0)];
        {
            i = 1;
            while (i <= sbrDec.*.NSfb[@as(c_int, 0)]) : (i += 1) {
                sbrDec.*.FreqBandTable[@as(c_int, 0)][@bitCast(@as(isize, @intCast(i)))] = sbrDec.*.FreqBandTable[@as(c_int, 1)][@bitCast(@as(isize, @intCast((i << @intCast(@as(c_int, 1))) - @as(c_int, 1))))];
            }
        }
    }
    lsb = sbrDec.*.FreqBandTable[@as(c_int, 0)][@as(c_int, 0)];
    usb = sbrDec.*.FreqBandTable[@as(c_int, 0)][@bitCast(@as(isize, @intCast(sbrDec.*.NSfb[@as(c_int, 0)])))];
    sbrDec.*.lowSubband = lsb;
    sbrDec.*.highSubband = usb;
    sbrDec.*.noSubbands = usb - lsb;
    if ((lsb > @as(c_int, 32)) or (sbrDec.*.noSubbands <= @as(c_int, 0))) {
        return SBRDEC_ILLEGAL_SCFACTORS;
    }
    if (headerData.*.noise_bands == @as(c_int, 0)) {
        sbrDec.*.NoNoiseBands = 1;
    } else {
        if (!(lsb != 0)) {
            return SBRDEC_ILLEGAL_SCFACTORS;
        }
        tmp_q1 = pv_log2(@divTrunc(usb << @intCast(@as(c_int, 20)), lsb));
        tmp_q1 = fxp_mul32_Q15(headerData.*.noise_bands, tmp_q1);
        sbrDec.*.NoNoiseBands = (tmp_q1 + @as(c_int, 16)) >> @intCast(@as(c_int, 5));
        if (sbrDec.*.NoNoiseBands == @as(c_int, 0)) {
            sbrDec.*.NoNoiseBands = 1;
        }
    }
    headerData.*.noNoiseBands = sbrDec.*.NoNoiseBands;
    sbr_downsample_lo_res(@ptrCast(@alignCast(&sbrDec.*.FreqBandTableNoise)), sbrDec.*.NoNoiseBands, @ptrCast(@alignCast(&sbrDec.*.FreqBandTable[@as(c_int, 0)])), sbrDec.*.NSfb[@as(c_int, 0)]);
    sbrDec.*.sbStopCodec = sbrDec.*.lowSubband;
    if (sbrDec.*.sbStopCodec > (upsampleFac << @intCast(@as(c_int, 5)))) {
        sbrDec.*.sbStopCodec = upsampleFac << @intCast(@as(c_int, 5));
    }
    hFrameData.*.nSfb[@as(c_int, 0)] = sbrDec.*.NSfb[@as(c_int, 0)];
    hFrameData.*.nSfb[@as(c_int, 1)] = sbrDec.*.NSfb[@as(c_int, 1)];
    hFrameData.*.nNfb = hFrameData.*.sbr_header.noNoiseBands;
    hFrameData.*.offset = (hFrameData.*.nSfb[@as(c_int, 0)] << @intCast(@as(c_int, 1))) - hFrameData.*.nSfb[@as(c_int, 1)];
    return @bitCast(SBRDEC_OK);
}

