pub fn sbr_update_freq_scale(arg_v_k_master: [*c]Int32, arg_h_num_bands: [*c]Int32, lsbM: Int32, usb: Int32, freqScale: Int32, alterScale: Int32, channelOffset: Int32) void {
    var v_k_master = arg_v_k_master;
    _ = &v_k_master;
    var h_num_bands = arg_h_num_bands;
    _ = &h_num_bands;
    _ = &lsbM;
    _ = &usb;
    _ = &freqScale;
    _ = &alterScale;
    _ = &channelOffset;
    var i: Int32 = undefined;
    _ = &i;
    var numBands: Int32 = 0;
    _ = &numBands;
    var numBands2: Int32 = undefined;
    _ = &numBands2;
    var tmp_q1: Int32 = undefined;
    _ = &tmp_q1;
    if (freqScale > @as(c_int, 0)) {
        var reg: Int32 = undefined;
        _ = &reg;
        var regions: Int32 = undefined;
        _ = &regions;
        var b_p_o: Int32 = undefined;
        _ = &b_p_o;
        var k: [3]Int32 = undefined;
        _ = &k;
        var d: [50]Int32 = undefined;
        _ = &d;
        var d2: [50]Int32 = undefined;
        _ = &d2;
        var w: [2]Int32 = [2]Int32{
            @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))),
            @intFromFloat((@as(f32, 1.0) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 1.0) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))),
        };
        _ = &w;
        k[@as(c_int, 0)] = lsbM;
        k[@as(c_int, 1)] = usb;
        k[@as(c_int, 2)] = usb;
        b_p_o = if (freqScale == @as(c_int, 1)) @as(c_int, 12) else @as(c_int, 8);
        b_p_o = if (freqScale == @as(c_int, 2)) @as(c_int, 10) else b_p_o;
        w[@as(c_int, 1)] = if (alterScale == @as(c_int, 0)) @as(Int32, @intFromFloat((@as(f32, 0.5) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 0.5) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))) else @as(Int32, @intFromFloat((@as(f32, 0.384615) * @as(f32, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 30))))) + (if (@as(f32, 0.384615) >= @as(f32, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5))));
        if (usb > fxp_mul32_Q28(lsbM, @intFromFloat((@as(f64, 2.2449) * @as(f64, @floatFromInt(@as(c_int, 1) << @intCast(@as(c_int, 28))))) + @as(f64, @floatCast(if (@as(f64, 2.2449) >= @as(f64, @floatFromInt(@as(c_int, 0)))) @as(f32, 0.5) else -@as(f32, 0.5)))))) {
            regions = 2;
            k[@as(c_int, 1)] = lsbM << @intCast(@as(c_int, 1));
        } else {
            regions = 1;
        }
        h_num_bands.* = 0;
        {
            reg = 0;
            while (reg < regions) : (reg += 1) {
                if (reg == @as(c_int, 0)) {
                    tmp_q1 = pv_log2(@divTrunc(k[@as(c_int, 1)] << @intCast(@as(c_int, 20)), k[@as(c_int, 0)]));
                    tmp_q1 = fxp_mul32_Q15(tmp_q1, b_p_o);
                    tmp_q1 = (tmp_q1 + @as(c_int, 32)) >> @intCast(@as(c_int, 6));
                    numBands = tmp_q1 << @intCast(@as(c_int, 1));
                    CalcBands(@ptrCast(@alignCast(&d)), k[@as(c_int, 0)], k[@as(c_int, 1)], numBands);
                    shellsort(@ptrCast(@alignCast(&d)), numBands);
                    cumSum(k[@as(c_int, 0)] - channelOffset, @ptrCast(@alignCast(&d)), numBands, v_k_master + @as(usize, @bitCast(@as(isize, @intCast(h_num_bands.*)))));
                    h_num_bands.* += numBands;
                } else {
                    tmp_q1 = pv_log2(@divTrunc(k[@bitCast(@as(isize, @intCast(reg + @as(c_int, 1))))] << @intCast(@as(c_int, 20)), k[@bitCast(@as(isize, @intCast(reg)))]));
                    tmp_q1 = fxp_mul32_Q30(tmp_q1, w[@bitCast(@as(isize, @intCast(reg)))]);
                    tmp_q1 = fxp_mul32_Q15(tmp_q1, b_p_o);
                    tmp_q1 = (tmp_q1 + @as(c_int, 16)) >> @intCast(@as(c_int, 5));
                    numBands2 = tmp_q1 << @intCast(@as(c_int, 1));
                    CalcBands(@ptrCast(@alignCast(&d2)), k[@bitCast(@as(isize, @intCast(reg)))], k[@bitCast(@as(isize, @intCast(reg + @as(c_int, 1))))], numBands2);
                    shellsort(@ptrCast(@alignCast(&d2)), numBands2);
                    if (d[@bitCast(@as(isize, @intCast(numBands - @as(c_int, 1))))] > d2[@as(c_int, 0)]) {
                        var change: Int32 = d[@bitCast(@as(isize, @intCast(numBands - @as(c_int, 1))))] - d2[@as(c_int, 0)];
                        _ = &change;
                        if (change > ((d2[@bitCast(@as(isize, @intCast(numBands2 - @as(c_int, 1))))] - d2[@as(c_int, 0)]) >> @intCast(@as(c_int, 1)))) {
                            change = (d2[@bitCast(@as(isize, @intCast(numBands2 - @as(c_int, 1))))] - d2[@as(c_int, 0)]) >> @intCast(@as(c_int, 1));
                        }
                        d2[@as(c_int, 0)] += change;
                        d2[@bitCast(@as(isize, @intCast(numBands2 - @as(c_int, 1))))] -= change;
                        shellsort(@ptrCast(@alignCast(&d2)), numBands2);
                    }
                    cumSum(k[@bitCast(@as(isize, @intCast(reg)))] - channelOffset, @ptrCast(@alignCast(&d2)), numBands2, v_k_master + @as(usize, @bitCast(@as(isize, @intCast(h_num_bands.*)))));
                    h_num_bands.* += numBands2;
                }
            }
        }
    } else {
        var k2_achived: Int32 = undefined;
        _ = &k2_achived;
        var k2_diff: Int32 = undefined;
        _ = &k2_diff;
        var diff_tot: [79]Int32 = undefined;
        _ = &diff_tot;
        var dk: Int32 = undefined;
        _ = &dk;
        var incr: Int32 = 0;
        _ = &incr;
        if (alterScale != 0) {
            numBands = (usb - lsbM) >> @intCast(@as(c_int, 1));
            dk = 1;
            k2_achived = lsbM + numBands;
        } else {
            numBands = usb - lsbM;
            if ((numBands & @as(c_int, 1)) != 0) {
                numBands -= 1;
            }
            dk = 2;
            k2_achived = lsbM + (numBands << @intCast(@as(c_int, 1)));
        }
        k2_diff = usb - k2_achived;
        {
            i = 0;
            while (i < numBands) : (i += 1) {
                diff_tot[@bitCast(@as(isize, @intCast(i)))] = dk;
            }
        }
        if (k2_diff < @as(c_int, 0)) {
            incr = 1;
            i = 0;
        }
        if (k2_diff > @as(c_int, 0)) {
            incr = -@as(c_int, 1);
            i = numBands - @as(c_int, 1);
        }
        while (k2_diff != @as(c_int, 0)) {
            diff_tot[@bitCast(@as(isize, @intCast(i)))] -= incr;
            i += incr;
            k2_diff += incr;
        }
        cumSum(lsbM, @ptrCast(@alignCast(&diff_tot)), numBands, v_k_master);
        h_num_bands.* = numBands;
    }
}

