pub fn set_mc_info(arg_pMC_Info: [*c]MC_Info, audioObjectType: tMP4AudioObjectType, sampling_rate_idx: Int, tag: Int, is_cpe: Int, arg_pWinSeqInfo: [*c][*c]FrameInfo, arg_sfbwidth128: [*c]Int) Int {
    var pMC_Info = arg_pMC_Info;
    _ = &pMC_Info;
    _ = &audioObjectType;
    _ = &sampling_rate_idx;
    _ = &tag;
    _ = &is_cpe;
    var pWinSeqInfo = arg_pWinSeqInfo;
    _ = &pWinSeqInfo;
    var sfbwidth128 = arg_sfbwidth128;
    _ = &sfbwidth128;
    var pCh_Info: [*c]Ch_Info = undefined;
    _ = &pCh_Info;
    pMC_Info.*.audioObjectType = audioObjectType;
    if (pMC_Info.*.sampling_rate_idx != sampling_rate_idx) {
        pMC_Info.*.sampling_rate_idx = sampling_rate_idx;
        var status: Int = undefined;
        _ = &status;
        status = infoinit(sampling_rate_idx, pWinSeqInfo, sfbwidth128);
        if (@as(c_int, 0) != status) {
            return 1;
        }
    }
    pMC_Info.*.nch = @as(c_int, 1) + is_cpe;
    pCh_Info = &pMC_Info.*.ch_info[@as(c_int, 0)];
    pCh_Info.*.tag = tag;
    pCh_Info.*.cpe = is_cpe;
    if (is_cpe != @as(c_int, 0)) {
        pCh_Info = &pMC_Info.*.ch_info[@as(c_int, 1)];
        pCh_Info.*.cpe = 1;
    }
    return @as(c_int, 0);
}

