pub fn shellsort(arg_in: [*c]Int32, arg_n: Int32) void {
    var in = arg_in;
    _ = &in;
    var n = arg_n;
    _ = &n;
    var i: Int32 = undefined;
    _ = &i;
    var j: Int32 = undefined;
    _ = &j;
    var v: Int32 = undefined;
    _ = &v;
    var inc: Int32 = 1;
    _ = &inc;
    while (true) {
        inc = (@as(c_int, 3) * inc) + @as(c_int, 1);
        if (!(inc <= n)) break;
    }
    while (true) {
        inc = @divTrunc(inc, @as(c_int, 3));
        {
            i = inc + @as(c_int, 1);
            while (i <= n) : (i += 1) {
                v = in[@bitCast(@as(isize, @intCast(i - @as(c_int, 1))))];
                j = i;
                while (in[@bitCast(@as(isize, @intCast((j - inc) - @as(c_int, 1))))] > v) {
                    in[@bitCast(@as(isize, @intCast(j - @as(c_int, 1))))] = in[@bitCast(@as(isize, @intCast((j - inc) - @as(c_int, 1))))];
                    j -= inc;
                    if (j <= inc) {
                        break;
                    }
                }
                in[@bitCast(@as(isize, @intCast(j - @as(c_int, 1))))] = v;
            }
        }
        if (!(inc > @as(c_int, 1))) break;
    }
}

pub fn shft_lft_1(arg_L_var1: Int32) Int32 {
    var L_var1 = arg_L_var1;
    _ = &L_var1;
    if (((L_var1 << @intCast(@as(c_int, 1))) >> @intCast(@as(c_int, 1))) == L_var1) {
        L_var1 <<= @intCast(@as(c_int, 1));
    } else {
        L_var1 = (L_var1 >> @intCast(@as(c_int, 31))) ^ @as(c_int, 2147483647);
    }
    return L_var1;
}

