    _ = &i;
    var j: Int = undefined;
    _ = &j;
    var temp: Int32 = undefined;
    _ = &temp;
    var y0: Int32 = undefined;
    _ = &y0;
    var p_state: [*c]Int32 = null;
    _ = &p_state;
    var p_lpc: [*c]const Int32 = undefined;
    _ = &p_lpc;
