                    while (j > i) : (j -= 1) {
                        y0 +%= fxp_mul32_Q31((blk: {
                            const ref = &p_state;
                            const tmp = ref.*;
                            ref.* -= 1;
                            break :blk tmp;
                        }).*, (blk: {
                            const ref = &p_lpc;
                            const tmp = ref.*;
                            ref.* += 1;
                            break :blk tmp;
                        }).*);
                    }
                }
                p_state = p_spec;
                p_spec.* = (pv_shr(p_spec.*, shift_down_amount)) +% (pv_shl(-%y0, shift_up));
                p_spec += 1;
            }
        }
        if (spec_length > order) {
            {
                i = spec_length - order;
                while (i != @as(c_int, 0)) : (i -= 1) {
                    p_lpc = lpc;
                    y0 = 0;
                    {
                        j = order;
                        while (j != @as(c_int, 0)) : (j -= 1) {
                            y0 +%= fxp_mul32_Q31((blk: {
                                const ref = &p_state;
                                const tmp = ref.*;
                                ref.* -= 1;
                                break :blk tmp;
                            }).*, (blk: {
                                const ref = &p_lpc;
                                const tmp = ref.*;
                                ref.* += 1;
                                break :blk tmp;
                            }).*);
                        }
                    }
                    p_state = p_spec;
                    p_spec.* = (pv_shr(p_spec.*, shift_down_amount)) +% (pv_shl(-%y0, shift_up));
                    p_spec += 1;
                }
            }
        }
    }
    return shift_down_amount;
}

pub fn tns_decode_coef(order: Int, coef_res: Int, arg_lpc_coef: [*c]Int32, arg_scratchTnsDecCoefMem: [*c]Int32) Int {
    _ = &order;
    _ = &coef_res;
    var lpc_coef = arg_lpc_coef;
    _ = &lpc_coef;
    var scratchTnsDecCoefMem = arg_scratchTnsDecCoefMem;
    _ = &scratchTnsDecCoefMem;
    var i: Int = undefined;
    _ = &i;
    var m: Int = undefined;
    _ = &m;
    var pB: [*c]Int32 = &scratchTnsDecCoefMem[TNS_MAX_ORDER];
    _ = &pB;
    var pA: [*c]Int32 = scratchTnsDecCoefMem;
    _ = &pA;
    var temp_ptr: [*c]Int32 = null;
    _ = &temp_ptr;
    var pLPC: [*c]Int32 = undefined;
    _ = &pLPC;
    var q_lpc: Int = Q_LPC;
    _ = &q_lpc;
    var pTnsTable: [*c]const Int32 = undefined;
    _ = &pTnsTable;
    var coef_offset: Int = undefined;
    _ = &coef_offset;
    var table_index: Int32 = undefined;
    _ = &table_index;
    var shift_amount: Int = undefined;
    _ = &shift_amount;
    var sin_result: Int32 = undefined;
    _ = &sin_result;
    var tempInt32: Int32 = undefined;
    _ = &tempInt32;
    var max: Int32 = undefined;
    _ = &max;
    var mask: Int32 = undefined;
    _ = &mask;
    var mult_high: Int32 = undefined;
    _ = &mult_high;
    coef_offset = neg_offset[@bitCast(@as(isize, @intCast(coef_res)))];
    pTnsTable = @ptrCast(@alignCast(&tns_table[@bitCast(@as(isize, @intCast(coef_res)))]));
    m = 0;
    pLPC = lpc_coef;
    while (true) {
        table_index = coef_offset + (blk: {
            const ref = &pLPC;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).*;
        sin_result = (pTnsTable + @as(usize, @bitCast(@as(isize, @intCast(table_index))))).*;
        {
            i = m;
            while (i > @as(c_int, 0)) : (i -= 1) {
                mult_high = fxp_mul32_Q31((blk: {
                    const ref = &temp_ptr;
                    const tmp = ref.*;
                    ref.* -= 1;
                    break :blk tmp;
                }).*, sin_result);
                (blk: {
                    const ref = &pB;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = (blk: {
                    const ref = &pA;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* + (mult_high << @intCast(@as(c_int, 1)));
            }
        }
        pB.* = sin_result >> @intCast(@as(c_int, 12));
        temp_ptr = pA;
        pA = pB;
        pB = temp_ptr;
        temp_ptr = pA;
        tempInt32 = pA.*;
        mask = tempInt32 >> @intCast(@as(c_int, 31));
        tempInt32 ^= mask;
        max = tempInt32;
        {
            i = m;
            while (i > @as(c_int, 0)) : (i -= 1) {
                tempInt32 = (blk: {
                    const ref = &pA;
                    ref.* -= 1;
                    break :blk ref.*;
                }).*;
                mask = tempInt32 >> @intCast(@as(c_int, 31));
                tempInt32 ^= mask;
                max |= tempInt32;
            }
        }
        pB -= @as(usize, @bitCast(@as(isize, @intCast(m))));
        if (@as(c_long, max) >= @as(c_long, 1073741824)) {
            max >>= @intCast(@as(c_int, 1));
            {
                i = m;
                while (i > @as(c_int, 0)) : (i -= 1) {
                    (blk: {
                        const ref = &pA;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* >>= @intCast(@as(c_int, 1));
                    (blk: {
                        const ref = &pB;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).* >>= @intCast(@as(c_int, 1));
                }
            }
            pA.* >>= @intCast(@as(c_int, 1));
            q_lpc -= 1;
            pA -= @as(usize, @bitCast(@as(isize, @intCast(m))));
            pB -= @as(usize, @bitCast(@as(isize, @intCast(m))));
        }
        m += 1;
        if (!(m < order)) break;
    }
    shift_amount = 0;
    while (max > @as(c_int, 32767)) {
        max >>= @intCast(@as(c_int, 1));
        shift_amount += 1;
    }
    if (max != @as(c_int, 0)) {
        while (max < @as(c_int, 16384)) {
            max <<= @intCast(@as(c_int, 1));
            shift_amount -= 1;
        }
    }
    pLPC = lpc_coef;
    if (shift_amount >= @as(c_int, 0)) {
        {
            m = order;
            while (m > @as(c_int, 0)) : (m -= 1) {
                (blk: {
                    const ref = &pLPC;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* = pv_shl((blk: {
                    const ref = &pA;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).*, @as(c_int, 16) - shift_amount);
            }
        }
    }
    q_lpc -= shift_amount;
    if (q_lpc > @as(c_int, 15)) {
        shift_amount = q_lpc - @as(c_int, 15);
        pLPC = lpc_coef;
        {
            m = order;
            while (m > @as(c_int, 0)) : (m -= 1) {
                (blk: {
                    const ref = &pLPC;
                    const tmp = ref.*;
                    ref.* += 1;
                    break :blk tmp;
                }).* >>= @intCast(shift_amount);
            }
        }
        q_lpc -= shift_amount;
    }
    return q_lpc;
}

pub fn tns_inv_filter(arg_coef: [*c]Int32, num_coef: Int, direction: Int, arg_lpc: [*c]const Int32, lpc_qformat: Int, order: Int, arg_scratch_memory: [*c]Int32) void {
    var coef = arg_coef;
    _ = &coef;
    _ = &num_coef;
    _ = &direction;
    var lpc = arg_lpc;
    _ = &lpc;
    _ = &lpc_qformat;
    _ = &order;
    var scratch_memory = arg_scratch_memory;
    _ = &scratch_memory;
    var i: Int = undefined;
    _ = &i;
    var j: Int = undefined;
    _ = &j;
    var shift_amt: Int = undefined;
    _ = &shift_amt;
    var wrap_point: Int = undefined;
    _ = &wrap_point;
    var mult: Int32 = undefined;
    _ = &mult;
    var pFilterInput: [*c]Int32 = scratch_memory;
    _ = &pFilterInput;
    var pLPC: [*c]const Int32 = undefined;
    _ = &pLPC;
    var pCoef: [*c]Int32 = coef;
    _ = &pCoef;
    if (direction == -@as(c_int, 1)) {
        pCoef += @as(usize, @bitCast(@as(isize, @intCast(num_coef - @as(c_int, 1)))));
    }
    {
        i = order;
        while (i != @as(c_int, 0)) : (i -= 1) {
            (blk: {
                const ref = &pFilterInput;
                const tmp = ref.*;
                ref.* += 1;
                break :blk tmp;
            }).* = 0;
        }
    }
    wrap_point = 0;
    shift_amt = lpc_qformat - @as(c_int, 5);
    {
        i = num_coef;
        while (i > @as(c_int, 0)) : (i -= 1) {
            pLPC = lpc;
            mult = 0;
            {
                j = wrap_point;
                while (j > @as(c_int, 0)) : (j -= 1) {
                    mult += fxp_mul32_Q31((blk: {
                        const ref = &pLPC;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*, (blk: {
                        const ref = &pFilterInput;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*) >> @intCast(@as(c_int, 5));
                }
            }
            pFilterInput = scratch_memory;
            {
                j = order - wrap_point;
                while (j > @as(c_int, 0)) : (j -= 1) {
                    mult += fxp_mul32_Q31((blk: {
                        const ref = &pLPC;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*, (blk: {
                        const ref = &pFilterInput;
                        const tmp = ref.*;
                        ref.* += 1;
                        break :blk tmp;
                    }).*) >> @intCast(@as(c_int, 5));
                }
            }
            (blk: {
                const ref = &pFilterInput;
                ref.* -= 1;
                break :blk ref.*;
            }).* = pCoef.*;
            pCoef.* += pv_shr(mult, shift_amt);
            pCoef += @as(usize, @bitCast(@as(isize, @intCast(direction))));
            wrap_point += 1;
            if (wrap_point == order) {
                wrap_point = 0;
            }
        }
    }
}

