        }).* = @truncate(temp_spec);
        temp_spec = if (temp_spec > @as(c_int, 0)) temp_spec else -temp_spec;
        if (temp_spec > max.*) {
            max.* = temp_spec;
        }
    }
    temp_spec = (codeword_indx * div_mod[@bitCast(@as(isize, @intCast(mod)))]) >> @intCast(@as(c_int, 13));
    codeword_indx -= temp_spec * mod;
    temp_spec -= off;
    (blk: {
