pub fn memcpy(dst: ?*anyopaque, src: ?*const anyopaque, n: usize) ?*anyopaque {
    if (n != 0) @memcpy(@as([*]u8, @ptrCast(dst.?))[0..n], @as([*]const u8, @ptrCast(src.?))[0..n]);
    return dst;
}
pub fn memmove(dst: ?*anyopaque, src: ?*const anyopaque, n: usize) ?*anyopaque {
    if (n != 0) {
        const d = @as([*]u8, @ptrCast(dst.?))[0..n];
        const a = @as([*]const u8, @ptrCast(src.?))[0..n];
        if (@intFromPtr(d.ptr) < @intFromPtr(a.ptr)) @import("std").mem.copyForwards(u8, d, a) else @import("std").mem.copyBackwards(u8, d, a);
    }
    return dst;
}
pub fn memset(dst: ?*anyopaque, value: c_int, n: usize) ?*anyopaque {
    if (n != 0) @memset(@as([*]u8, @ptrCast(dst.?))[0..n], @as(u8, @truncate(@as(c_uint, @bitCast(value)))));
    return dst;
}

fn ShiftType(comptime T: type) type {
    return if (T == comptime_int) usize else T;
}
inline fn pv_shl(value: anytype, amount: anytype) ShiftType(@TypeOf(value)) {
    const T = ShiftType(@TypeOf(value));
    return @import("std").math.shl(T, @as(T, value), amount);
}
inline fn pv_shr(value: anytype, amount: anytype) ShiftType(@TypeOf(value)) {
    const T = ShiftType(@TypeOf(value));
    return @import("std").math.shr(T, @as(T, value), amount);
}

// Pointer-bearing PS state has native alignment and request ownership. The
// 32-bit reference's Int32 scratch overlays cannot hold 64-bit pointer arrays.
const NativeHybridStorage = extern struct {
    hybrid: HYBRID,
    resolution: [3]i32,
    real: [3][12]i32,
    imag: [3][12]i32,
    real_ptrs: [3][*c]i32,
    imag_ptrs: [3][*c]i32,
    temp_real: [8]i32,
    temp_imag: [8]i32,
};
fn initNativeHybrid(ps: [*c]STRUCT_PS_DEC) i32 {
    const store = &ps.*.native_hybrid;
    store.* = @import("std").mem.zeroes(NativeHybridStorage);
    store.resolution = .{ 8, 2, 2 };
    const h = &store.hybrid;
    h.nQmfBands = 3;
    h.pResolution = &store.resolution;
    h.qmfBufferMove = 12;
    for (0..3) |i| {
        store.real_ptrs[i] = &store.real[i];
        store.imag_ptrs[i] = &store.imag[i];
    }
    h.mQmfBufferReal = &store.real_ptrs;
    h.mQmfBufferImag = &store.imag_ptrs;
    h.mTempReal = &store.temp_real;
    h.mTempImag = &store.temp_imag;
    ps.*.hHybrid = h;
    return 0;
}

const NativePsDelays = extern struct {
    decay: [3][20]i32,
    hybrid: [4][10]i32,
    qmf_real: [237]i32,
    qmf_imag: [237]i32,
    qmf_real_ptrs: [61][*c]i32,
    qmf_imag_ptrs: [61][*c]i32,
    sub_real: [10][2]i32,
    sub_imag: [10][2]i32,
    sub_real_ptrs: [10][*c]i32,
    sub_imag_ptrs: [10][*c]i32,
    serial_qmf_real: [240]i32,
    serial_qmf_imag: [240]i32,
    serial_sub_real: [120]i32,
    serial_sub_imag: [120]i32,
    serial_qmf_real_ptrs: [3][5][*c]i32,
    serial_qmf_imag_ptrs: [3][5][*c]i32,
    serial_sub_real_ptrs: [3][5][*c]i32,
    serial_sub_imag_ptrs: [3][5][*c]i32,
};
